fn print_query_result(columns: &[String], rows: &[Vec<kkdb::types::Value>]) {
    if columns.is_empty() && rows.is_empty() {
        return;
    }

    // Calculate column widths
    let mut widths: Vec<usize> = columns.iter().map(|c| c.len()).collect();
    for row in rows {
        for (i, val) in row.iter().enumerate() {
            if i < widths.len() {
                let w = format!("{}", val).len();
                if w > widths[i] {
                    widths[i] = w;
                }
            }
        }
    }

    // Print header
    let header: Vec<String> = columns
        .iter()
        .enumerate()
        .map(|(i, c)| format!("{:width$}", c, width = widths[i]))
        .collect();
    println!("{}", header.join(" | "));

    // Print separator
    let sep: Vec<String> = widths.iter().map(|w| "-".repeat(*w)).collect();
    println!("{}", sep.join("-+-"));

    // Print rows
    for row in rows {
        let vals: Vec<String> = row
            .iter()
            .enumerate()
            .map(|(i, v)| {
                let s = format!("{}", v);
                if i < widths.len() {
                    format!("{:width$}", s, width = widths[i])
                } else {
                    s
                }
            })
            .collect();
        println!("{}", vals.join(" | "));
    }

    println!("({} rows)", rows.len());
}

fn print_help() {
    println!("KKDB - A SQLite implementation in Rust");
    println!();
    println!("Commands:");
    println!("  .help              Show this help message");
    println!("  .quit / .exit      Exit the program");
    println!("  .tables            List all tables");
    println!("  .schema [TABLE]    Show CREATE statement for tables");
    println!("  .open FILE         Open a database file");
    println!("  .memory            Switch to in-memory database");
    println!();
    println!("SQL Statements:");
    println!("  CREATE TABLE name (col1 TYPE, col2 TYPE, ...)");
    println!("  DROP TABLE [IF EXISTS] name");
    println!("  INSERT INTO name [(cols)] VALUES (vals), ...");
    println!("  SELECT cols FROM table [WHERE ...] [ORDER BY ...] [LIMIT n]");
    println!("  UPDATE name SET col=val [WHERE ...]");
    println!("  DELETE FROM name [WHERE ...]");
    println!("  EXPLAIN statement");
}

fn handle_dot_command(vm: &mut VM, cmd: &str) -> Option<VM> {
    let parts: Vec<&str> = cmd.trim().splitn(2, ' ').collect();
    let command = parts[0].to_lowercase();

    match command.as_str() {
        ".help" => {
            print_help();
            None
        }
        ".quit" | ".exit" => {
            std::process::exit(0);
        }
        ".tables" => {
            let mut names: Vec<&String> = vm.schema.tables.keys().collect();
            names.sort();
            for name in names {
                println!("{}", name);
            }
            None
        }
        ".schema" => {
            let filter = parts.get(1).map(|s| s.trim());
            let mut entries: Vec<(String, String)> = Vec::new();

            // Prefer persisted schema catalog so output includes exact SQL.
            let schema_root = vm.pager.schema_root_page();
            let mut btree = BTree::new(&mut vm.pager);
            match btree.scan_all(schema_root) {
                Ok(rows) => {
                    for (_rowid, row) in rows {
                        if row.len() < 5 {
                            continue;
                        }
                        let name = match &row[1] {
                            Value::Text(v) => v.to_string(),
                            _ => continue,
                        };
                        let sql = match &row[4] {
                            Value::Text(v) => v.to_string(),
                            _ => continue,
                        };
                        if let Some(f) = filter {
                            if !name.eq_ignore_ascii_case(f) {
                                continue;
                            }
                        }
                        entries.push((name, sql));
                    }
                }
                Err(_) => {
                    // Fallback: reconstruct from in-memory schema cache.
                    for (name, table) in &vm.schema.tables {
                        if let Some(f) = filter {
                            if !name.eq_ignore_ascii_case(f) {
                                continue;
                            }
                        }
                        let cols: Vec<String> = table
                            .columns
                            .iter()
                            .map(|c| {
                                let mut s = format!("{} {}", c.name, c.data_type);
                                if c.primary_key {
                                    s.push_str(" PRIMARY KEY");
                                }
                                if c.autoincrement {
                                    s.push_str(" AUTOINCREMENT");
                                }
                                if c.not_null {
                                    s.push_str(" NOT NULL");
                                }
                                if c.unique {
                                    s.push_str(" UNIQUE");
                                }
                                s
                            })
                            .collect();
                        entries.push((
                            name.clone(),
                            format!("CREATE TABLE {} ({})", name, cols.join(", ")),
                        ));
                    }
                }
            }

            entries.sort_by(|a, b| a.0.cmp(&b.0));
            for (_name, sql) in entries {
                let text = sql.trim();
                if text.ends_with(';') {
                    println!("{}", text);
                } else {
                    println!("{};", text);
                }
            }
            None
        }
        ".open" => {
            if let Some(path) = parts.get(1) {
                match VM::open(path.trim()) {
                    Ok(new_vm) => {
                        println!("Opened database: {}", path.trim());
                        Some(new_vm)
                    }
                    Err(e) => {
                        eprintln!("Error: {}", e);
                        None
                    }
                }
            } else {
                eprintln!("Usage: .open FILENAME");
                None
            }
        }
        ".memory" => {
            println!("Switched to in-memory database");
            Some(VM::new_memory())
        }
        _ => {
            eprintln!("Unknown command: {}. Use .help for help.", command);
            None
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut vm = if args.len() > 1 {
        match VM::open(&args[1]) {
            Ok(vm) => {
                println!("KKDB v0.1.0 - opened '{}'", args[1]);
                vm
            }
            Err(e) => {
                eprintln!("Error opening '{}': {}", args[1], e);
                std::process::exit(1);
            }
        }
    } else {
        println!("KKDB v0.1.0 - in-memory database");
        VM::new_memory()
    };

    println!("Type .help for usage hints, .quit to exit.");
    println!();

    // SERVER MODE
    if args.iter().any(|arg| arg == "--server") {
        let port_str = args
            .iter()
            .skip_while(|arg| *arg != "--port")
            .nth(1)
            .cloned()
            .unwrap_or_else(|| "3306".to_string());
        let port: u16 = port_str.parse().unwrap_or(3306);

        let http_port_str = args
            .iter()
            .skip_while(|arg| *arg != "--http-port")
            .nth(1)
            .cloned()
            .unwrap_or_else(|| "6543".to_string());
        let http_port: u16 = http_port_str.parse().unwrap_or(6543);

        // New async MySQL Wire Protocol port (standard MySQL clients: DBeaver, mysql2 etc.)
        let mysql_port_str = args
            .iter()
            .skip_while(|arg| *arg != "--mysql-port")
            .nth(1)
            .cloned()
            .unwrap_or_else(|| "3307".to_string());
        let mysql_port: u16 = mysql_port_str.parse().unwrap_or(3307);

        // ── Resolve data directory: --data-dir flag > kkdb_config table > None ─
        let data_dir_cli = args
            .iter()
            .skip_while(|arg| *arg != "--data-dir")
            .nth(1)
            .cloned();

        let data_dir: Option<std::path::PathBuf> = if let Some(dir) = data_dir_cli {
            // CLI flag takes precedence
            Some(std::path::PathBuf::from(dir))
        } else {
            // Fallback: read kkdb_config table if it exists
            let config_val = vm
                .execute_sql("SELECT value FROM kkdb_config WHERE key = 'http.data_dir'")
                .ok()
                .and_then(|r| match r {
                    kkdb::vm::execute::ExecResult::QueryResult { rows, .. } => rows
                        .into_iter()
                        .next()
                        .and_then(|row| row.into_iter().next())
                        .map(|v| v.to_string()),
                    _ => None,
                });
            config_val.map(std::path::PathBuf::from)
        };

        if let Some(ref dir) = data_dir {
            println!("[KKDB] Per-user data dir: {}", dir.display());
        } else {
            println!("[KKDB] HTTP API running in in-memory mode (no --data-dir set)");
        }

        let shared_vm = Arc::new(Mutex::new(vm));

        // Start HTTP REST API (Supabase-style) in a background OS thread
        std::thread::spawn(move || {
            let rt = tokio::runtime::Runtime::new().expect("tokio runtime");
            rt.block_on(async move {
                let state = match data_dir {
                    Some(dir) => match kkdb::server::http_api::AppState::with_dir(dir) {
                        Ok(s) => s,
                        Err(e) => {
                            eprintln!("[KKDB] Failed to open HTTP data dir: {e}");
                            std::process::exit(1);
                        }
                    },
                    None => kkdb::server::http_api::AppState::in_memory(),
                };
                let router = kkdb::server::http_api::build_router(state);
                let addr = format!("0.0.0.0:{}", http_port);
                let listener = tokio::net::TcpListener::bind(&addr)
                    .await
                    .expect("Failed to bind HTTP API port");
                println!("[KKDB] HTTP API  listening on http://{}", addr);
                axum::serve(listener, router)
                    .await
                    .expect("HTTP API server error");
            });
        });

        // Start async MySQL Wire Protocol server in a background OS thread
        let mysql_data_dir = args
            .iter()
            .skip_while(|arg| *arg != "--data-dir")
            .nth(1)
            .cloned()
            .map(std::path::PathBuf::from);
        let _ = Arc::clone(&shared_vm); // keep shared_vm alive
        std::thread::spawn(move || {
            let rt = tokio::runtime::Runtime::new().expect("tokio runtime (mysql)");
            rt.block_on(async move {
                let state = match mysql_data_dir {
                    Some(dir) => match kkdb::server::http_api::AppState::with_dir(dir) {
                        Ok(s) => s,
                        Err(e) => {
                            eprintln!("[MySQL] Failed to open data dir: {e}");
                            return;
                        }
                    },
                    None => kkdb::server::http_api::AppState::in_memory(),
                };
                let addr = format!("0.0.0.0:{mysql_port}");
                if let Err(e) = kkdb::server::mysql::serve_mysql(&addr, state).await {
                    eprintln!("[MySQL] Server error: {e}");
                }
            });
        });

        println!("[KKDB] MySQL API listening on 0.0.0.0:{}", port);

        // ── Optional Raft cluster mode ──────────────────────────────────────
        // Flags: --node-id <u64>  --raft-addr <host:port>  --peers <id=host:port,...>
        let node_id: Option<u64> = args
            .iter()
            .skip_while(|a| *a != "--node-id")
            .nth(1)
            .and_then(|s| s.parse().ok());

        let raft_addr_str: Option<String> = args
            .iter()
            .skip_while(|a| *a != "--raft-addr")
            .nth(1)
            .cloned();

        if let (Some(nid), Some(raft_addr_str)) = (node_id, raft_addr_str) {
            // Parse peers: "2=127.0.0.1:7002,3=127.0.0.1:7003"
            let peers_raw: Option<String> =
                args.iter().skip_while(|a| *a != "--peers").nth(1).cloned();

            let peer_addrs: std::collections::BTreeMap<u64, String> = peers_raw
                .unwrap_or_default()
                .split(',')
                .filter_map(|s| {
                    let mut parts = s.splitn(2, '=');
                    let id: u64 = parts.next()?.trim().parse().ok()?;
                    let addr = format!("http://{}", parts.next()?.trim());
                    Some((id, addr))
                })
                .collect();

            let self_url = format!("http://{}", raft_addr_str);
            let raft_socket: std::net::SocketAddr =
                raft_addr_str.parse().expect("invalid --raft-addr");

            // Build data dir for this raft node (reuse data_dir logic above)
            let data_dir_raft = args
                .iter()
                .skip_while(|a| *a != "--data-dir")
                .nth(1)
                .cloned()
                .map(std::path::PathBuf::from);

            // WAL dir = same as data dir (will create {data_dir}/raft/ subdirectory)
            let wal_dir = data_dir_raft.clone();

            let raft_state = match data_dir_raft {
                Some(dir) => match kkdb::server::http_api::AppState::with_dir(dir) {
                    Ok(s) => s,
                    Err(e) => {
                        eprintln!("[Raft] Failed to open data dir: {e}");
                        std::process::exit(1);
                    }
                },
                None => kkdb::server::http_api::AppState::in_memory(),
            };

            std::thread::spawn(move || {
                let rt = tokio::runtime::Runtime::new().unwrap();
                rt.block_on(async move {
                    let binlog = wal_dir.as_ref().map(|dir| {
                        let inner = dir.join("binlog.kkdb");
                        let mgr = kkdb::binlog::BinlogManager::open(&inner).unwrap();
                        kkdb::binlog::BinlogBroadcaster::new(mgr, 1024)
                    });

                    let node = kkdb::raft::node::new_with_http_network(
                        nid,
                        raft_state,
                        self_url,
                        peer_addrs.clone(),
                        wal_dir,
                        binlog,
                    )
                    .await
                    .expect("create raft node");
                    let node = std::sync::Arc::new(node);

                    // Bootstrap single node or if --peers is empty
                    if peer_addrs.is_empty() {
                        println!("[Raft] Single-node bootstrap, node {nid}");
                        node.init_single().await.unwrap_or_default();
                    }
                    // (Multi-node: operator calls POST /raft/init after all nodes start)

                    println!("[Raft] Node {nid} RPC server on {raft_socket}");
                    kkdb::raft::node::start_raft_http_server(
                        std::sync::Arc::clone(&node),
                        raft_socket,
                    )
                    .await;
                });
            });
        }

        if let Err(e) = kkdb::server::start_server(shared_vm, port) {
            eprintln!("Fatal server error: {}", e);
        }
        return;
    }

    // REPL MODE
    let mut rl = DefaultEditor::new().expect("Failed to create line editor");
    let mut multi_line_buf = String::new();

    loop {
        let prompt = if multi_line_buf.is_empty() {
            "kkdb> "
        } else {
            "  ... "
        };

        match rl.readline(prompt) {
            Ok(line) => {
                let trimmed = line.trim();

                if trimmed.is_empty() {
                    continue;
                }

                // Dot commands
                if trimmed.starts_with('.') && multi_line_buf.is_empty() {
                    let _ = rl.add_history_entry(trimmed);
                    if let Some(new_vm) = handle_dot_command(&mut vm, trimmed) {
                        vm = new_vm;
                    }
                    continue;
                }

                multi_line_buf.push_str(trimmed);
                multi_line_buf.push(' ');

                // Check if statement is complete (ends with semicolon)
                if !trimmed.ends_with(';') {
                    continue;
                }

                let sql = multi_line_buf.trim().to_string();
                multi_line_buf.clear();

                let _ = rl.add_history_entry(&sql);

                match vm.execute_sql(&sql) {
                    Ok(result) => match result {
                        ExecResult::Ok { message } => println!("{}", message),
                        ExecResult::RowsAffected { message, .. } => println!("{}", message),
                        ExecResult::QueryResult { columns, rows } => {
                            print_query_result(&columns, &rows);
                        }
                        ExecResult::Explain { plan } => print!("{}", plan),
                    },
                    Err(e) => eprintln!("Error: {}", e),
                }
            }
            Err(ReadlineError::Interrupted) => {
                multi_line_buf.clear();
                println!("^C");
            }
            Err(ReadlineError::Eof) => {
                println!("Bye!");
                break;
            }
            Err(e) => {
                eprintln!("Error: {}", e);
                break;
            }
        }
    }
}

//! Distributed Transaction Coordinator — Two-Phase Commit (2PC) Protocol
//!
//! Implements the classic 2PC protocol for cross-node atomic transactions
//! on top of the existing Raft consensus layer.
//!
//! # Protocol Flow
//!
//! ```text
//!  Coordinator                   Participant A           Participant B
//!      │                              │                       │
//!      │── PREPARE ──────────────────►│                       │
//!      │── PREPARE ──────────────────────────────────────────►│
//!      │                              │                       │
//!      │◄─ VOTE_COMMIT ──────────────│                       │
//!      │◄─ VOTE_COMMIT ──────────────────────────────────────│
//!      │                              │                       │
//!      │── COMMIT ───────────────────►│                       │
//!      │── COMMIT ───────────────────────────────────────────►│
//!      │                              │                       │
//!      │◄─ ACK ──────────────────────│                       │
//!      │◄─ ACK ──────────────────────────────────────────────│
//! ```
//!
//! # 3PC Extension
//!
//! Adds a PRE_COMMIT phase between PREPARE and COMMIT to avoid blocking
//! when the coordinator fails after collecting all votes:
//!
//! ```text
//!  PREPARE → VOTE → PRE_COMMIT → ACK → COMMIT → ACK
//! ```

use std::collections::HashMap;
use std::fmt;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Globally unique transaction ID for distributed transactions.
pub type DtxId = u64;

/// Participant node identifier.
pub type ParticipantId = u64;

/// State of a distributed transaction.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DtxState {
    /// Transaction initiated, preparing to send PREPARE.
    Init,
    /// PREPARE messages sent, waiting for votes.
    Preparing,
    /// All participants voted COMMIT — pre-commit phase (3PC only).
    PreCommitted,
    /// Decision: COMMIT — sending COMMIT to all participants.
    Committing,
    /// Decision: ABORT — sending ABORT to all participants.
    Aborting,
    /// Terminal: successfully committed on all participants.
    Committed,
    /// Terminal: aborted on all participants.
    Aborted,
}

impl fmt::Display for DtxState {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DtxState::Init => write!(f, "INIT"),
            DtxState::Preparing => write!(f, "PREPARING"),
            DtxState::PreCommitted => write!(f, "PRE_COMMITTED"),
            DtxState::Committing => write!(f, "COMMITTING"),
            DtxState::Aborting => write!(f, "ABORTING"),
            DtxState::Committed => write!(f, "COMMITTED"),
            DtxState::Aborted => write!(f, "ABORTED"),
        }
    }
}

/// Vote from a participant in phase 1.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Vote {
    /// Participant is ready to commit.
    Commit,
    /// Participant cannot commit (constraint violation, timeout, etc.).
    Abort,
}

/// A message in the 2PC/3PC protocol.
#[derive(Debug, Clone)]
pub enum DtxMessage {
    /// Phase 1: Coordinator asks participant to prepare.
    Prepare {
        dtx_id: DtxId,
        sql: String,
    },
    /// Phase 1 response: Participant votes.
    VoteResult {
        dtx_id: DtxId,
        participant: ParticipantId,
        vote: Vote,
        /// Optional error message if vote is Abort.
        reason: Option<String>,
    },
    /// Phase 2 (3PC only): Coordinator signals pre-commit.
    PreCommit {
        dtx_id: DtxId,
    },
    /// Phase 2 (3PC only): Participant acknowledges pre-commit.
    PreCommitAck {
        dtx_id: DtxId,
        participant: ParticipantId,
    },
    /// Final phase: Coordinator orders commit.
    Commit {
        dtx_id: DtxId,
    },
    /// Final phase: Coordinator orders abort.
    Abort {
        dtx_id: DtxId,
        reason: String,
    },
    /// Acknowledgement from participant after commit/abort.
    Ack {
        dtx_id: DtxId,
        participant: ParticipantId,
        success: bool,
    },
}

/// A single participant's state in a distributed transaction.
#[derive(Debug, Clone)]
pub struct ParticipantState {
    pub id: ParticipantId,
    pub vote: Option<Vote>,
    pub vote_reason: Option<String>,
    pub pre_commit_acked: bool,
    pub committed: bool,
    pub aborted: bool,
}

impl ParticipantState {
    fn new(id: ParticipantId) -> Self {
        Self {
            id,
            vote: None,
            vote_reason: None,
            pre_commit_acked: false,
            committed: false,
            aborted: false,
        }
    }
}

/// Coordinator-side view of a distributed transaction.
#[derive(Debug, Clone)]
pub struct DistributedTransaction {
    /// Unique transaction ID.
    pub id: DtxId,
    /// SQL statement(s) being executed across participants.
    pub sql: String,
    /// Current state of the 2PC protocol.
    pub state: DtxState,
    /// Per-participant state.
    pub participants: HashMap<ParticipantId, ParticipantState>,
    /// Whether to use 3PC (with pre-commit phase).
    pub use_3pc: bool,
    /// Timeout for each phase.
    pub phase_timeout: Duration,
    /// When the current phase started.
    pub phase_start: Instant,
    /// Decision log for recovery.
    pub decision_log: Vec<String>,
}

impl DistributedTransaction {
    /// Create a new distributed transaction.
    pub fn new(
        id: DtxId,
        sql: String,
        participants: Vec<ParticipantId>,
        use_3pc: bool,
        phase_timeout: Duration,
    ) -> Self {
        let participant_map = participants
            .into_iter()
            .map(|pid| (pid, ParticipantState::new(pid)))
            .collect();
        Self {
            id,
            sql,
            state: DtxState::Init,
            participants: participant_map,
            use_3pc,
            phase_timeout,
            phase_start: Instant::now(),
            decision_log: vec![format!("DTX-{}: created", id)],
        }
    }

    /// Number of participants.
    pub fn participant_count(&self) -> usize {
        self.participants.len()
    }

    /// Check if we have all votes collected.
    pub fn all_votes_received(&self) -> bool {
        self.participants.values().all(|p| p.vote.is_some())
    }

    /// Check if all votes are COMMIT.
    pub fn all_voted_commit(&self) -> bool {
        self.participants
            .values()
            .all(|p| p.vote == Some(Vote::Commit))
    }

    /// Check if any participant voted ABORT.
    pub fn any_voted_abort(&self) -> bool {
        self.participants
            .values()
            .any(|p| p.vote == Some(Vote::Abort))
    }

    /// Check if all pre-commit acks received (3PC).
    pub fn all_pre_commit_acked(&self) -> bool {
        self.participants.values().all(|p| p.pre_commit_acked)
    }

    /// Check if all participants have committed.
    pub fn all_committed(&self) -> bool {
        self.participants.values().all(|p| p.committed)
    }

    /// Check if all participants have aborted.
    pub fn all_aborted(&self) -> bool {
        self.participants.values().all(|p| p.aborted)
    }

    /// Check if the current phase has timed out.
    pub fn phase_timed_out(&self) -> bool {
        self.phase_start.elapsed() > self.phase_timeout
    }

    /// Record a vote from a participant.
    pub fn record_vote(
        &mut self,
        participant: ParticipantId,
        vote: Vote,
        reason: Option<String>,
    ) -> Result<(), String> {
        let ps = self
            .participants
            .get_mut(&participant)
            .ok_or_else(|| format!("unknown participant {}", participant))?;
        if ps.vote.is_some() {
            return Err(format!(
                "participant {} already voted",
                participant
            ));
        }
        ps.vote = Some(vote);
        ps.vote_reason = reason.clone();
        self.decision_log.push(format!(
            "DTX-{}: participant {} voted {:?}{}",
            self.id,
            participant,
            vote,
            reason.map(|r| format!(" ({})", r)).unwrap_or_default()
        ));
        Ok(())
    }

    /// Record a pre-commit ack from a participant (3PC).
    pub fn record_pre_commit_ack(&mut self, participant: ParticipantId) -> Result<(), String> {
        let ps = self
            .participants
            .get_mut(&participant)
            .ok_or_else(|| format!("unknown participant {}", participant))?;
        ps.pre_commit_acked = true;
        self.decision_log
            .push(format!("DTX-{}: participant {} pre-commit-acked", self.id, participant));
        Ok(())
    }

    /// Record that a participant has committed.
    pub fn record_committed(&mut self, participant: ParticipantId) -> Result<(), String> {
        let ps = self
            .participants
            .get_mut(&participant)
            .ok_or_else(|| format!("unknown participant {}", participant))?;
        ps.committed = true;
        self.decision_log
            .push(format!("DTX-{}: participant {} committed", self.id, participant));
        Ok(())
    }

    /// Record that a participant has aborted.
    pub fn record_aborted(&mut self, participant: ParticipantId) -> Result<(), String> {
        let ps = self
            .participants
            .get_mut(&participant)
            .ok_or_else(|| format!("unknown participant {}", participant))?;
        ps.aborted = true;
        self.decision_log
            .push(format!("DTX-{}: participant {} aborted", self.id, participant));
        Ok(())
    }
}

/// The 2PC/3PC Coordinator — manages distributed transaction state.
///
/// Thread-safe via inner `Mutex`.
pub struct DtxCoordinator {
    inner: Mutex<CoordinatorInner>,
}

struct CoordinatorInner {
    /// Active distributed transactions.
    transactions: HashMap<DtxId, DistributedTransaction>,
    /// Next transaction ID.
    next_id: DtxId,
    /// Completed transaction log (last N for debugging).
    completed_log: Vec<(DtxId, DtxState)>,
    /// Maximum completed log entries to retain.
    max_completed_log: usize,
    /// Statistics.
    stats: DtxStats,
}

/// Coordinator statistics.
#[derive(Debug, Clone, Default)]
pub struct DtxStats {
    pub total_transactions: u64,
    pub total_committed: u64,
    pub total_aborted: u64,
    pub total_timeouts: u64,
    pub active_transactions: usize,
}

impl DtxCoordinator {
    /// Create a new coordinator.
    pub fn new() -> Self {
        Self {
            inner: Mutex::new(CoordinatorInner {
                transactions: HashMap::new(),
                next_id: 1,
                completed_log: Vec::new(),
                max_completed_log: 100,
                stats: DtxStats::default(),
            }),
        }
    }

    /// Begin a new distributed transaction.
    ///
    /// Returns the `DtxId` and a list of `DtxMessage::Prepare` messages
    /// that should be sent to each participant.
    pub fn begin(
        &self,
        sql: String,
        participants: Vec<ParticipantId>,
        use_3pc: bool,
        phase_timeout: Duration,
    ) -> (DtxId, Vec<DtxMessage>) {
        let mut inner = self.inner.lock().unwrap();
        let id = inner.next_id;
        inner.next_id += 1;
        inner.stats.total_transactions += 1;
        inner.stats.active_transactions += 1;

        let dtx = DistributedTransaction::new(
            id,
            sql.clone(),
            participants.clone(),
            use_3pc,
            phase_timeout,
        );
        inner.transactions.insert(id, dtx);

        let messages = participants
            .into_iter()
            .map(|_pid| DtxMessage::Prepare {
                dtx_id: id,
                sql: sql.clone(),
            })
            .collect();

        (id, messages)
    }

    /// Process a vote from a participant.
    ///
    /// Returns the next messages to send (if any), or the final decision.
    pub fn process_vote(
        &self,
        dtx_id: DtxId,
        participant: ParticipantId,
        vote: Vote,
        reason: Option<String>,
    ) -> Result<Vec<DtxMessage>, String> {
        let mut inner = self.inner.lock().unwrap();
        let dtx = inner
            .transactions
            .get_mut(&dtx_id)
            .ok_or_else(|| format!("DTX-{} not found", dtx_id))?;

        dtx.record_vote(participant, vote, reason)?;

        // If any participant votes ABORT, immediately decide ABORT
        if dtx.any_voted_abort() {
            dtx.state = DtxState::Aborting;
            let abort_reason = dtx
                .participants
                .values()
                .filter_map(|p| {
                    if p.vote == Some(Vote::Abort) {
                        p.vote_reason.clone()
                    } else {
                        None
                    }
                })
                .collect::<Vec<_>>()
                .join("; ");
            dtx.decision_log
                .push(format!("DTX-{}: decision=ABORT ({})", dtx_id, abort_reason));
            return Ok(vec![DtxMessage::Abort {
                dtx_id,
                reason: abort_reason,
            }]);
        }

        // If all votes received and all are COMMIT
        if dtx.all_votes_received() && dtx.all_voted_commit() {
            if dtx.use_3pc {
                // 3PC: move to PRE_COMMIT phase
                dtx.state = DtxState::PreCommitted;
                dtx.phase_start = Instant::now();
                dtx.decision_log
                    .push(format!("DTX-{}: all voted COMMIT, entering PRE_COMMIT", dtx_id));
                return Ok(vec![DtxMessage::PreCommit { dtx_id }]);
            } else {
                // 2PC: directly COMMIT
                dtx.state = DtxState::Committing;
                dtx.phase_start = Instant::now();
                dtx.decision_log
                    .push(format!("DTX-{}: all voted COMMIT, decision=COMMIT", dtx_id));
                return Ok(vec![DtxMessage::Commit { dtx_id }]);
            }
        }

        // Still waiting for more votes
        Ok(vec![])
    }

    /// Process a pre-commit acknowledgement (3PC only).
    pub fn process_pre_commit_ack(
        &self,
        dtx_id: DtxId,
        participant: ParticipantId,
    ) -> Result<Vec<DtxMessage>, String> {
        let mut inner = self.inner.lock().unwrap();
        let dtx = inner
            .transactions
            .get_mut(&dtx_id)
            .ok_or_else(|| format!("DTX-{} not found", dtx_id))?;

        dtx.record_pre_commit_ack(participant)?;

        if dtx.all_pre_commit_acked() {
            dtx.state = DtxState::Committing;
            dtx.phase_start = Instant::now();
            dtx.decision_log
                .push(format!("DTX-{}: all pre-commit acked, decision=COMMIT", dtx_id));
            return Ok(vec![DtxMessage::Commit { dtx_id }]);
        }

        Ok(vec![])
    }

    /// Process a commit/abort acknowledgement from a participant.
    pub fn process_ack(
        &self,
        dtx_id: DtxId,
        participant: ParticipantId,
        was_commit: bool,
    ) -> Result<Option<DtxState>, String> {
        let mut inner = self.inner.lock().unwrap();
        let dtx = inner
            .transactions
            .get_mut(&dtx_id)
            .ok_or_else(|| format!("DTX-{} not found", dtx_id))?;

        if was_commit {
            dtx.record_committed(participant)?;
            if dtx.all_committed() {
                dtx.state = DtxState::Committed;
                inner.stats.total_committed += 1;
                inner.stats.active_transactions =
                    inner.stats.active_transactions.saturating_sub(1);
                inner
                    .completed_log
                    .push((dtx_id, DtxState::Committed));
                if inner.completed_log.len() > inner.max_completed_log {
                    inner.completed_log.remove(0);
                }
                return Ok(Some(DtxState::Committed));
            }
        } else {
            dtx.record_aborted(participant)?;
            if dtx.all_aborted() {
                dtx.state = DtxState::Aborted;
                inner.stats.total_aborted += 1;
                inner.stats.active_transactions =
                    inner.stats.active_transactions.saturating_sub(1);
                inner.completed_log.push((dtx_id, DtxState::Aborted));
                if inner.completed_log.len() > inner.max_completed_log {
                    inner.completed_log.remove(0);
                }
                return Ok(Some(DtxState::Aborted));
            }
        }

        Ok(None)
    }

    /// Check for timed-out transactions and abort them.
    pub fn check_timeouts(&self) -> Vec<(DtxId, DtxMessage)> {
        let mut inner = self.inner.lock().unwrap();
        let mut aborts = Vec::new();

        let timed_out: Vec<DtxId> = inner
            .transactions
            .iter()
            .filter(|(_, dtx)| {
                dtx.phase_timed_out()
                    && !matches!(
                        dtx.state,
                        DtxState::Committed | DtxState::Aborted
                    )
            })
            .map(|(&id, _)| id)
            .collect();

        for dtx_id in timed_out {
            if let Some(dtx) = inner.transactions.get_mut(&dtx_id) {
                dtx.state = DtxState::Aborting;
                dtx.decision_log
                    .push(format!("DTX-{}: TIMEOUT in state {}", dtx_id, dtx.state));
                inner.stats.total_timeouts += 1;
                aborts.push((
                    dtx_id,
                    DtxMessage::Abort {
                        dtx_id,
                        reason: "coordinator timeout".to_string(),
                    },
                ));
            }
        }

        aborts
    }

    /// Get the current state of a distributed transaction.
    pub fn get_state(&self, dtx_id: DtxId) -> Option<DtxState> {
        let inner = self.inner.lock().unwrap();
        inner.transactions.get(&dtx_id).map(|dtx| dtx.state)
    }

    /// Get the decision log for a transaction.
    pub fn get_decision_log(&self, dtx_id: DtxId) -> Option<Vec<String>> {
        let inner = self.inner.lock().unwrap();
        inner
            .transactions
            .get(&dtx_id)
            .map(|dtx| dtx.decision_log.clone())
    }

    /// Get coordinator statistics.
    pub fn stats(&self) -> DtxStats {
        let inner = self.inner.lock().unwrap();
        inner.stats.clone()
    }

    /// Remove a completed transaction from active tracking.
    pub fn cleanup(&self, dtx_id: DtxId) -> bool {
        let mut inner = self.inner.lock().unwrap();
        inner.transactions.remove(&dtx_id).is_some()
    }
}

impl Default for DtxCoordinator {
    fn default() -> Self {
        Self::new()
    }
}

/// Participant-side handler for distributed transactions.
///
/// Each node runs a `DtxParticipant` that processes incoming 2PC messages
/// and manages local transaction state.
pub struct DtxParticipant {
    inner: Mutex<ParticipantInner>,
}

struct ParticipantInner {
    /// This participant's ID.
    node_id: ParticipantId,
    /// Prepared (but not yet committed) transactions: dtx_id → SQL.
    prepared: HashMap<DtxId, PreparedTransaction>,
    /// Statistics.
    stats: ParticipantStats,
}

/// A locally-prepared distributed transaction (awaiting commit/abort).
#[derive(Debug, Clone)]
pub struct PreparedTransaction {
    pub dtx_id: DtxId,
    pub sql: String,
    pub prepared_at: Instant,
    /// Whether the local execution succeeded (used for vote decision).
    pub local_ok: bool,
    /// Local error message if execution failed.
    pub local_error: Option<String>,
}

/// Participant statistics.
#[derive(Debug, Clone, Default)]
pub struct ParticipantStats {
    pub total_prepares: u64,
    pub total_commits: u64,
    pub total_aborts: u64,
    pub active_prepared: usize,
}

impl DtxParticipant {
    /// Create a new participant.
    pub fn new(node_id: ParticipantId) -> Self {
        Self {
            inner: Mutex::new(ParticipantInner {
                node_id,
                prepared: HashMap::new(),
                stats: ParticipantStats::default(),
            }),
        }
    }

    /// Handle a PREPARE message.
    ///
    /// Executes the SQL locally in a "prepare" mode (BEGIN + execute but don't commit).
    /// Returns a VoteResult message.
    ///
    /// `local_execute` is called with the SQL to attempt local execution.
    /// It should return `Ok(())` if the participant can commit, or `Err(reason)` if not.
    pub fn handle_prepare<F>(
        &self,
        dtx_id: DtxId,
        sql: String,
        local_execute: F,
    ) -> DtxMessage
    where
        F: FnOnce(&str) -> Result<(), String>,
    {
        let mut inner = self.inner.lock().unwrap();
        inner.stats.total_prepares += 1;

        let result = local_execute(&sql);
        let (vote, reason, local_ok, local_error) = match result {
            Ok(()) => (Vote::Commit, None, true, None),
            Err(e) => (Vote::Abort, Some(e.clone()), false, Some(e)),
        };

        let prepared = PreparedTransaction {
            dtx_id,
            sql,
            prepared_at: Instant::now(),
            local_ok,
            local_error,
        };
        inner.prepared.insert(dtx_id, prepared);
        inner.stats.active_prepared = inner.prepared.len();

        DtxMessage::VoteResult {
            dtx_id,
            participant: inner.node_id,
            vote,
            reason,
        }
    }

    /// Handle a COMMIT message — finalize the local transaction.
    ///
    /// `local_commit` is called to actually commit the prepared transaction.
    pub fn handle_commit<F>(&self, dtx_id: DtxId, local_commit: F) -> DtxMessage
    where
        F: FnOnce(DtxId) -> bool,
    {
        let mut inner = self.inner.lock().unwrap();
        let success = local_commit(dtx_id);
        inner.prepared.remove(&dtx_id);
        inner.stats.total_commits += 1;
        inner.stats.active_prepared = inner.prepared.len();

        DtxMessage::Ack {
            dtx_id,
            participant: inner.node_id,
            success,
        }
    }

    /// Handle an ABORT message — rollback the local transaction.
    ///
    /// `local_abort` is called to rollback the prepared transaction.
    pub fn handle_abort<F>(&self, dtx_id: DtxId, local_abort: F) -> DtxMessage
    where
        F: FnOnce(DtxId) -> bool,
    {
        let mut inner = self.inner.lock().unwrap();
        let success = local_abort(dtx_id);
        inner.prepared.remove(&dtx_id);
        inner.stats.total_aborts += 1;
        inner.stats.active_prepared = inner.prepared.len();

        DtxMessage::Ack {
            dtx_id,
            participant: inner.node_id,
            success,
        }
    }

    /// Handle a PRE_COMMIT message (3PC).
    pub fn handle_pre_commit(&self, dtx_id: DtxId) -> DtxMessage {
        let inner = self.inner.lock().unwrap();
        DtxMessage::PreCommitAck {
            dtx_id,
            participant: inner.node_id,
        }
    }

    /// Get participant statistics.
    pub fn stats(&self) -> ParticipantStats {
        let inner = self.inner.lock().unwrap();
        inner.stats.clone()
    }

    /// Get the node ID.
    pub fn node_id(&self) -> ParticipantId {
        let inner = self.inner.lock().unwrap();
        inner.node_id
    }

    /// Check if a transaction is currently prepared.
    pub fn is_prepared(&self, dtx_id: DtxId) -> bool {
        let inner = self.inner.lock().unwrap();
        inner.prepared.contains_key(&dtx_id)
    }

    /// Get the number of currently prepared transactions.
    pub fn prepared_count(&self) -> usize {
        let inner = self.inner.lock().unwrap();
        inner.prepared.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_2pc_happy_path() {
        let coord = DtxCoordinator::new();
        let p1 = DtxParticipant::new(1);
        let p2 = DtxParticipant::new(2);

        // Begin distributed transaction
        let (dtx_id, prepare_msgs) = coord.begin(
            "INSERT INTO t VALUES (1)".to_string(),
            vec![1, 2],
            false, // 2PC
            Duration::from_secs(5),
        );
        assert_eq!(prepare_msgs.len(), 2);
        assert_eq!(coord.get_state(dtx_id), Some(DtxState::Init));

        // Participants handle PREPARE
        let vote1 = p1.handle_prepare(dtx_id, "INSERT INTO t VALUES (1)".to_string(), |_| Ok(()));
        let vote2 = p2.handle_prepare(dtx_id, "INSERT INTO t VALUES (1)".to_string(), |_| Ok(()));

        // Process votes
        match vote1 {
            DtxMessage::VoteResult { vote, participant, .. } => {
                assert_eq!(vote, Vote::Commit);
                let msgs = coord.process_vote(dtx_id, participant, vote, None).unwrap();
                assert!(msgs.is_empty()); // still waiting for p2
            }
            _ => panic!("expected VoteResult"),
        }
        match vote2 {
            DtxMessage::VoteResult { vote, participant, .. } => {
                assert_eq!(vote, Vote::Commit);
                let msgs = coord.process_vote(dtx_id, participant, vote, None).unwrap();
                // All voted commit — should get COMMIT message
                assert_eq!(msgs.len(), 1);
                assert!(matches!(msgs[0], DtxMessage::Commit { .. }));
            }
            _ => panic!("expected VoteResult"),
        }

        assert_eq!(coord.get_state(dtx_id), Some(DtxState::Committing));

        // Participants handle COMMIT
        let ack1 = p1.handle_commit(dtx_id, |_| true);
        let ack2 = p2.handle_commit(dtx_id, |_| true);

        match ack1 {
            DtxMessage::Ack { participant, success, .. } => {
                assert!(success);
                let result = coord.process_ack(dtx_id, participant, true).unwrap();
                assert_eq!(result, None); // still waiting for p2
            }
            _ => panic!("expected Ack"),
        }
        match ack2 {
            DtxMessage::Ack { participant, success, .. } => {
                assert!(success);
                let result = coord.process_ack(dtx_id, participant, true).unwrap();
                assert_eq!(result, Some(DtxState::Committed));
            }
            _ => panic!("expected Ack"),
        }

        let stats = coord.stats();
        assert_eq!(stats.total_committed, 1);
        assert_eq!(stats.total_aborted, 0);
    }

    #[test]
    fn test_2pc_abort_on_vote() {
        let coord = DtxCoordinator::new();
        let p1 = DtxParticipant::new(1);
        let p2 = DtxParticipant::new(2);

        let (dtx_id, _) = coord.begin(
            "INSERT INTO t VALUES (1)".to_string(),
            vec![1, 2],
            false,
            Duration::from_secs(5),
        );

        // p1 votes commit, p2 votes abort
        let _vote1 = p1.handle_prepare(dtx_id, "sql".to_string(), |_| Ok(()));
        let vote2 = p2.handle_prepare(dtx_id, "sql".to_string(), |_| {
            Err("constraint violation".to_string())
        });

        coord.process_vote(dtx_id, 1, Vote::Commit, None).unwrap();

        match vote2 {
            DtxMessage::VoteResult { vote, participant, reason, .. } => {
                assert_eq!(vote, Vote::Abort);
                let msgs = coord.process_vote(dtx_id, participant, vote, reason).unwrap();
                assert_eq!(msgs.len(), 1);
                assert!(matches!(msgs[0], DtxMessage::Abort { .. }));
            }
            _ => panic!("expected VoteResult"),
        }

        assert_eq!(coord.get_state(dtx_id), Some(DtxState::Aborting));

        // Process abort acks
        let ack1 = p1.handle_abort(dtx_id, |_| true);
        let ack2 = p2.handle_abort(dtx_id, |_| true);

        if let DtxMessage::Ack { participant, .. } = ack1 {
            coord.process_ack(dtx_id, participant, false).unwrap();
        }
        if let DtxMessage::Ack { participant, .. } = ack2 {
            let result = coord.process_ack(dtx_id, participant, false).unwrap();
            assert_eq!(result, Some(DtxState::Aborted));
        }

        let stats = coord.stats();
        assert_eq!(stats.total_aborted, 1);
    }

    #[test]
    fn test_3pc_happy_path() {
        let coord = DtxCoordinator::new();
        let p1 = DtxParticipant::new(1);
        let p2 = DtxParticipant::new(2);

        let (dtx_id, _) = coord.begin(
            "UPDATE t SET v=1".to_string(),
            vec![1, 2],
            true, // 3PC
            Duration::from_secs(5),
        );

        // Both vote commit
        p1.handle_prepare(dtx_id, "sql".to_string(), |_| Ok(()));
        p2.handle_prepare(dtx_id, "sql".to_string(), |_| Ok(()));

        coord.process_vote(dtx_id, 1, Vote::Commit, None).unwrap();
        let msgs = coord.process_vote(dtx_id, 2, Vote::Commit, None).unwrap();
        // Should get PreCommit message (3PC)
        assert_eq!(msgs.len(), 1);
        assert!(matches!(msgs[0], DtxMessage::PreCommit { .. }));
        assert_eq!(coord.get_state(dtx_id), Some(DtxState::PreCommitted));

        // Pre-commit acks
        let pc_ack1 = p1.handle_pre_commit(dtx_id);
        let pc_ack2 = p2.handle_pre_commit(dtx_id);

        if let DtxMessage::PreCommitAck { participant, .. } = pc_ack1 {
            let msgs = coord.process_pre_commit_ack(dtx_id, participant).unwrap();
            assert!(msgs.is_empty());
        }
        if let DtxMessage::PreCommitAck { participant, .. } = pc_ack2 {
            let msgs = coord.process_pre_commit_ack(dtx_id, participant).unwrap();
            assert_eq!(msgs.len(), 1);
            assert!(matches!(msgs[0], DtxMessage::Commit { .. }));
        }

        assert_eq!(coord.get_state(dtx_id), Some(DtxState::Committing));

        // Final commit acks
        let ack1 = p1.handle_commit(dtx_id, |_| true);
        let ack2 = p2.handle_commit(dtx_id, |_| true);
        if let DtxMessage::Ack { participant, .. } = ack1 {
            coord.process_ack(dtx_id, participant, true).unwrap();
        }
        if let DtxMessage::Ack { participant, .. } = ack2 {
            let result = coord.process_ack(dtx_id, participant, true).unwrap();
            assert_eq!(result, Some(DtxState::Committed));
        }
    }

    #[test]
    fn test_coordinator_timeout() {
        let coord = DtxCoordinator::new();

        let (dtx_id, _) = coord.begin(
            "sql".to_string(),
            vec![1, 2],
            false,
            Duration::from_millis(1), // immediate timeout
        );

        // Wait for timeout
        std::thread::sleep(Duration::from_millis(5));

        let timeouts = coord.check_timeouts();
        assert!(!timeouts.is_empty());
        assert_eq!(timeouts[0].0, dtx_id);
        assert!(matches!(timeouts[0].1, DtxMessage::Abort { .. }));

        let stats = coord.stats();
        assert_eq!(stats.total_timeouts, 1);
    }

    #[test]
    fn test_participant_state_tracking() {
        let p = DtxParticipant::new(42);
        assert_eq!(p.node_id(), 42);
        assert_eq!(p.prepared_count(), 0);

        p.handle_prepare(1, "sql".to_string(), |_| Ok(()));
        assert!(p.is_prepared(1));
        assert_eq!(p.prepared_count(), 1);

        p.handle_commit(1, |_| true);
        assert!(!p.is_prepared(1));
        assert_eq!(p.prepared_count(), 0);

        let stats = p.stats();
        assert_eq!(stats.total_prepares, 1);
        assert_eq!(stats.total_commits, 1);
    }

    #[test]
    fn test_coordinator_cleanup() {
        let coord = DtxCoordinator::new();
        let (dtx_id, _) = coord.begin("sql".to_string(), vec![1], false, Duration::from_secs(5));
        assert!(coord.get_state(dtx_id).is_some());
        assert!(coord.cleanup(dtx_id));
        assert!(coord.get_state(dtx_id).is_none());
        assert!(!coord.cleanup(999));
    }

    #[test]
    fn test_decision_log() {
        let coord = DtxCoordinator::new();
        let (dtx_id, _) = coord.begin("sql".to_string(), vec![1], false, Duration::from_secs(5));

        let log = coord.get_decision_log(dtx_id).unwrap();
        assert!(!log.is_empty());
        assert!(log[0].contains("created"));

        coord.process_vote(dtx_id, 1, Vote::Commit, None).unwrap();
        let log = coord.get_decision_log(dtx_id).unwrap();
        assert!(log.len() >= 2);
    }

    #[test]
    fn test_dtx_state_display() {
        assert_eq!(format!("{}", DtxState::Init), "INIT");
        assert_eq!(format!("{}", DtxState::Preparing), "PREPARING");
        assert_eq!(format!("{}", DtxState::PreCommitted), "PRE_COMMITTED");
        assert_eq!(format!("{}", DtxState::Committing), "COMMITTING");
        assert_eq!(format!("{}", DtxState::Aborting), "ABORTING");
        assert_eq!(format!("{}", DtxState::Committed), "COMMITTED");
        assert_eq!(format!("{}", DtxState::Aborted), "ABORTED");
    }

    #[test]
    fn test_duplicate_vote_error() {
        let coord = DtxCoordinator::new();
        let (dtx_id, _) = coord.begin("sql".to_string(), vec![1, 2], false, Duration::from_secs(5));

        coord.process_vote(dtx_id, 1, Vote::Commit, None).unwrap();
        let result = coord.process_vote(dtx_id, 1, Vote::Commit, None);
        assert!(result.is_err());
    }

    #[test]
    fn test_unknown_participant_error() {
        let coord = DtxCoordinator::new();
        let (dtx_id, _) = coord.begin("sql".to_string(), vec![1], false, Duration::from_secs(5));

        let result = coord.process_vote(dtx_id, 999, Vote::Commit, None);
        assert!(result.is_err());
    }

    #[test]
    fn test_participant_abort_handler() {
        let p = DtxParticipant::new(1);
        p.handle_prepare(1, "sql".to_string(), |_| Ok(()));
        let ack = p.handle_abort(1, |_| true);
        assert!(matches!(ack, DtxMessage::Ack { success: true, .. }));
        assert!(!p.is_prepared(1));
        let stats = p.stats();
        assert_eq!(stats.total_aborts, 1);
    }

    #[test]
    fn test_coordinator_default() {
        let coord = DtxCoordinator::default();
        let stats = coord.stats();
        assert_eq!(stats.total_transactions, 0);
    }
}

//! HTTP-based Raft network client for KKDB (Phase 2, cross-process).
//!
//! `HttpNetworkFactory` implements `RaftNetworkFactory` using `reqwest` to
//! POST JSON to the target node's `/raft/*` endpoints.

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use openraft::{
    error::{InstallSnapshotError, RPCError, RaftError, Unreachable},
    network::{RPCOption, RaftNetwork, RaftNetworkFactory},
    raft::{
        AppendEntriesRequest, AppendEntriesResponse, InstallSnapshotRequest,
        InstallSnapshotResponse, VoteRequest, VoteResponse,
    },
    BasicNode,
};
use serde::de::DeserializeOwned;
use serde::Serialize;

use crate::raft::types::{KkdbNodeId, KkdbTypeConfig};

// ─── Address registry ─────────────────────────────────────────────────────────

/// Maps each node_id → that node's Raft HTTP base URL (e.g. "http://127.0.0.1:7001")
pub type AddrRegistry = Arc<Mutex<BTreeMap<KkdbNodeId, String>>>;

// ─── Factory ──────────────────────────────────────────────────────────────────

/// HTTP-based Raft network factory.
#[derive(Clone)]
pub struct HttpNetworkFactory {
    pub addresses: AddrRegistry,
    pub client: reqwest::Client,
}

impl HttpNetworkFactory {
    /// `addresses` maps node_id → "http://host:port" for all known peers.
    pub fn new(addresses: AddrRegistry) -> Self {
        let client = reqwest::Client::builder()
            .timeout(Duration::from_secs(5))
            .build()
            .expect("build reqwest client");
        Self { addresses, client }
    }
}

impl RaftNetworkFactory<KkdbTypeConfig> for HttpNetworkFactory {
    type Network = HttpNetwork;

    async fn new_client(&mut self, target: KkdbNodeId, node: &BasicNode) -> Self::Network {
        // Prefer the address from our registry; fall back to node.addr
        let base = {
            let reg = self.addresses.lock().unwrap();
            reg.get(&target)
                .cloned()
                .unwrap_or_else(|| format!("http://{}", node.addr))
        };
        HttpNetwork {
            target,
            base_url: base,
            client: self.client.clone(),
        }
    }
}

// ─── Per-peer HTTP connection ─────────────────────────────────────────────────

/// One HTTP connection to a single peer node.
pub struct HttpNetwork {
    pub target: KkdbNodeId,
    pub base_url: String,
    pub client: reqwest::Client,
}

impl HttpNetwork {
    /// POST `body` to `{base_url}{path}` and deserialize `R` from the response.
    async fn post<B, R>(&self, path: &str, body: &B) -> Result<R, Unreachable>
    where
        B: Serialize,
        R: DeserializeOwned,
    {
        let url = format!("{}{}", self.base_url, path);
        let resp = self
            .client
            .post(&url)
            .json(body)
            .send()
            .await
            .map_err(|e| {
                Unreachable::new(&std::io::Error::new(
                    std::io::ErrorKind::ConnectionRefused,
                    e.to_string(),
                ))
            })?;

        resp.json::<R>().await.map_err(|e| {
            Unreachable::new(&std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                e.to_string(),
            ))
        })
    }
}

impl RaftNetwork<KkdbTypeConfig> for HttpNetwork {
    async fn append_entries(
        &mut self,
        rpc: AppendEntriesRequest<KkdbTypeConfig>,
        _option: RPCOption,
    ) -> Result<
        AppendEntriesResponse<KkdbNodeId>,
        RPCError<KkdbNodeId, BasicNode, RaftError<KkdbNodeId>>,
    > {
        self.post("/raft/append-entries", &rpc)
            .await
            .map_err(RPCError::Unreachable)
    }

    async fn vote(
        &mut self,
        rpc: VoteRequest<KkdbNodeId>,
        _option: RPCOption,
    ) -> Result<VoteResponse<KkdbNodeId>, RPCError<KkdbNodeId, BasicNode, RaftError<KkdbNodeId>>>
    {
        self.post("/raft/vote", &rpc)
            .await
            .map_err(RPCError::Unreachable)
    }

    async fn install_snapshot(
        &mut self,
        rpc: InstallSnapshotRequest<KkdbTypeConfig>,
        _option: RPCOption,
    ) -> Result<
        InstallSnapshotResponse<KkdbNodeId>,
        RPCError<KkdbNodeId, BasicNode, RaftError<KkdbNodeId, InstallSnapshotError>>,
    > {
        self.post("/raft/install-snapshot", &rpc)
            .await
            .map_err(RPCError::Unreachable)
    }
}

//! HTTP JSON-RPC transport for KKDB Raft (Phase 2, cross-process).
//!
//! Replaces the in-memory channel transport with real HTTP calls so that
//! individual KKDB nodes can run in separate processes (or on separate hosts).
//!
//! ## Endpoints
//!
//! | Method | Path                          | Description                      |
//! |--------|-------------------------------|----------------------------------|
//! | POST   | `/raft/append-entries`        | AppendEntriesRequest (internal)  |
//! | POST   | `/raft/vote`                  | VoteRequest (internal)           |
//! | POST   | `/raft/install-snapshot`      | InstallSnapshotRequest (internal)|
//! | POST   | `/raft/init`                  | Cluster bootstrap                |
//! | POST   | `/raft/add-learner`           | Add a new learner node           |
//! | POST   | `/raft/change-membership`     | Promote / demote nodes           |
//! | POST   | `/raft/status`                | Basic status (legacy)            |
//! | GET    | `/raft/metrics`               | Rich JSON cluster metrics        |
//! | GET    | `/raft/metrics/prometheus`    | Prometheus text exposition       |

use std::collections::BTreeMap;
use std::sync::Arc;

use axum::{
    extract::{Query, State},
    http::{header, StatusCode},
    response::IntoResponse,
    routing::{get, post},
    Json, Router,
};
use openraft::BasicNode;
use serde::{Deserialize, Serialize};

use crate::binlog::BinlogBroadcaster;
use crate::raft::log_store::KkdbLogStore;
use crate::raft::node::KkdbNode;
use crate::raft::types::{KkdbNodeId, KkdbTypeConfig};

// ─── Shared state for the Raft HTTP server ────────────────────────────────────

/// State injected into every Raft RPC handler.
#[derive(Clone)]
pub struct RaftApiState {
    pub node: Arc<KkdbNode>,
    /// WAL log store — for compaction stats in metrics endpoint.
    pub log_store: Option<KkdbLogStore>,
    /// Binlog broadcaster — for `/binlog/stream` replication endpoint.
    pub binlog: Option<BinlogBroadcaster>,
}

// ─── Request / response helpers ───────────────────────────────────────────────

/// Payload for /raft/init: map of node_id → addr
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InitRequest {
    /// e.g. { "1": "127.0.0.1:7001", "2": "127.0.0.1:7002" }
    pub nodes: BTreeMap<KkdbNodeId, String>,
}

/// Payload for /raft/add-learner and /raft/change-membership
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MembershipRequest {
    pub node_id: KkdbNodeId,
    pub addr: Option<String>,
    /// For change-membership: if true, retain existing voters; if false replace
    pub retain: Option<bool>,
}

// ─── Rich metrics types ───────────────────────────────────────────────────────

/// Full JSON metrics snapshot for GET /raft/metrics.
#[derive(Debug, Serialize)]
pub struct RaftMetricsJson {
    pub node_id: KkdbNodeId,
    pub role: String,
    pub current_leader: Option<KkdbNodeId>,
    pub current_term: u64,
    pub last_log_index: Option<u64>,
    pub last_applied_index: Option<u64>,
    pub snapshot_last_log_index: Option<u64>,
    pub membership_voter_ids: Vec<KkdbNodeId>,
    pub wal: WalMetrics,
}

/// WAL compaction diagnostics.
#[derive(Debug, Serialize)]
pub struct WalMetrics {
    pub live_records: u64,
    pub total_records: u64,
    pub dead_records: u64,
    pub compaction_ratio_pct: u64,
}

// ─── Internal helper: build metrics snapshot ─────────────────────────────────

fn build_metrics_json(s: &RaftApiState) -> RaftMetricsJson {
    let m = s.node.metrics();

    let role = if m.current_leader == Some(s.node.id) {
        "Leader"
    } else if m.current_leader.is_some() {
        "Follower"
    } else {
        "Candidate"
    }
    .to_string();

    let membership_voter_ids = m
        .membership_config
        .membership()
        .voter_ids()
        .collect::<Vec<_>>();

    let last_log_index = m.last_log_index;
    let last_applied_index = m.last_applied.map(|l| l.index);
    let snapshot_last_log_index = m.snapshot.as_ref().map(|s| s.index);

    // WAL compaction stats
    let wal = if let Some(ref store) = s.log_store {
        let (live, total, dead) = store.compaction_stats();
        let ratio = if total > 0 { dead * 100 / total } else { 0 };
        WalMetrics {
            live_records: live,
            total_records: total,
            dead_records: dead,
            compaction_ratio_pct: ratio,
        }
    } else {
        WalMetrics {
            live_records: 0,
            total_records: 0,
            dead_records: 0,
            compaction_ratio_pct: 0,
        }
    };

    RaftMetricsJson {
        node_id: s.node.id,
        role,
        current_leader: m.current_leader,
        current_term: m.current_term,
        last_log_index,
        last_applied_index,
        snapshot_last_log_index,
        membership_voter_ids,
        wal,
    }
}

/// Render a metrics snapshot as Prometheus text exposition format.
fn render_prometheus(metrics: &RaftMetricsJson) -> String {
    let mut out = String::with_capacity(1024);

    let push = |out: &mut String, name: &str, help: &str, typ: &str, value: u64| {
        out.push_str(&format!("# HELP kkdb_{name} {help}\n"));
        out.push_str(&format!("# TYPE kkdb_{name} {typ}\n"));
        out.push_str(&format!(
            "kkdb_{name}{{node=\"{}\"}} {value}\n\n",
            metrics.node_id
        ));
    };

    push(
        &mut out,
        "raft_is_leader",
        "1 if this node is the current Raft leader, 0 otherwise",
        "gauge",
        if metrics.current_leader == Some(metrics.node_id) {
            1
        } else {
            0
        },
    );
    push(
        &mut out,
        "raft_current_term",
        "Current Raft term",
        "gauge",
        metrics.current_term,
    );
    push(
        &mut out,
        "raft_last_log_index",
        "Index of the last log entry",
        "gauge",
        metrics.last_log_index.unwrap_or(0),
    );
    push(
        &mut out,
        "raft_last_applied_index",
        "Index of the last log entry applied to the state machine",
        "gauge",
        metrics.last_applied_index.unwrap_or(0),
    );
    push(
        &mut out,
        "raft_snapshot_last_log_index",
        "Last log index covered by the most recent snapshot",
        "gauge",
        metrics.snapshot_last_log_index.unwrap_or(0),
    );
    push(
        &mut out,
        "wal_live_records",
        "Live log entries currently in the WAL",
        "gauge",
        metrics.wal.live_records,
    );
    push(
        &mut out,
        "wal_total_records",
        "Total records ever written to the WAL (live + dead)",
        "counter",
        metrics.wal.total_records,
    );
    push(
        &mut out,
        "wal_dead_records",
        "Dead records in the WAL eligible for compaction",
        "gauge",
        metrics.wal.dead_records,
    );
    push(
        &mut out,
        "wal_compaction_ratio_pct",
        "Percentage of WAL records that are dead (0-100)",
        "gauge",
        metrics.wal.compaction_ratio_pct,
    );
    push(
        &mut out,
        "membership_voter_count",
        "Number of voting members in the current Raft membership config",
        "gauge",
        metrics.membership_voter_ids.len() as u64,
    );

    out
}

// ─── Raft internal RPC handlers ───────────────────────────────────────────────

async fn append_entries_handler(
    State(s): State<RaftApiState>,
    Json(rpc): Json<openraft::raft::AppendEntriesRequest<KkdbTypeConfig>>,
) -> impl IntoResponse {
    match s.node.raft.append_entries(rpc).await {
        Ok(resp) => (StatusCode::OK, Json(serde_json::to_value(resp)
            .unwrap_or_else(|e| serde_json::json!({ "error": format!("serialize: {e}") })))),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({ "error": e.to_string() })),
        ),
    }
}

async fn vote_handler(
    State(s): State<RaftApiState>,
    Json(rpc): Json<openraft::raft::VoteRequest<KkdbNodeId>>,
) -> impl IntoResponse {
    match s.node.raft.vote(rpc).await {
        Ok(resp) => (StatusCode::OK, Json(serde_json::to_value(resp)
            .unwrap_or_else(|e| serde_json::json!({ "error": format!("serialize: {e}") })))),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({ "error": e.to_string() })),
        ),
    }
}

async fn install_snapshot_handler(
    State(s): State<RaftApiState>,
    Json(rpc): Json<openraft::raft::InstallSnapshotRequest<KkdbTypeConfig>>,
) -> impl IntoResponse {
    match s.node.raft.install_snapshot(rpc).await {
        Ok(resp) => (StatusCode::OK, Json(serde_json::to_value(resp)
            .unwrap_or_else(|e| serde_json::json!({ "error": format!("serialize: {e}") })))),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({ "error": e.to_string() })),
        ),
    }
}

// ─── Cluster admin handlers ───────────────────────────────────────────────────

async fn init_handler(
    State(s): State<RaftApiState>,
    Json(req): Json<InitRequest>,
) -> impl IntoResponse {
    let members: BTreeMap<KkdbNodeId, BasicNode> = req
        .nodes
        .into_iter()
        .map(|(id, addr)| (id, BasicNode { addr }))
        .collect();
    match s.node.init_with_members(members).await {
        Ok(_) => (StatusCode::OK, Json(serde_json::json!({ "ok": true }))),
        Err(e) => (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({ "error": e.to_string() })),
        ),
    }
}

async fn add_learner_handler(
    State(s): State<RaftApiState>,
    Json(req): Json<MembershipRequest>,
) -> impl IntoResponse {
    let node_info = BasicNode {
        addr: req.addr.unwrap_or_default(),
    };
    match s.node.raft.add_learner(req.node_id, node_info, true).await {
        Ok(resp) => (StatusCode::OK, Json(serde_json::to_value(resp)
            .unwrap_or_else(|e| serde_json::json!({ "error": format!("serialize: {e}") })))),
        Err(e) => (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({ "error": e.to_string() })),
        ),
    }
}

async fn change_membership_handler(
    State(s): State<RaftApiState>,
    Json(req): Json<MembershipRequest>,
) -> impl IntoResponse {
    let retain = req.retain.unwrap_or(true);
    let mut voters = std::collections::BTreeSet::new();
    voters.insert(req.node_id);
    match s.node.raft.change_membership(voters, retain).await {
        Ok(resp) => (StatusCode::OK, Json(serde_json::to_value(resp)
            .unwrap_or_else(|e| serde_json::json!({ "error": format!("serialize: {e}") })))),
        Err(e) => (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({ "error": e.to_string() })),
        ),
    }
}

/// Legacy POST /raft/status (kept for backward compat)
async fn status_handler(State(s): State<RaftApiState>) -> impl IntoResponse {
    let m = s.node.metrics();
    (
        StatusCode::OK,
        Json(serde_json::json!({
            "node_id": s.node.id,
            "leader":  m.current_leader,
            "term":    m.current_term,
            "last_log_index": m.last_log_index,
            "last_applied":   m.last_applied,
            "is_leader": s.node.is_leader(),
        })),
    )
}

// ─── Monitoring endpoints ─────────────────────────────────────────────────────

/// GET /raft/metrics — rich JSON cluster + WAL metrics.
async fn metrics_json_handler(State(s): State<RaftApiState>) -> impl IntoResponse {
    let metrics = build_metrics_json(&s);
    (StatusCode::OK, Json(metrics))
}

/// GET /raft/metrics/prometheus — Prometheus text exposition format.
async fn metrics_prometheus_handler(State(s): State<RaftApiState>) -> impl IntoResponse {
    let metrics = build_metrics_json(&s);
    let body = render_prometheus(&metrics);
    (
        StatusCode::OK,
        [(
            header::CONTENT_TYPE,
            "text/plain; version=0.0.4; charset=utf-8",
        )],
        body,
    )
}

// ─── Binlog streaming handler ─────────────────────────────────────────────────

/// Query params for GET /binlog/stream
#[derive(Debug, Deserialize)]
struct BinlogStreamParams {
    /// Byte offset to start reading from (default = 0 = full history).
    #[serde(default)]
    from_pos: u64,
}

/// GET /binlog/stream?from_pos=N
///
/// Returns all binlog records from byte offset `from_pos` onwards as NDJSON.
/// Each line is a JSON object: `{"pos": <u64>, "data": "<base64>"}` where:
/// - `pos`  is the byte offset *after* this record (use as the next `from_pos`).
/// - `data` is base64-encoded framed bytes: `[len:u32 LE][crc32:u32 LE][payload]`.
///
/// Consumers should poll this endpoint (long-polling or periodic pull) and
/// advance `from_pos` each time. A `pos == 0` response means no new data.
async fn binlog_stream_handler(
    State(s): State<RaftApiState>,
    Query(params): Query<BinlogStreamParams>,
) -> impl IntoResponse {
    let Some(ref broadcaster) = s.binlog else {
        return (
            StatusCode::SERVICE_UNAVAILABLE,
            [(header::CONTENT_TYPE, "application/x-ndjson")],
            "{\"error\":\"binlog not enabled on this node\"}".to_string(),
        );
    };

    let mgr = broadcaster.manager.lock().unwrap();
    let records = match mgr.read_from(params.from_pos) {
        Ok(r) => r,
        Err(e) => {
            drop(mgr);
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                [(header::CONTENT_TYPE, "application/x-ndjson")],
                format!("{{\"error\":\"{}\"}}", e),
            );
        }
    };
    drop(mgr);

    // Serialize each (next_pos, framed_bytes) as one NDJSON line
    let mut body = String::new();
    for (next_pos, framed) in records {
        let data_b64 = crate::binlog::base64_encode(&framed);
        body.push_str(&format!(
            "{{\"pos\":{next_pos},\"data\":\"{data_b64}\"}}
"
        ));
    }

    (
        StatusCode::OK,
        [(header::CONTENT_TYPE, "application/x-ndjson")],
        body,
    )
}

// ─── Router builder ───────────────────────────────────────────────────────────

/// Build the Raft-internal HTTP router for a node.
/// Mount this on a separate port (e.g. 7001) from the REST API port.
///
/// Pass `log_store` to enable WAL compaction stats in the metrics endpoint.
pub fn build_raft_router(node: Arc<KkdbNode>) -> Router {
    build_raft_router_with_store(node, None, None)
}

pub fn build_raft_router_with_store(
    node: Arc<KkdbNode>,
    log_store: Option<KkdbLogStore>,
    binlog: Option<BinlogBroadcaster>,
) -> Router {
    let state = RaftApiState {
        node,
        log_store,
        binlog,
    };
    Router::new()
        // Internal Raft RPCs (called by other nodes)
        .route("/raft/append-entries", post(append_entries_handler))
        .route("/raft/vote", post(vote_handler))
        .route("/raft/install-snapshot", post(install_snapshot_handler))
        // Cluster admin
        .route("/raft/init", post(init_handler))
        .route("/raft/add-learner", post(add_learner_handler))
        .route("/raft/change-membership", post(change_membership_handler))
        .route("/raft/status", post(status_handler))
        // Monitoring
        .route("/raft/metrics", get(metrics_json_handler))
        .route("/raft/metrics/prometheus", get(metrics_prometheus_handler))
        // Binlog streaming (pull replication)
        .route("/binlog/stream", get(binlog_stream_handler))
        .with_state(state)
}

//! Persistent WAL-backed Raft log storage for KKDB.
//!
//! ## File layout
//!
//! ```text
//! {dir}/raft/
//!   wal.log       — append-only log of entries (CRC32-protected records)
//!   vote.json     — persisted Vote (overwritten on each save)
//!   purge.json    — persisted last_purged_log_id
//! ```
//!
//! ## WAL record format
//!
//! Each record is:
//!   [4 bytes LE: payload_len] [payload_len bytes: JSON] [4 bytes LE: crc32]
//!
//! On startup every record is replayed to rebuild the in-memory BTreeMap.
//! `truncate` / `purge` are done by:
//!   - `truncate` → re-writing the WAL without the truncated entries
//!   - `purge`    → dropping entries from memory + updating purge.json
//!     (WAL compaction happens on next restart via replay-then-rewrite)

use std::collections::BTreeMap;
use std::fmt::Debug;
use std::fs::{self, File, OpenOptions};
use std::io::{self, BufReader, BufWriter, Read, Write};
use std::ops::RangeBounds;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

use openraft::{
    storage::{LogFlushed, RaftLogStorage},
    Entry, LogId, LogState, OptionalSend, RaftLogReader, StorageError, StorageIOError, Vote,
};
use serde::{Deserialize, Serialize};

use crate::raft::types::{KkdbNodeId, KkdbTypeConfig};

// ─── WAL helpers ──────────────────────────────────────────────────────────────

/// Compute crc32 of a byte slice.
fn crc32(data: &[u8]) -> u32 {
    let mut c: u32 = 0xffff_ffff;
    for &b in data {
        c ^= b as u32;
        for _ in 0..8 {
            if c & 1 != 0 {
                c = (c >> 1) ^ 0xEDB8_8320;
            } else {
                c >>= 1;
            }
        }
    }
    !c
}

fn write_record(w: &mut impl Write, payload: &[u8]) -> io::Result<()> {
    let len = payload.len() as u32;
    w.write_all(&len.to_le_bytes())?;
    w.write_all(payload)?;
    w.write_all(&crc32(payload).to_le_bytes())?;
    Ok(())
}

fn read_record(r: &mut impl Read) -> io::Result<Option<Vec<u8>>> {
    let mut len_buf = [0u8; 4];
    match r.read_exact(&mut len_buf) {
        Ok(_) => {}
        Err(e) if e.kind() == io::ErrorKind::UnexpectedEof => return Ok(None),
        Err(e) => return Err(e),
    }
    let len = u32::from_le_bytes(len_buf) as usize;
    let mut payload = vec![0u8; len];
    r.read_exact(&mut payload)?;
    let mut crc_buf = [0u8; 4];
    r.read_exact(&mut crc_buf)?;
    let recorded = u32::from_le_bytes(crc_buf);
    if crc32(&payload) != recorded {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "WAL CRC mismatch",
        ));
    }
    Ok(Some(payload))
}

// ─── Inner data ───────────────────────────────────────────────────────────────

#[derive(Default)]
pub struct KkdbLogStoreInner {
    pub last_purged_log_id: Option<LogId<KkdbNodeId>>,
    /// In-memory cache of unpurged log entries.
    pub log: BTreeMap<u64, Entry<KkdbTypeConfig>>,
    pub voted_for: Option<Vote<KkdbNodeId>>,
    /// WAL file (None = in-memory only).
    pub wal_file: Option<PathBuf>,
    /// Total records ever written to WAL (live + dead Truncate/purged Append).
    /// Used to decide when to compact.
    pub total_records: u64,
}


// ─── Public log store ─────────────────────────────────────────────────────────

#[derive(Clone, Default)]
pub struct KkdbLogStore {
    pub inner: Arc<Mutex<KkdbLogStoreInner>>,
}

/// Number of dead records (purged Appends + Truncate markers) in the WAL
/// before an automatic compaction is triggered.
const COMPACT_THRESHOLD: u64 = 1000;

impl KkdbLogStore {
    // ── Persistent constructor ─────────────────────────────────────────────

    /// Open (or create) a WAL-backed log store in `dir`.
    ///
    /// The directory structure created:
    ///   `dir/raft/wal.log`
    ///   `dir/raft/vote.json`
    ///   `dir/raft/purge.json`
    pub fn open(dir: &Path) -> io::Result<Self> {
        let raft_dir = dir.join("raft");
        fs::create_dir_all(&raft_dir)?;

        let wal_path = raft_dir.join("wal.log");
        let vote_path = raft_dir.join("vote.json");
        let purge_path = raft_dir.join("purge.json");

        // Recover vote
        let voted_for: Option<Vote<KkdbNodeId>> = if vote_path.exists() {
            let bytes = fs::read(&vote_path)?;
            serde_json::from_slice(&bytes).ok()
        } else {
            None
        };

        // Recover last_purged_log_id
        let last_purged: Option<LogId<KkdbNodeId>> = if purge_path.exists() {
            let bytes = fs::read(&purge_path)?;
            serde_json::from_slice(&bytes).ok()
        } else {
            None
        };

        // Replay WAL, counting total records for compaction heuristic
        let mut log: BTreeMap<u64, Entry<KkdbTypeConfig>> = BTreeMap::new();
        let mut total_records: u64 = 0;
        if wal_path.exists() {
            let f = File::open(&wal_path)?;
            let mut r = BufReader::new(f);
            loop {
                match read_record(&mut r) {
                    Ok(Some(payload)) => {
                        total_records += 1;
                        match serde_json::from_slice::<WalRecord>(&payload) {
                            Ok(WalRecord::Append(entry)) => {
                                log.insert(entry.log_id.index, entry);
                            }
                            Ok(WalRecord::Truncate { from_index }) => {
                                log.retain(|&k, _| k < from_index);
                            }
                            Err(_) => {} // skip corrupt record
                        }
                    }
                    Ok(None) => break, // EOF
                    Err(_) => break,   // truncated tail — stop, rest is lost
                }
            }
            // Drop purged entries from replay
            if let Some(ref p) = last_purged {
                log.retain(|&k, _| k > p.index);
            }
        }

        let inner = KkdbLogStoreInner {
            last_purged_log_id: last_purged,
            log,
            voted_for,
            wal_file: Some(wal_path),
            total_records,
        };
        Ok(Self {
            inner: Arc::new(Mutex::new(inner)),
        })
    }

    // ── WAL compaction ─────────────────────────────────────────────────────────

    /// Rewrite `wal.log` keeping only entries that are **after**
    /// `last_purged_log_id` (i.e., the currently live in-memory entries).
    ///
    /// The rewrite is atomic: entries are written to `wal.new`, then the file
    /// is renamed over `wal.log`. On crash mid-rename the old WAL is preserved.
    ///
    /// Returns the number of dead records eliminated.
    pub fn compact(&self) -> io::Result<u64> {
        let mut inner = self.inner.lock().unwrap();
        let wal_path = match inner.wal_file {
            Some(ref p) => p.clone(),
            None => return Ok(0), // in-memory mode — nothing to compact
        };

        let live_count = inner.log.len() as u64;
        let dead = inner.total_records.saturating_sub(live_count);
        if dead == 0 {
            return Ok(0);
        }

        // Write only the live entries to a temporary file
        let tmp_path = wal_path.with_extension("new");
        {
            let f = OpenOptions::new()
                .create(true)
                .write(true)
                .truncate(true)
                .open(&tmp_path)?;
            let mut w = BufWriter::new(f);
            for entry in inner.log.values() {
                let rec = WalRecord::Append(entry.clone());
                let payload = serde_json::to_vec(&rec)
                    .map_err(io::Error::other)?;
                write_record(&mut w, &payload)?;
            }
            w.flush()?;
        }

        // Atomic rename
        fs::rename(&tmp_path, &wal_path)?;

        // Reset counter
        inner.total_records = live_count;

        Ok(dead)
    }

    /// Returns (live_records, total_records, dead_records) for diagnostic use.
    pub fn compaction_stats(&self) -> (u64, u64, u64) {
        let inner = self.inner.lock().unwrap();
        let live = inner.log.len() as u64;
        let total = inner.total_records;
        (live, total, total.saturating_sub(live))
    }

    // ── WAL write helpers (must hold the lock) ─────────────────────────────

    fn wal_append(wal_path: &Path, entry: &Entry<KkdbTypeConfig>) -> io::Result<()> {
        let rec = WalRecord::Append(entry.clone());
        let payload =
            serde_json::to_vec(&rec).map_err(io::Error::other)?;
        let mut f = OpenOptions::new()
            .create(true)
            .append(true)
            .open(wal_path)?;
        {
            // Scope BufWriter so it is dropped (and its borrow released) before sync_data().
            let mut w = BufWriter::new(&mut f);
            write_record(&mut w, &payload)?;
            w.flush()?;
        }
        // S6 fix: fsync to guarantee durability before ACK-ing to Raft leader.
        // flush() only moves data to OS page cache; sync_data() ensures it reaches disk.
        f.sync_data()?;
        Ok(())
    }

    fn wal_truncate(wal_path: &Path, from_index: u64) -> io::Result<()> {
        let rec = WalRecord::Truncate { from_index };
        let payload =
            serde_json::to_vec(&rec).map_err(io::Error::other)?;
        let mut f = OpenOptions::new()
            .create(true)
            .append(true)
            .open(wal_path)?;
        {
            let mut w = BufWriter::new(&mut f);
            write_record(&mut w, &payload)?;
            w.flush()?;
        }
        // S6 fix: fsync after truncate records as well
        f.sync_data()?;
        Ok(())
    }

    fn write_vote(wal_file: &Path, vote: &Vote<KkdbNodeId>) -> io::Result<()> {
        // I27 clarification: `wal_file` is the full path to wal.log.
        // The vote.json lives in the same directory (the raft/ dir), so we use .parent().
        // Renamed parameter from `dir` to `wal_file` to make the intent explicit.
        let raft_dir = wal_file.parent().unwrap_or(wal_file);
        let path = raft_dir.join("vote.json");
        let bytes =
            serde_json::to_vec(vote).map_err(io::Error::other)?;
        fs::write(path, bytes)
    }

    fn write_purge(wal_file: &Path, log_id: &LogId<KkdbNodeId>) -> io::Result<()> {
        // Same as write_vote: `wal_file` is the path to wal.log; parent() gives raft/ dir.
        let raft_dir = wal_file.parent().unwrap_or(wal_file);
        let path = raft_dir.join("purge.json");
        let bytes =
            serde_json::to_vec(log_id).map_err(io::Error::other)?;
        fs::write(path, bytes)
    }

    // ─── Test helpers ───────────────────────────────────────────────────────────

    /// Directly append entries to memory + WAL (bypasses LogFlushed for test use).
    pub fn append_direct(&self, entries: Vec<Entry<KkdbTypeConfig>>) -> io::Result<()> {
        let mut inner = self.inner.lock().unwrap();
        for entry in entries {
            if let Some(ref wal) = inner.wal_file.clone() {
                Self::wal_append(wal, &entry)?;
                inner.total_records += 1;
            }
            inner.log.insert(entry.log_id.index, entry);
        }
        Ok(())
    }

    /// Directly truncate from `from_index` (for test use).
    pub fn truncate_direct(&self, from_index: u64) -> io::Result<()> {
        let mut inner = self.inner.lock().unwrap();
        if let Some(ref wal) = inner.wal_file.clone() {
            Self::wal_truncate(wal, from_index)?;
        }
        inner.log.retain(|&k, _| k < from_index);
        Ok(())
    }

    /// Directly purge up to `log_id` (for test use).
    pub fn purge_direct(&self, log_id: LogId<KkdbNodeId>) -> io::Result<()> {
        let mut inner = self.inner.lock().unwrap();
        // treat purged entries as dead records for compaction tracking
        let purged = inner.log.range(..=log_id.index).count() as u64;
        inner.total_records += purged;
        inner.last_purged_log_id = Some(log_id);
        inner.log.retain(|&k, _| k > log_id.index);
        if let Some(ref wal) = inner.wal_file.clone() {
            Self::write_purge(wal, &log_id)?;
        }
        Ok(())
    }

    /// Read all log entries from the in-memory BTreeMap (for assertions).
    pub fn all_entries(&self) -> Vec<Entry<KkdbTypeConfig>> {
        self.inner.lock().unwrap().log.values().cloned().collect()
    }

    /// Count of entries in memory.
    pub fn entry_count(&self) -> usize {
        self.inner.lock().unwrap().log.len()
    }

    /// Last log index in memory.
    pub fn last_index(&self) -> Option<u64> {
        self.inner.lock().unwrap().log.keys().next_back().copied()
    }

    /// Last purged log id.
    pub fn last_purged(&self) -> Option<LogId<KkdbNodeId>> {
        self.inner.lock().unwrap().last_purged_log_id
    }

    /// Persisted vote.
    pub fn persisted_vote(&self) -> Option<Vote<KkdbNodeId>> {
        self.inner.lock().unwrap().voted_for
    }
}

// ─── WAL record enum ─────────────────────────────────────────────────────────

#[derive(Serialize, Deserialize)]
enum WalRecord {
    Append(Entry<KkdbTypeConfig>),
    Truncate { from_index: u64 },
}

// ─── Storage error helper ─────────────────────────────────────────────────────

fn io_to_storage_err(e: impl std::error::Error + 'static) -> StorageError<KkdbNodeId> {
    StorageIOError::write_logs(&e).into()
}

// ─── RaftLogReader ────────────────────────────────────────────────────────────

impl RaftLogReader<KkdbTypeConfig> for KkdbLogStore {
    async fn try_get_log_entries<RB>(
        &mut self,
        range: RB,
    ) -> Result<Vec<Entry<KkdbTypeConfig>>, StorageError<KkdbNodeId>>
    where
        RB: RangeBounds<u64> + Clone + Debug + OptionalSend,
    {
        let inner = self.inner.lock().unwrap();
        Ok(inner.log.range(range).map(|(_, e)| e.clone()).collect())
    }
}

// ─── RaftLogStorage ───────────────────────────────────────────────────────────

impl RaftLogStorage<KkdbTypeConfig> for KkdbLogStore {
    type LogReader = Self;

    async fn get_log_state(
        &mut self,
    ) -> Result<LogState<KkdbTypeConfig>, StorageError<KkdbNodeId>> {
        let inner = self.inner.lock().unwrap();
        let last = inner.log.values().next_back().map(|e| e.log_id);
        Ok(LogState {
            last_purged_log_id: inner.last_purged_log_id,
            last_log_id: last.or(inner.last_purged_log_id),
        })
    }

    async fn get_log_reader(&mut self) -> Self::LogReader {
        self.clone()
    }

    async fn save_vote(&mut self, vote: &Vote<KkdbNodeId>) -> Result<(), StorageError<KkdbNodeId>> {
        let mut inner = self.inner.lock().unwrap();
        inner.voted_for = Some(*vote);
        if let Some(ref wal) = inner.wal_file {
            Self::write_vote(wal, vote).map_err(io_to_storage_err)?;
        }
        Ok(())
    }

    async fn read_vote(&mut self) -> Result<Option<Vote<KkdbNodeId>>, StorageError<KkdbNodeId>> {
        Ok(self.inner.lock().unwrap().voted_for)
    }

    async fn append<I>(
        &mut self,
        entries: I,
        callback: LogFlushed<KkdbTypeConfig>,
    ) -> Result<(), StorageError<KkdbNodeId>>
    where
        I: IntoIterator<Item = Entry<KkdbTypeConfig>> + OptionalSend,
        I::IntoIter: OptionalSend,
    {
        let mut inner = self.inner.lock().unwrap();
        for entry in entries {
            if let Some(ref wal) = inner.wal_file {
                Self::wal_append(wal, &entry).map_err(io_to_storage_err)?;
                inner.total_records += 1;
            }
            inner.log.insert(entry.log_id.index, entry);
        }
        // Data is now fsynced to disk (or in-memory for tests)
        callback.log_io_completed(Ok(()));
        Ok(())
    }

    async fn truncate(
        &mut self,
        log_id: LogId<KkdbNodeId>,
    ) -> Result<(), StorageError<KkdbNodeId>> {
        let mut inner = self.inner.lock().unwrap();
        if let Some(ref wal) = inner.wal_file.clone() {
            Self::wal_truncate(wal, log_id.index).map_err(io_to_storage_err)?;
            // Count the Truncate marker + the about-to-be-removed entries as dead
            let removed = inner.log.range(log_id.index..).count() as u64;
            inner.total_records += 1 + removed; // 1 for the Truncate record itself
        }
        inner.log.retain(|&k, _| k < log_id.index);
        Ok(())
    }

    async fn purge(&mut self, log_id: LogId<KkdbNodeId>) -> Result<(), StorageError<KkdbNodeId>> {
        let mut inner = self.inner.lock().unwrap();
        // Count entries being purged as dead records
        let purged_count = inner.log.range(..=log_id.index).count() as u64;
        inner.last_purged_log_id = Some(log_id);
        inner.log.retain(|&k, _| k > log_id.index);
        if let Some(ref wal) = inner.wal_file.clone() {
            Self::write_purge(wal, &log_id).map_err(io_to_storage_err)?;
        }

        // Auto-compact when dead records exceed threshold
        let live = inner.log.len() as u64;
        let dead = inner.total_records.saturating_sub(live) + purged_count;
        drop(inner); // release lock before compact() which re-acquires it
        if dead > COMPACT_THRESHOLD {
            let _ = self.compact(); // best-effort: ignore errors (WAL still valid)
        }
        Ok(())
    }
}

//! Raft distributed consensus module for KKDB.
//!
//! This module provides a multi-node, strongly consistent cluster using
//! `openraft v0.9` with KKDB's VM as the state machine.
//!
//! # Modules
//!
//! - `types`      — type configuration, request/response structs
//! - `log_store`  — unified RaftStorage (log + state machine + snapshots)
//! - `network`    — in-memory channel-based RPC transport (Phase 1)
//! - `node`       — high-level KkdbNode API and cluster utilities

pub mod dtx;
pub mod http_network;
pub mod http_transport;
pub mod log_store;
pub mod network;
pub mod node;
pub mod state_machine;
pub mod types;

pub use node::{start_cluster_3, KkdbNode, KkdbRaft};
pub use types::{KkdbNodeId, KkdbRequest, KkdbResponse, KkdbTypeConfig};

//! In-memory Raft network transport for KKDB (Phase 1).
//!
//! Uses a shared registry of Raft handles so nodes in the same process
//! can communicate directly without real TCP sockets.

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};

use openraft::{
    error::{InstallSnapshotError, RPCError, RaftError, RemoteError, Unreachable},
    network::{RPCOption, RaftNetwork, RaftNetworkFactory},
    raft::{
        AppendEntriesRequest, AppendEntriesResponse, InstallSnapshotRequest,
        InstallSnapshotResponse, VoteRequest, VoteResponse,
    },
    BasicNode,
};

use crate::raft::types::{KkdbNodeId, KkdbTypeConfig};

/// A handle to a running Raft node for peer-to-peer RPC.
pub type NodeHandle = Arc<openraft::Raft<KkdbTypeConfig>>;

/// Shared registry: node_id → Raft handle.
pub type NodeRegistry = Arc<Mutex<BTreeMap<KkdbNodeId, NodeHandle>>>;

/// The network factory — one per node, holds registry reference.
#[derive(Clone)]
pub struct KkdbNetworkFactory {
    pub registry: NodeRegistry,
}

impl KkdbNetworkFactory {
    pub fn new(registry: NodeRegistry) -> Self {
        Self { registry }
    }
}

impl RaftNetworkFactory<KkdbTypeConfig> for KkdbNetworkFactory {
    type Network = KkdbNetwork;

    async fn new_client(&mut self, target: KkdbNodeId, _node: &BasicNode) -> Self::Network {
        KkdbNetwork {
            target,
            registry: Arc::clone(&self.registry),
        }
    }
}

/// Per-peer connection: routes RPC calls directly to the target's Raft handle.
pub struct KkdbNetwork {
    pub target: KkdbNodeId,
    pub registry: NodeRegistry,
}

impl KkdbNetwork {
    fn get_raft(&self) -> Result<NodeHandle, Unreachable> {
        self.registry
            .lock()
            .unwrap()
            .get(&self.target)
            .cloned()
            .ok_or_else(|| {
                let e = std::io::Error::new(
                    std::io::ErrorKind::NotConnected,
                    format!("node {} not in registry", self.target),
                );
                Unreachable::new(&e)
            })
    }
}

impl RaftNetwork<KkdbTypeConfig> for KkdbNetwork {
    async fn append_entries(
        &mut self,
        rpc: AppendEntriesRequest<KkdbTypeConfig>,
        _option: RPCOption,
    ) -> Result<
        AppendEntriesResponse<KkdbNodeId>,
        RPCError<KkdbNodeId, BasicNode, RaftError<KkdbNodeId>>,
    > {
        let raft = self.get_raft().map_err(RPCError::Unreachable)?;
        raft.append_entries(rpc)
            .await
            .map_err(|e| RPCError::RemoteError(RemoteError::new(self.target, e)))
    }

    async fn vote(
        &mut self,
        rpc: VoteRequest<KkdbNodeId>,
        _option: RPCOption,
    ) -> Result<VoteResponse<KkdbNodeId>, RPCError<KkdbNodeId, BasicNode, RaftError<KkdbNodeId>>>
    {
        let raft = self.get_raft().map_err(RPCError::Unreachable)?;
        raft.vote(rpc)
            .await
            .map_err(|e| RPCError::RemoteError(RemoteError::new(self.target, e)))
    }

    async fn install_snapshot(
        &mut self,
        rpc: InstallSnapshotRequest<KkdbTypeConfig>,
        _option: RPCOption,
    ) -> Result<
        InstallSnapshotResponse<KkdbNodeId>,
        RPCError<KkdbNodeId, BasicNode, RaftError<KkdbNodeId, InstallSnapshotError>>,
    > {
        let raft = self.get_raft().map_err(RPCError::Unreachable)?;
        raft.install_snapshot(rpc)
            .await
            .map_err(|e| RPCError::RemoteError(RemoteError::new(self.target, e)))
    }
}

//! High-level KKDB Raft node.
//!
//! `KkdbNode` wraps `openraft::Raft` and provides clean methods for:
//! - Initializing a cluster
//! - Submitting SQL writes through Raft
//! - Querying cluster status

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};

use openraft::{BasicNode, Config, Raft};

use crate::binlog::BinlogBroadcaster;
use crate::raft::{
    log_store::KkdbLogStore,
    network::{KkdbNetworkFactory, NodeRegistry},
    state_machine::KkdbStateMachine,
    types::{KkdbNodeId, KkdbRequest, KkdbResponse, KkdbTypeConfig},
};
use crate::server::http_api::AppState;

/// The concrete Raft type for KKDB.
pub type KkdbRaft = Raft<KkdbTypeConfig>;

/// A KKDB Raft node.
#[derive(Clone)]
pub struct KkdbNode {
    pub id: KkdbNodeId,
    pub raft: KkdbRaft,
    pub registry: NodeRegistry,
    /// Binlog broadcaster — Some if this node is the binlog source.
    pub binlog: Option<BinlogBroadcaster>,
}

impl KkdbNode {
    /// Create and register a new in-process node.
    ///
    /// `wal_dir` — if `Some(path)`, the Raft log is persisted to `{path}/raft/`.
    ///             If `None`, an in-memory log store is used (tests).
    /// `binlog`  — if `Some(broadcaster)`, every committed write is also emitted
    ///             to the binlog for subscriber fan-out and pull replication.
    pub async fn new(
        id: KkdbNodeId,
        app_state: AppState,
        registry: NodeRegistry,
        wal_dir: Option<&std::path::Path>,
        binlog: Option<BinlogBroadcaster>,
    ) -> Result<Self, Box<dyn std::error::Error + Send + Sync>> {
        let config = Arc::new(
            Config {
                heartbeat_interval: 250,
                election_timeout_min: 299,
                election_timeout_max: 500,
                ..Default::default()
            }
            .validate()
            .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?,
        );

        let log_store = match wal_dir {
            Some(dir) => KkdbLogStore::open(dir)
                .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?,
            None => KkdbLogStore::default(),
        };
        let mut state_machine = match wal_dir {
            Some(dir) => KkdbStateMachine::open(app_state, dir)
                .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?,
            None => KkdbStateMachine::new(app_state),
        };
        // Wire the binlog broadcaster into the state machine
        state_machine.binlog = binlog.clone();

        let network = KkdbNetworkFactory::new(Arc::clone(&registry));

        let raft = Raft::new(id, config, network, log_store, state_machine)
            .await
            .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?;

        // Register in shared peer map
        registry.lock().unwrap().insert(id, Arc::new(raft.clone()));

        Ok(Self {
            id,
            raft,
            registry,
            binlog,
        })
    }

    /// Initialize a single-node cluster (node becomes Leader immediately).
    pub async fn init_single(&self) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let mut members = BTreeMap::new();
        members.insert(
            self.id,
            BasicNode {
                addr: format!("node-{}", self.id),
            },
        );
        self.raft
            .initialize(members)
            .await
            .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)
    }

    /// Initialize with a specific member set (for multi-node bootstrap).
    pub async fn init_with_members(
        &self,
        members: BTreeMap<KkdbNodeId, BasicNode>,
    ) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        self.raft
            .initialize(members)
            .await
            .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)
    }

    /// Submit a SQL write through Raft. Must be called on (or forwarded to) the Leader.
    pub async fn write(
        &self,
        req: KkdbRequest,
    ) -> Result<KkdbResponse, Box<dyn std::error::Error + Send + Sync>> {
        let resp = self
            .raft
            .client_write(req)
            .await
            .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?;
        Ok(resp.data)
    }

    /// Current Raft metrics snapshot.
    pub fn metrics(&self) -> openraft::RaftMetrics<KkdbNodeId, BasicNode> {
        self.raft.metrics().borrow().clone()
    }

    /// True if this node believes it is the current Leader.
    pub fn is_leader(&self) -> bool {
        let m = self.metrics();
        m.current_leader == Some(self.id)
    }

    /// Wait until a Leader is elected, up to `timeout`.
    pub async fn wait_for_leader(
        &self,
        timeout: std::time::Duration,
    ) -> Result<KkdbNodeId, Box<dyn std::error::Error + Send + Sync>> {
        let m = self
            .raft
            .wait(Some(timeout))
            .metrics(|m| m.current_leader.is_some(), "leader elected")
            .await
            .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?;
        Ok(m.current_leader.unwrap())
    }

    // ── Distributed read / write helpers ─────────────────────────────────────

    /// Ensure this node has applied all log entries up to the current commit
    /// index before serving a read — i.e., ReadIndex linearizable read fence.
    ///
    /// Call this before executing SELECT on a follower so the local VM is
    /// up-to-date with the latest committed state.
    ///
    /// Returns `Ok(())` immediately on the leader (already up-to-date).
    /// Times out after 5 seconds if the cluster is unavailable.
    pub async fn ensure_linearizable(
        &self,
    ) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        self.raft
            .ensure_linearizable()
            .await
            .map(|_| ())
            .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)
    }

    /// Get the REST base URL of the current leader, if known.
    ///
    /// `peer_rest_addrs` is passed in from `AppState`; it maps
    /// `node_id → "http://host:port"`.
    pub fn leader_rest_url(
        &self,
        peer_rest_addrs: &std::collections::BTreeMap<u64, String>,
    ) -> Option<String> {
        let leader_id = self.metrics().current_leader?;
        peer_rest_addrs.get(&leader_id).cloned()
    }

    /// Shutdown cleanly.
    pub async fn shutdown(self) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        self.raft
            .shutdown()
            .await
            .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)
    }
}

/// Start a fully initialized 3-node in-memory cluster.
/// Returns [leader, follower1, follower2].
pub async fn start_cluster_3(
    states: [AppState; 3],
) -> Result<[KkdbNode; 3], Box<dyn std::error::Error + Send + Sync>> {
    let registry: NodeRegistry = Arc::new(Mutex::new(BTreeMap::new()));

    let n1 = KkdbNode::new(1, states[0].clone(), Arc::clone(&registry), None, None).await?;
    let n2 = KkdbNode::new(2, states[1].clone(), Arc::clone(&registry), None, None).await?;
    let n3 = KkdbNode::new(3, states[2].clone(), Arc::clone(&registry), None, None).await?;

    let mut members = BTreeMap::new();
    members.insert(
        1u64,
        BasicNode {
            addr: "node-1".into(),
        },
    );
    members.insert(
        2u64,
        BasicNode {
            addr: "node-2".into(),
        },
    );
    members.insert(
        3u64,
        BasicNode {
            addr: "node-3".into(),
        },
    );

    // Only node 1 calls initialize; others receive membership via Raft replication
    n1.init_with_members(members).await?;

    Ok([n1, n2, n3])
}

// ─── Phase 2: HTTP-based cluster node ─────────────────────────────────────────

/// Create a Raft node that communicates with peers over HTTP (Phase 2).
///
/// `self_addr`   — this node's HTTP Raft RPC address (e.g. "http://127.0.0.1:7001")
/// `peer_addrs`  — map of other known nodes: { node_id → "http://host:port" }
/// `wal_dir`     — if `Some(dir)`, log is persisted to `{dir}/raft/`
pub async fn new_with_http_network(
    id: KkdbNodeId,
    app_state: AppState,
    self_addr: String,
    peer_addrs: BTreeMap<KkdbNodeId, String>,
    wal_dir: Option<std::path::PathBuf>,
    binlog: Option<crate::binlog::BinlogBroadcaster>,
) -> Result<KkdbNode, Box<dyn std::error::Error + Send + Sync>> {
    use crate::raft::http_network::{AddrRegistry, HttpNetworkFactory};

    // Build address registry including self
    let mut addrs = peer_addrs;
    addrs.insert(id, self_addr);
    let addr_registry: AddrRegistry = Arc::new(Mutex::new(addrs));

    let config = Arc::new(
        Config {
            heartbeat_interval: 250,
            election_timeout_min: 299,
            election_timeout_max: 500,
            ..Default::default()
        }
        .validate()
        .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?,
    );

    let log_store = match wal_dir.as_deref() {
        Some(dir) => crate::raft::log_store::KkdbLogStore::open(dir)
            .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?,
        None => crate::raft::log_store::KkdbLogStore::default(),
    };
    let mut state_machine = match wal_dir.as_deref() {
        Some(dir) => crate::raft::state_machine::KkdbStateMachine::open(app_state, dir)
            .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?,
        None => crate::raft::state_machine::KkdbStateMachine::new(app_state),
    };
    state_machine.binlog = binlog.clone();

    let network = HttpNetworkFactory::new(Arc::clone(&addr_registry));

    // In-memory registry used only to store the self-handle for the HTTP server
    let registry: NodeRegistry = Arc::new(Mutex::new(BTreeMap::new()));
    let raft = Raft::new(id, config, network, log_store, state_machine)
        .await
        .map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?;
    registry.lock().unwrap().insert(id, Arc::new(raft.clone()));

    Ok(KkdbNode {
        id,
        raft,
        registry,
        binlog,
    })
}

/// Bind the Raft HTTP RPC server on `raft_addr` (e.g. "0.0.0.0:7001").
/// This must be called after creating the node so handlers can access `node.raft`.
pub async fn start_raft_http_server(node: Arc<KkdbNode>, raft_addr: std::net::SocketAddr) {
    use crate::raft::http_transport::build_raft_router;
    let router = build_raft_router(node);
    let listener = tokio::net::TcpListener::bind(raft_addr)
        .await
        .expect("bind Raft HTTP port");
    axum::serve(listener, router)
        .await
        .expect("Raft HTTP server");
}

//! State machine for KKDB Raft (openraft v0.9 + storage-v2).
//!
//! `KkdbStateMachine` implements `RaftStateMachine`. When the Raft consensus
//! engine commits a log entry it calls `apply()` here, which routes the SQL
//! to the correct per-user KKDB VM and executes it.
//!
//! ## Snapshot persistence
//!
//! When `snapshot_dir` is `Some(dir)`:
//!   - `build_snapshot` → JSON-serialises `KkdbSnapshotData` + meta, writes
//!     atomically to `{dir}/raft/snapshot.json` via a `.tmp` rename.
//!   - `get_current_snapshot` → reads and deserialises `snapshot.json`.
//!   - `install_snapshot` → saves the incoming blob to disk, then replays SQL.
//!
//! When `snapshot_dir` is `None` (tests / in-memory mode) snapshots are
//! purely in-memory with no disk I/O.

use std::io::Cursor;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

use openraft::{
    storage::RaftStateMachine, Entry, EntryPayload, LogId, RaftSnapshotBuilder, Snapshot,
    SnapshotMeta, StorageError, StorageIOError, StoredMembership,
};
use serde::{Deserialize, Serialize};

use crate::binlog::{BinlogBroadcaster, LogRecord};
use crate::raft::types::{KkdbNodeId, KkdbRequest, KkdbResponse, KkdbTypeConfig};
use crate::server::http_api::AppState;
use crate::vm::execute::VM;

// ─── On-disk snapshot format ──────────────────────────────────────────────────

/// What is persisted to `snapshot.json`.
#[derive(Debug, Default, Clone, Serialize, Deserialize)]
pub struct PersistedSnapshot {
    pub meta: SerializedSnapshotMeta,
    pub data: KkdbSnapshotData,
}

/// A serialisable copy of `SnapshotMeta` (which contains non-Serialize fields
/// in some openraft versions, so we extract what we need manually).
#[derive(Debug, Default, Clone, Serialize, Deserialize)]
pub struct SerializedSnapshotMeta {
    pub last_log_id: Option<LogId<KkdbNodeId>>,
    pub last_membership: StoredMembership<KkdbNodeId, openraft::BasicNode>,
    pub snapshot_id: String,
}

/// The actual payload carried inside a snapshot.
#[derive(Debug, Default, Clone, Serialize, Deserialize)]
pub struct KkdbSnapshotData {
    /// All SQL writes that have been applied, in order.
    pub entries: Vec<KkdbRequest>,
    pub last_applied: Option<LogId<KkdbNodeId>>,
    pub last_membership: StoredMembership<KkdbNodeId, openraft::BasicNode>,
}

// ─── State machine ────────────────────────────────────────────────────────────

#[derive(Clone)]
pub struct KkdbStateMachine {
    pub app_state: AppState,
    pub last_applied_log: Option<LogId<KkdbNodeId>>,
    pub last_membership: StoredMembership<KkdbNodeId, openraft::BasicNode>,
    /// Running log of applied SQL requests (used for snapshot building).
    pub applied_entries: Vec<KkdbRequest>,
    pub snapshot_idx: u64,
    /// Root directory for snapshot files. `None` = in-memory only.
    pub snapshot_dir: Option<PathBuf>,
    /// Cached last snapshot meta+data for `get_current_snapshot`.
    pub current_snapshot: Option<PersistedSnapshot>,
    /// Binlog broadcaster. When set, every committed Raft write is also
    /// appended to the binlog and fanned out to all subscribers.
    pub binlog: Option<BinlogBroadcaster>,
}

impl KkdbStateMachine {
    /// Create an in-memory state machine (tests).
    pub fn new(app_state: AppState) -> Self {
        Self {
            app_state,
            last_applied_log: None,
            last_membership: StoredMembership::default(),
            applied_entries: Vec::new(),
            snapshot_idx: 0,
            snapshot_dir: None,
            current_snapshot: None,
            binlog: None,
        }
    }

    /// Create a persistent state machine backed by `dir`.
    ///
    /// On construction it tries to load an existing snapshot from disk and
    /// replay its SQL to restore the VM state.
    pub fn open(app_state: AppState, dir: &Path) -> std::io::Result<Self> {
        let snapshot_dir = dir.join("raft");
        std::fs::create_dir_all(&snapshot_dir)?;

        let mut sm = Self {
            app_state,
            last_applied_log: None,
            last_membership: StoredMembership::default(),
            applied_entries: Vec::new(),
            snapshot_idx: 0,
            snapshot_dir: Some(snapshot_dir.clone()),
            current_snapshot: None,
            binlog: None, // caller sets this after open()
        };

        // Load snapshot from disk if it exists
        let snap_path = snapshot_dir.join("snapshot.json");
        if snap_path.exists() {
            let bytes = std::fs::read(&snap_path)?;
            if let Ok(persisted) = serde_json::from_slice::<PersistedSnapshot>(&bytes) {
                sm.last_applied_log = persisted.data.last_applied;
                sm.last_membership = persisted.data.last_membership.clone();
                sm.applied_entries = persisted.data.entries.clone();
                sm.current_snapshot = Some(persisted.clone());

                // Replay snapshot SQL to restore VM state
                for req in &persisted.data.entries {
                    sm.apply_request(req);
                }
            }
        }
        Ok(sm)
    }

    /// Route a SQL request to the correct VM and execute it.
    pub fn apply_request(&self, req: &KkdbRequest) -> KkdbResponse {
        let vm_arc = if req.user_id.is_empty() {
            Arc::clone(&self.app_state.auth_vm)
        } else {
            let mut cache = self.app_state.user_vms.lock().unwrap();
            if let Some(vm) = cache.get(&req.user_id) {
                Arc::clone(vm)
            } else {
                let vm = match &self.app_state.data_dir {
                    Some(base) => {
                        let path = base.as_ref().join(&req.user_id);
                        match VM::open(&path.to_string_lossy()) {
                            Ok(v) => v,
                            Err(e) => {
                                return KkdbResponse {
                                    message: e.to_string(),
                                    ok: false,
                                }
                            }
                        }
                    }
                    None => VM::new_memory(),
                };
                let arc = Arc::new(Mutex::new(vm));
                cache.insert(req.user_id.clone(), Arc::clone(&arc));
                arc
            }
        };
        let mut vm = vm_arc.lock().unwrap();
        match vm.execute_sql(&req.sql) {
            Ok(r) => KkdbResponse {
                message: format!("{r:?}"),
                ok: true,
            },
            Err(e) => KkdbResponse {
                message: e.to_string(),
                ok: false,
            },
        }
    }

    // ── Disk I/O helpers ──────────────────────────────────────────────────────

    fn write_snapshot_to_disk(dir: &Path, persisted: &PersistedSnapshot) -> std::io::Result<()> {
        let bytes = serde_json::to_vec(persisted)
            .map_err(std::io::Error::other)?;
        // Atomic write: write to .tmp then rename
        let tmp_path = dir.join("snapshot.tmp");
        let snap_path = dir.join("snapshot.json");
        std::fs::write(&tmp_path, &bytes)?;
        std::fs::rename(&tmp_path, &snap_path)?;
        Ok(())
    }

    fn read_snapshot_from_disk(dir: &Path) -> std::io::Result<Option<PersistedSnapshot>> {
        let snap_path = dir.join("snapshot.json");
        if !snap_path.exists() {
            return Ok(None);
        }
        let bytes = std::fs::read(&snap_path)?;
        serde_json::from_slice(&bytes)
            .map(Some)
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))
    }
}

// ─── RaftSnapshotBuilder ──────────────────────────────────────────────────────

impl RaftSnapshotBuilder<KkdbTypeConfig> for KkdbStateMachine {
    async fn build_snapshot(
        &mut self,
    ) -> Result<Snapshot<KkdbTypeConfig>, StorageError<KkdbNodeId>> {
        self.snapshot_idx += 1;
        let snap_data = KkdbSnapshotData {
            entries: self.applied_entries.clone(),
            last_applied: self.last_applied_log,
            last_membership: self.last_membership.clone(),
        };
        let snap_id = match self.last_applied_log {
            Some(l) => format!("{}-{}-{}", l.leader_id, l.index, self.snapshot_idx),
            None => format!("empty-{}", self.snapshot_idx),
        };
        let meta = SnapshotMeta {
            last_log_id: self.last_applied_log,
            last_membership: self.last_membership.clone(),
            snapshot_id: snap_id.clone(),
        };

        // Build the persisted form (meta + data as one JSON blob)
        let persisted = PersistedSnapshot {
            meta: SerializedSnapshotMeta {
                last_log_id: meta.last_log_id,
                last_membership: meta.last_membership.clone(),
                snapshot_id: snap_id,
            },
            data: snap_data,
        };

        // Write to disk (if configured)
        if let Some(ref dir) = self.snapshot_dir.clone() {
            Self::write_snapshot_to_disk(dir, &persisted)
                .map_err(|e| StorageIOError::write_snapshot(Some(meta.signature()), &e))?;
        }
        self.current_snapshot = Some(persisted.clone());

        let bytes = serde_json::to_vec(&persisted).unwrap_or_default();
        Ok(Snapshot {
            meta,
            snapshot: Box::new(Cursor::new(bytes)),
        })
    }
}

// ─── RaftStateMachine ─────────────────────────────────────────────────────────

impl RaftStateMachine<KkdbTypeConfig> for KkdbStateMachine {
    type SnapshotBuilder = Self;

    async fn applied_state(
        &mut self,
    ) -> Result<
        (
            Option<LogId<KkdbNodeId>>,
            StoredMembership<KkdbNodeId, openraft::BasicNode>,
        ),
        StorageError<KkdbNodeId>,
    > {
        Ok((self.last_applied_log, self.last_membership.clone()))
    }

    async fn apply<I>(&mut self, entries: I) -> Result<Vec<KkdbResponse>, StorageError<KkdbNodeId>>
    where
        I: IntoIterator<Item = Entry<KkdbTypeConfig>> + openraft::OptionalSend,
        I::IntoIter: openraft::OptionalSend,
    {
        let mut replies = Vec::new();
        for entry in entries {
            self.last_applied_log = Some(entry.log_id);
            let raft_index = entry.log_id.index;

            let resp = match &entry.payload {
                EntryPayload::Blank => KkdbResponse {
                    message: "blank".into(),
                    ok: true,
                },
                EntryPayload::Normal(req) => {
                    self.applied_entries.push(req.clone());
                    let resp = self.apply_request(req);

                    // ── Binlog: emit Sql record for every committed write ────────────
                    if let Some(ref broadcaster) = self.binlog {
                        let record = LogRecord::Sql {
                            sql: req.sql.clone(),
                            user_id: req.user_id.clone(),
                            raft_index,
                        };
                        // Best-effort: never fail Raft apply due to binlog errors
                        if let Err(e) = broadcaster.append_and_broadcast(&record) {
                            eprintln!("[Binlog] append error at raft_index={raft_index}: {e}");
                        }
                    }

                    resp
                }
                EntryPayload::Membership(mem) => {
                    self.last_membership = StoredMembership::new(Some(entry.log_id), mem.clone());
                    KkdbResponse {
                        message: "membership".into(),
                        ok: true,
                    }
                }
            };
            replies.push(resp);
        }
        Ok(replies)
    }

    async fn get_snapshot_builder(&mut self) -> Self::SnapshotBuilder {
        self.clone()
    }

    async fn begin_receiving_snapshot(
        &mut self,
    ) -> Result<Box<Cursor<Vec<u8>>>, StorageError<KkdbNodeId>> {
        Ok(Box::new(Cursor::new(Vec::new())))
    }

    async fn install_snapshot(
        &mut self,
        meta: &SnapshotMeta<KkdbNodeId, openraft::BasicNode>,
        snapshot: Box<Cursor<Vec<u8>>>,
    ) -> Result<(), StorageError<KkdbNodeId>> {
        let bytes = snapshot.into_inner();

        // Try to parse as full PersistedSnapshot (leader sends it); or as
        // bare KkdbSnapshotData for backward compat.
        let persisted: PersistedSnapshot = serde_json::from_slice(&bytes).unwrap_or_else(|_| {
            let data: KkdbSnapshotData = serde_json::from_slice(&bytes).unwrap_or_default();
            PersistedSnapshot {
                meta: SerializedSnapshotMeta {
                    last_log_id: meta.last_log_id,
                    last_membership: meta.last_membership.clone(),
                    snapshot_id: meta.snapshot_id.clone(),
                },
                data,
            }
        });

        // Persist to disk (atomic)
        if let Some(ref dir) = self.snapshot_dir.clone() {
            Self::write_snapshot_to_disk(dir, &persisted)
                .map_err(|e| StorageIOError::write_snapshot(Some(meta.signature()), &e))?;
        }

        // Update in-memory state
        self.last_applied_log = persisted.data.last_applied;
        self.last_membership = persisted.data.last_membership.clone();
        self.applied_entries = persisted.data.entries.clone();
        self.current_snapshot = Some(persisted.clone());

        // Replay SQL to restore VM state
        for req in &persisted.data.entries {
            self.apply_request(req);
        }
        Ok(())
    }

    async fn get_current_snapshot(
        &mut self,
    ) -> Result<Option<Snapshot<KkdbTypeConfig>>, StorageError<KkdbNodeId>> {
        // Try in-memory cache first
        if let Some(ref persisted) = self.current_snapshot {
            let bytes = serde_json::to_vec(persisted).unwrap_or_default();
            let meta = SnapshotMeta {
                last_log_id: persisted.meta.last_log_id,
                last_membership: persisted.meta.last_membership.clone(),
                snapshot_id: persisted.meta.snapshot_id.clone(),
            };
            return Ok(Some(Snapshot {
                meta,
                snapshot: Box::new(Cursor::new(bytes)),
            }));
        }

        // Fall back to disk
        if let Some(ref dir) = self.snapshot_dir.clone() {
            match Self::read_snapshot_from_disk(dir) {
                Ok(Some(persisted)) => {
                    let bytes = serde_json::to_vec(&persisted).unwrap_or_default();
                    let meta = SnapshotMeta {
                        last_log_id: persisted.meta.last_log_id,
                        last_membership: persisted.meta.last_membership.clone(),
                        snapshot_id: persisted.meta.snapshot_id.clone(),
                    };
                    self.current_snapshot = Some(persisted);
                    return Ok(Some(Snapshot {
                        meta,
                        snapshot: Box::new(Cursor::new(bytes)),
                    }));
                }
                Ok(None) => {}
                Err(e) => {
                    // Log but don't fail — a missing snapshot is recoverable via log replay
                    eprintln!("[Raft] Warning: could not read snapshot from disk: {e}");
                }
            }
        }

        Ok(None)
    }
}

//! Raft type configuration and application request types for KKDB.

use openraft::BasicNode;
use serde::{Deserialize, Serialize};

/// The application-level "request" that gets replicated through Raft.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct KkdbRequest {
    /// SQL statement (DML or DDL) to replicate
    pub sql: String,
    /// The user_id whose isolated VM should execute the SQL.
    /// Empty string = execute against the global auth VM.
    pub user_id: String,
}

/// The application-level "response" returned after apply().
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct KkdbResponse {
    pub message: String,
    pub ok: bool,
}

/// Node ID type for the Raft cluster.
pub type KkdbNodeId = u64;

openraft::declare_raft_types!(
    /// KKDB's Raft type configuration.
    pub KkdbTypeConfig:
        D      = KkdbRequest,
        R      = KkdbResponse,
        Node   = BasicNode,
        NodeId = KkdbNodeId,
        Entry  = openraft::Entry<KkdbTypeConfig>,
        SnapshotData = std::io::Cursor<Vec<u8>>
);

use crate::error::{KkdbError, Result};
use crate::sql::ast::{ColumnDef, Expr, UnaryOperator};
use crate::storage::btree::BTree;
use crate::storage::pager::Pager;
use crate::types::{DataType, Row, Value};
use std::collections::{HashMap, HashSet};

/// Helper for zero-alloc lowercase key lookup (fast path: already lowercase 鈫?borrow)
enum LowercaseKey<'a> {
    Borrowed(&'a str),
    Owned(String),
}

impl<'a> AsRef<str> for LowercaseKey<'a> {
    #[inline]
    fn as_ref(&self) -> &str {
        match self {
            LowercaseKey::Borrowed(s) => s,
            LowercaseKey::Owned(s) => s.as_str(),
        }
    }
}

/// Schema table root is tracked by the pager (v2 superblock schema_root)
/// Each row in the schema table represents a database object (table, index, etc.)
///
/// Schema table columns:
///   type TEXT      - "table" or "index"
///   name TEXT      - name of the object
///   tbl_name TEXT  - table name (same as name for tables)
///   rootpage INT   - root page number of the B-tree
///   sql TEXT       - CREATE statement
///
/// Cached table schema info
#[derive(Debug, Clone)]
pub struct TableSchema {
    pub name: String,
    pub columns: Vec<ColumnInfo>,
    pub col_names: Vec<String>,
    pub root_page: u32,
    pub next_rowid: i64,
    /// Non-None for views: holds the SELECT AST to expand at query time (Batch E)
    pub view_select: Option<crate::sql::ast::SelectStmt>,
    /// L1: Foreign key constraints defined on this table
    pub foreign_keys: Vec<ForeignKey>,
    /// L2: CHECK constraints: (optional constraint name, expression AST)
    pub check_constraints: Vec<(Option<String>, crate::sql::ast::Expr)>,
    /// L4: True if this table is an FTS virtual table
    pub is_fts: bool,
    /// RLS: whether row-level security is enabled on this table
    pub rls_enabled: bool,
    /// RLS: list of policies defined on this table
    pub policies: Vec<PolicySchema>,
    /// InnoDB-style flag: true when data B-Tree is ordered by the primary key (clustered).
    /// Always true for KKDB tables — data is stored in rowid order, and
    /// INTEGER PRIMARY KEY is mapped directly to the internal rowid.
    pub clustered_index: bool,
}

impl TableSchema {
    /// Return the name of the primary key column, if exactly one exists.
    pub fn primary_key_column(&self) -> Option<&str> {
        let mut pk = None;
        for col in &self.columns {
            if col.primary_key {
                if pk.is_some() {
                    return None; // composite PK — not a single column
                }
                pk = Some(col.name.as_str());
            }
        }
        pk
    }

    /// Return the column index of the primary key, if exactly one PK column exists.
    pub fn primary_key_col_index(&self) -> Option<usize> {
        let mut pk_idx = None;
        for col in &self.columns {
            if col.primary_key {
                if pk_idx.is_some() {
                    return None;
                }
                pk_idx = Some(col.col_index);
            }
        }
        pk_idx
    }

    /// Check if the primary key is an INTEGER type (InnoDB-style clustered by rowid).
    pub fn pk_is_integer_clustered(&self) -> bool {
        self.clustered_index
            && self.columns.iter().any(|c| {
                c.primary_key && matches!(c.data_type, DataType::Integer)
            })
    }
}

/// RLS policy stored in memory alongside the TableSchema
#[derive(Debug, Clone)]
pub struct PolicySchema {
    /// Policy name
    pub name: String,
    /// Optional role restriction (None = all users)
    pub role: Option<String>,
    /// USING expression (evaluated at SELECT time for row filtering)
    pub using_expr: Option<crate::sql::ast::Expr>,
    /// WITH CHECK expression (evaluated at INSERT/UPDATE time)
    pub check_expr: Option<crate::sql::ast::Expr>,
}

#[derive(Debug, Clone)]
pub struct ColumnInfo {
    pub name: String,
    pub data_type: DataType,
    pub primary_key: bool,
    pub autoincrement: bool,
    pub not_null: bool,
    pub unique: bool,
    pub col_index: usize,
    /// O1: column-level statistics (populated by ANALYZE TABLE)
    pub stats: Option<ColumnStats>,
}

/// O1: Column statistics for cost-based optimizer hints.
#[derive(Debug, Clone)]
pub struct ColumnStats {
    /// Total rows scanned
    pub total_count: i64,
    /// Number of NULL values
    pub null_count: i64,
    /// Number of distinct non-null values
    pub ndv: i64,
    /// Minimum value (None if all NULL or empty)
    pub min: Option<crate::types::Value>,
    /// Maximum value (None if all NULL or empty)
    pub max: Option<crate::types::Value>,
    /// O2: Equi-depth histogram buckets for range selectivity estimation.
    /// Each bucket stores (upper_bound, cumulative_count).
    /// `cumulative_count` is the number of rows with value ≤ `upper_bound`.
    pub histogram: Option<Vec<HistogramBucket>>,
}

/// O2: A single equi-depth histogram bucket for CBO range estimation.
#[derive(Debug, Clone)]
pub struct HistogramBucket {
    /// Upper bound value of this bucket (inclusive)
    pub upper_bound: crate::types::Value,
    /// Cumulative row count: total rows with value ≤ upper_bound
    pub cumulative_count: i64,
    /// Number of distinct values in this bucket
    pub ndv_in_bucket: i64,
}

/// L1: Represents a FOREIGN KEY constraint stored in the schema.
#[derive(Debug, Clone)]
pub struct ForeignKey {
    /// The column in this table that holds the FK value
    pub col_name: String,
    /// The column index in this table
    pub col_index: usize,
    /// Referenced table name (lowercase)
    pub ref_table: String,
    /// Referenced column name (or the PK if empty)
    pub ref_col: Option<String>,
    /// Action on parent DELETE
    pub on_delete: crate::sql::ast::FkAction,
    /// Action on parent UPDATE
    pub on_update: crate::sql::ast::FkAction,
}

/// L3: Trigger definition cached in schema
#[derive(Debug, Clone)]
pub struct TriggerSchema {
    pub name: String,
    pub timing: crate::sql::ast::TriggerTiming,
    pub event: crate::sql::ast::TriggerEvent,
    pub table_name: String,
    pub body_sql: String,
    pub rowid: i64,
}

/// Cached index schema info
#[derive(Debug, Clone)]
pub struct IndexSchema {
    pub name: String,
    pub table_name: String,
    pub columns: Vec<String>,
    pub root_page: u32,
    pub unique: bool,
    /// True for FULLTEXT INDEX entries (stored in same schema table as type="fulltext_index")
    pub is_fts: bool,
}

/// Schema manager - maintains the catalog of tables
#[derive(Clone)]
pub struct Schema {
    pub tables: HashMap<String, TableSchema>,
    pub indexes: HashMap<String, IndexSchema>,
    indexes_by_table: HashMap<String, Vec<String>>,
    /// L3: Triggers grouped by table name (lowercase)
    pub triggers: HashMap<String, Vec<TriggerSchema>>,
    /// Vector indexes: in-memory HNSW graphs keyed by index name
    pub vector_indexes: crate::vector::VectorIndexRegistry,
}

impl Default for Schema {
    fn default() -> Self {
        Self::new()
    }
}

impl Schema {
    pub fn new() -> Self {
        Schema {
            tables: HashMap::new(),
            indexes: HashMap::new(),
            indexes_by_table: HashMap::new(),
            triggers: HashMap::new(),
            vector_indexes: crate::vector::VectorIndexRegistry::new(),
        }
    }

    /// Load all table schemas from the schema table root page.
    pub fn load_from_pager(&mut self, pager: &mut Pager) -> Result<()> {
        self.tables.clear();
        self.indexes.clear();
        self.indexes_by_table.clear();

        let schema_root = pager.schema_root_page();
        let mut btree = BTree::new(pager);
        let rows = btree.scan_all(schema_root)?;

        for (_rowid, row) in rows {
            if row.len() < 5 {
                continue;
            }

            let obj_type = match &row[0] {
                Value::Text(s) => s.to_string(),
                _ => continue,
            };
            let name = match &row[1] {
                Value::Text(s) => s.to_string(),
                _ => continue,
            };
            let root_page = match &row[3] {
                Value::Integer(v) => *v as u32,
                _ => continue,
            };
            let sql = match &row[4] {
                Value::Text(s) => s.to_string(),
                _ => continue,
            };

            if obj_type == "table" || obj_type == "fts_table" {
                let is_fts = obj_type == "fts_table";
                // Parse the CREATE TABLE SQL to get column info
                match crate::sql::parser::parse_sql(&sql) {
                    Ok(crate::sql::ast::Statement::CreateTable(create)) => {
                        let mut columns = Vec::new();
                        let mut check_constraints = Vec::new();
                        // C1 fix: reconstruct FK list from the persisted CREATE TABLE SQL
                        let mut foreign_keys = Vec::new();
                        for (i, col_def) in create.columns.iter().enumerate() {
                            columns.push(ColumnInfo {
                                name: col_def.name.clone(),
                                data_type: col_def.data_type.clone(),
                                primary_key: col_def.primary_key,
                                autoincrement: col_def.autoincrement,
                                not_null: col_def.not_null,
                                unique: col_def.unique,
                                col_index: i,
                                stats: None,
                            });
                            if let Some(ref check) = col_def.check_expr {
                                check_constraints.push((None, check.clone()));
                            }
                            // Restore FK from column-level REFERENCES clause
                            if let Some(ref fkref) = col_def.references {
                                foreign_keys.push(ForeignKey {
                                    col_name: col_def.name.clone(),
                                    col_index: i,
                                    ref_table: fkref.table.to_ascii_lowercase(),
                                    ref_col: fkref.column.clone(),
                                    on_delete: fkref.on_delete.clone(),
                                    on_update: fkref.on_update.clone(),
                                });
                            }
                        }

                        for tc in &create.checks {
                            check_constraints.push(tc.clone());
                        }

                        // Get max rowid for autoincrement.
                        // NOTE: In multi-file mode, root_page belongs to the table's own pager,
                        // not the catalog pager. Silently default to 1; VM::open will fix it up.
                        let next_rowid = btree.max_rowid(root_page).unwrap_or(0) + 1;

                        let col_names: Vec<String> =
                            columns.iter().map(|c| c.name.clone()).collect();
                        self.tables.insert(
                            name.to_lowercase(),
                            TableSchema {
                                name,
                                columns,
                                col_names,
                                root_page,
                                next_rowid,
                                view_select: None,
                                foreign_keys,
                                check_constraints,
                                is_fts,
                                rls_enabled: false,
                                policies: Vec::new(),
                                clustered_index: true, // InnoDB-style: data in PK order
                            },
                        );
                    }
                    _ => {
                        // Can't parse - store minimal info
                        self.tables.insert(
                            name.to_lowercase(),
                            TableSchema {
                                name,
                                columns: Vec::new(),
                                col_names: Vec::new(),
                                root_page,
                                next_rowid: 1,
                                view_select: None,
                                foreign_keys: Vec::new(),
                                check_constraints: Vec::new(),
                                is_fts,
                                rls_enabled: false,
                                policies: Vec::new(),
                                clustered_index: true,
                            },
                        );
                    }
                }
            } else if obj_type == "index" || obj_type == "fulltext_index" {
                // Parse the CREATE INDEX SQL to get index info
                let is_fts_idx = obj_type == "fulltext_index";
                let tbl_name = match &row[2] {
                    Value::Text(s) => s.to_string(),
                    _ => continue,
                };
                // Determine columns: for fulltext_index parse from sql pattern
                let columns: Vec<String> = if is_fts_idx {
                    // Extract columns from persisted SQL: "CREATE FULLTEXT INDEX name ON tbl (col1,col2)"
                    let upper = sql.to_ascii_uppercase();
                    let rest = &sql[upper.find("ON").unwrap_or(0)..];
                    let op = rest.find('(');
                    let cp = rest.rfind(')');
                    match (op, cp) {
                        (Some(o), Some(c)) if c > o => rest[o + 1..c]
                            .split(',')
                            .map(|s| s.trim().trim_matches('`').to_string())
                            .filter(|s| !s.is_empty())
                            .collect(),
                        _ => Vec::new(),
                    }
                } else {
                    match crate::sql::parser::parse_sql(&sql) {
                        Ok(crate::sql::ast::Statement::CreateIndex(ci)) => ci.columns,
                        _ => Vec::new(),
                    }
                };
                // C2 fix: restore the unique flag from the persisted CREATE [UNIQUE] INDEX SQL
                let unique = if is_fts_idx {
                    false
                } else {
                    match crate::sql::parser::parse_sql(&sql) {
                        Ok(crate::sql::ast::Statement::CreateIndex(ci)) => ci.unique,
                        _ => false,
                    }
                };
                let tbl_lower = tbl_name.to_lowercase();
                let idx_name_lower = name.to_lowercase();
                self.indexes_by_table
                    .entry(tbl_lower)
                    .or_default()
                    .push(idx_name_lower.clone());
                self.indexes.insert(
                    idx_name_lower,
                    IndexSchema {
                        name: name.clone(),
                        table_name: tbl_name,
                        columns,
                        root_page,
                        unique,
                        is_fts: is_fts_idx,
                    },
                );
            } else if obj_type == "trigger" {
                // L3: Restore trigger schema from serialized metadata in sql column.
                let tbl_name = match &row[2] {
                    Value::Text(s) => s.to_string(),
                    _ => continue,
                };
                let rowid_val = match &row[3] {
                    Value::Integer(v) => *v,
                    _ => 0,
                };
                let parts: Vec<&str> = sql.splitn(3, '|').collect();
                if parts.len() == 3 {
                    use crate::sql::ast::{TriggerEvent, TriggerTiming};
                    let timing = match parts[0] {
                        "BEFORE" => TriggerTiming::Before,
                        _ => TriggerTiming::After,
                    };
                    let event = match parts[1] {
                        "INSERT" => TriggerEvent::Insert,
                        "UPDATE" => TriggerEvent::Update,
                        _ => TriggerEvent::Delete,
                    };
                    let tbl_lower = tbl_name.to_lowercase();
                    self.triggers
                        .entry(tbl_lower)
                        .or_default()
                        .push(TriggerSchema {
                            name,
                            timing,
                            event,
                            table_name: tbl_name,
                            body_sql: parts[2].to_string(),
                            rowid: rowid_val,
                        });
                }
            } else if obj_type == "rls_enabled" {
                // M5 fix: re-apply persisted RLS flag to the table on reload
                let tbl_key = name.to_lowercase();
                if let Some(tbl) = self.tables.get_mut(&tbl_key) {
                    tbl.rls_enabled = true;
                }
            } else if obj_type == "vector_index" {
                // Phase 2/3: restore HNSW vector index registration from catalog.
                // The sql column holds the full CREATE VECTOR INDEX DDL, which we re-parse.
                // The HNSW graph is initialized empty here; VM::open backfills it from table rows.
                let tbl_name = match &row[2] {
                    Value::Text(s) => s.to_string(),
                    _ => continue,
                };
                // Re-parse the stored DDL to recover dim / distance / column.
                match crate::sql::parser::parse_sql(&sql) {
                    Ok(crate::sql::ast::Statement::CreateVectorIndex(vi_stmt)) => {
                        use crate::vector::{distance::DistanceMetric, VectorIndex};
                        // Look up the column index from the already-loaded table schema.
                        let col_idx = if let Some(tbl) = self.tables.get(&tbl_name.to_lowercase()) {
                            tbl.columns
                                .iter()
                                .find(|c| c.name.eq_ignore_ascii_case(&vi_stmt.column))
                                .map(|c| c.col_index)
                                .unwrap_or(0)
                        } else {
                            0
                        };
                        let metric = match vi_stmt.distance {
                            crate::sql::ast::VecDistanceType::Cosine => DistanceMetric::Cosine,
                            crate::sql::ast::VecDistanceType::L2 => DistanceMetric::L2,
                        };
                        let index_id = self.vector_indexes.alloc_index_id();
                        let vi = VectorIndex::new(
                            vi_stmt.index_name.clone(),
                            tbl_name.clone(),
                            vi_stmt.column.clone(),
                            col_idx,
                            vi_stmt.dim,
                            metric,
                            index_id,
                        );
                        self.vector_indexes.register(vi);
                    }
                    _ => {
                        // Couldn't re-parse DDL — skip (non-fatal, index will be absent until
                        // manually recreated; this can happen during format migrations)
                    }
                }
            }
        }

        Ok(())
    }

    /// L3: Persist a trigger and add to memory schema.
    pub fn save_trigger(&mut self, pager: &mut Pager, trigger: TriggerSchema) -> Result<()> {
        use crate::sql::ast::{TriggerEvent, TriggerTiming};
        let timing_str = match trigger.timing {
            TriggerTiming::Before => "BEFORE",
            TriggerTiming::After => "AFTER",
        };
        let event_str = match trigger.event {
            TriggerEvent::Insert => "INSERT",
            TriggerEvent::Update => "UPDATE",
            TriggerEvent::Delete => "DELETE",
        };
        // Encode: type | name | tbl_name | 0 | "timing|event|body_sql"
        let encoded = format!("{}|{}|{}", timing_str, event_str, trigger.body_sql);
        let schema_row: Row = vec![
            Value::Text("trigger".into()),
            Value::Text(trigger.name.clone().into()),
            Value::Text(trigger.table_name.clone().into()),
            Value::Integer(0),
            Value::Text(encoded.into()),
        ];
        let schema_root = pager.schema_root_page();
        let mut btree = BTree::new(pager);
        let next_rowid = btree.max_rowid(schema_root).unwrap_or(0) + 1;
        let new_root = btree.insert(schema_root, next_rowid, &schema_row)?;
        if new_root != schema_root {
            pager.set_schema_root_page(new_root)?;
        }
        let tbl_lower = trigger.table_name.to_lowercase();
        let mut trigger_mut = trigger;
        trigger_mut.rowid = next_rowid;
        self.triggers
            .entry(tbl_lower)
            .or_default()
            .push(trigger_mut);
        Ok(())
    }

    /// L3: Remove a trigger by name from catalog and memory.
    pub fn drop_trigger_by_name(
        &mut self,
        pager: &mut Pager,
        name: &str,
        if_exists: bool,
    ) -> Result<()> {
        let mut found_rowid = None;
        let mut found_tbl = None;
        let mut found_idx = None;
        'outer: for (tbl, vec) in &self.triggers {
            for (i, t) in vec.iter().enumerate() {
                if t.name.eq_ignore_ascii_case(name) {
                    found_rowid = Some(t.rowid);
                    found_tbl = Some(tbl.clone());
                    found_idx = Some(i);
                    break 'outer;
                }
            }
        }
        match (found_rowid, found_tbl, found_idx) {
            (Some(rowid), Some(tbl), Some(idx)) => {
                let schema_root = pager.schema_root_page();
                let mut btree = BTree::new(pager);
                let (_found, new_root) = btree.delete_by_rowid(schema_root, rowid)?;
                if new_root != schema_root {
                    pager.set_schema_root_page(new_root)?;
                }
                if let Some(vec) = self.triggers.get_mut(&tbl) {
                    vec.remove(idx);
                }
                Ok(())
            }
            _ => {
                if if_exists {
                    Ok(())
                } else {
                    Err(crate::error::KkdbError::RuntimeError(format!(
                        "trigger '{}' does not exist",
                        name
                    )))
                }
            }
        }
    }

    /// L3: Get all triggers for a table matching timing + event.
    pub fn get_triggers(
        &self,
        table_name: &str,
        timing: &crate::sql::ast::TriggerTiming,
        event: &crate::sql::ast::TriggerEvent,
    ) -> Vec<&TriggerSchema> {
        self.triggers
            .get(&table_name.to_lowercase())
            .map(|v| {
                v.iter()
                    .filter(|t| &t.timing == timing && &t.event == event)
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Register a new table in the schema.
    ///
    /// `catalog_pager`: holds the schema B-Tree (pages 1-3).
    /// `table_pager`: the pager where this table's data B-Tree will live
    ///   (same as `catalog_pager` in single-file/memory mode, separate file in multi-file mode).
    #[allow(clippy::too_many_arguments)]
    pub fn create_table(
        &mut self,
        catalog_pager: &mut Pager,
        table_pager: &mut Pager,
        name: &str,
        column_defs: &[ColumnDef],
        if_not_exists: bool,
        original_sql: &str,
        extra_checks: &[(Option<String>, crate::sql::ast::Expr)],
        is_fts: bool,
    ) -> Result<()> {
        let name_lower = name.to_lowercase();
        if self.tables.contains_key(&name_lower) {
            if if_not_exists {
                return Ok(());
            }
            return Err(KkdbError::TableAlreadyExists(name.to_string()));
        }

        // Create a new B-tree for the table (in the table's own pager).
        let root_page = {
            let mut btree = BTree::new(table_pager);
            btree.create_table()?
        };

        // Build column info + FK list + CHECK constraints
        let mut columns = Vec::new();
        let mut foreign_keys = Vec::new();
        let mut check_constraints: Vec<(Option<String>, crate::sql::ast::Expr)> = Vec::new();
        for (i, col_def) in column_defs.iter().enumerate() {
            columns.push(ColumnInfo {
                name: col_def.name.clone(),
                data_type: col_def.data_type.clone(),
                primary_key: col_def.primary_key,
                autoincrement: col_def.autoincrement,
                not_null: col_def.not_null,
                unique: col_def.unique,
                col_index: i,
                stats: None,
            });
            // L1: collect FK references
            if let Some(ref fkref) = col_def.references {
                foreign_keys.push(ForeignKey {
                    col_name: col_def.name.clone(),
                    col_index: i,
                    ref_table: fkref.table.to_ascii_lowercase(),
                    ref_col: fkref.column.clone(),
                    on_delete: fkref.on_delete.clone(),
                    on_update: fkref.on_update.clone(),
                });
            }
            // L2: collect column-level CHECK constraints
            if let Some(ref check) = col_def.check_expr {
                check_constraints.push((None, check.clone()));
            }
        }
        // L2: add table-level CHECK constraints
        for tc in extra_checks {
            check_constraints.push(tc.clone());
        }

        // Insert into schema table (catalog pager).
        let type_val = if is_fts { "fts_table" } else { "table" };
        let schema_row: Row = vec![
            Value::Text(type_val.into()),
            Value::Text(name.to_string().into()),
            Value::Text(name.to_string().into()),
            Value::Integer(root_page as i64),
            Value::Text(original_sql.to_string().into()),
        ];

        let schema_root = catalog_pager.schema_root_page();
        let schema_rowid = {
            let mut btree = BTree::new(catalog_pager);
            let max_id = btree.max_rowid(schema_root).unwrap_or(0);
            max_id + 1
        };

        {
            let mut btree = BTree::new(catalog_pager);
            let new_root = btree.insert(schema_root, schema_rowid, &schema_row)?;
            if new_root != schema_root {
                btree.pager.set_schema_root_page(new_root)?;
            }
        };

        let col_names: Vec<String> = columns.iter().map(|c| c.name.clone()).collect();
        self.tables.insert(
            name_lower,
            TableSchema {
                name: name.to_string(),
                columns,
                col_names,
                root_page,
                next_rowid: 1,
                view_select: None,
                foreign_keys,
                check_constraints,
                is_fts,
                rls_enabled: false,
                policies: Vec::new(),
                clustered_index: true, // InnoDB-style: data in PK order
            },
        );

        Ok(())
    }

    /// Drop a table
    pub fn drop_table(&mut self, pager: &mut Pager, name: &str, if_exists: bool) -> Result<()> {
        let name_lower = name.to_lowercase();
        if !self.tables.contains_key(&name_lower) {
            if if_exists {
                return Ok(());
            }
            return Err(KkdbError::TableNotFound(name.to_string()));
        }

        // Collect index names for this table
        let idx_names: Vec<String> = self
            .indexes
            .values()
            .filter(|idx| idx.table_name.eq_ignore_ascii_case(name))
            .map(|idx| idx.name.clone())
            .collect();

        // Remove table and associated indexes from schema table.
        {
            let mut schema_root = pager.schema_root_page();
            let mut btree = BTree::new(pager);
            let rows = btree.scan_all(schema_root)?;
            for (rowid, row) in rows {
                if row.len() >= 2 {
                    if let Value::Text(ref n) = row[1] {
                        if n.eq_ignore_ascii_case(name)
                            || idx_names.iter().any(|i| i.eq_ignore_ascii_case(n))
                        {
                            let (_, new_root) = btree.delete_by_rowid(schema_root, rowid)?;
                            if new_root != schema_root {
                                btree.pager.set_schema_root_page(new_root)?;
                                schema_root = new_root;
                            }
                        }
                    }
                }
            }
        }

        // Remove from in-memory cache
        for idx_name in &idx_names {
            self.indexes.remove(&idx_name.to_lowercase());
        }
        self.indexes_by_table.remove(&name_lower);
        self.tables.remove(&name_lower);
        Ok(())
    }

    /// Drop an index
    pub fn drop_index(&mut self, pager: &mut Pager, name: &str, if_exists: bool) -> Result<()> {
        let idx_lower = name.to_lowercase();
        let idx = match self.indexes.get(&idx_lower) {
            Some(i) => i.clone(),
            None => {
                if if_exists {
                    return Ok(());
                }
                return Err(KkdbError::Internal(format!("index '{}' not found", name)));
            }
        };

        // Remove from schema table
        let mut schema_root = pager.schema_root_page();
        let mut btree = BTree::new(pager);
        let rows = btree.scan_all(schema_root)?;
        for (rowid, row) in rows {
            if row.len() >= 2 {
                if let Value::Text(ref n) = row[1] {
                    if n.eq_ignore_ascii_case(name) {
                        let (_, new_root) = btree.delete_by_rowid(schema_root, rowid)?;
                        if new_root != schema_root {
                            btree.pager.set_schema_root_page(new_root)?;
                            schema_root = new_root; // keep var in sync before break
                            let _ = schema_root; // suppress unused_assignments
                        }
                        break;
                    }
                }
            }
        }

        // Remove from in-memory caches
        let tbl_lower = idx.table_name.to_lowercase();
        if let Some(list) = self.indexes_by_table.get_mut(&tbl_lower) {
            list.retain(|n| !n.eq_ignore_ascii_case(name));
        }
        self.indexes.remove(&idx_lower);
        Ok(())
    }

    /// Create a new index.
    /// `catalog_pager`: holds the schema B-Tree catalog.
    /// `table_pager`: the pager where this table's data and indexes live.
    #[allow(clippy::too_many_arguments)]
    pub fn create_index(
        &mut self,
        catalog_pager: &mut Pager,
        table_pager: &mut Pager,
        index_name: &str,
        table_name: &str,
        columns: &[String],
        unique: bool,
        if_not_exists: bool,
        original_sql: &str,
    ) -> Result<()> {
        let idx_lower = index_name.to_lowercase();
        if self.indexes.contains_key(&idx_lower) {
            if if_not_exists {
                return Ok(());
            }
            return Err(KkdbError::Internal(format!(
                "index '{}' already exists",
                index_name
            )));
        }

        // Verify table exists and columns are valid
        let table = self.get_table(table_name)?.clone();
        let mut col_indices = Vec::with_capacity(columns.len());
        for col_name in columns {
            let mut found = false;
            for col in &table.columns {
                if col.name.eq_ignore_ascii_case(col_name) {
                    col_indices.push(col.col_index);
                    found = true;
                    break;
                }
            }
            if !found {
                return Err(KkdbError::ColumnNotFound(format!(
                    "{}.{}",
                    table_name, col_name
                )));
            }
        }

        // Create a new B-tree for the index (in the table's own pager).
        let index_root = {
            let mut btree = BTree::new(table_pager);
            btree.create_table()?
        };

        // Populate the index with existing table data (scan from the table pager).
        let mut current_index_root = index_root;
        {
            let mut btree = BTree::new(table_pager);
            let table_rows = btree.scan_all(table.root_page)?;
            let mut idx_rowid = 1i64;
            let mut unique_seen: HashSet<Vec<u8>> = HashSet::new();
            for (tbl_rowid, row) in &table_rows {
                let mut index_row: Row = Vec::with_capacity(col_indices.len() + 1);
                for &ci in &col_indices {
                    index_row.push(if ci < row.len() {
                        row[ci].clone()
                    } else {
                        Value::Null
                    });
                }

                if unique && !index_row.iter().any(|v| matches!(v, Value::Null)) {
                    let key = Self::index_key(&index_row);
                    if !unique_seen.insert(key) {
                        return Err(KkdbError::ConstraintViolation(format!(
                            "UNIQUE constraint failed: {}.{}",
                            table_name,
                            columns.join(", ")
                        )));
                    }
                }

                index_row.push(Value::Integer(*tbl_rowid));
                current_index_root = btree.insert(current_index_root, idx_rowid, &index_row)?;
                idx_rowid += 1;
            }
        }

        // Insert index metadata into schema table (catalog pager).
        let schema_row: Row = vec![
            Value::Text("index".into()),
            Value::Text(index_name.to_string().into()),
            Value::Text(table_name.to_string().into()),
            Value::Integer(current_index_root as i64),
            Value::Text(original_sql.to_string().into()),
        ];
        {
            let schema_root = catalog_pager.schema_root_page();
            let mut btree = BTree::new(catalog_pager);
            let max_id = btree.max_rowid(schema_root).unwrap_or(0);
            let new_root = btree.insert(schema_root, max_id + 1, &schema_row)?;
            if new_root != schema_root {
                btree.pager.set_schema_root_page(new_root)?;
            }
        }

        self.indexes_by_table
            .entry(table_name.to_lowercase())
            .or_default()
            .push(idx_lower.clone());
        self.indexes.insert(
            idx_lower,
            IndexSchema {
                name: index_name.to_string(),
                table_name: table_name.to_string(),
                columns: columns.to_vec(),
                root_page: current_index_root,
                unique,
                is_fts: false,
            },
        );

        Ok(())
    }

    /// Check if any indexes exist for a given table 鈥?O(1)
    #[inline]
    pub fn has_indexes_for_table(&self, table_name: &str) -> bool {
        let key = Self::lowercase_key(table_name);
        self.indexes_by_table
            .get(key.as_ref())
            .is_some_and(|v| !v.is_empty())
    }

    /// Get all indexes for a given table 鈥?O(1) lookup
    pub fn indexes_for_table(&self, table_name: &str) -> Vec<&IndexSchema> {
        let key = Self::lowercase_key(table_name);
        match self.indexes_by_table.get(key.as_ref()) {
            Some(names) => names.iter().filter_map(|n| self.indexes.get(n)).collect(),
            None => Vec::new(),
        }
    }

    /// Register a FTS index schema in memory (without creating a B-Tree page).
    /// Used by exec_create_fulltext_index after persisting the catalog row.
    pub fn register_fts_index(
        &mut self,
        index_name: &str,
        table_name: &str,
        columns: Vec<String>,
        index_id: u32,
    ) {
        let idx_lower = index_name.to_lowercase();
        let tbl_lower = table_name.to_lowercase();
        self.indexes_by_table
            .entry(tbl_lower)
            .or_default()
            .push(idx_lower.clone());
        self.indexes.insert(
            idx_lower,
            IndexSchema {
                name: index_name.to_string(),
                table_name: table_name.to_string(),
                columns,
                root_page: index_id, // repurposed to hold FTS index_id
                unique: false,
                is_fts: true,
            },
        );
    }

    /// Get table schema (avoids heap alloc for names 鈮?28 bytes)
    pub fn get_table(&self, name: &str) -> Result<&TableSchema> {
        let key = Self::lowercase_key(name);
        self.tables
            .get(key.as_ref())
            .ok_or_else(|| KkdbError::TableNotFound(name.to_string()))
    }

    /// Get mutable table schema
    pub fn get_table_mut(&mut self, name: &str) -> Result<&mut TableSchema> {
        let key = Self::lowercase_key(name);
        self.tables
            .get_mut(key.as_ref())
            .ok_or_else(|| KkdbError::TableNotFound(name.to_string()))
    }

    /// Return all user table names
    pub fn list_tables(&self) -> Vec<String> {
        self.tables.keys().cloned().collect()
    }

    /// Add a view (Batch E): store it in memory only (no B-tree, root_page=0)
    pub fn add_view(&mut self, schema: TableSchema) {
        self.tables.insert(schema.name.to_lowercase(), schema);
    }

    /// Produce a lowercase key without heap allocation for short names.
    /// Returns a stack-backed str ref for names 鈮?28 bytes, else heap String.
    #[inline]
    fn lowercase_key(name: &str) -> LowercaseKey<'_> {
        // Fast path: already all-lowercase
        if !name.bytes().any(|b| b.is_ascii_uppercase()) {
            return LowercaseKey::Borrowed(name);
        }
        if name.len() <= 128 {
            let mut buf = [0u8; 128];
            for (i, b) in name.bytes().enumerate() {
                buf[i] = b.to_ascii_lowercase();
            }
            let s = std::str::from_utf8(&buf[..name.len()])
                .unwrap_or(name)
                .to_string();
            LowercaseKey::Owned(s)
        } else {
            LowercaseKey::Owned(name.to_lowercase())
        }
    }

    /// Find column index by name in a table
    pub fn find_column(&self, table_name: &str, col_name: &str) -> Result<usize> {
        let table = self.get_table(table_name)?;
        for col in &table.columns {
            if col.name.eq_ignore_ascii_case(col_name) {
                return Ok(col.col_index);
            }
        }
        Err(KkdbError::ColumnNotFound(format!(
            "{}.{}",
            table_name, col_name
        )))
    }

    // ---- ALTER TABLE operations ----

    /// Add a column to a table. Existing rows get NULL for the new column.
    pub fn alter_add_column(
        &mut self,
        pager: &mut Pager,
        table_name: &str,
        col: &ColumnDef,
    ) -> Result<()> {
        let table = self.get_table(table_name)?.clone();

        // Check for duplicate column name
        if table
            .columns
            .iter()
            .any(|c| c.name.eq_ignore_ascii_case(&col.name))
        {
            return Err(KkdbError::Internal(format!(
                "column '{}' already exists in table '{}'",
                col.name, table_name
            )));
        }

        // Cannot add a NOT NULL column without DEFAULT (existing rows would violate)
        if col.not_null && col.default.is_none() {
            return Err(KkdbError::ConstraintViolation(format!(
                "cannot add NOT NULL column '{}' without DEFAULT",
                col.name
            )));
        }

        // Append NULL (or default) value to every existing row
        let default_value = match &col.default {
            Some(expr) => Self::eval_default_expr(expr)?,
            None => Value::Null,
        };
        {
            let mut btree = BTree::new(pager);
            let rows = btree.scan_all(table.root_page)?;
            for (rowid, mut row) in rows {
                row.push(default_value.clone());
                btree.update_row(table.root_page, rowid, &row)?;
            }
        }

        // Update in-memory schema
        let new_col_index = table.columns.len();
        let tbl = self.get_table_mut(table_name)?;
        tbl.columns.push(ColumnInfo {
            name: col.name.clone(),
            data_type: col.data_type.clone(),
            primary_key: false,
            autoincrement: false,
            not_null: col.not_null,
            unique: col.unique,
            col_index: new_col_index,
            stats: None,
        });
        tbl.col_names.push(col.name.clone());

        // Update schema table SQL
        self.update_schema_sql(pager, table_name)?;
        Ok(())
    }

    /// Drop a column from a table.
    pub fn alter_drop_column(
        &mut self,
        pager: &mut Pager,
        table_name: &str,
        col_name: &str,
    ) -> Result<()> {
        let table = self.get_table(table_name)?.clone();

        let col_idx = table
            .columns
            .iter()
            .find(|c| c.name.eq_ignore_ascii_case(col_name))
            .map(|c| c.col_index)
            .ok_or_else(|| KkdbError::ColumnNotFound(format!("{}.{}", table_name, col_name)))?;

        // Cannot drop primary key column
        if table.columns[col_idx].primary_key {
            return Err(KkdbError::Internal(format!(
                "cannot drop PRIMARY KEY column '{}'",
                col_name
            )));
        }

        // Must have at least 1 column remaining
        if table.columns.len() <= 1 {
            return Err(KkdbError::Internal(
                "cannot drop the only column in a table".into(),
            ));
        }

        // Remove the column value from every row
        {
            let mut btree = BTree::new(pager);
            let rows = btree.scan_all(table.root_page)?;
            for (rowid, row) in rows {
                let mut new_row: Row = Vec::with_capacity(row.len() - 1);
                for (i, val) in row.into_iter().enumerate() {
                    if i != col_idx {
                        new_row.push(val);
                    }
                }
                btree.update_row(table.root_page, rowid, &new_row)?;
            }
        }

        // Drop any indexes that reference this column
        let idx_to_drop: Vec<String> = self
            .indexes
            .values()
            .filter(|idx| {
                idx.table_name.eq_ignore_ascii_case(table_name)
                    && idx.columns.iter().any(|c| c.eq_ignore_ascii_case(col_name))
            })
            .map(|idx| idx.name.clone())
            .collect();
        for idx_name in &idx_to_drop {
            // Remove from schema table
            let mut schema_root = pager.schema_root_page();
            let mut btree = BTree::new(pager);
            let schema_rows = btree.scan_all(schema_root)?;
            for (rowid, row) in schema_rows {
                if row.len() >= 2 {
                    if let Value::Text(ref n) = row[1] {
                        if n.eq_ignore_ascii_case(idx_name) {
                            let (_, new_root) = btree.delete_by_rowid(schema_root, rowid)?;
                            if new_root != schema_root {
                                btree.pager.set_schema_root_page(new_root)?;
                                schema_root = new_root;
                            }
                            break;
                        }
                    }
                }
            }
            self.indexes.remove(&idx_name.to_lowercase());
        }

        // Update in-memory column list
        let tbl = self.get_table_mut(table_name)?;
        tbl.columns
            .retain(|c| !c.name.eq_ignore_ascii_case(col_name));
        // Re-index columns
        for (i, c) in tbl.columns.iter_mut().enumerate() {
            c.col_index = i;
        }
        tbl.col_names = tbl.columns.iter().map(|c| c.name.clone()).collect();

        // Update indexes_by_table: remove dropped indexes
        for idx_name in &idx_to_drop {
            let tbl_lower = table_name.to_lowercase();
            if let Some(names) = self.indexes_by_table.get_mut(&tbl_lower) {
                names.retain(|n| !n.eq_ignore_ascii_case(idx_name));
            }
        }

        // Update schema table SQL
        self.update_schema_sql(pager, table_name)?;
        Ok(())
    }

    /// Rename a table.
    pub fn alter_rename_table(
        &mut self,
        pager: &mut Pager,
        old_name: &str,
        new_name: &str,
    ) -> Result<()> {
        let old_lower = old_name.to_lowercase();
        let new_lower = new_name.to_lowercase();

        if !self.tables.contains_key(&old_lower) {
            return Err(KkdbError::TableNotFound(old_name.to_string()));
        }
        if self.tables.contains_key(&new_lower) {
            return Err(KkdbError::TableAlreadyExists(new_name.to_string()));
        }

        // Update in-memory table
        let mut table = self.tables.remove(&old_lower).unwrap();
        table.name = new_name.to_string();
        self.tables.insert(new_lower.clone(), table);

        // Update index table_name references
        for idx in self.indexes.values_mut() {
            if idx.table_name.eq_ignore_ascii_case(old_name) {
                idx.table_name = new_name.to_string();
            }
        }

        // Move indexes_by_table entry from old to new table name
        if let Some(idx_names) = self.indexes_by_table.remove(&old_lower) {
            self.indexes_by_table.insert(new_lower, idx_names);
        }

        // Update schema table: change name and tbl_name in the row
        {
            let schema_root = pager.schema_root_page();
            let mut btree = BTree::new(pager);
            let rows = btree.scan_all(schema_root)?;
            for (rowid, row) in rows {
                if row.len() >= 5 {
                    if let (Value::Text(ref typ), Value::Text(ref n)) = (&row[0], &row[1]) {
                        if &**typ == "table" && n.eq_ignore_ascii_case(old_name) {
                            let mut new_row = row.clone();
                            new_row[1] = Value::Text(new_name.to_string().into());
                            new_row[2] = Value::Text(new_name.to_string().into());
                            // I28 fix: replace the table name in context-specific positions
                            // (after TABLE keyword) to avoid corrupting column names or
                            // literal values that happen to share the same string as old_name.
                            if let Value::Text(ref sql) = row[4] {
                                // Replace occurrences of old_name that follow a TABLE/INTO/UPDATE
                                // keyword (case-insensitive), bounded by whitespace, paren, or `;`.
                                // This is safer than bare replacen which can hit column names.
                                let mut new_sql = sql.as_ref().to_string();
                                for kw in &["TABLE ", "table ", "Table "] {
                                    let pat = format!("{}{}", kw, old_name);
                                    let repl = format!("{}{}", kw, new_name);
                                    new_sql = new_sql.replacen(&pat, &repl, 1);
                                }
                                new_row[4] = Value::Text(new_sql.into());
                            }
                            let new_root = btree.update_row(schema_root, rowid, &new_row)?;
                            if new_root != schema_root {
                                btree.pager.set_schema_root_page(new_root)?;
                            }
                            break;
                        }
                    }
                }
            }
        }

        Ok(())
    }

    /// Rename a column in a table.
    pub fn alter_rename_column(
        &mut self,
        pager: &mut Pager,
        table_name: &str,
        old_col: &str,
        new_col: &str,
    ) -> Result<()> {
        let table = self.get_table(table_name)?.clone();

        // Verify old column exists
        if !table
            .columns
            .iter()
            .any(|c| c.name.eq_ignore_ascii_case(old_col))
        {
            return Err(KkdbError::ColumnNotFound(format!(
                "{}.{}",
                table_name, old_col
            )));
        }

        // Verify new column name doesn't conflict
        if table
            .columns
            .iter()
            .any(|c| c.name.eq_ignore_ascii_case(new_col))
        {
            return Err(KkdbError::Internal(format!(
                "column '{}' already exists in table '{}'",
                new_col, table_name
            )));
        }

        // Update in-memory column name
        let tbl = self.get_table_mut(table_name)?;
        for col in &mut tbl.columns {
            if col.name.eq_ignore_ascii_case(old_col) {
                col.name = new_col.to_string();
                break;
            }
        }
        tbl.col_names = tbl.columns.iter().map(|c| c.name.clone()).collect();

        // Update index column references
        for idx in self.indexes.values_mut() {
            if idx.table_name.eq_ignore_ascii_case(table_name) {
                for c in &mut idx.columns {
                    if c.eq_ignore_ascii_case(old_col) {
                        *c = new_col.to_string();
                    }
                }
            }
        }

        // Update schema table SQL
        self.update_schema_sql(pager, table_name)?;
        Ok(())
    }

    /// Helper: rebuild and update the SQL stored in the schema table for a given table
    fn update_schema_sql(&self, pager: &mut Pager, table_name: &str) -> Result<()> {
        let table = self.get_table(table_name)?;
        let new_sql = self.rebuild_create_sql(table);

        let schema_root = pager.schema_root_page();
        let mut btree = BTree::new(pager);
        let rows = btree.scan_all(schema_root)?;
        for (rowid, row) in rows {
            if row.len() >= 5 {
                if let (Value::Text(ref typ), Value::Text(ref n)) = (&row[0], &row[1]) {
                    if &**typ == "table" && n.eq_ignore_ascii_case(table_name) {
                        let mut new_row = row.clone();
                        new_row[4] = Value::Text(new_sql.into());
                        let new_root = btree.update_row(schema_root, rowid, &new_row)?;
                        if new_root != schema_root {
                            btree.pager.set_schema_root_page(new_root)?;
                        }
                        return Ok(());
                    }
                }
            }
        }
        Ok(())
    }

    /// Rebuild CREATE TABLE SQL from in-memory schema
    fn rebuild_create_sql(&self, table: &TableSchema) -> String {
        let mut sql = format!("CREATE TABLE {} (", table.name);
        for (i, col) in table.columns.iter().enumerate() {
            if i > 0 {
                sql.push_str(", ");
            }
            sql.push_str(&col.name);
            sql.push(' ');
            sql.push_str(match col.data_type {
                DataType::Null => "BLOB",
                DataType::Integer => "INTEGER",
                DataType::Real => "REAL",
                DataType::Text => "TEXT",
                DataType::Blob => "BLOB",
                DataType::Timestamp => "TIMESTAMP",
            });
            if col.primary_key {
                sql.push_str(" PRIMARY KEY");
            }
            if col.autoincrement {
                sql.push_str(" AUTOINCREMENT");
            }
            if col.not_null && !col.primary_key {
                sql.push_str(" NOT NULL");
            }
            if col.unique && !col.primary_key {
                sql.push_str(" UNIQUE");
            }
        }
        sql.push(')');
        sql
    }

    #[inline]
    pub(crate) fn index_key(values: &[Value]) -> Vec<u8> {
        let mut key = Vec::new();
        for v in values {
            let encoded = v.serialize();
            key.extend_from_slice(&(encoded.len() as u32).to_le_bytes());
            key.extend_from_slice(&encoded);
        }
        key
    }

    fn eval_default_expr(expr: &Expr) -> Result<Value> {
        match expr {
            Expr::Null => Ok(Value::Null),
            Expr::IntegerLiteral(v) => Ok(Value::Integer(*v)),
            Expr::RealLiteral(v) => Ok(Value::Real(*v)),
            Expr::StringLiteral(v) => Ok(Value::Text(v.clone().into())),
            Expr::BlobLiteral(v) => Ok(Value::Blob(v.clone())),
            Expr::Nested(inner) => Self::eval_default_expr(inner),
            Expr::UnaryOp {
                op: UnaryOperator::Minus,
                expr: inner,
            } => match Self::eval_default_expr(inner)? {
                Value::Integer(v) => Ok(Value::Integer(v.wrapping_neg())),
                Value::Real(v) => Ok(Value::Real(-v)),
                _ => Err(KkdbError::ConstraintViolation(
                    "ALTER TABLE ADD COLUMN DEFAULT supports only numeric unary minus".into(),
                )),
            },
            _ => Err(KkdbError::ConstraintViolation(
                "ALTER TABLE ADD COLUMN DEFAULT supports only constant expressions".into(),
            )),
        }
    }
}

#[cfg(test)]
#[path = "schema_tests.rs"]
mod tests;

use super::*;
use crate::storage::pager::Pager;

fn setup() -> (Pager, Schema) {
    let pager = Pager::open_memory();
    let schema = Schema::new();
    (pager, schema)
}

/// Convenience for tests: call create_table with the same pager as both catalog and table.
/// SAFETY: catalog_pager and table_pager point to the same Pager object.
/// In single-file/memory mode this is valid because there is only one B-Tree file.
fn create_table_sp(
    schema: &mut Schema,
    pager: &mut Pager,
    name: &str,
    cols: &[ColumnDef],
    if_not_exists: bool,
    sql: &str,
) -> crate::error::Result<()> {
    // SAFETY: single aliased pager is the same object; OK for memory-mode tests.
    let p2: &mut Pager = unsafe { &mut *(pager as *mut Pager) };
    schema.create_table(pager, p2, name, cols, if_not_exists, sql, &[], false)
}

