#[test]
fn test_parse_subtract_vs_unary_minus() {
    // a - -1 鈫?Subtract(a, UnaryMinus(1))
    match parse("SELECT a - -1 FROM t1") {
        Statement::Select(sel) => {
            if let SelectColumn::Expr { expr, .. } = &sel.columns[0] {
