                        Expr::UnaryOp {
                            op: UnaryOperator::Minus,
                            ..
                        }
                    ));
                } else {
                    panic!("expected Subtract at top")
                }
            } else {
                panic!()
            }
        }
        _ => panic!(),
    }
}

#[test]
fn test_parse_not_backtrack_to_comparison() {
