    match parse("SELECT TRY_CAST(x AS INTEGER) FROM t") {
        Statement::Select(sel) => match &sel.columns[0] {
            SelectColumn::Expr { expr, .. } => {
                assert!(
                    matches!(expr, Expr::Cast { .. }),
                    "TRY_CAST should parse to Cast, got {:?}",
                    expr
                );
            }
            other => panic!("expected SelectColumn::Expr, got {:?}", other),
        },
        _ => panic!("expected Select"),
    }
}

#[test]
fn test_parse_r5_xor_binary_operator() {
    match parse("SELECT a XOR b FROM t") {
        Statement::Select(sel) => match &sel.columns[0] {
            SelectColumn::Expr { expr, .. } => {
                assert!(
                    matches!(
                        expr,
                        Expr::BinaryOp {
                            op: BinaryOperator::Xor,
                            ..
                        }
                    ),
                    "XOR should parse to BinaryOp::Xor, got {:?}",
                    expr
                );
            }
            other => panic!("expected SelectColumn::Expr, got {:?}", other),
        },
        _ => panic!("expected Select"),
    }
}

#[test]
fn test_parse_r5_bitwise_and_operator() {
    match parse("SELECT 5 & 3 FROM t") {
        Statement::Select(sel) => match &sel.columns[0] {
            SelectColumn::Expr { expr, .. } => {
                assert!(
                    matches!(
                        expr,
                        Expr::BinaryOp {
                            op: BinaryOperator::BitwiseAnd,
                            ..
                        }
                    ),
                    "& should parse to BitwiseAnd, got {:?}",
                    expr
                );
            }
            other => panic!("expected SelectColumn::Expr, got {:?}", other),
        },
        _ => panic!("expected Select"),
    }
}

#[test]
fn test_parse_r5_bitwise_or_operator() {
    // PostgreSQL dialect used by sqlparser recognises | as bitwise OR
    let result = parse_sql("SELECT 5 | 3 FROM t");
    if let Ok(Statement::Select(sel)) = result {
        if let SelectColumn::Expr { expr, .. } = &sel.columns[0] {
            assert!(
                matches!(
                    expr,
                    Expr::BinaryOp {
                        op: BinaryOperator::BitwiseOr,
                        ..
                    }
                ),
                "| should parse to BitwiseOr, got {:?}",
                expr
            );
        }
    }
    // Some dialects may not support |, that's ok — just must not panic
}

#[test]
fn test_parse_r5_any_op_eq_becomes_in_subquery() {
    // x = ANY(SELECT ...) → InSubquery
    match parse("SELECT * FROM t WHERE id = ANY(SELECT id FROM s)") {
        Statement::Select(sel) => {
            let where_expr = sel.where_clause.expect("should have WHERE");
            assert!(
                matches!(where_expr, Expr::InSubquery { negated: false, .. }),
                "id = ANY(subq) should become InSubquery, got {:?}",
                where_expr
            );
        }
        _ => panic!("expected Select"),
    }
}

#[test]
fn test_parse_r5_truncate_becomes_delete() {
    // TRUNCATE TABLE t → Statement::Delete with no WHERE clause
    match parse_sql("TRUNCATE TABLE t").unwrap() {
        Statement::Delete(d) => {
            assert_eq!(d.table_name, "t");
            assert!(
                d.where_clause.is_none(),
                "DELETE from TRUNCATE should have no WHERE"
            );
        }
        _ => panic!("expected Delete (from TRUNCATE)"),
    }
}

#[test]
fn test_parse_r5_unary_plus_passthrough() {
    // +42 → IntegerLiteral(42) — Plus is a no-op
    match parse("SELECT +42 FROM t") {
        Statement::Select(sel) => match &sel.columns[0] {
            SelectColumn::Expr { expr, .. } => {
                assert!(
                    matches!(expr, Expr::IntegerLiteral(42)),
                    "+42 should pass through as IntegerLiteral(42), got {:?}",
                    expr
                );
            }
            other => panic!("expected SelectColumn::Expr, got {:?}", other),
        },
        _ => panic!("expected Select"),
    }
}

#[test]
fn test_parse_r5_alter_view_returns_error() {
    let err = parse_sql("ALTER VIEW v RENAME TO v2");
    assert!(err.is_err(), "ALTER VIEW should produce a parse error");
}

#[test]
fn test_parse_r5_create_function_returns_error() {
    let err = parse_sql("CREATE FUNCTION f() RETURNS INTEGER AS $$ SELECT 1 $$ LANGUAGE SQL");
    assert!(err.is_err(), "CREATE FUNCTION should produce a parse error");
}

#[test]
fn test_parse_r5_tuple_single_element_passthrough() {
    // (42) single-element tuple → pass through as the inner expression
    match parse("SELECT (42) FROM t") {
        Statement::Select(sel) => {
            // Should NOT produce an error — either Nested(IntegerLiteral(42)) or just IntegerLiteral(42)
            assert!(!sel.columns.is_empty(), "should have at least one column");
        }
        _ => panic!("expected Select"),
    }
}

use crate::error::{KkdbError, Result};
use crate::types::DataType;
use sqlparser::ast as sa;

pub(super) fn unsupported(feature: impl Into<String>) -> KkdbError {
    KkdbError::ParseError(format!("unsupported SQL feature: {}", feature.into()))
}

pub(super) fn object_name_to_string(name: &sa::ObjectName) -> String {
    name.to_string()
}

pub(super) fn object_name_last_ident(name: &sa::ObjectName) -> Result<String> {
    for part in name.0.iter().rev() {
        if let Some(ident) = part.as_ident() {
            return Ok(ident.value.clone());
        }
    }
    Err(unsupported(format!("invalid object name `{name}`")))
}

pub(super) fn table_alias_to_string(alias: Option<sa::TableAlias>) -> Option<String> {
    alias.map(|a| a.name.value)
}

pub(super) fn convert_data_type(data_type: sa::DataType) -> DataType {
    if data_type == sa::DataType::Unspecified {
        return DataType::Blob;
    }

    let raw = data_type.to_string();
    let head: String = raw
        .chars()
        .take_while(|c| c.is_ascii_alphabetic())
        .map(|c| c.to_ascii_uppercase())
        .collect();

    if head.is_empty() {
        DataType::Text
    } else {
        DataType::from_str(&head)
    }
}

pub(super) fn parse_number_literal(raw: &str) -> Result<crate::sql::ast::Expr> {
    let is_real = raw.contains('.') || raw.contains('e') || raw.contains('E');
    if !is_real {
        if let Ok(v) = raw.parse::<i64>() {
            return Ok(crate::sql::ast::Expr::IntegerLiteral(v));
        }
    }
    let v = raw
        .parse::<f64>()
        .map_err(|_| KkdbError::ParseError(format!("invalid numeric literal `{raw}`")))?;
    Ok(crate::sql::ast::Expr::RealLiteral(v))
}

pub(super) fn parse_blob_hex(hex: &str) -> Result<Vec<u8>> {
    if !hex.len().is_multiple_of(2) {
        return Err(KkdbError::ParseError(format!(
            "invalid blob literal (odd hex length): `{hex}`"
        )));
    }

    let mut out = Vec::with_capacity(hex.len() / 2);
    let bytes = hex.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        let part = std::str::from_utf8(&bytes[i..i + 2]).map_err(|_| {
            KkdbError::ParseError(format!("invalid blob literal utf8 sequence: `{hex}`"))
        })?;
        let b = u8::from_str_radix(part, 16).map_err(|_| {
            KkdbError::ParseError(format!("invalid blob literal hex pair `{part}`"))
        })?;
        out.push(b);
        i += 2;
    }
    Ok(out)
}

use crate::error::Result;
use crate::sql::ast as kk;
use sqlparser::ast as sa;

use super::common::{parse_blob_hex, parse_number_literal, unsupported};
use super::query::convert_query_to_select;

pub(crate) fn convert_expr(expr: sa::Expr) -> Result<kk::Expr> {
    match expr {
        sa::Expr::Identifier(id) => Ok(kk::Expr::ColumnRef {
            table: None,
            column: id.value,
        }),
        sa::Expr::CompoundIdentifier(ids) => convert_compound_identifier(ids),
        sa::Expr::Value(value) => convert_value(value.value),
        sa::Expr::UnaryOp { op, expr } => {
            // Handle operators that can't map to kk::UnaryOperator directly
            match &op {
                // Plus is a no-op: +x = x
                sa::UnaryOperator::Plus => return convert_expr(*expr),
                // PG bitwise NOT ~x → BITWISE_NOT(x)
                sa::UnaryOperator::BitwiseNot => {
                    return Ok(kk::Expr::Function {
                        name: "BITWISE_NOT".to_string(),
                        args: vec![convert_expr(*expr)?],
                        distinct: false,
                    })
                }
                // PG absolute value @x → ABS(x)
                sa::UnaryOperator::PGAbs => {
                    return Ok(kk::Expr::Function {
                        name: "ABS".to_string(),
                        args: vec![convert_expr(*expr)?],
                        distinct: false,
                    })
                }
                // PG square root |/x → SQRT(x)
                sa::UnaryOperator::PGSquareRoot => {
                    return Ok(kk::Expr::Function {
                        name: "SQRT".to_string(),
                        args: vec![convert_expr(*expr)?],
                        distinct: false,
                    })
                }
                // PG cube root ||/x → CBRT(x)
                sa::UnaryOperator::PGCubeRoot => {
                    return Ok(kk::Expr::Function {
                        name: "CBRT".to_string(),
                        args: vec![convert_expr(*expr)?],
                        distinct: false,
                    })
                }
                // PG factorial: !!x or x! → FACTORIAL(x)
                sa::UnaryOperator::PGPrefixFactorial | sa::UnaryOperator::PGPostfixFactorial => {
                    return Ok(kk::Expr::Function {
                        name: "FACTORIAL".to_string(),
                        args: vec![convert_expr(*expr)?],
                        distinct: false,
                    })
                }
                _ => {}
            }
            let op = convert_unary_operator(op)?;
            Ok(kk::Expr::UnaryOp {
                op,
                expr: Box::new(convert_expr(*expr)?),
            })
        }
        sa::Expr::BinaryOp { left, op, right } => {
            // Operators that cannot map to kk::BinaryOperator — rewrite as function calls
            match &op {
                // <=> (MySQL NULL-safe equal) → __IS_NOT_DISTINCT_FROM__(l, r)
                sa::BinaryOperator::Spaceship => {
                    return Ok(kk::Expr::Function {
                        name: "__IS_NOT_DISTINCT_FROM__".to_string(),
                        args: vec![convert_expr(*left)?, convert_expr(*right)?],
                        distinct: false,
                    });
                }
                // a ^ b (PG exponentiation) → POWER(a, b)
                sa::BinaryOperator::PGExp => {
                    return Ok(kk::Expr::Function {
                        name: "POWER".to_string(),
                        args: vec![convert_expr(*left)?, convert_expr(*right)?],
                        distinct: false,
                    });
                }
                // -> or ->> (JSON field access) → JSON_EXTRACT(l, r)
                sa::BinaryOperator::Arrow | sa::BinaryOperator::LongArrow => {
                    return Ok(kk::Expr::Function {
                        name: "JSON_EXTRACT".to_string(),
                        args: vec![convert_expr(*left)?, convert_expr(*right)?],
                        distinct: false,
                    });
                }
                // ^@ (PG starts-with text operator) → STARTS_WITH(l, r)
                sa::BinaryOperator::PGStartsWith => {
                    return Ok(kk::Expr::Function {
                        name: "STARTS_WITH".to_string(),
                        args: vec![convert_expr(*left)?, convert_expr(*right)?],
                        distinct: false,
                    });
                }
                // Regex operators: ~ and ~* → REGEXP_LIKE(l, r)
                sa::BinaryOperator::PGRegexMatch | sa::BinaryOperator::PGRegexIMatch => {
                    return Ok(kk::Expr::Function {
                        name: "REGEXP_LIKE".to_string(),
                        args: vec![convert_expr(*left)?, convert_expr(*right)?],
                        distinct: false,
                    });
                }
                // Regex not-match operators: !~ and !~* → NOT REGEXP_LIKE(l, r)
                sa::BinaryOperator::PGRegexNotMatch | sa::BinaryOperator::PGRegexNotIMatch => {
                    return Ok(kk::Expr::Function {
                        name: "NOT".to_string(),
                        args: vec![kk::Expr::Function {
                            name: "REGEXP_LIKE".to_string(),
                            args: vec![convert_expr(*left)?, convert_expr(*right)?],
                            distinct: false,
                        }],
                        distinct: false,
                    });
                }
                _ => {}
            }
            Ok(kk::Expr::BinaryOp {
                left: Box::new(convert_expr(*left)?),
                op: convert_binary_operator(op)?,
                right: Box::new(convert_expr(*right)?),
            })
        }
        sa::Expr::IsNull(expr) => Ok(kk::Expr::IsNull {
            expr: Box::new(convert_expr(*expr)?),
            negated: false,
        }),
        sa::Expr::IsNotNull(expr) => Ok(kk::Expr::IsNull {
            expr: Box::new(convert_expr(*expr)?),
            negated: true,
        }),
        // IS TRUE / IS FALSE → compare with 1 / 0
        sa::Expr::IsTrue(expr) => Ok(kk::Expr::BinaryOp {
            left: Box::new(convert_expr(*expr)?),
            op: kk::BinaryOperator::Equal,
            right: Box::new(kk::Expr::IntegerLiteral(1)),
        }),
        sa::Expr::IsNotTrue(expr) => Ok(kk::Expr::BinaryOp {
            left: Box::new(convert_expr(*expr)?),
            op: kk::BinaryOperator::NotEqual,
            right: Box::new(kk::Expr::IntegerLiteral(1)),
        }),
        sa::Expr::IsFalse(expr) => Ok(kk::Expr::BinaryOp {
            left: Box::new(convert_expr(*expr)?),
            op: kk::BinaryOperator::Equal,
            right: Box::new(kk::Expr::IntegerLiteral(0)),
        }),
        sa::Expr::IsNotFalse(expr) => Ok(kk::Expr::BinaryOp {
            left: Box::new(convert_expr(*expr)?),
            op: kk::BinaryOperator::NotEqual,
            right: Box::new(kk::Expr::IntegerLiteral(0)),
        }),
        // IS UNKNOWN / IS NOT UNKNOWN → IS NULL / IS NOT NULL
        sa::Expr::IsUnknown(expr) => Ok(kk::Expr::IsNull {
            expr: Box::new(convert_expr(*expr)?),
            negated: false,
        }),
        sa::Expr::IsNotUnknown(expr) => Ok(kk::Expr::IsNull {
            expr: Box::new(convert_expr(*expr)?),
            negated: true,
        }),
        sa::Expr::InList {
            expr,
            list,
            negated,
        } => {
            let mut out = Vec::with_capacity(list.len());
            for item in list {
                out.push(convert_expr(item)?);
            }
            Ok(kk::Expr::InList {
                expr: Box::new(convert_expr(*expr)?),
                list: out,
                negated,
            })
        }
        sa::Expr::InSubquery {
            expr,
            subquery,
            negated,
        } => Ok(kk::Expr::InSubquery {
            expr: Box::new(convert_expr(*expr)?),
            subquery: Box::new(convert_query_to_select(*subquery)?),
            negated,
        }),
        sa::Expr::Like {
            expr,
            pattern,
            escape_char,
            negated,
            ..
        } => {
            let escape = match escape_char {
                Some(sa::Value::SingleQuotedString(s)) if !s.is_empty() => {
                    // SAFETY: guard `!s.is_empty()` ensures at least one char
                    Some(s.chars().next().unwrap())
                }
                Some(sa::Value::DoubleQuotedString(s)) if !s.is_empty() => {
                    // SAFETY: guard `!s.is_empty()` ensures at least one char
                    Some(s.chars().next().unwrap())
                }
                _ => None,
            };
            Ok(kk::Expr::Like {
                expr: Box::new(convert_expr(*expr)?),
                pattern: Box::new(convert_expr(*pattern)?),
                escape_char: escape,
                case_insensitive: false,
                negated,
            })
        }
        sa::Expr::ILike {
            expr,
            pattern,
            escape_char,
            negated,
            ..
        } => {
            let escape = match escape_char {
                Some(sa::Value::SingleQuotedString(s)) if !s.is_empty() => {
                    // SAFETY: guard `!s.is_empty()` ensures at least one char
                    Some(s.chars().next().unwrap())
                }
                Some(sa::Value::DoubleQuotedString(s)) if !s.is_empty() => {
                    // SAFETY: guard `!s.is_empty()` ensures at least one char
                    Some(s.chars().next().unwrap())
                }
                _ => None,
            };
            Ok(kk::Expr::Like {
                expr: Box::new(convert_expr(*expr)?),
                pattern: Box::new(convert_expr(*pattern)?),
                escape_char: escape,
                case_insensitive: true,
                negated,
            })
        }
        sa::Expr::SimilarTo {
            expr,
            pattern,
            negated,
            ..
        }
        | sa::Expr::RLike {
            expr,
            pattern,
            negated,
            ..
        } => {
            let func = kk::Expr::Function {
                name: "REGEXP_LIKE".to_string(),
                args: vec![convert_expr(*expr)?, convert_expr(*pattern)?],
                distinct: false,
            };
            if negated {
                Ok(kk::Expr::Function {
                    name: "NOT".to_string(),
                    args: vec![func],
                    distinct: false,
                })
            } else {
                Ok(func)
            }
        }
        sa::Expr::Between {
            expr,
            low,
            high,
            negated,
        } => Ok(kk::Expr::Between {
            expr: Box::new(convert_expr(*expr)?),
            low: Box::new(convert_expr(*low)?),
            high: Box::new(convert_expr(*high)?),
            negated,
        }),
        sa::Expr::Substring {
            expr,
            substring_from,
            substring_for,
            shorthand,
            ..
        } => {
            let mut args = Vec::with_capacity(3);
            args.push(convert_expr(*expr)?);
            if let Some(from) = substring_from {
                args.push(convert_expr(*from)?);
            }
            if let Some(for_len) = substring_for {
                args.push(convert_expr(*for_len)?);
            }
            Ok(kk::Expr::Function {
                name: if shorthand {
                    "SUBSTR".to_string()
                } else {
                    "SUBSTRING".to_string()
                },
                args,
                distinct: false,
            })
        }
        // TRIM / LTRIM / RTRIM — unified handler (supports LEADING 'x' FROM s)
        sa::Expr::Trim {
            expr,
            trim_where,
            trim_what,
            trim_characters: _,
        } => {
            let func_name = match trim_where {
                Some(sa::TrimWhereField::Leading) => "LTRIM",
                Some(sa::TrimWhereField::Trailing) => "RTRIM",
                _ => "TRIM",
            };
            let mut args = vec![convert_expr(*expr)?];
            if let Some(what) = trim_what {
                args.push(convert_expr(*what)?);
            }
            Ok(kk::Expr::Function {
                name: func_name.to_string(),
                args,
                distinct: false,
            })
        }
        sa::Expr::Function(function) => convert_function(function),
        sa::Expr::Subquery(query) => Ok(kk::Expr::Subquery(Box::new(convert_query_to_select(
            *query,
        )?))),
        sa::Expr::Exists { subquery, negated } => {
            let exists = kk::Expr::Exists(Box::new(convert_query_to_select(*subquery)?));
            if negated {
                Ok(kk::Expr::UnaryOp {
                    op: kk::UnaryOperator::Not,
                    expr: Box::new(exists),
                })
            } else {
                Ok(exists)
            }
        }
        sa::Expr::Nested(expr) => Ok(kk::Expr::Nested(Box::new(convert_expr(*expr)?))),
        sa::Expr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            let operand = operand
                .map(|e| convert_expr(*e).map(Box::new))
                .transpose()?;
            let when_clauses = conditions
                .into_iter()
                .map(|cw| Ok((convert_expr(cw.condition)?, convert_expr(cw.result)?)))
                .collect::<Result<Vec<_>>>()?;
            let else_clause = else_result
                .map(|e| convert_expr(*e).map(Box::new))
                .transpose()?;
            Ok(kk::Expr::Case {
                operand,
                when_clauses,
                else_clause,
            })
        }
        // Cast: CAST(expr AS type), TRY_CAST, SAFE_CAST, x::type (DoubleColon)
        sa::Expr::Cast {
            kind,
            expr,
            data_type,
            ..
        } => {
            let try_cast = matches!(kind, sa::CastKind::TryCast | sa::CastKind::SafeCast);
            Ok(kk::Expr::Cast {
                expr: Box::new(convert_expr(*expr)?),
                to_type: convert_cast_type(data_type),
                try_cast,
            })
        }
        // POSITION(needle IN haystack) → INSTR(haystack, needle) — note reversed args
        sa::Expr::Position { expr, r#in } => Ok(kk::Expr::Function {
            name: "INSTR".to_string(),
            args: vec![convert_expr(*r#in)?, convert_expr(*expr)?],
            distinct: false,
        }),
        // EXTRACT(field FROM expr) → DATE_EXTRACT(field_str, expr)
        sa::Expr::Extract {
            field,
            expr,
            syntax: _,
        } => {
            let field_str = kk::Expr::StringLiteral(format!("{field}"));
            Ok(kk::Expr::Function {
                name: "DATE_EXTRACT".to_string(),
                args: vec![field_str, convert_expr(*expr)?],
                distinct: false,
            })
        }
        // CEIL / FLOOR — sqlparser-rs 0.61+ native AST nodes
        sa::Expr::Ceil { expr, .. } => Ok(kk::Expr::Function {
            name: "CEIL".to_string(),
            args: vec![convert_expr(*expr)?],
            distinct: false,
        }),
        sa::Expr::Floor { expr, .. } => Ok(kk::Expr::Function {
            name: "FLOOR".to_string(),
            args: vec![convert_expr(*expr)?],
            distinct: false,
        }),

        // ── Batch A new arms ──────────────────────────────────────────────────

        // A1. COLLATE: capture internal expression and collation properties natively
        sa::Expr::Collate { expr, collation } => Ok(kk::Expr::Collate {
            expr: Box::new(convert_expr(*expr)?),
            collation: crate::sql::sqlparser_adapter::common::object_name_to_string(&collation),
        }),

        // A2. CONVERT(x, type) → Cast
        sa::Expr::Convert {
            expr,
            data_type: Some(dt),
            ..
        } => Ok(kk::Expr::Cast {
            expr: Box::new(convert_expr(*expr)?),
            to_type: convert_cast_type(dt),
            try_cast: false,
        }),
        sa::Expr::Convert { expr, .. } => convert_expr(*expr),

        // A3. OVERLAY(s PLACING repl FROM pos [FOR len]) → OVERLAY function
        sa::Expr::Overlay {
            expr,
            overlay_what,
            overlay_from,
            overlay_for,
        } => {
            let mut args = vec![
                convert_expr(*expr)?,
                convert_expr(*overlay_what)?,
                convert_expr(*overlay_from)?,
            ];
            if let Some(len) = overlay_for {
                args.push(convert_expr(*len)?);
            }
            Ok(kk::Expr::Function {
                name: "OVERLAY".to_string(),
                args,
                distinct: false,
            })
        }

        // A4. INTERVAL 'n' unit → Native Interval construction
        sa::Expr::Interval(sa::Interval {
            value,
            leading_field,
            ..
        }) => {
            let field_str = leading_field.as_ref().map(|f| f.to_string());
            Ok(kk::Expr::Interval {
                value: Box::new(convert_expr(*value)?),
                leading_field: field_str,
            })
        }

        // A5. TIMESTAMP AT TIME ZONE 'tz' → strip time zone, return inner expression
        sa::Expr::AtTimeZone { timestamp, .. } => convert_expr(*timestamp),

        // IS DISTINCT FROM / IS NOT DISTINCT FROM → NULL-safe equality via CASE WHEN
        sa::Expr::IsDistinctFrom(left, right) => {
            let l = convert_expr(*left)?;
            let r = convert_expr(*right)?;
            // IS DISTINCT FROM: CASE WHEN l IS NULL AND r IS NULL THEN 0
            //                        WHEN l IS NULL OR r IS NULL THEN 1
            //                        WHEN l = r THEN 0 ELSE 1 END
            // Simplified: NOT (l IS NOT DISTINCT FROM r)
            // Use: (l IS NULL AND r IS NOT NULL) OR (l IS NOT NULL AND r IS NULL) OR (l <> r)
            Ok(kk::Expr::Function {
                name: "__IS_DISTINCT_FROM__".to_string(),
                args: vec![l, r],
                distinct: false,
            })
        }
        sa::Expr::IsNotDistinctFrom(left, right) => {
            let l = convert_expr(*left)?;
            let r = convert_expr(*right)?;
            Ok(kk::Expr::Function {
                name: "__IS_NOT_DISTINCT_FROM__".to_string(),
                args: vec![l, r],
                distinct: false,
            })
        }

        // CompoundFieldAccess: a.b.c chain → take outermost two segments as table.column
        sa::Expr::CompoundFieldAccess { root, access_chain } => {
            // Collect the chain into a flat identifier list
            let root_str = match *root {
                sa::Expr::Identifier(id) => id.value,
                sa::Expr::CompoundIdentifier(ids) => ids
                    .into_iter()
                    .map(|i| i.value)
                    .collect::<Vec<_>>()
                    .join("."),
                other => return Err(unsupported(format!("complex field access root `{other}`"))),
            };
            let last = access_chain.last().map(|a| format!("{a}"));
            match last {
                Some(col) => Ok(kk::Expr::ColumnRef {
                    table: Some(root_str),
                    column: col,
                }),
                None => Ok(kk::Expr::ColumnRef {
                    table: None,
                    column: root_str,
                }),
            }
        }

        // TypedString: TIMESTAMP '...', DATE '...', etc. → strip type, keep string value
        // TypedString is a tuple-like variant wrapping a TypedString struct
        sa::Expr::TypedString(ts) => {
            if let Some(s) = ts.value.value.into_string() {
                Ok(kk::Expr::StringLiteral(s))
            } else {
                Ok(kk::Expr::Null)
            }
        }

        // Named expression: SOME_EXPR AS name (dialect-specific) → pass through inner
        sa::Expr::Named { expr, .. } => convert_expr(*expr),

        // IsNormalized → always 1 (assume already normalized)
        sa::Expr::IsNormalized { .. } => Ok(kk::Expr::IntegerLiteral(1)),

        // Prefixed: N'text', E'text' → strip prefix marker, treat as string
        sa::Expr::Prefixed { value, .. } => convert_expr(*value),

        // AnyOp: x = ANY(subq) → InSubquery when op is Eq; others unsupported
        sa::Expr::AnyOp {
            left,
            compare_op,
            right,
            ..
        } => {
            let subquery = match *right {
                sa::Expr::Subquery(q) => convert_query_to_select(*q)?,
                other => {
                    return Err(unsupported(format!(
                        "ANY with non-subquery operand `{other}`"
                    )))
                }
            };
            if compare_op == sa::BinaryOperator::Eq {
                Ok(kk::Expr::InSubquery {
                    expr: Box::new(convert_expr(*left)?),
                    subquery: Box::new(subquery),
                    negated: false,
                })
            } else {
                Ok(kk::Expr::AnyOp {
                    expr: Box::new(convert_expr(*left)?),
                    op: convert_binary_operator(compare_op)?,
                    subquery: Box::new(subquery),
                })
            }
        }

        // Array: ARRAY[1,2,3] → function JSON_ARRAY(1,2,3)
        sa::Expr::Array(sa::Array { elem, .. }) => {
            let mut args = Vec::with_capacity(elem.len());
            for e in elem {
                args.push(convert_expr(e)?);
            }
            Ok(kk::Expr::Function {
                name: "JSON_ARRAY".to_string(),
                args,
                distinct: false,
            })
        }
        // AllOp: x > ALL(subq)
        sa::Expr::AllOp {
            left,
            compare_op,
            right,
            ..
        } => {
            let subquery = match *right {
                sa::Expr::Subquery(q) => convert_query_to_select(*q)?,
                other => {
                    return Err(unsupported(format!(
                        "ALL with non-subquery operand `{other}`"
                    )))
                }
            };
            Ok(kk::Expr::AllOp {
                expr: Box::new(convert_expr(*left)?),
                op: convert_binary_operator(compare_op)?,
                subquery: Box::new(subquery),
            })
        }

        // InUnnest: col IN UNNEST(arr) → JSON_MEMBER_OF
        sa::Expr::InUnnest {
            expr,
            array_expr,
            negated,
        } => {
            let func = kk::Expr::Function {
                name: "JSON_MEMBER_OF".to_string(),
                args: vec![convert_expr(*expr)?, convert_expr(*array_expr)?],
                distinct: false,
            };
            if negated {
                Ok(kk::Expr::Function {
                    name: "NOT".to_string(),
                    args: vec![func],
                    distinct: false,
                })
            } else {
                Ok(func)
            }
        }

        // JsonAccess: col->'path' → JSON_EXTRACT(col, 'path_str')
        sa::Expr::JsonAccess { value, path } => Ok(kk::Expr::Function {
            name: "JSON_EXTRACT".to_string(),
            args: vec![
                convert_expr(*value)?,
                kk::Expr::StringLiteral(format!("{path}")),
            ],
            distinct: false,
        }),

        // arr[idx] → ARRAY_GET placeholder (no Expr::Index in sqlparser-rs 0.61; this is handled via CompoundFieldAccess or JsonAccess)
        // Tuple: (a, b, c) → pass through if single element, else unsupported
        sa::Expr::Tuple(elements) => {
            if elements.len() == 1 {
                // SAFETY: len() == 1 guarantees next() returns Some
                convert_expr(elements.into_iter().next().unwrap())
            } else {
                Err(unsupported("tuple constructor expression"))
            }
        }

        // MemberOf: x MEMBER OF(arr) → placeholder function
        sa::Expr::MemberOf(member_of) => Ok(kk::Expr::Function {
            name: "JSON_MEMBER_OF".to_string(),
            args: vec![
                convert_expr(*member_of.value)?,
                convert_expr(*member_of.array)?,
            ],
            distinct: false,
        }),

        // Wildcard in expression context (rare) → treat as 1
        sa::Expr::Wildcard(..) => Ok(kk::Expr::IntegerLiteral(1)),
        sa::Expr::QualifiedWildcard(..) => Err(unsupported("qualified wildcard in expression")),

        // Oracle-specific, MySQL FTS, other dialect-specific
        sa::Expr::OuterJoin(expr) => convert_expr(*expr), // Ignore (+) safely
        sa::Expr::Prior(_expr) => Err(unsupported("Oracle CONNECT BY PRIOR")),
        sa::Expr::Lambda(..) => Err(unsupported("Lambda expressions (x -> y)")),
        sa::Expr::MatchAgainst {
            columns,
            match_value,
            ..
        } => {
            // Extract column names (MySQL: ObjectName list)
            let col_names = columns
                .iter()
                .map(super::common::object_name_to_string)
                .collect::<Vec<_>>();

            // Extract the search string from the match_value (single-quoted string)
            let query_str = match match_value {
                sa::Value::SingleQuotedString(s) | sa::Value::DoubleQuotedString(s) => s,
                other => format!("{other}"),
            };

            Ok(kk::Expr::MatchAgainst {
                columns: col_names,
                query: query_str,
            })
        }
        sa::Expr::GroupingSets(..) | sa::Expr::Cube(..) | sa::Expr::Rollup(..) => Err(unsupported(
            "GROUPING SETS / CUBE / ROLLUP modifiers in GROUP BY",
        )),
        sa::Expr::Struct { .. } => Err(unsupported("STRUCT expression")),
        sa::Expr::Dictionary(values) => {
            let mut args = Vec::with_capacity(values.len() * 2);
            for d in values {
                let k_str = d.key.value.clone();
                args.push(kk::Expr::StringLiteral(k_str));
                args.push(convert_expr(*d.value.clone())?);
            }
            Ok(kk::Expr::Function {
                name: "JSON_OBJECT".to_string(),
                args,
                distinct: false,
            })
        }
        sa::Expr::Map(..) => Err(unsupported("MAP expression")),
    }
}

fn convert_cast_type(data_type: sqlparser::ast::DataType) -> kk::CastTargetType {
    let raw = data_type.to_string();
    let head: String = raw
        .chars()
        .take_while(|c| c.is_ascii_alphabetic())
        .map(|c| c.to_ascii_uppercase())
        .collect();
    match head.as_str() {
        "INT" | "INTEGER" | "INT2" | "INT4" | "INT8" | "BIGINT" | "SMALLINT" | "TINYINT"
        | "BOOLEAN" | "BOOL" => kk::CastTargetType::Integer,
        "REAL" | "FLOAT" | "FLOAT4" | "FLOAT8" | "DOUBLE" => kk::CastTargetType::Real,
        "TEXT" | "VARCHAR" | "CHAR" | "CHARACTER" | "CLOB" | "STRING" | "NCHAR" | "NVARCHAR" => {
            kk::CastTargetType::Text
        }
        "BLOB" | "BYTES" | "BYTEA" | "BINARY" | "VARBINARY" => kk::CastTargetType::Blob,
        "NUMERIC" | "DECIMAL" | "DEC" | "NUMBER" => kk::CastTargetType::Numeric,
        // Temporal types — stored as Text (ISO 8601), exposed as distinct cast types
        "DATE" => kk::CastTargetType::Date,
        "TIME" => kk::CastTargetType::Time,
        "TIMESTAMP" | "DATETIME" => kk::CastTargetType::Timestamp,
        // JSON — stored as Text
        "JSON" | "JSONB" => kk::CastTargetType::Json,
        _ => kk::CastTargetType::Text,
    }
}

fn convert_function(function: sa::Function) -> Result<kk::Expr> {
    let sa::Function {
        name,
        parameters,
        args,
        filter,
        null_treatment,
        over,
        within_group,
        ..
    } = function;

    if !matches!(parameters, sa::FunctionArguments::None) {
        return Err(unsupported("function parameters"));
    }
    // A6: filter is handled below (inline CASE WHEN rewrite)
    if null_treatment.is_some() {
        return Err(unsupported("function NULL treatment clause"));
    }
    // Bug 3 fix: OVER clause → convert to WindowFunction
    if let Some(window_type) = over {
        let func_name_str = name.to_string();
        let distinct_flag = matches!(
            &args,
            sa::FunctionArguments::List(l) if matches!(l.duplicate_treatment, Some(sa::DuplicateTreatment::Distinct))
        );
        let mut out_args = Vec::new();
        if let sa::FunctionArguments::List(ref list) = args {
            for arg in &list.args {
                if let sa::FunctionArg::Unnamed(sa::FunctionArgExpr::Expr(e)) = arg {
                    if let Ok(converted) = convert_expr(e.clone()) {
                        out_args.push(converted);
                    }
                }
            }
        }
        // Extract partition_by and order_by from window spec
        let (partition_by, order_by, frame) = match &window_type {
            sa::WindowType::WindowSpec(spec) => {
                let pb: Vec<kk::Expr> = spec
                    .partition_by
                    .iter()
                    .filter_map(|e| convert_expr(e.clone()).ok())
                    .collect();
                let ob: Vec<kk::OrderByItem> = spec
                    .order_by
                    .iter()
                    .map(|item| kk::OrderByItem {
                        expr: convert_expr(item.expr.clone()).unwrap_or(kk::Expr::Null),
                        ascending: item.options.asc.unwrap_or(true),
                        nulls_first: item.options.nulls_first,
                    })
                    .collect();
                let frame = if let Some(wf) = &spec.window_frame {
                    convert_window_frame(wf).ok()
                } else {
                    None
                };
                (pb, ob, frame)
            }
            sa::WindowType::NamedWindow(name) => {
                // Return a placeholder for named windows (resolved in eval_expr later)
                // For now we just store the name as a dummy column ref in partition_by
                let dummy_pb = vec![kk::Expr::ColumnRef {
                    table: None,
                    column: format!("__named_window_{}", name),
                }];
                (dummy_pb, Vec::new(), None)
            }
        };
        let func_variant = match func_name_str.to_uppercase().as_str() {
            "ROW_NUMBER" => kk::WindowFunc::RowNumber,
            "RANK" => kk::WindowFunc::Rank,
            "DENSE_RANK" => kk::WindowFunc::DenseRank,
            "NTILE" => kk::WindowFunc::Ntile(Box::new(
                out_args.first().cloned().unwrap_or(kk::Expr::Null),
            )),
            "LAG" => kk::WindowFunc::Lag {
                expr: Box::new(out_args.first().cloned().unwrap_or(kk::Expr::Null)),
                offset: out_args.get(1).cloned().map(Box::new),
                default: out_args.get(2).cloned().map(Box::new),
            },
            "LEAD" => kk::WindowFunc::Lead {
                expr: Box::new(out_args.first().cloned().unwrap_or(kk::Expr::Null)),
                offset: out_args.get(1).cloned().map(Box::new),
                default: out_args.get(2).cloned().map(Box::new),
            },
            "FIRST_VALUE" => kk::WindowFunc::FirstValue(Box::new(
                out_args.first().cloned().unwrap_or(kk::Expr::Null),
            )),
            "LAST_VALUE" => kk::WindowFunc::LastValue(Box::new(
                out_args.first().cloned().unwrap_or(kk::Expr::Null),
            )),
            "NTH_VALUE" => kk::WindowFunc::NthValue(
                Box::new(out_args.first().cloned().unwrap_or(kk::Expr::Null)),
                Box::new(out_args.get(1).cloned().unwrap_or(kk::Expr::Null)),
            ),
            _ => kk::WindowFunc::Aggregate {
                name: func_name_str.clone(),
                args: out_args,
                distinct: distinct_flag,
            },
        };
        return Ok(kk::Expr::WindowFunction {
            func: func_variant,
            partition_by,
            order_by,
            frame,
        });
    }
    if !within_group.is_empty() {
        return Err(unsupported("WITHIN GROUP"));
    }

    let func_name = name.to_string();
    let mut distinct = false;
    let mut out_args = Vec::new();

    match args {
        sa::FunctionArguments::None => {}
        sa::FunctionArguments::Subquery(query) => {
            out_args.push(kk::Expr::Subquery(Box::new(convert_query_to_select(
                *query,
            )?)));
        }
        sa::FunctionArguments::List(list) => {
            distinct = matches!(
                list.duplicate_treatment,
                Some(sa::DuplicateTreatment::Distinct)
            );
            if !list.clauses.is_empty() {
                return Err(unsupported("function argument clauses"));
            }
            for arg in list.args {
                convert_function_arg(arg, &func_name, &mut out_args)?;
            }
        }
    }

    // A6. FILTER (WHERE cond): rewrite each non-wildcard arg as CASE WHEN cond THEN arg ELSE NULL END
    // This makes COUNT(*) FILTER (WHERE x > 0) work as COUNT(CASE WHEN x > 0 THEN 1 ELSE NULL END)
    if let Some(filter_clause) = filter {
        let cond = convert_expr(*filter_clause)?;
        out_args = out_args
            .into_iter()
            .map(|arg| kk::Expr::Case {
                operand: None,
                when_clauses: vec![(cond.clone(), arg)],
                else_clause: Some(Box::new(kk::Expr::Null)),
            })
            .collect();
        // Handle COUNT(*) / COUNT(1) special case: if no args, use CASE WHEN cond THEN 1 ELSE NULL
        if out_args.is_empty() && func_name.eq_ignore_ascii_case("COUNT") {
            out_args.push(kk::Expr::Case {
                operand: None,
                when_clauses: vec![(cond, kk::Expr::IntegerLiteral(1))],
                else_clause: Some(Box::new(kk::Expr::Null)),
            });
        }
    }

    Ok(kk::Expr::Function {
        name: func_name,
        args: out_args,
        distinct,
    })
}

pub(crate) fn convert_window_frame(wf: &sa::WindowFrame) -> Result<kk::WindowFrame> {
    let unit = match wf.units {
        sa::WindowFrameUnits::Rows => kk::WindowFrameUnit::Rows,
        sa::WindowFrameUnits::Range => kk::WindowFrameUnit::Range,
        sa::WindowFrameUnits::Groups => kk::WindowFrameUnit::Groups,
    };
    let start = convert_window_bound(&wf.start_bound)?;
    let end = if let Some(eb) = &wf.end_bound {
        Some(convert_window_bound(eb)?)
    } else {
        None
    };
    Ok(kk::WindowFrame { unit, start, end })
}

pub(crate) fn convert_window_bound(wb: &sa::WindowFrameBound) -> Result<kk::WindowBound> {
    match wb {
        sa::WindowFrameBound::CurrentRow => Ok(kk::WindowBound::CurrentRow),
        sa::WindowFrameBound::Preceding(Some(e)) => Ok(kk::WindowBound::Preceding(Box::new(
            convert_expr(*e.clone())?,
        ))),
        sa::WindowFrameBound::Preceding(None) => Ok(kk::WindowBound::UnboundedPreceding),
        sa::WindowFrameBound::Following(Some(e)) => Ok(kk::WindowBound::Following(Box::new(
            convert_expr(*e.clone())?,
        ))),
        sa::WindowFrameBound::Following(None) => Ok(kk::WindowBound::UnboundedFollowing),
    }
}

fn convert_function_arg(
    arg: sa::FunctionArg,
    function_name: &str,
    out: &mut Vec<kk::Expr>,
) -> Result<()> {
    let inner = match arg {
        sa::FunctionArg::Unnamed(a)
        | sa::FunctionArg::Named { arg: a, .. }
        | sa::FunctionArg::ExprNamed { arg: a, .. } => a,
    };
    convert_function_arg_expr(inner, function_name, out)
}

fn convert_function_arg_expr(
    arg: sa::FunctionArgExpr,
    function_name: &str,
    out: &mut Vec<kk::Expr>,
) -> Result<()> {
    match arg {
        sa::FunctionArgExpr::Expr(expr) => {
            out.push(convert_expr(expr)?);
            Ok(())
        }
        sa::FunctionArgExpr::Wildcard | sa::FunctionArgExpr::QualifiedWildcard(_) => {
            if function_name.eq_ignore_ascii_case("COUNT") {
                out.push(kk::Expr::IntegerLiteral(1));
                Ok(())
            } else {
                Err(unsupported(format!(
                    "wildcard argument in function `{function_name}`"
                )))
            }
        }
    }
}

fn convert_value(value: sa::Value) -> Result<kk::Expr> {
    match value {
        sa::Value::Number(raw, _) => parse_number_literal(&raw),
        sa::Value::HexStringLiteral(hex) => Ok(kk::Expr::BlobLiteral(parse_blob_hex(&hex)?)),
        sa::Value::SingleQuotedByteStringLiteral(bytes)
        | sa::Value::DoubleQuotedByteStringLiteral(bytes)
        | sa::Value::TripleSingleQuotedByteStringLiteral(bytes)
        | sa::Value::TripleDoubleQuotedByteStringLiteral(bytes) => {
            Ok(kk::Expr::BlobLiteral(bytes.into_bytes()))
        }
        sa::Value::Null => Ok(kk::Expr::Null),
        sa::Value::Boolean(v) => Ok(kk::Expr::IntegerLiteral(if v { 1 } else { 0 })),
        sa::Value::Placeholder(_) => {
            // Assign the next sequential 0-based index for this `?` parameter.
            Ok(kk::Expr::Placeholder(super::next_placeholder_idx()))
        }
        other => {
            if let Some(s) = other.into_string() {
                Ok(kk::Expr::StringLiteral(s))
            } else {
                Err(unsupported("literal value"))
            }
        }
    }
}

fn convert_compound_identifier(ids: Vec<sa::Ident>) -> Result<kk::Expr> {
    if ids.is_empty() {
        return Err(unsupported("empty compound identifier"));
    }
    let mut parts: Vec<String> = ids.into_iter().map(|i| i.value).collect();
    // SAFETY: early return above ensures `parts` is non-empty
    let column = parts.pop().unwrap();
    if parts.is_empty() {
        Ok(kk::Expr::ColumnRef {
            table: None,
            column,
        })
    } else {
        Ok(kk::Expr::ColumnRef {
            table: Some(parts.join(".")),
            column,
        })
    }
}

fn convert_binary_operator(op: sa::BinaryOperator) -> Result<kk::BinaryOperator> {
    match op {
        sa::BinaryOperator::Plus => Ok(kk::BinaryOperator::Add),
        sa::BinaryOperator::Minus => Ok(kk::BinaryOperator::Subtract),
        sa::BinaryOperator::Multiply => Ok(kk::BinaryOperator::Multiply),
        sa::BinaryOperator::Divide => Ok(kk::BinaryOperator::Divide),
        sa::BinaryOperator::Modulo => Ok(kk::BinaryOperator::Modulo),
        sa::BinaryOperator::Eq => Ok(kk::BinaryOperator::Equal),
        sa::BinaryOperator::NotEq => Ok(kk::BinaryOperator::NotEqual),
        sa::BinaryOperator::Lt => Ok(kk::BinaryOperator::LessThan),
        sa::BinaryOperator::LtEq => Ok(kk::BinaryOperator::LessThanOrEqual),
        sa::BinaryOperator::Gt => Ok(kk::BinaryOperator::GreaterThan),
        sa::BinaryOperator::GtEq => Ok(kk::BinaryOperator::GreaterThanOrEqual),
        sa::BinaryOperator::And => Ok(kk::BinaryOperator::And),
        sa::BinaryOperator::Or => Ok(kk::BinaryOperator::Or),
        sa::BinaryOperator::StringConcat => Ok(kk::BinaryOperator::Concat),
        // Logical XOR
        sa::BinaryOperator::Xor => Ok(kk::BinaryOperator::Xor),
        // Bitwise operators
        sa::BinaryOperator::BitwiseOr => Ok(kk::BinaryOperator::BitwiseOr),
        sa::BinaryOperator::BitwiseAnd => Ok(kk::BinaryOperator::BitwiseAnd),
        sa::BinaryOperator::BitwiseXor | sa::BinaryOperator::PGBitwiseXor => {
            Ok(kk::BinaryOperator::BitwiseXor)
        }
        sa::BinaryOperator::PGBitwiseShiftLeft => Ok(kk::BinaryOperator::ShiftLeft),
        sa::BinaryOperator::PGBitwiseShiftRight => Ok(kk::BinaryOperator::ShiftRight),
        // Integer divide → wrap as function (div by zero → NULL)
        sa::BinaryOperator::DuckIntegerDivide | sa::BinaryOperator::MyIntegerDivide => {
            // This path is hit only when the op is not wrapped in an Expr variant
            // In practice the outer handler will wrap it with a Cast; return Divide as best effort
            Ok(kk::BinaryOperator::Divide)
        }
        // L4: FTS MATCH operator
        sa::BinaryOperator::Match => Ok(kk::BinaryOperator::FtsMatch),
        // Regex / LIKE-variant operators → unsupported (would silently return wrong results if mapped to Equal)
        sa::BinaryOperator::PGRegexMatch
        | sa::BinaryOperator::PGILikeMatch
        | sa::BinaryOperator::Regexp
        | sa::BinaryOperator::PGRegexIMatch
        | sa::BinaryOperator::PGRegexNotMatch
        | sa::BinaryOperator::PGRegexNotIMatch
        | sa::BinaryOperator::PGLikeMatch
        | sa::BinaryOperator::PGNotLikeMatch
        | sa::BinaryOperator::PGNotILikeMatch => {
            Err(unsupported(format!("regex/LIKE binary operator `{op}`")))
        }
        other => Err(unsupported(format!("binary operator `{other}`"))),
    }
}

fn convert_unary_operator(op: sa::UnaryOperator) -> Result<kk::UnaryOperator> {
    match op {
        sa::UnaryOperator::Minus => Ok(kk::UnaryOperator::Minus),
        sa::UnaryOperator::Not | sa::UnaryOperator::BangNot => Ok(kk::UnaryOperator::Not),
        other => Err(unsupported(format!("unary operator `{other}`"))),
    }
}

use crate::error::{KkdbError, Result};
use crate::sql::ast as kk;
use sqlparser::dialect::SQLiteDialect;
use sqlparser::parser::Parser as SqlParser;
use std::cell::Cell;

mod common;
mod expr;
mod query;
mod statement;

// ── Thread-local placeholder index counter ────────────────────────────────────
// Tracks how many `?` tokens have been encountered while converting a single
// SQL statement so we can assign sequential 0-based indexes.
thread_local! {
    static PLACEHOLDER_IDX: Cell<usize> = const { Cell::new(0) };
}

/// Reset the per-statement `?` counter.  Called once before each parse.
fn reset_placeholder_counter() {
    PLACEHOLDER_IDX.with(|c| c.set(0));
}

/// Return the next 0-based index for a `?` placeholder and advance the counter.
pub(super) fn next_placeholder_idx() -> usize {
    PLACEHOLDER_IDX.with(|c| {
        let idx = c.get();
        c.set(idx + 1);
        idx
    })
}

pub fn parse_sql_with_sqlparser(sql: &str) -> Result<kk::Statement> {
    let trimmed = sql.trim();
    if trimmed.is_empty() {
        return Err(KkdbError::ParseError("unexpected end of input".into()));
    }

    // Reset `?` placeholder index counter for this statement.
    reset_placeholder_counter();

    // Intercept `CREATE FULLTEXT INDEX` before handing to sqlparser.
    // sqlparser 0.61 does not expose a `full_text` field on CreateIndex.
    // We detect and parse this DDL manually.
    if let Some(stmt) = try_parse_create_fulltext_index(trimmed) {
        return stmt;
    }

    // Intercept `CREATE VECTOR INDEX` — same approach; sqlparser has no vector support.
    if let Some(stmt) = try_parse_create_vector_index(trimmed) {
        return stmt;
    }

    // Intercept `DROP VECTOR INDEX` — sqlparser has no vector support.
    if let Some(stmt) = try_parse_drop_vector_index(trimmed) {
        return stmt;
    }

    // Intercept `SHOW ENGINE STATUS` / `SHOW ENGINE INNODB STATUS` — not in sqlparser.
    {
        let upper = trimmed.to_ascii_uppercase();
        let upper_trimmed = upper.trim_end_matches(';').trim();
        if upper_trimmed == "SHOW ENGINE STATUS"
            || upper_trimmed == "SHOW ENGINE INNODB STATUS"
        {
            return Ok(kk::Statement::ShowEngineStatus);
        }
    }

    let dialect = SQLiteDialect {};
    let mut statements =
        SqlParser::parse_sql(&dialect, sql).map_err(|e| KkdbError::ParseError(e.to_string()))?;

    if statements.is_empty() {
        return Err(KkdbError::ParseError("unexpected end of input".into()));
    }
    if statements.len() != 1 {
        return Err(KkdbError::ParseError(
            "only a single SQL statement is supported".into(),
        ));
    }

    statement::convert_statement(statements.remove(0))
}

/// Attempt to parse `CREATE [UNIQUE] FULLTEXT INDEX name ON table (col1, col2, ...) [IF NOT EXISTS]`
/// Returns Some(Result<Statement>) if the SQL looks like a FULLTEXT index DDL, else None.
fn try_parse_create_fulltext_index(sql: &str) -> Option<Result<kk::Statement>> {
    // Fast path: must contain FULLTEXT (case-insensitive)
    let upper = sql.to_ascii_uppercase();
    if !upper.contains("FULLTEXT") {
        return None;
    }

    // Tokenise by whitespace and punctuation (comma / paren).
    // Expected grammar (simplified, case-insensitive):
    // CREATE [UNIQUE] FULLTEXT INDEX [IF NOT EXISTS] name ON table ( columns... )
    let tokens: Vec<&str> = sql.split_whitespace().collect();

    // Must start with CREATE
    if tokens
        .first()
        .map(|t| t.to_ascii_uppercase().as_str() != "CREATE")
        .unwrap_or(true)
    {
        return None;
    }

    // Walk past CREATE [UNIQUE]
    let mut idx = 1;
    if tokens
        .get(idx)
        .map(|t| t.eq_ignore_ascii_case("UNIQUE"))
        .unwrap_or(false)
    {
        idx += 1; // skip UNIQUE (UNIQUE FULLTEXT INDEX is valid MySQL)
    }

    // Must have FULLTEXT
    if tokens
        .get(idx)
        .map(|t| !t.eq_ignore_ascii_case("FULLTEXT"))
        .unwrap_or(true)
    {
        return None;
    }
    idx += 1;

    // Must have INDEX
    if tokens
        .get(idx)
        .map(|t| !t.eq_ignore_ascii_case("INDEX"))
        .unwrap_or(true)
    {
        return None;
    }
    idx += 1;

    // Optional IF NOT EXISTS
    let mut if_not_exists = false;
    if tokens
        .get(idx)
        .map(|t| t.eq_ignore_ascii_case("IF"))
        .unwrap_or(false)
    {
        idx += 1;
        if tokens
            .get(idx)
            .map(|t| t.eq_ignore_ascii_case("NOT"))
            .unwrap_or(false)
        {
            idx += 1;
        }
        if tokens
            .get(idx)
            .map(|t| t.eq_ignore_ascii_case("EXISTS"))
            .unwrap_or(false)
        {
            idx += 1;
        }
        if_not_exists = true;
    }

    // Index name
    let index_name = match tokens.get(idx) {
        Some(t) => t
            .trim_matches(|c: char| !c.is_alphanumeric() && c != '_')
            .to_string(),
        None => {
            return Some(Err(KkdbError::ParseError(
                "FULLTEXT INDEX missing name".into(),
            )))
        }
    };
    idx += 1;

    // ON
    if tokens
        .get(idx)
        .map(|t| !t.eq_ignore_ascii_case("ON"))
        .unwrap_or(true)
    {
        return Some(Err(KkdbError::ParseError(
            "FULLTEXT INDEX missing ON clause".into(),
        )));
    }
    idx += 1;

    // Table name
    let table_name_raw = match tokens.get(idx) {
        Some(t) => *t,
        None => {
            return Some(Err(KkdbError::ParseError(
                "FULLTEXT INDEX missing table name".into(),
            )))
        }
    };
    let _ = idx; // columns extracted from raw SQL below; idx pointer no longer needed

    // Strip table name from any leading `(`, e.g. `mytable(col1, col2)` all in one token.
    let table_name = if let Some(pos) = table_name_raw.find('(') {
        table_name_raw[..pos].to_string()
    } else {
        table_name_raw.to_string()
    };

    // Extract column list from the remainder of the SQL after the table name.
    // Find the `(...)` section in the original sql.
    let rest = &sql[sql.to_ascii_uppercase().find("ON").unwrap_or(0)..];
    let open_paren = rest.find('(');
    let close_paren = rest.rfind(')');
    let columns: Vec<String> = match (open_paren, close_paren) {
        (Some(op), Some(cp)) if cp > op => {
            let cols_str = &rest[op + 1..cp];
            cols_str
                .split(',')
                .map(|c| c.trim().trim_matches('`').trim_matches('"').to_string())
                .filter(|c| !c.is_empty())
                .collect()
        }
        _ => {
            return Some(Err(KkdbError::ParseError(
                "FULLTEXT INDEX missing column list".into(),
            )))
        }
    };

    Some(Ok(kk::Statement::CreateFulltextIndex(
        kk::CreateFulltextIndexStmt {
            index_name,
            table_name: table_name.trim_matches('`').to_string(),
            columns,
            if_not_exists,
        },
    )))
}

/// Attempt to parse:
/// `CREATE VECTOR INDEX [IF NOT EXISTS] name ON table (col) DIM N [DISTANCE COSINE|L2]`
///
/// Returns `Some(Result<Statement>)` when the SQL looks like a vector index DDL, else `None`.
fn try_parse_create_vector_index(sql: &str) -> Option<Result<kk::Statement>> {
    let upper = sql.to_ascii_uppercase();
    if !upper.contains("VECTOR") {
        return None;
    }

    let tokens: Vec<&str> = sql.split_whitespace().collect();

    // Must start with CREATE
    if tokens
        .first()
        .map(|t| !t.eq_ignore_ascii_case("CREATE"))
        .unwrap_or(true)
    {
        return None;
    }
    let mut idx = 1;

    // Must have VECTOR
    if tokens
        .get(idx)
        .map(|t| !t.eq_ignore_ascii_case("VECTOR"))
        .unwrap_or(true)
    {
        return None;
    }
    idx += 1;

    // Must have INDEX
    if tokens
        .get(idx)
        .map(|t| !t.eq_ignore_ascii_case("INDEX"))
        .unwrap_or(true)
    {
        return None;
    }
    idx += 1;

    // Optional IF NOT EXISTS
    let mut if_not_exists = false;
    if tokens
        .get(idx)
        .map(|t| t.eq_ignore_ascii_case("IF"))
        .unwrap_or(false)
    {
        idx += 1;
        if tokens
            .get(idx)
            .map(|t| t.eq_ignore_ascii_case("NOT"))
            .unwrap_or(false)
        {
            idx += 1;
        }
        if tokens
            .get(idx)
            .map(|t| t.eq_ignore_ascii_case("EXISTS"))
            .unwrap_or(false)
        {
            idx += 1;
        }
        if_not_exists = true;
    }

    // Index name
    let index_name = match tokens.get(idx) {
        Some(t) => t
            .trim_matches(|c: char| !c.is_alphanumeric() && c != '_')
            .to_string(),
        None => {
            return Some(Err(KkdbError::ParseError(
                "VECTOR INDEX missing name".into(),
            )))
        }
    };
    idx += 1;

    // ON
    if tokens
        .get(idx)
        .map(|t| !t.eq_ignore_ascii_case("ON"))
        .unwrap_or(true)
    {
        return Some(Err(KkdbError::ParseError(
            "VECTOR INDEX missing ON clause".into(),
        )));
    }
    idx += 1;

    // Table name (may be followed immediately by `(col)` in same token)
    let table_name_raw = match tokens.get(idx) {
        Some(t) => *t,
        None => {
            return Some(Err(KkdbError::ParseError(
                "VECTOR INDEX missing table name".into(),
            )))
        }
    };
    let table_name = if let Some(pos) = table_name_raw.find('(') {
        table_name_raw[..pos].to_string()
    } else {
        table_name_raw.to_string()
    };
    idx += 1;

    // Extract column from `(col)` — find first `(...)` in the SQL after ON
    let after_on = &sql[upper.find("ON").unwrap_or(0)..];
    let column = {
        let op = after_on.find('(');
        let cp = after_on.find(')');
        match (op, cp) {
            (Some(o), Some(c)) if c > o => after_on[o + 1..c]
                .trim()
                .trim_matches('`')
                .trim_matches('"')
                .to_string(),
            _ => {
                return Some(Err(KkdbError::ParseError(
                    "VECTOR INDEX missing (column)".into(),
                )))
            }
        }
    };

    // Skip past the `)` in token stream; find DIM keyword
    // Advance idx past any tokens still inside / after the paren group
    while idx < tokens.len() && !tokens[idx].to_ascii_uppercase().starts_with("DIM") {
        idx += 1;
    }

    // DIM N
    let dim: u32 = if tokens
        .get(idx)
        .map(|t| t.eq_ignore_ascii_case("DIM"))
        .unwrap_or(false)
    {
        idx += 1;
        match tokens.get(idx).and_then(|t| {
            let cleaned = t.trim_matches(|c: char| !c.is_ascii_digit());
            cleaned.parse::<u32>().ok()
        }) {
            Some(n) => {
                idx += 1;
                n
            }
            None => {
                return Some(Err(KkdbError::ParseError(
                    "VECTOR INDEX DIM must be a positive integer".into(),
                )))
            }
        }
    } else {
        return Some(Err(KkdbError::ParseError(
            "VECTOR INDEX requires DIM N clause".into(),
        )));
    };

    // Optional DISTANCE COSINE|L2
    let distance = if tokens
        .get(idx)
        .map(|t| t.eq_ignore_ascii_case("DISTANCE"))
        .unwrap_or(false)
    {
        idx += 1;
        match tokens.get(idx).map(|t| t.to_ascii_uppercase()).as_deref() {
            Some("COSINE") | Some("COS") => kk::VecDistanceType::Cosine,
            Some("L2") | Some("EUCLIDEAN") => kk::VecDistanceType::L2,
            other => {
                return Some(Err(KkdbError::ParseError(format!(
                    "unknown distance metric {:?}; use COSINE or L2",
                    other
                ))))
            }
        }
    } else {
        kk::VecDistanceType::Cosine // default
    };

    Some(Ok(kk::Statement::CreateVectorIndex(
        kk::CreateVectorIndexStmt {
            index_name,
            table_name: table_name.trim_matches('`').to_string(),
            column,
            dim,
            distance,
            if_not_exists,
        },
    )))
}

/// Attempt to parse `DROP VECTOR INDEX [IF EXISTS] name`
///
/// Returns `Some(Result<Statement>)` when the SQL looks like a DROP VECTOR INDEX, else `None`.
fn try_parse_drop_vector_index(sql: &str) -> Option<Result<kk::Statement>> {
    let upper = sql.to_ascii_uppercase();
    // Fast path: must contain both DROP and VECTOR
    if !upper.contains("DROP") || !upper.contains("VECTOR") {
        return None;
    }

    let tokens: Vec<&str> = sql.split_whitespace().collect();

    // Must start with DROP
    if tokens
        .first()
        .map(|t| !t.eq_ignore_ascii_case("DROP"))
        .unwrap_or(true)
    {
        return None;
    }
    let mut idx = 1;

    // Must have VECTOR
    if tokens
        .get(idx)
        .map(|t| !t.eq_ignore_ascii_case("VECTOR"))
        .unwrap_or(true)
    {
        return None;
    }
    idx += 1;

    // Must have INDEX
    if tokens
        .get(idx)
        .map(|t| !t.eq_ignore_ascii_case("INDEX"))
        .unwrap_or(true)
    {
        return None;
    }
    idx += 1;

    // Optional IF EXISTS
    let mut if_exists = false;
    if tokens
        .get(idx)
        .map(|t| t.eq_ignore_ascii_case("IF"))
        .unwrap_or(false)
    {
        idx += 1;
        if tokens
            .get(idx)
            .map(|t| t.eq_ignore_ascii_case("EXISTS"))
            .unwrap_or(false)
        {
            idx += 1;
        }
        if_exists = true;
    }

    // Index name
    let index_name = match tokens.get(idx) {
        Some(t) => t
            .trim_matches(|c: char| !c.is_alphanumeric() && c != '_')
            .to_string(),
        None => {
            return Some(Err(KkdbError::ParseError(
                "DROP VECTOR INDEX missing name".into(),
            )))
        }
    };

    if index_name.is_empty() {
        return Some(Err(KkdbError::ParseError(
            "DROP VECTOR INDEX missing name".into(),
        )));
    }

    Some(Ok(kk::Statement::DropVectorIndex {
        index_name,
        if_exists,
    }))
}

use crate::error::Result;
use crate::sql::ast as kk;
use sqlparser::ast as sa;

use super::common::{
    object_name_last_ident, object_name_to_string, table_alias_to_string, unsupported,
};
use super::expr::convert_expr;

pub(crate) fn convert_query_to_select(query: sa::Query) -> Result<kk::SelectStmt> {
    if query.fetch.is_some() {
        return Err(unsupported("FETCH"));
    }
    // R6: Extract FOR UPDATE flag instead of rejecting
    let for_update = !query.locks.is_empty()
        && query.locks.iter().any(|l| {
            matches!(l.lock_type, sa::LockType::Update)
        });
    if query.for_clause.is_some() {
        return Err(unsupported("FOR clause"));
    }
    if query.settings.is_some() {
        return Err(unsupported("SETTINGS"));
    }
    if query.format_clause.is_some() {
        return Err(unsupported("FORMAT"));
    }
    if !query.pipe_operators.is_empty() {
        return Err(unsupported("pipe operator"));
    }

    // Batch D / L7: extract CTEs from WITH clause
    let ctes = if let Some(with) = query.with {
        let is_recursive = with.recursive;
        let mut out = Vec::with_capacity(with.cte_tables.len());
        for cte in with.cte_tables {
            out.push(kk::CteDefinition {
                name: cte.alias.name.value.clone(),
                columns: cte
                    .alias
                    .columns
                    .iter()
                    .map(|c| c.name.value.clone())
                    .collect(),
                query: Box::new(convert_query_to_select(*cte.query)?),
                is_recursive,
            });
        }
        out
    } else {
        Vec::new()
    };

    let mut select = match *query.body {
        sa::SetExpr::Select(select) => convert_select(*select)?,
        sa::SetExpr::Query(inner) => convert_query_to_select(*inner)?,
        // Batch B: nested set operation (A UNION B UNION C) — wrap in SetOp FROM clause
        sa::SetExpr::SetOperation {
            op,
            set_quantifier,
            left,
            right,
        } => {
            use super::statement::convert_set_expr_to_setop;
            let stmt = convert_set_expr_to_setop(op, set_quantifier, left, right)?;
            // Extract ORDER BY / LIMIT from the query and put them on the SetOpStmt
            let (limit, offset) = if let Some(lc) = query.limit_clause {
                match lc {
                    sa::LimitClause::LimitOffset { limit, offset, .. } => (
                        limit.map(super::expr::convert_expr).transpose()?,
                        offset
                            .map(|o| super::expr::convert_expr(o.value))
                            .transpose()?,
                    ),
                    sa::LimitClause::OffsetCommaLimit { offset, limit } => (
                        Some(super::expr::convert_expr(limit)?),
                        Some(super::expr::convert_expr(offset)?),
                    ),
                }
            } else {
                (None, None)
            };
            let order_by = if let Some(ob) = query.order_by {
                convert_order_by(ob)?
            } else {
                Vec::new()
            };
            let full_stmt = kk::SetOpStmt {
                kind: stmt.kind,
                left: stmt.left,
                right: stmt.right,
                order_by,
                limit,
                offset,
            };
            // Return a synthetic SelectStmt that has SetOp as its FROM source
            return Ok(kk::SelectStmt {
                distinct: false,
                columns: vec![kk::SelectColumn::AllColumns],
                from: Some(kk::FromClause::SetOp {
                    stmt: Box::new(full_stmt),
                    alias: "__setop__".to_string(),
                }),
                where_clause: None,
                group_by: Vec::new(),
                having: None,
                order_by: Vec::new(),
                limit: None,
                offset: None,
                ctes: Vec::new(),
                window_defs: Vec::new(),
                for_update: false,
            });
        }
        other => return Err(unsupported(format!("query body `{other}`"))),
    };

    if let Some(order_by) = query.order_by {
        select.order_by = convert_order_by(order_by)?;
    }
    if let Some(limit_clause) = query.limit_clause {
        let (limit, offset) = convert_limit_clause(limit_clause)?;
        select.limit = limit;
        select.offset = offset;
    }
    select.ctes = ctes;
    // R6: Propagate FOR UPDATE flag
    select.for_update = for_update;
    Ok(select)
}

fn convert_select(select: sa::Select) -> Result<kk::SelectStmt> {
    if select.flavor != sa::SelectFlavor::Standard {
        return Err(unsupported("non-standard SELECT flavor"));
    }
    if select.into.is_some() {
        return Err(unsupported("SELECT INTO"));
    }
    if select.top.is_some() {
        return Err(unsupported("SELECT TOP"));
    }
    if !select.lateral_views.is_empty() {
        return Err(unsupported("LATERAL VIEW"));
    }
    if select.prewhere.is_some() {
        return Err(unsupported("PREWHERE"));
    }
    if !select.connect_by.is_empty() {
        return Err(unsupported("CONNECT BY"));
    }
    if !select.cluster_by.is_empty() {
        return Err(unsupported("CLUSTER BY"));
    }
    if !select.distribute_by.is_empty() {
        return Err(unsupported("DISTRIBUTE BY"));
    }
    if !select.sort_by.is_empty() {
        return Err(unsupported("SORT BY"));
    }
    let mut window_defs = Vec::new();
    for curr_def in select.named_window {
        let name = curr_def.0.value;
        let spec = match curr_def.1 {
            sa::NamedWindowExpr::WindowSpec(spec) => spec,
            sa::NamedWindowExpr::NamedWindow(_) => {
                return Err(unsupported("reference to another named window"))
            }
        };
        let partition_by: Vec<kk::Expr> = spec
            .partition_by
            .iter()
            .filter_map(|e| super::expr::convert_expr(e.clone()).ok())
            .collect();
        let order_by: Vec<kk::OrderByItem> = spec
            .order_by
            .iter()
            .map(|item| kk::OrderByItem {
                expr: super::expr::convert_expr(item.expr.clone()).unwrap_or(kk::Expr::Null),
                ascending: item.options.asc.unwrap_or(true),
                nulls_first: item.options.nulls_first,
            })
            .collect();
        let frame = if let Some(wf) = &spec.window_frame {
            super::expr::convert_window_frame(wf).ok()
        } else {
            None
        };
        window_defs.push(kk::NamedWindowDefinition {
            name,
            partition_by,
            order_by,
            frame,
        });
    }
    if select.qualify.is_some() {
        return Err(unsupported("QUALIFY"));
    }
    if select.value_table_mode.is_some() {
        return Err(unsupported("value-table mode"));
    }

    let mut columns = Vec::with_capacity(select.projection.len());
    for item in select.projection {
        columns.push(convert_select_item(item)?);
    }

    let from = convert_from_clause(select.from)?;
    let where_clause = select.selection.map(convert_expr).transpose()?;
    let group_by = convert_group_by(select.group_by)?;
    let having = select.having.map(convert_expr).transpose()?;

    Ok(kk::SelectStmt {
        distinct: select.distinct.is_some(),
        columns,
        from,
        where_clause,
        group_by,
        having,
        order_by: Vec::new(),
        limit: None,
        offset: None,
        ctes: Vec::new(),
        window_defs,
        for_update: false,
    })
}

fn convert_select_item(item: sa::SelectItem) -> Result<kk::SelectColumn> {
    match item {
        sa::SelectItem::Wildcard(_) => Ok(kk::SelectColumn::AllColumns),
        sa::SelectItem::QualifiedWildcard(kind, _) => match kind {
            sa::SelectItemQualifiedWildcardKind::ObjectName(obj) => Ok(
                kk::SelectColumn::TableAllColumns(object_name_to_string(&obj)),
            ),
            sa::SelectItemQualifiedWildcardKind::Expr(expr) => Err(unsupported(format!(
                "projection `{expr}.*` is not supported"
            ))),
        },
        sa::SelectItem::UnnamedExpr(expr) => Ok(kk::SelectColumn::Expr {
            expr: convert_expr(expr)?,
            alias: None,
        }),
        sa::SelectItem::ExprWithAlias { expr, alias } => Ok(kk::SelectColumn::Expr {
            expr: convert_expr(expr)?,
            alias: Some(alias.value),
        }),
    }
}

fn convert_group_by(group_by: sa::GroupByExpr) -> Result<Vec<kk::Expr>> {
    match group_by {
        sa::GroupByExpr::Expressions(exprs, modifiers) => {
            if !modifiers.is_empty() {
                return Err(unsupported("GROUP BY modifiers"));
            }
            let mut out = Vec::with_capacity(exprs.len());
            for expr in exprs {
                out.push(convert_expr(expr)?);
            }
            Ok(out)
        }
        sa::GroupByExpr::All(_) => Err(unsupported("GROUP BY ALL")),
    }
}

fn convert_order_by(order_by: sa::OrderBy) -> Result<Vec<kk::OrderByItem>> {
    if order_by.interpolate.is_some() {
        return Err(unsupported("ORDER BY INTERPOLATE"));
    }

    let exprs = match order_by.kind {
        sa::OrderByKind::Expressions(exprs) => exprs,
        sa::OrderByKind::All(_) => return Err(unsupported("ORDER BY ALL")),
    };

    let mut out = Vec::with_capacity(exprs.len());
    for item in exprs {
        out.push(kk::OrderByItem {
            expr: convert_expr(item.expr)?,
            ascending: item.options.asc.unwrap_or(true),
            nulls_first: item.options.nulls_first,
        });
    }
    Ok(out)
}

fn convert_limit_clause(
    limit_clause: sa::LimitClause,
) -> Result<(Option<kk::Expr>, Option<kk::Expr>)> {
    match limit_clause {
        sa::LimitClause::LimitOffset {
            limit,
            offset,
            limit_by,
        } => {
            if !limit_by.is_empty() {
                return Err(unsupported("LIMIT BY"));
            }
            let limit = limit.map(convert_expr).transpose()?;
            let offset = offset.map(|o| convert_expr(o.value)).transpose()?;
            Ok((limit, offset))
        }
        sa::LimitClause::OffsetCommaLimit { offset, limit } => {
            let limit = Some(convert_expr(limit)?);
            let offset = Some(convert_expr(offset)?);
            Ok((limit, offset))
        }
    }
}

fn convert_from_clause(from: Vec<sa::TableWithJoins>) -> Result<Option<kk::FromClause>> {
    if from.is_empty() {
        return Ok(None);
    }

    let mut iter = from.into_iter();
    // SAFETY: early return above ensures `from` is non-empty
    let mut current = convert_table_with_joins(iter.next().unwrap())?;
    for table in iter {
        let right = convert_table_with_joins(table)?;
        current = kk::FromClause::Join {
            left: Box::new(current),
            join_type: kk::JoinType::Cross,
            right: Box::new(right),
            on: None,
        };
    }
    Ok(Some(current))
}

fn convert_table_with_joins(table: sa::TableWithJoins) -> Result<kk::FromClause> {
    let mut left = convert_table_factor(table.relation)?;
    for join in table.joins {
        let right = convert_table_factor(join.relation)?;
        let (join_type, on) = convert_join_operator(join.join_operator, &left, &right)?;
        left = kk::FromClause::Join {
            left: Box::new(left),
            join_type,
            right: Box::new(right),
            on,
        };
    }
    Ok(left)
}

fn convert_table_factor(factor: sa::TableFactor) -> Result<kk::FromClause> {
    match factor {
        sa::TableFactor::Table {
            name, alias, args, ..
        } => {
            if let Some(func_args) = args {
                // sqlparser parses GENERATE_SERIES(1,5) and UNNEST('...') as
                // TableFactor::Table with a `args: TableFunctionArgs` field
                let func_name = object_name_to_string(&name);
                let mut kk_args = Vec::new();
                for arg in &func_args.args {
                    if let sa::FunctionArg::Unnamed(sa::FunctionArgExpr::Expr(e)) = arg {
                        kk_args.push(super::expr::convert_expr(e.clone())?);
                    }
                }
                // Extract alias and optional column alias from TableAlias
                let (table_alias, col_alias) = if let Some(ta) = alias {
                    let col = ta.columns.into_iter().next().map(|c| c.name.value);
                    (Some(ta.name.value), col)
                } else {
                    (None, None)
                };
                return Ok(kk::FromClause::TableFunction {
                    name: func_name,
                    args: kk_args,
                    alias: table_alias,
                    column: col_alias,
                });
            }
            Ok(kk::FromClause::Table {
                name: object_name_to_string(&name),
                alias: table_alias_to_string(alias),
            })
        }
        sa::TableFactor::Derived {
            subquery, alias, ..
        } => {
            let alias = alias
                .map(|a| a.name.value)
                .ok_or_else(|| unsupported("subquery in FROM requires alias"))?;
            Ok(kk::FromClause::Subquery {
                query: Box::new(convert_query_to_select(*subquery)?),
                alias,
            })
        }
        sa::TableFactor::NestedJoin {
            table_with_joins,
            alias,
        } => {
            if alias.is_some() {
                return Err(unsupported("alias on parenthesized join"));
            }
            convert_table_with_joins(*table_with_joins)
        }
        // Table-valued functions: UNNEST(arr), generate_series(start, stop[, step])
        sa::TableFactor::TableFunction { expr, alias } => {
            // The expr must be a function call
            match expr {
                sa::Expr::Function(func) => {
                    let func_name = func.name.to_string();
                    // Extract positional arguments
                    let mut args = Vec::new();
                    if let sa::FunctionArguments::List(ref list) = func.args {
                        for arg in &list.args {
                            if let sa::FunctionArg::Unnamed(sa::FunctionArgExpr::Expr(e)) = arg {
                                args.push(super::expr::convert_expr(e.clone())?);
                            }
                        }
                    }
                    // Alias: from `TableAlias { name, columns }` — name is the table alias,
                    // columns[0] (if present) is the column alias for the generated column
                    let (table_alias, col_alias) = if let Some(ta) = alias {
                        let col = ta.columns.into_iter().next().map(|c| c.name.value);
                        (Some(ta.name.value), col)
                    } else {
                        (None, None)
                    };
                    Ok(kk::FromClause::TableFunction {
                        name: func_name,
                        args,
                        alias: table_alias,
                        column: col_alias,
                    })
                }
                other => Err(unsupported(format!(
                    "FROM TABLE FUNCTION with non-function expression `{other}`"
                ))),
            }
        }
        other => Err(unsupported(format!("FROM table factor `{other}`"))),
    }
}

fn convert_join_operator(
    op: sa::JoinOperator,
    left_rel: &kk::FromClause,
    right_rel: &kk::FromClause,
) -> Result<(kk::JoinType, Option<kk::Expr>)> {
    // Helper: check if a constraint is Natural before consuming it
    let is_natural = |c: &sa::JoinConstraint| matches!(c, sa::JoinConstraint::Natural);

    match op {
        sa::JoinOperator::Join(c)
        | sa::JoinOperator::Inner(c)
        | sa::JoinOperator::StraightJoin(c) => {
            // Batch C: NATURAL JOIN is Inner with JoinConstraint::Natural
            if is_natural(&c) {
                Ok((kk::JoinType::Natural, None))
            } else {
                Ok((
                    kk::JoinType::Inner,
                    convert_join_constraint(c, left_rel, right_rel)?,
                ))
            }
        }
        sa::JoinOperator::Left(c) | sa::JoinOperator::LeftOuter(c) => {
            if is_natural(&c) {
                Ok((kk::JoinType::Natural, None))
            } else {
                Ok((
                    kk::JoinType::Left,
                    convert_join_constraint(c, left_rel, right_rel)?,
                ))
            }
        }
        sa::JoinOperator::Right(c) | sa::JoinOperator::RightOuter(c) => {
            if is_natural(&c) {
                Ok((kk::JoinType::Natural, None))
            } else {
                Ok((
                    kk::JoinType::Right,
                    convert_join_constraint(c, left_rel, right_rel)?,
                ))
            }
        }
        sa::JoinOperator::LeftSemi(c) => Ok((
            kk::JoinType::LeftSemi,
            convert_join_constraint(c, left_rel, right_rel)?,
        )),
        sa::JoinOperator::RightSemi(c) => Ok((
            kk::JoinType::RightSemi,
            convert_join_constraint(c, left_rel, right_rel)?,
        )),
        // Batch C: FULL OUTER JOIN
        sa::JoinOperator::FullOuter(c) => Ok((
            kk::JoinType::Full,
            convert_join_constraint(c, left_rel, right_rel)?,
        )),
        sa::JoinOperator::CrossJoin(c) => {
            if is_natural(&c) {
                Ok((kk::JoinType::Natural, None))
            } else {
                let on = convert_join_constraint(c, left_rel, right_rel)?;
                if on.is_some() {
                    return Err(unsupported("CROSS JOIN with ON/USING"));
                }
                Ok((kk::JoinType::Cross, None))
            }
        }
        // LeftSemi / RightSemi — approximate as INNER JOIN
        // (semi-join eliminates duplicate right rows; INNER JOIN may produce more rows for
        // LeftAnti / RightAnti — anti-join (NOT IN subquery), complex, unsupported
        sa::JoinOperator::LeftAnti(c) | sa::JoinOperator::RightAnti(c) => {
            let _ = c; // consume to avoid unused warning
            Err(unsupported("ANTI JOIN is not supported"))
        }
        other => Err(unsupported(format!("join operator `{:?}`", other))),
    }
}

fn convert_join_constraint(
    constraint: sa::JoinConstraint,
    left_rel: &kk::FromClause,
    right_rel: &kk::FromClause,
) -> Result<Option<kk::Expr>> {
    match constraint {
        sa::JoinConstraint::None => Ok(None),
        sa::JoinConstraint::On(expr) => Ok(Some(convert_expr(expr)?)),
        sa::JoinConstraint::Using(columns) => {
            Ok(Some(convert_join_using(columns, left_rel, right_rel)?))
        }
        // Batch C: NATURAL JOIN — defer ON computation to exec time
        sa::JoinConstraint::Natural => Ok(None), // executor will resolve from schema
    }
}

fn convert_join_using(
    columns: Vec<sa::ObjectName>,
    left_rel: &kk::FromClause,
    right_rel: &kk::FromClause,
) -> Result<kk::Expr> {
    if columns.is_empty() {
        return Err(unsupported("JOIN USING without columns"));
    }

    let mut iter = columns.into_iter();
    // SAFETY: early return above ensures `columns` is non-empty
    let mut expr = using_column_eq(left_rel, right_rel, iter.next().unwrap())?;
    for col in iter {
        let next = using_column_eq(left_rel, right_rel, col)?;
        expr = kk::Expr::BinaryOp {
            left: Box::new(expr),
            op: kk::BinaryOperator::And,
            right: Box::new(next),
        };
    }
    Ok(expr)
}

#[allow(clippy::only_used_in_recursion)]
fn using_side_expr(from: &kk::FromClause, side: &str, column: &str) -> Result<kk::Expr> {
    match from {
        kk::FromClause::Table { name, alias } => Ok(kk::Expr::ColumnRef {
            table: Some(alias.clone().unwrap_or_else(|| name.clone())),
            column: column.to_string(),
        }),
        kk::FromClause::Subquery { alias, .. } => Ok(kk::Expr::ColumnRef {
            table: Some(alias.clone()),
            column: column.to_string(),
        }),
        kk::FromClause::Join {
            join_type,
            left,
            right,
            ..
        } => match join_type {
            kk::JoinType::Inner | kk::JoinType::Cross => Ok(kk::Expr::Function {
                // SQL USING semantics use a merged key column; COALESCE approximates this on join trees.
                name: "COALESCE".to_string(),
                args: vec![
                    using_side_expr(left, side, column)?,
                    using_side_expr(right, side, column)?,
                ],
                distinct: false,
            }),
            kk::JoinType::Left | kk::JoinType::LeftSemi => using_side_expr(left, side, column),
            kk::JoinType::Right | kk::JoinType::RightSemi => using_side_expr(right, side, column),
            // Batch C: FULL/NATURAL JOIN — treat like INNER for USING purposes
            kk::JoinType::Full | kk::JoinType::Natural => Ok(kk::Expr::Function {
                name: "COALESCE".to_string(),
                args: vec![
                    using_side_expr(left, side, column)?,
                    using_side_expr(right, side, column)?,
                ],
                distinct: false,
            }),
        },
        // Batch B: SetOp — treat as anonymous subquery with given side
        kk::FromClause::SetOp { alias, .. } => Ok(kk::Expr::ColumnRef {
            table: Some(alias.clone()),
            column: column.to_string(),
        }),
        // TableFunction — treat output column as unqualified (table-valued functions produce flat rows)
        kk::FromClause::TableFunction { alias, name, .. } => Ok(kk::Expr::ColumnRef {
            table: alias.clone().or_else(|| Some(name.clone())),
            column: column.to_string(),
        }),
    }
}

fn using_column_eq(
    left_rel: &kk::FromClause,
    right_rel: &kk::FromClause,
    column: sa::ObjectName,
) -> Result<kk::Expr> {
    let col = object_name_last_ident(&column)?;
    Ok(kk::Expr::BinaryOp {
        left: Box::new(using_side_expr(left_rel, "left", &col)?),
        op: kk::BinaryOperator::Equal,
        right: Box::new(using_side_expr(right_rel, "right", &col)?),
    })
}

use crate::error::{KkdbError, Result};
use crate::sql::ast as kk;
use sqlparser::ast as sa;

use super::common::{
    convert_data_type, object_name_last_ident, object_name_to_string, unsupported,
};
use super::expr::convert_expr;
use super::query::convert_query_to_select;

pub(crate) fn convert_statement(stmt: sa::Statement) -> Result<kk::Statement> {
    match stmt {
        sa::Statement::Query(query) => convert_query_statement(*query),
        sa::Statement::Insert(insert) => convert_insert(insert),
        sa::Statement::Update(update) => convert_update(update),
        sa::Statement::Delete(delete) => convert_delete(delete),
        sa::Statement::CreateTable(create) => convert_create_table(create),
        sa::Statement::CreateIndex(create) => convert_create_index(create),
        sa::Statement::AlterTable(alter) => convert_alter_table(alter),
        sa::Statement::Drop {
            object_type,
            if_exists,
            names,
            ..
        } => convert_drop(object_type, if_exists, names),
        sa::Statement::StartTransaction { .. } => Ok(kk::Statement::Begin),
        sa::Statement::Commit { .. } => Ok(kk::Statement::Commit),
        sa::Statement::Rollback { savepoint, .. } => {
            if let Some(sp) = savepoint {
                Ok(kk::Statement::RollbackToSavepoint(sp.value))
            } else {
                Ok(kk::Statement::Rollback)
            }
        }
        sa::Statement::Savepoint { name } => Ok(kk::Statement::Savepoint(name.value)),
        sa::Statement::ReleaseSavepoint { name } => Ok(kk::Statement::ReleaseSavepoint(name.value)),
        sa::Statement::ShowTables { .. } => Ok(kk::Statement::ShowTables),
        sa::Statement::Vacuum { .. } => Ok(kk::Statement::Vacuum),
        // O1: ANALYZE TABLE t
        sa::Statement::Analyze(a) => {
            let table_name = a
                .table_name
                .map(|n| object_name_to_string(&n))
                .ok_or_else(|| unsupported("ANALYZE without table name"))?;
            Ok(kk::Statement::AnalyzeTable(table_name))
        }
        // Batch E: CREATE VIEW
        sa::Statement::CreateView(cv) => {
            let view_query = convert_query_to_select(*cv.query)?;
            Ok(kk::Statement::CreateView(kk::CreateViewStmt {
                name: object_name_to_string(&cv.name),
                columns: cv.columns.into_iter().map(|c| c.name.value).collect(),
                query: Box::new(view_query),
                or_replace: cv.or_replace,
                if_not_exists: cv.if_not_exists,
            }))
        }
        // L4: CREATE VIRTUAL TABLE
        sa::Statement::CreateVirtualTable {
            name,
            module_name,
            module_args,
            if_not_exists,
            ..
        } => {
            if module_name.value.to_lowercase() != "fts5" {
                return Err(unsupported(format!(
                    "virtual table module {}",
                    module_name.value
                )));
            }
            let mut columns = Vec::new();
            for arg in module_args {
                columns.push(kk::ColumnDef {
                    name: arg.value,
                    data_type: crate::types::DataType::Text,
                    primary_key: false,
                    autoincrement: false,
                    not_null: false,
                    unique: false,
                    default: None,
                    references: None,
                    check_expr: None,
                });
            }
            Ok(kk::Statement::CreateTable(kk::CreateTableStmt {
                table_name: object_name_to_string(&name),
                columns,
                if_not_exists,
                is_fts: true,
                source: None,
                checks: Vec::new(),
            }))
        }
        // L3: CREATE TRIGGER
        sa::Statement::CreateTrigger(ct) => {
            let trig_name = object_name_to_string(&ct.name);
            let timing = match ct.period.as_ref().map(|p| p.to_string().to_uppercase()) {
                Some(ref p) if p == "BEFORE" => kk::TriggerTiming::Before,
                Some(ref p) if p == "AFTER" => kk::TriggerTiming::After,
                _ => return Err(unsupported(format!("trigger timing {:?}", ct.period))),
            };
            let event = match ct.events.first() {
                Some(sqlparser::ast::TriggerEvent::Insert) => kk::TriggerEvent::Insert,
                Some(sqlparser::ast::TriggerEvent::Delete) => kk::TriggerEvent::Delete,
                Some(sqlparser::ast::TriggerEvent::Update { .. }) => kk::TriggerEvent::Update,
                _ => return Err(unsupported(format!("trigger event {:?}", ct.events))),
            };
            let t_name = object_name_to_string(&ct.table_name);
            let body_sql = ct
                .statements
                .as_ref()
                .map(|cs| format!("{cs}"))
                .unwrap_or_default();
            Ok(kk::Statement::CreateTrigger(kk::CreateTriggerStmt {
                name: trig_name,
                timing,
                event,
                table_name: t_name,
                body_sql,
                or_replace: ct.or_replace,
            }))
        }
        // L3: DROP TRIGGER
        sa::Statement::DropTrigger(dt) => Ok(kk::Statement::DropTrigger {
            name: object_name_to_string(&dt.trigger_name),
            if_exists: dt.if_exists,
        }),
        sa::Statement::Explain { statement, analyze, format, .. } => {
            let inner = convert_statement(*statement)?;
            // Check for FORMAT TREE (keyword or assignment)
            let is_tree = matches!(
                format,
                Some(sa::AnalyzeFormatKind::Keyword(sa::AnalyzeFormat::TREE))
                    | Some(sa::AnalyzeFormatKind::Assignment(sa::AnalyzeFormat::TREE))
            );
            let is_json = matches!(
                format,
                Some(sa::AnalyzeFormatKind::Keyword(sa::AnalyzeFormat::JSON))
                    | Some(sa::AnalyzeFormatKind::Assignment(sa::AnalyzeFormat::JSON))
            );
            if is_tree {
                Ok(kk::Statement::ExplainFormatTree(Box::new(inner)))
            } else if is_json {
                Ok(kk::Statement::ExplainFormatJson(Box::new(inner)))
            } else if analyze {
                Ok(kk::Statement::ExplainAnalyze(Box::new(inner)))
            } else {
                Ok(kk::Statement::Explain(Box::new(inner)))
            }
        }
        // R4: TRUNCATE → DELETE without WHERE (removes all rows)
        sa::Statement::Truncate(t) => {
            let table_name = if let Some(target) = t.table_names.into_iter().next() {
                object_name_to_string(&target.name)
            } else {
                return Err(unsupported("TRUNCATE with no table"));
            };
            Ok(kk::Statement::Delete(kk::DeleteStmt {
                table_name,
                where_clause: None,
                returning: None,
            }))
        }
        // User Management
        sa::Statement::CreateRole(sa::CreateRole {
            names,
            login: _,
            password,
            ..
        }) => {
            if names.len() != 1 {
                return Err(unsupported("CREATE USER with multiple names"));
            }
            Ok(kk::Statement::CreateUser(kk::CreateUserStmt {
                username: object_name_to_string(&names[0]),
                password: password.as_ref().map(|pw| match pw {
                    sa::Password::Password(sa::Expr::Identifier(ident)) => ident.value.clone(),
                    sa::Password::Password(sa::Expr::Value(sa::ValueWithSpan {
                        value: sa::Value::SingleQuotedString(s),
                        ..
                    })) => s.clone(),
                    sa::Password::Password(sa::Expr::Value(sa::ValueWithSpan {
                        value: sa::Value::DoubleQuotedString(s),
                        ..
                    })) => s.clone(),
                    _ => "".to_string(), // Error handling skipped for this demo, just map safely
                }),
            }))
        }
        sa::Statement::AlterRole { name, operation: _ } => {
            // Simplified handling for AlterRole
            Ok(kk::Statement::AlterUser(kk::AlterUserStmt {
                username: name.value.clone(),
                password: None, // Simplified until full password map logic is needed from Operation
            }))
        }

        sa::Statement::Grant(sa::Grant {
            privileges,
            objects,
            grantees,
            ..
        }) => {
            let kk_privs = convert_privileges(privileges)?;
            let kk_obj = objects
                .map(convert_grant_object)
                .unwrap_or_else(|| Err(unsupported("GRANT without object")))?;
            Ok(kk::Statement::Grant(kk::GrantStmt {
                privileges: kk_privs,
                object: kk_obj,
                grantees: grantees
                    .into_iter()
                    .filter_map(|n| match n.name {
                        Some(sa::GranteeName::ObjectName(name)) => {
                            Some(object_name_to_string(&name))
                        }
                        Some(sa::GranteeName::UserHost { user, host }) => {
                            Some(format!("{}@{}", user.value, host.value))
                        }
                        None => None,
                    })
                    .collect(),
            }))
        }
        sa::Statement::Revoke(sa::Revoke {
            privileges,
            objects,
            grantees,
            ..
        }) => {
            let kk_privs = convert_privileges(privileges)?;
            let kk_obj = objects
                .map(convert_grant_object)
                .unwrap_or_else(|| Err(unsupported("REVOKE without object")))?;
            Ok(kk::Statement::Revoke(kk::RevokeStmt {
                privileges: kk_privs,
                object: kk_obj,
                grantees: grantees
                    .into_iter()
                    .filter_map(|n| match n.name {
                        Some(sa::GranteeName::ObjectName(name)) => {
                            Some(object_name_to_string(&name))
                        }
                        Some(sa::GranteeName::UserHost { user, host }) => {
                            Some(format!("{}@{}", user.value, host.value))
                        }
                        None => None,
                    })
                    .collect(),
            }))
        }
        // SET kkdb.key = 'value' (session variables for RLS / multi-tenant)
        sa::Statement::Set(sa::Set::SingleAssignment {
            variable, values, ..
        }) => {
            // variable is an ObjectName; join parts with '.'
            let key = variable
                .0
                .iter()
                .map(|i| format!("{i}"))
                .collect::<Vec<_>>()
                .join(".");
            // take the first value expression and coerce to string
            let value = values
                .into_iter()
                .next()
                .map(|expr| match expr {
                    sa::Expr::Value(sa::ValueWithSpan {
                        value: sa::Value::SingleQuotedString(s),
                        ..
                    }) => s,
                    sa::Expr::Value(sa::ValueWithSpan {
                        value: sa::Value::DoubleQuotedString(s),
                        ..
                    }) => s,
                    other => format!("{other}"),
                })
                .unwrap_or_default();
            Ok(kk::Statement::SetSessionVar { key, value })
        }
        // Quietly absorb other SET variants (e.g. SET NAMES, SET @@global...)
        sa::Statement::Set(_) => Err(unsupported("SET statement variant")),
        // RLS: CREATE POLICY / DROP POLICY
        sa::Statement::CreatePolicy(cp) => Ok(kk::Statement::CreatePolicy(kk::CreatePolicyStmt {
            name: cp.name.value,
            table_name: object_name_to_string(&cp.table_name),
            role: cp
                .to
                .as_ref()
                .and_then(|v| v.first())
                .map(|o| format!("{o}")),
            using_expr: cp.using.map(convert_expr).transpose()?,
            check_expr: cp.with_check.map(convert_expr).transpose()?,
        })),
        sa::Statement::DropPolicy(dp) => Ok(kk::Statement::DropPolicy(kk::DropPolicyStmt {
            name: dp.name.value,
            table_name: object_name_to_string(&dp.table_name),
            if_exists: dp.if_exists,
        })),
        sa::Statement::AlterView { .. } => Err(unsupported("ALTER VIEW")),
        sa::Statement::AlterIndex { .. } => Err(unsupported("ALTER INDEX")),
        sa::Statement::AlterSchema(..) => Err(unsupported("ALTER SCHEMA")),
        sa::Statement::AlterType(..) => Err(unsupported("ALTER TYPE")),
        sa::Statement::CreateFunction(..) => Err(unsupported("CREATE FUNCTION")),
        sa::Statement::CreateProcedure { .. } => Err(unsupported("CREATE PROCEDURE")),
        sa::Statement::DropFunction(..) => Err(unsupported("DROP FUNCTION")),
        sa::Statement::DropProcedure { .. } => Err(unsupported("DROP PROCEDURE")),
        sa::Statement::DropExtension(..) => Err(unsupported("DROP EXTENSION")),
        sa::Statement::CreateExtension(..) => Err(unsupported("CREATE EXTENSION")),
        sa::Statement::Declare { .. } => Err(unsupported("DECLARE cursor")),
        sa::Statement::Fetch { .. } => Err(unsupported("FETCH cursor")),
        sa::Statement::Close { .. } => Err(unsupported("CLOSE cursor")),
        sa::Statement::Open(..) => Err(unsupported("OPEN cursor")),
        sa::Statement::Call(..) => Err(unsupported("CALL stored procedure")),
        sa::Statement::Install { .. } => Err(unsupported("INSTALL")),
        sa::Statement::Load { .. } => Err(unsupported("LOAD")),
        sa::Statement::CreateSecret { .. } => Err(unsupported("CREATE SECRET")),
        sa::Statement::DropSecret { .. } => Err(unsupported("DROP SECRET")),
        sa::Statement::Msck(..) => Err(unsupported("MSCK")),
        sa::Statement::AttachDatabase { .. }
        | sa::Statement::AttachDuckDBDatabase { .. }
        | sa::Statement::DetachDuckDBDatabase { .. } => Err(unsupported("ATTACH/DETACH DATABASE")),
        other => Err(unsupported(format!("statement `{other}`"))),
    }
}

fn convert_drop(
    object_type: sa::ObjectType,
    if_exists: bool,
    names: Vec<sa::ObjectName>,
) -> Result<kk::Statement> {
    match object_type {
        sa::ObjectType::User | sa::ObjectType::Role => {
            if names.is_empty() {
                return Err(unsupported("DROP USER/ROLE without names"));
            }
            Ok(kk::Statement::DropUser(kk::DropUserStmt {
                usernames: names
                    .into_iter()
                    .map(|n| object_name_to_string(&n))
                    .collect(),
                if_exists,
            }))
        }
        sa::ObjectType::Table => {
            if names.len() != 1 {
                return Err(unsupported("DROP TABLE with multiple names"));
            }
            Ok(kk::Statement::DropTable(kk::DropTableStmt {
                table_name: object_name_to_string(&names[0]),
                if_exists,
            }))
        }
        sa::ObjectType::Index => {
            if names.len() != 1 {
                return Err(unsupported("DROP INDEX with multiple names"));
            }
            Ok(kk::Statement::DropIndex(kk::DropIndexStmt {
                index_name: object_name_to_string(&names[0]),
                if_exists,
            }))
        }
        sa::ObjectType::View => {
            // DROP VIEW treated like DROP TABLE — views stored in same schema map
            if names.len() != 1 {
                return Err(unsupported("DROP VIEW with multiple names"));
            }
            Ok(kk::Statement::DropTable(kk::DropTableStmt {
                table_name: object_name_to_string(&names[0]),
                if_exists,
            }))
        }
        other => Err(unsupported(format!("DROP {other}"))),
    }
}

fn convert_create_table(create: sa::CreateTable) -> Result<kk::Statement> {
    if create.columns.is_empty() && create.query.is_none() {
        return Err(KkdbError::ParseError(
            "CREATE TABLE requires at least one column".into(),
        ));
    }

    // CREATE TABLE AS SELECT
    if let Some(query) = create.query {
        let select = convert_query_to_select(*query)?;
        return Ok(kk::Statement::CreateTable(kk::CreateTableStmt {
            table_name: object_name_to_string(&create.name),
            columns: Vec::new(),
            if_not_exists: create.if_not_exists,
            is_fts: false,
            source: Some(Box::new(select)),
            checks: Vec::new(),
        }));
    }

    let mut columns = Vec::with_capacity(create.columns.len());
    for col in create.columns {
        columns.push(convert_column_def(col)?);
    }

    // Parse table-level CHECK constraints
    let mut checks: Vec<(Option<String>, kk::Expr)> = Vec::new();
    for tc in &create.constraints {
        if let sa::TableConstraint::Check(cc) = tc {
            let name = cc.name.as_ref().map(|i| i.value.clone());
            if let Ok(expr) = convert_expr(*cc.expr.clone()) {
                checks.push((name, expr));
            }
        }
    }

    Ok(kk::Statement::CreateTable(kk::CreateTableStmt {
        table_name: object_name_to_string(&create.name),
        columns,
        if_not_exists: create.if_not_exists,
        is_fts: false,
        source: None,
        checks,
    }))
}

fn convert_create_index(create: sa::CreateIndex) -> Result<kk::Statement> {
    let index_name = create
        .name
        .as_ref()
        .map(object_name_to_string)
        .ok_or_else(|| unsupported("CREATE INDEX without index name"))?;

    let mut columns = Vec::with_capacity(create.columns.len());
    for col in create.columns {
        columns.push(convert_index_column(col)?);
    }

    // Note: CREATE FULLTEXT INDEX is intercepted in parse_sql_with_sqlparser before
    // reaching this function (sqlparser 0.61 has no `full_text` field on CreateIndex).

    Ok(kk::Statement::CreateIndex(kk::CreateIndexStmt {
        index_name,
        table_name: object_name_to_string(&create.table_name),
        columns,
        unique: create.unique,
        if_not_exists: create.if_not_exists,
    }))
}

fn convert_index_column(col: sa::IndexColumn) -> Result<String> {
    match col.column.expr {
        sa::Expr::Identifier(id) => Ok(id.value),
        sa::Expr::CompoundIdentifier(ids) => ids
            .last()
            .map(|id| id.value.clone())
            .ok_or_else(|| unsupported("empty compound identifier in index column")),
        other => Err(unsupported(format!(
            "index expression `{other}` is not supported"
        ))),
    }
}

fn convert_alter_table(alter: sa::AlterTable) -> Result<kk::Statement> {
    if alter.operations.len() != 1 {
        return Err(unsupported("ALTER TABLE with multiple operations"));
    }

    let table_name = object_name_to_string(&alter.name);
    // SAFETY: early return above ensures exactly one operation
    let action = match alter.operations.into_iter().next().unwrap() {
        sa::AlterTableOperation::AddColumn { column_def, .. } => {
            kk::AlterTableAction::AddColumn(Box::new(convert_column_def(column_def)?))
        }
        sa::AlterTableOperation::DropColumn { column_names, .. } => {
            if column_names.len() != 1 {
                return Err(unsupported("ALTER TABLE DROP COLUMN with multiple columns"));
            }
            kk::AlterTableAction::DropColumn(column_names[0].value.clone())
        }
        sa::AlterTableOperation::RenameTable { table_name } => {
            let name = match table_name {
                sa::RenameTableNameKind::As(n) | sa::RenameTableNameKind::To(n) => {
                    object_name_to_string(&n)
                }
            };
            kk::AlterTableAction::RenameTable(name)
        }
        sa::AlterTableOperation::RenameColumn {
            old_column_name,
            new_column_name,
        } => kk::AlterTableAction::RenameColumn {
            old_name: old_column_name.value,
            new_name: new_column_name.value,
        },
        sa::AlterTableOperation::EnableRowLevelSecurity => {
            kk::AlterTableAction::EnableRowLevelSecurity
        }
        sa::AlterTableOperation::DisableRowLevelSecurity => {
            // Best-effort: treat as a no-op for now (could add DisableRLS later)
            return Err(unsupported("ALTER TABLE DISABLE ROW LEVEL SECURITY"));
        }
        other => {
            return Err(unsupported(format!(
                "ALTER TABLE operation `{other}` is not supported"
            )))
        }
    };

    Ok(kk::Statement::AlterTable(kk::AlterTableStmt {
        table_name,
        action,
    }))
}

fn convert_insert(insert: sa::Insert) -> Result<kk::Statement> {
    if !insert.into {
        return Err(unsupported("INSERT without INTO"));
    }
    if !insert.assignments.is_empty() {
        return Err(unsupported("INSERT ... SET"));
    }
    if insert.on.is_some() {
        return Err(unsupported("INSERT ... ON CONFLICT/ON DUPLICATE"));
    }
    let returning = if let Some(ret_items) = insert.returning {
        let exprs: crate::error::Result<Vec<_>> = ret_items
            .into_iter()
            .map(|si| match si {
                sa::SelectItem::UnnamedExpr(e) => convert_expr(e),
                sa::SelectItem::ExprWithAlias { expr, .. } => convert_expr(expr),
                sa::SelectItem::Wildcard(_) => Ok(kk::Expr::ColumnRef {
                    table: None,
                    column: "*".to_string(),
                }),
                _ => Err(unsupported("unsupported RETURNING expression")),
            })
            .collect();
        Some(exprs?)
    } else {
        None
    };

    // Determine conflict policy from OR clause (SQLite INSERT OR REPLACE/IGNORE)
    let conflict = if insert.or.is_some() {
        match insert.or.as_ref() {
            Some(sa::SqliteOnConflict::Replace) => kk::ConflictPolicy::Replace,
            Some(sa::SqliteOnConflict::Ignore) => kk::ConflictPolicy::Ignore,
            _ => kk::ConflictPolicy::Error,
        }
    } else {
        kk::ConflictPolicy::Error
    };

    let table_name = match insert.table {
        sa::TableObject::TableName(name) => object_name_to_string(&name),
        sa::TableObject::TableFunction(_) => {
            return Err(unsupported("INSERT INTO TABLE FUNCTION"));
        }
    };

    let source = insert
        .source
        .ok_or_else(|| unsupported("INSERT without VALUES source"))?;

    let source = match *source.body {
        sa::SetExpr::Values(values) => {
            let mut rows = Vec::with_capacity(values.rows.len());
            for row in values.rows {
                let mut out = Vec::with_capacity(row.len());
                for expr in row {
                    out.push(convert_expr(expr)?);
                }
                rows.push(out);
            }
            kk::InsertSource::Values(rows)
        }
        sa::SetExpr::Select(select) => {
            let stmt = convert_select_body(*select)?;
            kk::InsertSource::Select(Box::new(stmt))
        }
        _ => return Err(unsupported("INSERT source must be VALUES or SELECT")),
    };

    Ok(kk::Statement::Insert(kk::InsertStmt {
        table_name,
        columns: if insert.columns.is_empty() {
            None
        } else {
            Some(insert.columns.into_iter().map(|c| c.value).collect())
        },
        source,
        conflict,
        returning,
    }))
}

fn convert_select_body(select: sa::Select) -> Result<kk::SelectStmt> {
    use super::query::convert_query_to_select;
    let query = sa::Query {
        with: None,
        body: Box::new(sa::SetExpr::Select(Box::new(select))),
        order_by: None,
        limit_clause: None,
        fetch: None,
        locks: Vec::new(),
        for_clause: None,
        settings: None,
        format_clause: None,
        pipe_operators: Vec::new(),
    };
    convert_query_to_select(query)
}

fn convert_update(update: sa::Update) -> Result<kk::Statement> {
    if update.from.is_some() {
        return Err(unsupported("UPDATE ... FROM"));
    }
    if update.limit.is_some() {
        return Err(unsupported("UPDATE ... LIMIT"));
    }
    let returning = if let Some(ret_items) = update.returning {
        let exprs: crate::error::Result<Vec<_>> = ret_items
            .into_iter()
            .map(|si| match si {
                sa::SelectItem::UnnamedExpr(e) => convert_expr(e),
                sa::SelectItem::ExprWithAlias { expr, .. } => convert_expr(expr),
                sa::SelectItem::Wildcard(_) => Ok(kk::Expr::ColumnRef {
                    table: None,
                    column: "*".to_string(),
                }),
                _ => Err(unsupported("unsupported RETURNING expression")),
            })
            .collect();
        Some(exprs?)
    } else {
        None
    };
    let table_name = extract_simple_table_name(update.table, "UPDATE target")?;
    let mut assignments = Vec::with_capacity(update.assignments.len());
    for assignment in update.assignments {
        let col = match assignment.target {
            sa::AssignmentTarget::ColumnName(name) => object_name_last_ident(&name)?,
            sa::AssignmentTarget::Tuple(_) => {
                return Err(unsupported("tuple assignment in UPDATE"));
            }
        };
        assignments.push((col, convert_expr(assignment.value)?));
    }
    let where_clause = update.selection.map(convert_expr).transpose()?;
    Ok(kk::Statement::Update(kk::UpdateStmt {
        table_name,
        assignments,
        where_clause,
        returning,
    }))
}

fn convert_delete(delete: sa::Delete) -> Result<kk::Statement> {
    if delete.using.is_some() {
        return Err(unsupported("DELETE ... USING"));
    }
    if !delete.order_by.is_empty() {
        return Err(unsupported("DELETE ... ORDER BY"));
    }
    if delete.limit.is_some() {
        return Err(unsupported("DELETE ... LIMIT"));
    }
    let returning = if let Some(ret_items) = delete.returning {
        let exprs: crate::error::Result<Vec<_>> = ret_items
            .into_iter()
            .map(|si| match si {
                sa::SelectItem::UnnamedExpr(e) => convert_expr(e),
                sa::SelectItem::ExprWithAlias { expr, .. } => convert_expr(expr),
                sa::SelectItem::Wildcard(_) => Ok(kk::Expr::ColumnRef {
                    table: None,
                    column: "*".to_string(),
                }),
                _ => Err(unsupported("unsupported RETURNING expression")),
            })
            .collect();
        Some(exprs?)
    } else {
        None
    };
    let mut tables = match delete.from {
        sa::FromTable::WithFromKeyword(tables) | sa::FromTable::WithoutKeyword(tables) => tables,
    };
    if tables.len() != 1 {
        return Err(unsupported("DELETE from multiple tables"));
    }
    let table_name = extract_simple_table_name(tables.remove(0), "DELETE target")?;
    let where_clause = delete.selection.map(convert_expr).transpose()?;
    Ok(kk::Statement::Delete(kk::DeleteStmt {
        table_name,
        where_clause,
        returning,
    }))
}

fn extract_simple_table_name(table: sa::TableWithJoins, context: &str) -> Result<String> {
    if !table.joins.is_empty() {
        return Err(unsupported(format!("{context} with JOIN")));
    }
    match table.relation {
        sa::TableFactor::Table { name, args, .. } => {
            if args.is_some() {
                return Err(unsupported(format!("{context} table function args")));
            }
            Ok(object_name_to_string(&name))
        }
        other => Err(unsupported(format!("{context} table factor `{other}`"))),
    }
}

fn convert_column_def(col: sa::ColumnDef) -> Result<kk::ColumnDef> {
    let mut out = kk::ColumnDef {
        name: col.name.value,
        data_type: convert_data_type(col.data_type),
        primary_key: false,
        autoincrement: false,
        not_null: false,
        unique: false,
        default: None,
        references: None,
        check_expr: None,
    };

    for option in col.options {
        match option.option {
            sa::ColumnOption::NotNull => out.not_null = true,
            sa::ColumnOption::PrimaryKey(_) => out.primary_key = true,
            sa::ColumnOption::Unique(_) => out.unique = true,
            sa::ColumnOption::Default(expr) => out.default = Some(convert_expr(expr)?),
            // L1: REFERENCES table(col) column-level constraint
            sa::ColumnOption::ForeignKey(fk) => {
                let table_name = fk
                    .foreign_table
                    .0
                    .iter()
                    .filter_map(|part| match part {
                        sa::ObjectNamePart::Identifier(ident) => Some(ident.value.clone()),
                        _ => None,
                    })
                    .collect::<Vec<_>>()
                    .join(".");
                let ref_col = fk
                    .referred_columns
                    .into_iter()
                    .next()
                    .map(|ident| ident.value);
                out.references = Some(kk::ForeignKeyRef {
                    table: table_name,
                    column: ref_col,
                    on_delete: convert_fk_action(fk.on_delete),
                    on_update: convert_fk_action(fk.on_update),
                });
            }
            // L2: CHECK (expr) column-level constraint
            sa::ColumnOption::Check(cc) => {
                if let Ok(expr) = convert_expr(*cc.expr) {
                    out.check_expr = Some(expr);
                }
            }
            sa::ColumnOption::DialectSpecific(tokens) => {
                for tok in tokens {
                    if tok.to_string().eq_ignore_ascii_case("AUTOINCREMENT") {
                        out.autoincrement = true;
                    }
                }
            }
            sa::ColumnOption::Identity(sa::IdentityPropertyKind::Autoincrement(_)) => {
                out.autoincrement = true;
            }
            sa::ColumnOption::Null
            | sa::ColumnOption::OnConflict(_)
            | sa::ColumnOption::Comment(_)
            | sa::ColumnOption::CharacterSet(_)
            | sa::ColumnOption::Collation(_) => {}
            _ => {}
        }
    }
    Ok(out)
}

/// Convert a top-level Query AST node to either a simple Select or a SetOp statement.
/// Handles UNION / INTERSECT / EXCEPT and correctly places ORDER BY / LIMIT on the
/// combined result (not on the right-side query).
fn convert_query_statement(query: sa::Query) -> Result<kk::Statement> {
    use super::query::convert_query_to_select;

    if query.fetch.is_some() {
        return Err(unsupported("FETCH at query level"));
    }
    // R6: FOR UPDATE is now handled in convert_query_to_select — no rejection here
    if query.for_clause.is_some() {
        return Err(unsupported("FOR clause"));
    }
    // WITH CTE is handled in convert_query_to_select — do NOT block it here

    // Peel off ORDER BY / LIMIT / WITH that belong to the whole statement
    let top_order_by = query.order_by;
    let top_limit = query.limit_clause;
    let top_with = query.with;

    match *query.body {
        sa::SetExpr::SetOperation {
            op,
            set_quantifier,
            left,
            right,
        } => {
            // Bug #3 fix: ByName means UNION DISTINCT by column name — treat as DISTINCT
            let all = matches!(set_quantifier, sa::SetQuantifier::All);
            let kind = match op {
                sa::SetOperator::Union => {
                    if all {
                        kk::SetOpKind::UnionAll
                    } else {
                        kk::SetOpKind::UnionDistinct
                    }
                }
                sa::SetOperator::Intersect => {
                    if all {
                        kk::SetOpKind::IntersectAll
                    } else {
                        kk::SetOpKind::IntersectDistinct
                    }
                }
                sa::SetOperator::Except | sa::SetOperator::Minus => {
                    if all {
                        kk::SetOpKind::ExceptAll
                    } else {
                        kk::SetOpKind::ExceptDistinct
                    }
                }
            };

            // Bug #2 fix: left/right may themselves be SetOperations — recurse via
            // convert_query_statement if needed, then unwrap to SelectStmt.
            // For simplicity we flatten each side: if a side is a SetOperation it will
            // produce a nested SetOp Statement; we call exec_set_op recursively.
            // The left side never has ORDER BY / LIMIT.
            let left_query = sa::Query {
                with: None,
                body: left,
                order_by: None,
                limit_clause: None,
                fetch: None,
                locks: Vec::new(),
                for_clause: None,
                settings: None,
                format_clause: None,
                pipe_operators: Vec::new(),
            };
            // Bug #2 fix: right side also never has ORDER BY / LIMIT (those are on top)
            let right_query = sa::Query {
                with: None,
                body: right,
                order_by: None,
                limit_clause: None,
                fetch: None,
                locks: Vec::new(),
                for_clause: None,
                settings: None,
                format_clause: None,
                pipe_operators: Vec::new(),
            };

            let left_select = Box::new(convert_query_to_select(left_query)?);
            let right_select = Box::new(convert_query_to_select(right_query)?);

            // Bug #1 fix: ORDER BY / LIMIT go on SetOpStmt, applied after combining
            let (limit, offset) = if let Some(lc) = top_limit {
                match lc {
                    sa::LimitClause::LimitOffset { limit, offset, .. } => (
                        limit.map(convert_expr).transpose()?,
                        offset.map(|o| convert_expr(o.value)).transpose()?,
                    ),
                    sa::LimitClause::OffsetCommaLimit { offset, limit } => {
                        (Some(convert_expr(limit)?), Some(convert_expr(offset)?))
                    }
                }
            } else {
                (None, None)
            };

            let order_by = if let Some(ob) = top_order_by {
                convert_order_by_items(ob)?
            } else {
                Vec::new()
            };

            Ok(kk::Statement::SetOp(kk::SetOpStmt {
                kind,
                left: left_select,
                right: right_select,
                order_by,
                limit,
                offset,
            }))
        }
        body => {
            // Simple SELECT with top-level ORDER BY / LIMIT / WITH (CTE)
            let assembled = sa::Query {
                with: top_with, // preserve CTE definitions
                body: Box::new(body),
                order_by: top_order_by,
                limit_clause: top_limit,
                fetch: None,
                locks: Vec::new(),
                for_clause: None,
                settings: None,
                format_clause: None,
                pipe_operators: Vec::new(),
            };
            let select = convert_query_to_select(assembled)?;
            Ok(kk::Statement::Select(Box::new(select)))
        }
    }
}

// Helper: convert ORDER BY expressions for SetOpStmt
fn convert_order_by_items(order_by: sa::OrderBy) -> Result<Vec<kk::OrderByItem>> {
    if order_by.interpolate.is_some() {
        return Err(unsupported("ORDER BY INTERPOLATE"));
    }
    let exprs = match order_by.kind {
        sa::OrderByKind::Expressions(exprs) => exprs,
        sa::OrderByKind::All(_) => return Err(unsupported("ORDER BY ALL")),
    };
    let mut out = Vec::with_capacity(exprs.len());
    for item in exprs {
        out.push(kk::OrderByItem {
            expr: convert_expr(item.expr)?,
            ascending: item.options.asc.unwrap_or(true),
            nulls_first: item.options.nulls_first,
        });
    }
    Ok(out)
}

/// Public helper: convert a set expression (UNION/INTERSECT/EXCEPT) into a SetOpStmt.
/// Used by query.rs when a nested set operation appears as a sub-query body.
pub(crate) fn convert_set_expr_to_setop(
    op: sa::SetOperator,
    set_quantifier: sa::SetQuantifier,
    left: Box<sa::SetExpr>,
    right: Box<sa::SetExpr>,
) -> Result<kk::SetOpStmt> {
    let all = matches!(set_quantifier, sa::SetQuantifier::All);
    let kind = match op {
        sa::SetOperator::Union => {
            if all {
                kk::SetOpKind::UnionAll
            } else {
                kk::SetOpKind::UnionDistinct
            }
        }
        sa::SetOperator::Intersect => {
            if all {
                kk::SetOpKind::IntersectAll
            } else {
                kk::SetOpKind::IntersectDistinct
            }
        }
        sa::SetOperator::Except | sa::SetOperator::Minus => {
            if all {
                kk::SetOpKind::ExceptAll
            } else {
                kk::SetOpKind::ExceptDistinct
            }
        }
    };
    use super::query::convert_query_to_select;
    let left_select = Box::new(convert_query_to_select(sa::Query {
        with: None,
        body: left,
        order_by: None,
        limit_clause: None,
        fetch: None,
        locks: Vec::new(),
        for_clause: None,
        settings: None,
        format_clause: None,
        pipe_operators: Vec::new(),
    })?);
    let right_select = Box::new(convert_query_to_select(sa::Query {
        with: None,
        body: right,
        order_by: None,
        limit_clause: None,
        fetch: None,
        locks: Vec::new(),
        for_clause: None,
        settings: None,
        format_clause: None,
        pipe_operators: Vec::new(),
    })?);
    Ok(kk::SetOpStmt {
        kind,
        left: left_select,
        right: right_select,
        order_by: Vec::new(),
        limit: None,
        offset: None,
    })
}

fn convert_privileges(privs: sa::Privileges) -> Result<kk::PrivilegeList> {
    match privs {
        sa::Privileges::All { .. } => Ok(kk::PrivilegeList::All),
        sa::Privileges::Actions(actions) => {
            let mut lst = Vec::new();
            for act in actions {
                match act {
                    sa::Action::Select { .. } => lst.push("SELECT".to_string()),
                    sa::Action::Insert { .. } => lst.push("INSERT".to_string()),
                    sa::Action::Update { .. } => lst.push("UPDATE".to_string()),
                    sa::Action::Delete => lst.push("DELETE".to_string()),
                    sa::Action::References { .. } => lst.push("REFERENCES".to_string()),
                    sa::Action::Trigger => lst.push("TRIGGER".to_string()),
                    sa::Action::Truncate => lst.push("TRUNCATE".to_string()),
                    sa::Action::Connect => lst.push("CONNECT".to_string()),
                    sa::Action::Create { .. } => lst.push("CREATE".to_string()),
                    sa::Action::Execute { .. } => lst.push("EXECUTE".to_string()),
                    sa::Action::Usage => lst.push("USAGE".to_string()),
                    // Catch-all
                    _ => lst.push(format!("{:?}", act).to_uppercase()),
                }
            }
            Ok(kk::PrivilegeList::Specific(lst))
        }
    }
}

fn convert_grant_object(obj: sa::GrantObjects) -> Result<kk::GrantObject> {
    match obj {
        sa::GrantObjects::Tables(tables) => {
            let first = tables
                .first()
                .ok_or_else(|| unsupported("GRANT without object"))?;
            Ok(kk::GrantObject::Table(object_name_to_string(first)))
        }
        sa::GrantObjects::Sequences(_) => Err(unsupported("GRANT ON SEQUENCE")),
        sa::GrantObjects::Schemas(schemas) => {
            let first = schemas
                .first()
                .ok_or_else(|| unsupported("GRANT without object"))?;
            Ok(kk::GrantObject::Database(object_name_to_string(first)))
        }
        sa::GrantObjects::Databases(dbs) => {
            let first = dbs
                .first()
                .ok_or_else(|| unsupported("GRANT without object"))?;
            Ok(kk::GrantObject::Database(object_name_to_string(first)))
        }
        _ => Err(unsupported("Unknown GRANT Object format")),
    }
}

/// Convert sqlparser ReferentialAction into our FkAction enum.
fn convert_fk_action(action: Option<sa::ReferentialAction>) -> kk::FkAction {
    match action {
        Some(sa::ReferentialAction::Cascade) => kk::FkAction::Cascade,
        Some(sa::ReferentialAction::SetNull) => kk::FkAction::SetNull,
        _ => kk::FkAction::Restrict,
    }
}

use crate::error::{KkdbError, Result};
use crate::storage::pager::{page_size_to_u16, page_size_to_u16_val, u16_to_page_size, Pager, PAGE_SIZE};
use crate::types::{deserialize_row, serialize_row, serialize_row_into, Row};

/// B-Tree page types (compatible with SQLite format concepts)
/// 0x02 = interior index b-tree page
/// 0x05 = interior table b-tree page
/// 0x0A = leaf index b-tree page
/// 0x0D = leaf table b-tree page
const LEAF_TABLE: u8 = 0x0D;
const INTERIOR_TABLE: u8 = 0x05;

/// Overflow page: [next_overflow_page: u32 (0 = end)][data: PAGE_SIZE-4 bytes]
const OVERFLOW_DATA_SIZE: usize = PAGE_SIZE - 4;

/// Maximum payload stored inline in a leaf cell.
/// If payload exceeds this, an overflow chain is written.
/// Keep well under PAGE_SIZE/2 so at least 2 cells fit per page.
const MAX_INLINE_PAYLOAD: usize = PAGE_SIZE / 2 - 32; // ≈ 2016 bytes

/// Bit-flag stored in the high bit of the on-disk `payload_size` field.
/// When set, the cell carries an overflow chain.
/// On-disk: bit31 = overflow flag; bits 0-30 = inline_payload_len.
const OVERFLOW_FLAG: u32 = 0x8000_0000;

/// B-Tree page header layout:
/// Leaf page (LEAF_TABLE = 0x0D):
/// [0]      page_type (1 byte)
/// [1..3]   cell_count (2 bytes, u16 LE)
/// [3..5]   cell_content_offset (2 bytes, u16 LE) - start of cell content area
/// [5]      fragmented_free_bytes (1 byte)
/// [6..10]  next_leaf_page (4 bytes, u32 LE) — 0 = no next leaf
/// [10..14] prev_leaf_page (4 bytes, u32 LE) — 0 = no prev leaf (doubly-linked list)
///
/// Interior page (INTERIOR_TABLE = 0x05):
/// [0]      page_type (1 byte)
/// [1..3]   cell_count (2 bytes, u16 LE)
/// [3..5]   cell_content_offset (2 bytes, u16 LE)
/// [5]      fragmented_free_bytes (1 byte)
/// [6..10]  right_child_page (4 bytes, u32 LE)
///
/// After header: cell pointer array (2 bytes per pointer, u16 LE)
const LEAF_HEADER_SIZE: usize = 14; // 1+2+2+1+4+4 (includes next_leaf + prev_leaf fields)
const INTERIOR_HEADER_SIZE: usize = 10;

/// Maximum number of child pointers per interior page (computed from PAGE_SIZE).
/// Each cell needs at least 2 bytes (pointer) + 4 bytes (child_page) + 8 bytes (rowid) = 14.
/// Plus 1 extra for the right_child.
const MAX_INTERIOR_CHILDREN: usize = (PAGE_SIZE - INTERIOR_HEADER_SIZE) / 14 + 2;

/// B-Tree operations on the pager
pub struct BTree<'a> {
    pub pager: &'a mut Pager,
}

/// Validates that `cell_offset + needed` fits within `PAGE_SIZE`.
/// Returns `cell_offset` on success or a `CorruptDatabase` error if out of bounds.
#[inline]
fn validate_cell_offset(cell_offset: usize, needed: usize) -> Result<usize> {
    if cell_offset + needed > PAGE_SIZE {
        return Err(KkdbError::CorruptDatabase(format!(
            "cell offset {} + {} exceeds page size {}",
            cell_offset, needed, PAGE_SIZE
        )));
    }
    Ok(cell_offset)
}

impl<'a> BTree<'a> {
    pub fn new(pager: &'a mut Pager) -> Self {
        BTree { pager }
    }

    /// Get the B-tree header offset for a page.
    #[inline]
    fn header_offset(page_num: u32) -> usize {
        let _ = page_num;
        0
    }

    /// Write page header
    fn write_page_header(&mut self, page_num: u32, header: &PageHeader) -> Result<()> {
        let off = Self::header_offset(page_num);
        let page = self.pager.get_page_mut(page_num)?;

        page.data[off] = header.page_type;
        page.data[off + 1..off + 3].copy_from_slice(&header.cell_count.to_le_bytes());
        page.data[off + 3..off + 5].copy_from_slice(&header.cell_content_offset.to_le_bytes());
        page.data[off + 5] = 0; // fragmented bytes
                                // [6..10]: next_leaf (leaf) or right_child (interior) — both encoded as u32
        let ext_value: u32 = header.right_child.unwrap_or(0);
        page.data[off + 6..off + 10].copy_from_slice(&ext_value.to_le_bytes());
        // [10..14]: prev_leaf for leaf pages (zeroed for interior pages)
        if header.page_type == LEAF_TABLE {
            page.data[off + 10..off + 14].copy_from_slice(&0u32.to_le_bytes());
        }

        Ok(())
    }

    // ── leaf linked-list helpers (doubly-linked) ──────────────────────────

    /// Read the `next_leaf` pointer from a leaf page header (bytes [6..10]).
    fn get_next_leaf(&mut self, page_num: u32) -> Result<u32> {
        let page = self.pager.get_page(page_num)?;
        let off = Self::header_offset(page_num);
        Ok(u32::from_le_bytes(
            page.data[off + 6..off + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid next_leaf field".into()))?,
        ))
    }

    /// Write the `next_leaf` pointer into a leaf page header.
    fn set_next_leaf(&mut self, page_num: u32, next: u32) -> Result<()> {
        let off = Self::header_offset(page_num);
        let page = self.pager.get_page_mut(page_num)?;
        page.data[off + 6..off + 10].copy_from_slice(&next.to_le_bytes());
        Ok(())
    }

    /// Read the `prev_leaf` pointer from a leaf page header (bytes [10..14]).
    fn get_prev_leaf(&mut self, page_num: u32) -> Result<u32> {
        let page = self.pager.get_page(page_num)?;
        let off = Self::header_offset(page_num);
        Ok(u32::from_le_bytes(
            page.data[off + 10..off + 14].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid prev_leaf field".into()))?,
        ))
    }

    /// Write the `prev_leaf` pointer into a leaf page header.
    fn set_prev_leaf(&mut self, page_num: u32, prev: u32) -> Result<()> {
        let off = Self::header_offset(page_num);
        let page = self.pager.get_page_mut(page_num)?;
        page.data[off + 10..off + 14].copy_from_slice(&prev.to_le_bytes());
        Ok(())
    }

    /// Initialize a new page as a leaf table page
    pub fn init_leaf_page(&mut self, page_num: u32) -> Result<()> {
        let header = PageHeader {
            page_type: LEAF_TABLE,
            cell_count: 0,
            cell_content_offset: page_size_to_u16(),
            right_child: None,
        };
        self.write_page_header(page_num, &header)
    }

    /// Initialize a new page as an interior table page
    fn init_interior_page(&mut self, page_num: u32, right_child: u32) -> Result<()> {
        let header = PageHeader {
            page_type: INTERIOR_TABLE,
            cell_count: 0,
            cell_content_offset: page_size_to_u16(),
            right_child: Some(right_child),
        };
        self.write_page_header(page_num, &header)
    }

    /// Create a new table, returns the root page number
    pub fn create_table(&mut self) -> Result<u32> {
        let page_num = self.pager.allocate_page()?;
        self.init_leaf_page(page_num)?;
        Ok(page_num)
    }

    // -----------------------------------------------------------------------
    // Overflow page helpers
    // -----------------------------------------------------------------------

    /// Write `payload` into a chain of overflow pages.
    /// Returns the page number of the first overflow page.
    fn write_overflow_chain(&mut self, payload: &[u8]) -> Result<u32> {
        let mut chunks = payload.chunks(OVERFLOW_DATA_SIZE).peekable();
        let first_page = self.pager.allocate_page()?;
        let mut cur_page = first_page;

        while let Some(chunk) = chunks.next() {
            let next_page = if chunks.peek().is_some() {

                self.pager.allocate_page()?
            } else {
                0 // terminal
            };

            let page = self.pager.get_page_mut(cur_page)?;
            // Write next-pointer
            page.data[0..4].copy_from_slice(&next_page.to_le_bytes());
            // Write chunk data
            page.data[4..4 + chunk.len()].copy_from_slice(chunk);
            // Zero remaining bytes in last page
            if next_page == 0 && chunk.len() < OVERFLOW_DATA_SIZE {
                for b in &mut page.data[4 + chunk.len()..PAGE_SIZE] {
                    *b = 0;
                }
            }

            if chunks.peek().is_some() {
                cur_page = next_page;
            }
        }
        Ok(first_page)
    }

    /// Read the full payload for a cell, following overflow chain if needed.
    ///
    /// `raw_payload_size` is the raw u32 read from disk (may have OVERFLOW_FLAG set).
    /// `inline_start` is the byte offset inside the page where the inline payload begins
    /// (i.e. cell_offset + 12).
    /// `page_data` is the page's data slice.
    ///
    /// Returns the complete payload bytes.
    fn read_cell_payload(
        &mut self,
        raw_payload_size: u32,
        inline_start: usize,
        page_data: &[u8],
    ) -> Result<Vec<u8>> {
        if raw_payload_size & OVERFLOW_FLAG == 0 {
            // Normal cell — payload is fully inline
            let len = raw_payload_size as usize;
            if inline_start + len > page_data.len() {
                return Err(KkdbError::CorruptDatabase(format!(
                    "inline payload extends beyond page boundary: offset {} + len {} > page_size {}",
                    inline_start, len, page_data.len()
                )));
            }
            return Ok(page_data[inline_start..inline_start + len].to_vec());
        }

        // Overflow cell layout (after rowid, before overflow ptr):
        //   [inline_len: u32-without-flag (0 inline bytes stored here, flag already stripped)]
        //   [total_payload_len: u32]
        //   [overflow_first_page: u32]
        //   [inline_bytes: inline_len bytes]  (always 0 in current impl)
        let inline_len = (raw_payload_size & !OVERFLOW_FLAG) as usize;
        if inline_start + 8 > page_data.len() {
            return Err(KkdbError::CorruptDatabase(
                "overflow header extends beyond page boundary".into(),
            ));
        }
        let total_len = u32::from_le_bytes(
            page_data[inline_start..inline_start + 4]
                .try_into()
                .map_err(|_| KkdbError::CorruptDatabase("invalid overflow total_len".into()))?,
        ) as usize;
        let overflow_page = u32::from_le_bytes(
            page_data[inline_start + 4..inline_start + 8]
                .try_into()
                .map_err(|_| KkdbError::CorruptDatabase("invalid overflow page pointer".into()))?,
        );

        let mut result = Vec::with_capacity(total_len);
        // Copy any inline prefix
        if inline_start + 8 + inline_len > page_data.len() {
            return Err(KkdbError::CorruptDatabase(
                "overflow inline bytes extend beyond page boundary".into(),
            ));
        }
        result.extend_from_slice(&page_data[inline_start + 8..inline_start + 8 + inline_len]);

        // Follow overflow chain
        let mut cur_page = overflow_page;
        while cur_page != 0 && result.len() < total_len {
            let remaining = total_len - result.len();
            let page = self.pager.get_page(cur_page)?;
            let next_page = u32::from_le_bytes(page.data[0..4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid overflow next pointer".into()))?);
            let to_copy = remaining.min(OVERFLOW_DATA_SIZE);
            result.extend_from_slice(&page.data[4..4 + to_copy]);
            cur_page = next_page;
        }
        Ok(result)
    }

    /// Free an overflow chain starting at `first_page`.
    /// Each page in the chain is returned to the pager's free pool via `pager.free_page`.
    fn free_overflow_chain(&mut self, first_page: u32) -> Result<()> {
        let mut cur = first_page;
        while cur != 0 {
            // Read next pointer before handing the page back to the pool
            let next = {
                let page = self.pager.get_page(cur)?;
                u32::from_le_bytes(page.data[0..4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid overflow next pointer".into()))?)
            };
            self.pager.free_page(cur)?;
            cur = next;
        }
        Ok(())
    }

    // -----------------------------------------------------------------------
    // Public insert API
    // -----------------------------------------------------------------------

    /// Insert a row using a reusable serialize buffer (avoids per-call allocation)
    pub fn insert_with_buf(
        &mut self,
        root_page: u32,
        rowid: i64,
        row: &Row,
        buf: &mut Vec<u8>,
    ) -> Result<u32> {
        serialize_row_into(row, buf);
        match self.insert_into_page(root_page, rowid, buf)? {
            InsertResult::Done => Ok(root_page),
            InsertResult::Split {
                divider_key,
                new_page,
            } => {
                let new_root = self.pager.allocate_page()?;
                self.init_interior_page(new_root, new_page)?;
                self.insert_interior_cell(new_root, divider_key, root_page)?;
                Ok(new_root)
            }
        }
    }

    /// Insert a row into a table B-tree, returns the (possibly new) root page
    pub fn insert(&mut self, root_page: u32, rowid: i64, row: &Row) -> Result<u32> {
        let payload = serialize_row(row);
        match self.insert_into_page(root_page, rowid, &payload)? {
            InsertResult::Done => Ok(root_page),
            InsertResult::Split {
                divider_key,
                new_page,
            } => {
                // Create new root pointing to old root (left) and new_page (right)
                let new_root = self.pager.allocate_page()?;
                self.init_interior_page(new_root, new_page)?;
                self.insert_interior_cell(new_root, divider_key, root_page)?;
                Ok(new_root)
            }
        }
    }

    /// Internal insert - returns Done or Split info to propagate upward
    fn insert_into_page(
        &mut self,
        page_num: u32,
        rowid: i64,
        payload: &[u8],
    ) -> Result<InsertResult> {
        // Guard against payload sizes that would truncate when cast to u32
        if payload.len() > u32::MAX as usize {
            return Err(KkdbError::BTreeError(format!(
                "payload too large: {} bytes exceeds u32::MAX",
                payload.len()
            )));
        }
        // Single page access: read header inline to determine page type and available space
        let (page_type, cell_count, cell_content_offset, _right_child) = {
            let page = self.pager.get_page(page_num)?;
            let off = Self::header_offset(page_num);
            let pt = page.data[off];
            let cc = u16::from_le_bytes(page.data[off + 1..off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?);
            let cco = u16::from_le_bytes(page.data[off + 3..off + 5].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_content_offset field".into()))?);
            let rc = if pt == INTERIOR_TABLE {
                Some(u32::from_le_bytes(
                    page.data[off + 6..off + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid right_child field".into()))?,
                ))
            } else {
                None
            };
            (pt, cc, cco, rc)
        };

        match page_type {
            LEAF_TABLE => {
                // Does this payload need an overflow chain?
                let needs_overflow = payload.len() > MAX_INLINE_PAYLOAD;
                // Inline cell size: normal = 12 + payload.len(); overflow = 12 + 8 (total_len+first_page)
                let cell_len = if needs_overflow {
                    12 + 8
                } else {
                    12 + payload.len()
                };

                let hdr_offset = Self::header_offset(page_num);
                let ptr_array_end = hdr_offset + LEAF_HEADER_SIZE + (cell_count as usize) * 2;
                let available = u16_to_page_size(cell_content_offset).saturating_sub(ptr_array_end);

                if cell_len + 2 <= available {
                    // Fast path: write directly to page
                    if needs_overflow {
                        // Write overflow chain first, then inline cell stub
                        let overflow_page = self.write_overflow_chain(payload)?;
                        self.insert_overflow_cell_raw(
                            page_num,
                            rowid,
                            payload.len() as u32,
                            overflow_page,
                        )?;
                    } else {
                        self.insert_cell_into_leaf_raw(page_num, rowid, payload)?;
                    }
                    Ok(InsertResult::Done)
                } else {
                    // Split path: need materialized cell_data
                    let cell_data = if needs_overflow {
                        let overflow_page = self.write_overflow_chain(payload)?;
                        Self::make_overflow_cell(rowid, payload.len() as u32, overflow_page)
                    } else {
                        Self::make_leaf_cell(rowid, payload)
                    };
                    self.split_leaf(page_num, rowid, &cell_data)
                }
            }
            INTERIOR_TABLE => {
                let child_page = self.find_child_page(page_num, rowid)?;
                match self.insert_into_page(child_page, rowid, payload)? {
                    InsertResult::Done => Ok(InsertResult::Done),
                    InsertResult::Split {
                        divider_key,
                        new_page,
                    } => {
                        // Re-read header inline (may have changed after recursive insert)
                        let available = {
                            let page = self.pager.get_page(page_num)?;
                            let off = Self::header_offset(page_num);
                            let cc =
                                u16::from_le_bytes(page.data[off + 1..off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?)
                                    as usize;
                            let cco =
                                u16_to_page_size(u16::from_le_bytes(page.data[off + 3..off + 5].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_content_offset field".into()))?));
                            let ptr_end = off + INTERIOR_HEADER_SIZE + cc * 2;
                            cco.saturating_sub(ptr_end)
                        };
                        if 12 + 2 <= available {
                            self.insert_interior_cell(page_num, divider_key, child_page)?;
                            self.replace_child_pointer(
                                page_num,
                                child_page,
                                divider_key,
                                new_page,
                            )?;
                            Ok(InsertResult::Done)
                        } else {
                            self.split_interior(page_num, divider_key, child_page, new_page)
                        }
                    }
                }
            }
            _ => Err(KkdbError::BTreeError(format!(
                "invalid page type: 0x{:02x}",
                page_type
            ))),
        }
    }

    /// Make a normal leaf table cell: [payload_size:u32][rowid:i64][payload]
    fn make_leaf_cell(rowid: i64, payload: &[u8]) -> Vec<u8> {
        let mut cell = Vec::with_capacity(12 + payload.len());
        cell.extend_from_slice(&(payload.len() as u32).to_le_bytes());
        cell.extend_from_slice(&rowid.to_le_bytes());
        cell.extend_from_slice(payload);
        cell
    }

    /// Make an overflow cell stub:
    /// [payload_size|OVERFLOW_FLAG:u32][rowid:i64][total_payload_len:u32][overflow_first_page:u32]
    fn make_overflow_cell(rowid: i64, total_payload_len: u32, overflow_first_page: u32) -> Vec<u8> {
        let mut cell = Vec::with_capacity(20);
        // payload_size field: OVERFLOW_FLAG set, inline_len = 0
        cell.extend_from_slice(&OVERFLOW_FLAG.to_le_bytes());
        cell.extend_from_slice(&rowid.to_le_bytes());
        cell.extend_from_slice(&total_payload_len.to_le_bytes());
        cell.extend_from_slice(&overflow_first_page.to_le_bytes());
        cell
    }

    /// Binary-search helper: find insertion index in a leaf's pointer array.
    /// Returns `Err` if `rowid` already exists.
    fn leaf_insert_index(
        page_data: &[u8],
        ptr_base: usize,
        cell_count: usize,
        rowid: i64,
    ) -> Result<usize> {
        let mut lo = 0usize;
        let mut hi = cell_count;
        while lo < hi {
            let mid = lo + (hi - lo) / 2;
            let mid_ptr = ptr_base + mid * 2;
            let mid_cell_off =
                u16::from_le_bytes(page_data[mid_ptr..mid_ptr + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?) as usize;
            let mid_rowid = i64::from_le_bytes(
                page_data[mid_cell_off + 4..mid_cell_off + 12]
                    .try_into()
                    .map_err(|_| KkdbError::CorruptDatabase("invalid rowid field".into()))?,
            );
            if mid_rowid == rowid {
                return Err(KkdbError::ConstraintViolation(format!(
                    "UNIQUE constraint failed: rowid {rowid}"
                )));
            } else if mid_rowid < rowid {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        Ok(lo)
    }

    /// Write a pre-built cell at `new_content_offset` inside the page and update pointer array + header.
    fn write_cell_to_leaf(
        page: &mut crate::storage::pager::Page,
        hdr_offset: usize,
        cell_data: &[u8],
        insert_idx: usize,
        cell_count: usize,
    ) -> Result<()> {
        let hdr_size = LEAF_HEADER_SIZE;
        let ptr_base = hdr_offset + hdr_size;
        let cell_content_offset = u16_to_page_size(u16::from_le_bytes(
            page.data[hdr_offset + 3..hdr_offset + 5]
                .try_into()
                .map_err(|_| KkdbError::CorruptDatabase("invalid cell_content_offset field".into()))?,
        ));
        if cell_content_offset < cell_data.len() {
            return Err(KkdbError::CorruptDatabase("leaf page overflow: cell_content_offset < cell size".into()));
        }
        let new_offset = cell_content_offset - cell_data.len();

        // Write cell bytes
        page.data[new_offset..new_offset + cell_data.len()].copy_from_slice(cell_data);

        // Shift pointers right
        for i in (insert_idx..cell_count).rev() {
            let src = ptr_base + i * 2;
            let dst = ptr_base + (i + 1) * 2;
            let val = u16::from_le_bytes(page.data[src..src + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?);
            page.data[dst..dst + 2].copy_from_slice(&val.to_le_bytes());
        }
        page.data[ptr_base + insert_idx * 2..ptr_base + insert_idx * 2 + 2]
            .copy_from_slice(&(new_offset as u16).to_le_bytes());

        // Update header
        page.data[hdr_offset + 1..hdr_offset + 3]
            .copy_from_slice(&((cell_count + 1) as u16).to_le_bytes());
        page.data[hdr_offset + 3..hdr_offset + 5]
            .copy_from_slice(&(new_offset as u16).to_le_bytes());
        Ok(())
    }

    /// Insert a normal (non-overflow) cell into a leaf page directly (no intermediate Vec).
    /// Fix #8: now delegates the pointer-shift + header-update step to write_cell_to_leaf.
    fn insert_cell_into_leaf_raw(
        &mut self,
        page_num: u32,
        rowid: i64,
        payload: &[u8],
    ) -> Result<()> {
        let hdr_offset = Self::header_offset(page_num);
        let cell_len = 12 + payload.len();

        let page = self.pager.get_page_mut(page_num)?;
        let off = hdr_offset;
        let cell_count =
            u16::from_le_bytes(page.data[off + 1..off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?) as usize;
        let ptr_base = hdr_offset + LEAF_HEADER_SIZE;

        let insert_idx = Self::leaf_insert_index(&page.data, ptr_base, cell_count, rowid)?;

        // Build the 12-byte cell header inline and write header + payload into the page,
        // then let write_cell_to_leaf handle the pointer-array shift and header update.
        let cell_content_offset =
            u16_to_page_size(u16::from_le_bytes(page.data[off + 3..off + 5].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_content_offset field".into()))?));
        if cell_content_offset < cell_len {
            return Err(KkdbError::CorruptDatabase("leaf page overflow: cell_content_offset < cell size".into()));
        }
        let new_offset = cell_content_offset - cell_len;
        page.data[new_offset..new_offset + 4]
            .copy_from_slice(&(payload.len() as u32).to_le_bytes());
        page.data[new_offset + 4..new_offset + 12].copy_from_slice(&rowid.to_le_bytes());
        page.data[new_offset + 12..new_offset + cell_len].copy_from_slice(payload);

        // Shift pointer array and update header counts / cell_content_offset.
        let ptr_base_end = ptr_base + cell_count * 2;
        for i in (insert_idx..cell_count).rev() {
            let src = ptr_base + i * 2;
            let dst = src + 2;
            let val = u16::from_le_bytes(page.data[src..src + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?);
            page.data[dst..dst + 2].copy_from_slice(&val.to_le_bytes());
        }
        let _ = ptr_base_end;
        page.data[ptr_base + insert_idx * 2..ptr_base + insert_idx * 2 + 2]
            .copy_from_slice(&(new_offset as u16).to_le_bytes());
        page.data[off + 1..off + 3].copy_from_slice(&((cell_count + 1) as u16).to_le_bytes());
        page.data[off + 3..off + 5].copy_from_slice(&(new_offset as u16).to_le_bytes());

        Ok(())
    }

    /// Insert an overflow-cell stub into a leaf page directly.
    /// Inline portion: [OVERFLOW_FLAG | 0 : u32][rowid: i64][total_len: u32][first_overflow_page: u32] = 20 bytes
    fn insert_overflow_cell_raw(
        &mut self,
        page_num: u32,
        rowid: i64,
        total_payload_len: u32,
        overflow_first_page: u32,
    ) -> Result<()> {
        let hdr_offset = Self::header_offset(page_num);
        let cell_len = 20usize; // 4 + 8 + 4 + 4

        let page = self.pager.get_page_mut(page_num)?;
        let off = hdr_offset;
        let cell_count =
            u16::from_le_bytes(page.data[off + 1..off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?) as usize;
        let ptr_base = hdr_offset + LEAF_HEADER_SIZE;
        let insert_idx = Self::leaf_insert_index(&page.data, ptr_base, cell_count, rowid)?;

        let cell_content_offset =
            u16_to_page_size(u16::from_le_bytes(page.data[off + 3..off + 5].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_content_offset field".into()))?));
        if cell_content_offset < cell_len {
            return Err(KkdbError::CorruptDatabase("leaf page overflow: cell_content_offset < cell size".into()));
        }
        let new_offset = cell_content_offset - cell_len;

        page.data[new_offset..new_offset + 4].copy_from_slice(&OVERFLOW_FLAG.to_le_bytes());
        page.data[new_offset + 4..new_offset + 12].copy_from_slice(&rowid.to_le_bytes());
        page.data[new_offset + 12..new_offset + 16]
            .copy_from_slice(&total_payload_len.to_le_bytes());
        page.data[new_offset + 16..new_offset + 20]
            .copy_from_slice(&overflow_first_page.to_le_bytes());

        for i in (insert_idx..cell_count).rev() {
            let src = ptr_base + i * 2;
            let dst = ptr_base + (i + 1) * 2;
            let val = u16::from_le_bytes(page.data[src..src + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?);
            page.data[dst..dst + 2].copy_from_slice(&val.to_le_bytes());
        }
        page.data[ptr_base + insert_idx * 2..ptr_base + insert_idx * 2 + 2]
            .copy_from_slice(&(new_offset as u16).to_le_bytes());

        page.data[off + 1..off + 3].copy_from_slice(&((cell_count + 1) as u16).to_le_bytes());
        page.data[off + 3..off + 5].copy_from_slice(&(new_offset as u16).to_le_bytes());

        Ok(())
    }

    /// Insert a cell into a leaf page (assumes it fits) — takes a pre-built cell_data slice.
    ///
    /// Fix #8: uses `leaf_insert_index` + `write_cell_to_leaf` instead of inlining a second
    /// copy of the binary-search and pointer-shift logic.
    fn insert_cell_into_leaf(&mut self, page_num: u32, rowid: i64, cell_data: &[u8]) -> Result<()> {
        let hdr_offset = Self::header_offset(page_num);
        let page = self.pager.get_page_mut(page_num)?;
        let off = hdr_offset;
        let cell_count =
            u16::from_le_bytes(page.data[off + 1..off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?) as usize;
        let ptr_base = hdr_offset + LEAF_HEADER_SIZE;

        let insert_idx = Self::leaf_insert_index(&page.data, ptr_base, cell_count, rowid)?;
        Self::write_cell_to_leaf(page, hdr_offset, cell_data, insert_idx, cell_count)?;
        Ok(())
    }

    /// Split a leaf page and insert a cell — returns Split info to propagate upward.
    /// Maintains the doubly-linked leaf list:
    ///   left.next = right, right.next = old_next,
    ///   right.prev = left, old_next.prev = right (if old_next != 0).
    fn split_leaf(&mut self, page_num: u32, rowid: i64, cell_data: &[u8]) -> Result<InsertResult> {
        // Read old next_leaf and prev_leaf before we clear the page
        let old_next = self.get_next_leaf(page_num)?;
        let old_prev = self.get_prev_leaf(page_num)?;

        // Collect all raw cell bytes at once (may include overflow stubs)
        let mut cells: Vec<(i64, Vec<u8>)> = {
            let page = self.pager.get_page(page_num)?;
            let data = &page.data;
            let hdr_offset = Self::header_offset(page_num);
            let cell_count =
                u16::from_le_bytes(data[hdr_offset + 1..hdr_offset + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?)
                    as usize;
            let ptr_base = hdr_offset + LEAF_HEADER_SIZE;
            let mut v = Vec::with_capacity(cell_count + 1);
            for i in 0..cell_count {
                let ptr_off = ptr_base + i * 2;
                let cell_off =
                    u16::from_le_bytes(data[ptr_off..ptr_off + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?) as usize;
                validate_cell_offset(cell_off, 12)?;
                let raw_size = u32::from_le_bytes(data[cell_off..cell_off + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid payload size field".into()))?);
                let rid = i64::from_le_bytes(data[cell_off + 4..cell_off + 12].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid rowid field".into()))?);
                // Cell length on the page (stub only for overflow cells)
                let cell_len = if raw_size & OVERFLOW_FLAG != 0 {
                    20 // overflow stub: 4+8+4+4
                } else {
                    12 + (raw_size as usize)
                };
                validate_cell_offset(cell_off, cell_len)?;
                v.push((rid, data[cell_off..cell_off + cell_len].to_vec()));
            }
            v
        };

        let insert_pos = cells
            .iter()
            .position(|(rid, _)| rowid < *rid)
            .unwrap_or(cells.len());
        cells.insert(insert_pos, (rowid, cell_data.to_vec()));

        let mut mid = cells.len() / 2;
        if insert_pos == cells.len() - 1 {
            mid = cells.len() - 1; // Right-Edge Append Optimization
        }

        let divider_key = cells[mid].0;

        // Re-init left page and fill
        self.init_leaf_page(page_num)?;
        for (rid, cell) in &cells[..mid] {
            self.insert_cell_into_leaf(page_num, *rid, cell)?;
        }

        // Allocate + fill right page
        let right_page_num = self.pager.allocate_page()?;
        self.init_leaf_page(right_page_num)?;
        for (rid, cell) in &cells[mid..] {
            self.insert_cell_into_leaf(right_page_num, *rid, cell)?;
        }

        // Wire doubly-linked leaf list:
        //   left(page_num) → right_page_num → old_next
        //   left.prev = old_prev (restored after init_leaf_page zeroed it)
        //   right.prev = left
        //   old_next.prev = right (if old_next != 0)
        self.set_next_leaf(page_num, right_page_num)?;
        self.set_prev_leaf(page_num, old_prev)?;
        self.set_next_leaf(right_page_num, old_next)?;
        self.set_prev_leaf(right_page_num, page_num)?;
        if old_next != 0 {
            self.set_prev_leaf(old_next, right_page_num)?;
        }

        Ok(InsertResult::Split {
            divider_key,
            new_page: right_page_num,
        })
    }

    /// Split an interior page — returns Split info to propagate upward
    fn split_interior(
        &mut self,
        page_num: u32,
        new_key: i64,
        left_child: u32,
        right_child_of_new: u32,
    ) -> Result<InsertResult> {
        // Single page access: read header + collect all cells
        let (mut cells, old_right_child) = {
            let page = self.pager.get_page(page_num)?;
            let data = &page.data;
            let hdr_offset = Self::header_offset(page_num);
            let cell_count =
                u16::from_le_bytes(data[hdr_offset + 1..hdr_offset + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?)
                    as usize;
            let rc = u32::from_le_bytes(data[hdr_offset + 6..hdr_offset + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid right_child field".into()))?);
            let mut v = Vec::with_capacity(cell_count + 1);
            for i in 0..cell_count {
                let ptr_offset = hdr_offset + INTERIOR_HEADER_SIZE + i * 2;
                let cell_offset =
                    u16::from_le_bytes(data[ptr_offset..ptr_offset + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?)
                        as usize;
                validate_cell_offset(cell_offset, 12)?;
                let child =
                    u32::from_le_bytes(data[cell_offset..cell_offset + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid child page pointer".into()))?);
                let key =
                    i64::from_le_bytes(data[cell_offset + 4..cell_offset + 12].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid key field".into()))?);
                v.push((child, key));
            }
            (v, rc)
        };

        // Insert new cell in sorted position
        // The new cell: left_child points to left_child, key = new_key
        // After this cell, the next cell's left_child (or right_child) = right_child_of_new
        let insert_pos = cells
            .iter()
            .position(|(_, k)| new_key < *k)
            .unwrap_or(cells.len());
        cells.insert(insert_pos, (left_child, new_key));

        // Fix child pointers: the cell at insert_pos+1 should have left_child = right_child_of_new
        // Or if insert_pos is last, the page's right_child = right_child_of_new
        let final_right_child;
        if insert_pos + 1 < cells.len() {
            cells[insert_pos + 1].0 = right_child_of_new;
            final_right_child = old_right_child;
        } else {
            final_right_child = right_child_of_new;
        }

        let mut mid = cells.len() / 2;
        // Right-Edge Append Optimization for Interior Nodes
        if insert_pos == cells.len() - 1 {
            mid = cells.len() - 1;
        }

        // Split at midpoint: promote middle key
        let promoted_key = cells[mid].1;

        // Left page (reuse current page): cells[0..mid], right_child = cells[mid].0
        let left_right_child = cells[mid].0;
        self.init_interior_page(page_num, left_right_child)?;
        for cell in cells.iter().take(mid) {
            self.insert_interior_cell(page_num, cell.1, cell.0)?;
        }

        // Right page (new): cells[mid+1..], right_child = final_right_child
        let new_page = self.pager.allocate_page()?;
        self.init_interior_page(new_page, final_right_child)?;
        for cell in cells.iter().skip(mid + 1) {
            self.insert_interior_cell(new_page, cell.1, cell.0)?;
        }

        Ok(InsertResult::Split {
            divider_key: promoted_key,
            new_page,
        })
    }

    /// After inserting a divider cell, update the child pointer:
    /// The cell with key = divider_key has left_child = old_child_page.
    /// The right side of that divider should point to new_page.
    /// This means: if there's a cell after divider_key, its left_child = new_page.
    /// Otherwise, the page's right_child = new_page.
    fn replace_child_pointer(
        &mut self,
        page_num: u32,
        _old_child: u32,
        divider_key: i64,
        new_page: u32,
    ) -> Result<()> {
        let hdr_offset = Self::header_offset(page_num);
        // Single page access: read header, find divider, update pointer
        let page = self.pager.get_page_mut(page_num)?;
        let off = hdr_offset;
        let cell_count =
            u16::from_le_bytes(page.data[off + 1..off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?) as usize;
        let ptr_base = hdr_offset + INTERIOR_HEADER_SIZE;

        // Find the cell with key == divider_key
        let mut divider_idx = None;
        for i in 0..cell_count {
            let p = ptr_base + i * 2;
            let cell_off = u16::from_le_bytes(page.data[p..p + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?) as usize;
            validate_cell_offset(cell_off, 12)?;
            let key =
                i64::from_le_bytes(page.data[cell_off + 4..cell_off + 12].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid key field".into()))?);
            if key == divider_key {
                divider_idx = Some(i);
                break;
            }
        }

        let div_i = divider_idx
            .ok_or_else(|| KkdbError::BTreeError("divider key not found after insert".into()))?;

        if div_i + 1 < cell_count {
            // Update left_child of the NEXT cell to new_page
            let next_ptr_offset = ptr_base + (div_i + 1) * 2;
            let next_cell_offset = u16::from_le_bytes(
                page.data[next_ptr_offset..next_ptr_offset + 2]
                    .try_into()
                    .map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?,
            ) as usize;
            page.data[next_cell_offset..next_cell_offset + 4]
                .copy_from_slice(&new_page.to_le_bytes());
        } else {
            // divider is the last cell — update right_child in header
            page.data[off + 6..off + 10].copy_from_slice(&new_page.to_le_bytes());
        }

        Ok(())
    }

    /// Insert a cell into an interior page (sorted by key)
    fn insert_interior_cell(&mut self, page_num: u32, key: i64, left_child: u32) -> Result<()> {
        let hdr_offset = Self::header_offset(page_num);

        // Interior cell: [left_child_page: u32][key: i64] = 12 bytes
        let mut cell_data = [0u8; 12];
        cell_data[0..4].copy_from_slice(&left_child.to_le_bytes());
        cell_data[4..12].copy_from_slice(&key.to_le_bytes());

        // Single page access: read header, binary search, write cell, shift pointers, update header
        let page = self.pager.get_page_mut(page_num)?;
        let off = hdr_offset;
        let cell_count =
            u16::from_le_bytes(page.data[off + 1..off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?) as usize;
        let cell_content_offset =
            u16_to_page_size(u16::from_le_bytes(page.data[off + 3..off + 5].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_content_offset field".into()))?));

        // Binary search for insertion position (inline — avoids per-iteration page lookup)
        let ptr_base = hdr_offset + INTERIOR_HEADER_SIZE;
        let mut lo = 0usize;
        let mut hi = cell_count;
        while lo < hi {
            let mid = lo + (hi - lo) / 2;
            let mid_ptr = ptr_base + mid * 2;
            let mid_cell_off =
                u16::from_le_bytes(page.data[mid_ptr..mid_ptr + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?) as usize;
            let mid_key = i64::from_le_bytes(
                page.data[mid_cell_off + 4..mid_cell_off + 12]
                    .try_into()
                    .map_err(|_| KkdbError::CorruptDatabase("invalid key field".into()))?,
            );
            if key < mid_key {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        let insert_idx = lo;

        // Write cell content
        if cell_content_offset < cell_data.len() {
            return Err(KkdbError::CorruptDatabase("interior page overflow: cell_content_offset < cell size".into()));
        }
        let new_content_offset = cell_content_offset - cell_data.len();
        page.data[new_content_offset..new_content_offset + cell_data.len()]
            .copy_from_slice(&cell_data);

        // Shift cell pointers to make room at insert_idx
        for i in (insert_idx..cell_count).rev() {
            let src = ptr_base + i * 2;
            let dst = ptr_base + (i + 1) * 2;
            let val = u16::from_le_bytes(page.data[src..src + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?);
            page.data[dst..dst + 2].copy_from_slice(&val.to_le_bytes());
        }
        // Write new pointer at insert_idx
        let ptr_offset = ptr_base + insert_idx * 2;
        page.data[ptr_offset..ptr_offset + 2]
            .copy_from_slice(&(new_content_offset as u16).to_le_bytes());

        // Update header in-place
        page.data[off + 1..off + 3].copy_from_slice(&((cell_count + 1) as u16).to_le_bytes());
        page.data[off + 3..off + 5].copy_from_slice(&(new_content_offset as u16).to_le_bytes());

        Ok(())
    }

    /// Find the child page for a given rowid in an interior page (binary search)
    fn find_child_page(&mut self, page_num: u32, rowid: i64) -> Result<u32> {
        let page = self.pager.get_page(page_num)?;
        let data = &page.data;
        let hdr_offset = Self::header_offset(page_num);

        let cell_count =
            u16::from_le_bytes(data[hdr_offset + 1..hdr_offset + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?) as usize;
        let right_child =
            u32::from_le_bytes(data[hdr_offset + 6..hdr_offset + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid right_child field".into()))?);

        if cell_count == 0 {
            return Ok(right_child);
        }

        // Binary search: find first cell where key > rowid
        let mut lo = 0usize;
        let mut hi = cell_count;
        while lo < hi {
            let mid = lo + (hi - lo) / 2;
            let ptr_offset = hdr_offset + INTERIOR_HEADER_SIZE + mid * 2;
            let cell_offset =
                u16::from_le_bytes(data[ptr_offset..ptr_offset + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?) as usize;
            validate_cell_offset(cell_offset, 12)?;
            let key =
                i64::from_le_bytes(data[cell_offset + 4..cell_offset + 12].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid key field".into()))?);

            if rowid < key {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }

        // lo = first cell where key > rowid
        if lo < cell_count {
            let ptr_offset = hdr_offset + INTERIOR_HEADER_SIZE + lo * 2;
            let cell_offset =
                u16::from_le_bytes(data[ptr_offset..ptr_offset + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?) as usize;
            validate_cell_offset(cell_offset, 4)?;
            let child = u32::from_le_bytes(data[cell_offset..cell_offset + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid child page pointer".into()))?);
            Ok(child)
        } else {
            Ok(right_child)
        }
    }

    // ── Q1 Leaf chain scan ───────────────────────────────────────────────

    /// Walk interior nodes to find the page number of the leftmost leaf.
    fn find_leftmost_leaf(&mut self, root_page: u32) -> Result<u32> {
        let mut cur = root_page;
        loop {
            let page = self.pager.get_page(cur)?;
            let hdr_off = Self::header_offset(cur);
            if page.data[hdr_off] == LEAF_TABLE {
                return Ok(cur);
            }
            // Interior: leftmost child is encoded in the first pointer-array entry
            let cell_count =
                u16::from_le_bytes(page.data[hdr_off + 1..hdr_off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?)
                    as usize;
            let ptr_base = hdr_off + INTERIOR_HEADER_SIZE;
            cur = if cell_count > 0 {
                let cell_off =
                    u16::from_le_bytes(page.data[ptr_base..ptr_base + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?)
                        as usize;
                validate_cell_offset(cell_off, 4)?;
                // Interior cell: [left_child:u32][key:i64]
                u32::from_le_bytes(page.data[cell_off..cell_off + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid child page pointer".into()))?)
            } else {
                // Empty interior: right_child is the only child
                u32::from_le_bytes(page.data[hdr_off + 6..hdr_off + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid right_child field".into()))?)
            };
        }
    }

    /// Scan all (rowid, row) by following the leaf next_leaf linked list.
    /// O(n) and avoids interior node traversal after the initial leftmost-leaf descent.
    fn scan_leaf_chain(&mut self, root_page: u32) -> Result<Vec<(i64, Row)>> {
        let first_leaf = self.find_leftmost_leaf(root_page)?;
        let mut results = Vec::new();
        let mut cur = first_leaf;
        while cur != 0 {
            let page_data = self.pager.get_page(cur)?.data.to_vec();
            let hdr_off = Self::header_offset(cur);
            let cell_count =
                u16::from_le_bytes(page_data[hdr_off + 1..hdr_off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?)
                    as usize;
            let ptr_base = hdr_off + LEAF_HEADER_SIZE;
            for i in 0..cell_count {
                let ptr_off = ptr_base + i * 2;
                let cell_off =
                    u16::from_le_bytes(page_data[ptr_off..ptr_off + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?)
                        as usize;
                let raw_size =
                    u32::from_le_bytes(page_data[cell_off..cell_off + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid payload size field".into()))?);
                let rowid =
                    i64::from_le_bytes(page_data[cell_off + 4..cell_off + 12].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid rowid field".into()))?);
                let payload = self.read_cell_payload(raw_size, cell_off + 12, &page_data)?;
                let row = deserialize_row(&payload)?;
                results.push((rowid, row));
            }
            // Advance to next leaf via the linked list
            let next = u32::from_le_bytes(page_data[hdr_off + 6..hdr_off + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid next_leaf field".into()))?);
            cur = next;
        }
        Ok(results)
    }

    /// Scan all rows by following the leaf chain (rows only, no rowids).
    fn scan_leaf_chain_rows(&mut self, root_page: u32) -> Result<Vec<Row>> {
        let first_leaf = self.find_leftmost_leaf(root_page)?;
        let mut results = Vec::new();
        let mut cur = first_leaf;
        while cur != 0 {
            let page_data = self.pager.get_page(cur)?.data.to_vec();
            let hdr_off = Self::header_offset(cur);
            let cell_count =
                u16::from_le_bytes(page_data[hdr_off + 1..hdr_off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?)
                    as usize;
            let ptr_base = hdr_off + LEAF_HEADER_SIZE;
            for i in 0..cell_count {
                let ptr_off = ptr_base + i * 2;
                let cell_off =
                    u16::from_le_bytes(page_data[ptr_off..ptr_off + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?)
                        as usize;
                validate_cell_offset(cell_off, 4)?;
                let raw_size =
                    u32::from_le_bytes(page_data[cell_off..cell_off + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid payload size field".into()))?);
                let payload = self.read_cell_payload(raw_size, cell_off + 12, &page_data)?;
                let row = deserialize_row(&payload)?;
                results.push(row);
            }
            let next = u32::from_le_bytes(page_data[hdr_off + 6..hdr_off + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid next_leaf field".into()))?);
            cur = next;
        }
        Ok(results)
    }

    /// Scan rows with an early-exit limit using the leaf chain.
    fn scan_leaf_chain_rows_limit(&mut self, root_page: u32, limit: usize) -> Result<Vec<Row>> {
        let first_leaf = self.find_leftmost_leaf(root_page)?;
        let mut results = Vec::with_capacity(limit);
        let mut cur = first_leaf;
        'outer: while cur != 0 {
            let page_data = self.pager.get_page(cur)?.data.to_vec();
            let hdr_off = Self::header_offset(cur);
            let cell_count =
                u16::from_le_bytes(page_data[hdr_off + 1..hdr_off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?)
                    as usize;
            let ptr_base = hdr_off + LEAF_HEADER_SIZE;
            for i in 0..cell_count {
                if results.len() >= limit {
                    break 'outer;
                }
                let ptr_off = ptr_base + i * 2;
                let cell_off =
                    u16::from_le_bytes(page_data[ptr_off..ptr_off + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?)
                        as usize;
                validate_cell_offset(cell_off, 4)?;
                let raw_size =
                    u32::from_le_bytes(page_data[cell_off..cell_off + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid payload size field".into()))?);
                let payload = self.read_cell_payload(raw_size, cell_off + 12, &page_data)?;
                let row = deserialize_row(&payload)?;
                results.push(row);
            }
            let next = u32::from_le_bytes(page_data[hdr_off + 6..hdr_off + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid next_leaf field".into()))?);
            cur = next;
        }
        Ok(results)
    }

    // ── Public scan API ────────────────────────────────────────────────────────

    /// Scan all rows in a table — uses leaf chain scan (O(n), no interior traversal)
    pub fn scan_all(&mut self, root_page: u32) -> Result<Vec<(i64, Row)>> {
        self.scan_leaf_chain(root_page)
    }

    /// Scan all rows without rowids — uses leaf chain scan
    pub fn scan_rows(&mut self, root_page: u32) -> Result<Vec<Row>> {
        self.scan_leaf_chain_rows(root_page)
    }

    /// Scan rows with an early-exit limit — uses leaf chain scan
    pub fn scan_rows_limit(&mut self, root_page: u32, limit: usize) -> Result<Vec<Row>> {
        self.scan_leaf_chain_rows_limit(root_page, limit)
    }

    // ── Backward (reverse) scan via prev_leaf doubly-linked list ─────────────

    /// Walk interior nodes to find the page number of the rightmost leaf.
    fn find_rightmost_leaf(&mut self, page_num: u32) -> Result<u32> {
        let page = self.pager.get_page(page_num)?;
        let data = &page.data;
        let off = Self::header_offset(page_num);
        let page_type = data[off];
        match page_type {
            LEAF_TABLE => Ok(page_num),
            INTERIOR_TABLE => {
                let right_child = u32::from_le_bytes(
                    data[off + 6..off + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid right_child field".into()))?,
                );
                self.find_rightmost_leaf(right_child)
            }
            _ => Err(KkdbError::BTreeError(format!(
                "unexpected page type: 0x{:02x}",
                page_type
            ))),
        }
    }

    /// Scan all rows in reverse order using the prev_leaf doubly-linked list.
    /// Starts from the rightmost leaf and follows prev_leaf pointers backwards.
    /// Within each leaf, cells are iterated in reverse order.
    pub fn scan_all_reverse(&mut self, root_page: u32) -> Result<Vec<(i64, Row)>> {
        let last_leaf = self.find_rightmost_leaf(root_page)?;
        let mut results = Vec::new();
        let mut cur = last_leaf;
        while cur != 0 {
            let page_data = self.pager.get_page(cur)?.data.to_vec();
            let hdr_off = Self::header_offset(cur);
            let cell_count =
                u16::from_le_bytes(page_data[hdr_off + 1..hdr_off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?)
                    as usize;
            let ptr_base = hdr_off + LEAF_HEADER_SIZE;
            // Iterate cells in reverse within this leaf
            for i in (0..cell_count).rev() {
                let ptr_off = ptr_base + i * 2;
                let cell_off =
                    u16::from_le_bytes(page_data[ptr_off..ptr_off + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?)
                        as usize;
                validate_cell_offset(cell_off, 12)?;
                let raw_size = u32::from_le_bytes(page_data[cell_off..cell_off + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid payload size field".into()))?);
                let rowid = i64::from_le_bytes(page_data[cell_off + 4..cell_off + 12].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid rowid field".into()))?);
                let payload = self.read_cell_payload(raw_size, cell_off + 12, &page_data)?;
                let row = deserialize_row(&payload)?;
                results.push((rowid, row));
            }
            // Follow prev_leaf pointer backwards
            let prev = u32::from_le_bytes(page_data[hdr_off + 10..hdr_off + 14].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid prev_leaf field".into()))?);
            cur = prev;
        }
        Ok(results)
    }

    /// Scan rows in reverse with an early-exit limit.
    pub fn scan_rows_reverse_limit(&mut self, root_page: u32, limit: usize) -> Result<Vec<Row>> {
        let last_leaf = self.find_rightmost_leaf(root_page)?;
        let mut results = Vec::with_capacity(limit);
        let mut cur = last_leaf;
        'outer: while cur != 0 {
            let page_data = self.pager.get_page(cur)?.data.to_vec();
            let hdr_off = Self::header_offset(cur);
            let cell_count =
                u16::from_le_bytes(page_data[hdr_off + 1..hdr_off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?)
                    as usize;
            let ptr_base = hdr_off + LEAF_HEADER_SIZE;
            for i in (0..cell_count).rev() {
                if results.len() >= limit {
                    break 'outer;
                }
                let ptr_off = ptr_base + i * 2;
                let cell_off =
                    u16::from_le_bytes(page_data[ptr_off..ptr_off + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?)
                        as usize;
                validate_cell_offset(cell_off, 4)?;
                let raw_size =
                    u32::from_le_bytes(page_data[cell_off..cell_off + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid payload size field".into()))?);
                let payload = self.read_cell_payload(raw_size, cell_off + 12, &page_data)?;
                let row = deserialize_row(&payload)?;
                results.push(row);
            }
            let prev = u32::from_le_bytes(page_data[hdr_off + 10..hdr_off + 14].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid prev_leaf field".into()))?);
            cur = prev;
        }
        Ok(results)
    }

    // ── F1: Prefix-compressed index scan ──────────────────────────────────────

    /// Scan all index entries from a prefix-compressed index B-Tree.
    ///
    /// Each leaf page is decoded with a fresh `PrefixPageDecoder` (reset at page boundary).
    /// Returns `(btree_rowid, index_row)` pairs.
    pub fn scan_all_compressed(&mut self, root_page: u32) -> Result<Vec<(i64, Row)>> {
        use crate::types::deserialize_index_row_with_prefix;
        let first_leaf = self.find_leftmost_leaf(root_page)?;
        let mut results = Vec::new();
        let mut cur = first_leaf;
        while cur != 0 {
            let page_data = self.pager.get_page(cur)?.data.to_vec();
            let hdr_off = Self::header_offset(cur);
            let cell_count =
                u16::from_le_bytes(page_data[hdr_off + 1..hdr_off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?)
                    as usize;
            let ptr_base = hdr_off + LEAF_HEADER_SIZE;
            // Per-page decoder — reset prefix at each new page
            let mut prev_key: Vec<u8> = Vec::new();
            for i in 0..cell_count {
                let ptr_off = ptr_base + i * 2;
                let cell_off =
                    u16::from_le_bytes(page_data[ptr_off..ptr_off + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?)
                        as usize;
                validate_cell_offset(cell_off, 12)?;
                let raw_size =
                    u32::from_le_bytes(page_data[cell_off..cell_off + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid payload size field".into()))?);
                let rowid =
                    i64::from_le_bytes(page_data[cell_off + 4..cell_off + 12].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid rowid field".into()))?);
                let payload = self.read_cell_payload(raw_size, cell_off + 12, &page_data)?;
                let (row, new_prev) = deserialize_index_row_with_prefix(&payload, &prev_key)?;
                prev_key = new_prev;
                results.push((rowid, row));
            }
            let next = u32::from_le_bytes(page_data[hdr_off + 6..hdr_off + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid next_leaf field".into()))?);
            cur = next;
        }
        Ok(results)
    }

    /// Insert a prefix-compressed index row into a B-Tree.
    ///
    /// # ⚠️ IMPORTANT: Monotonic / Bulk-Load Only
    ///
    /// Prefix compression is delta-encoded relative to `prev_key` per **page**.
    /// The B-Tree leaf scanner (`scan_all_compressed`) resets the prev_key to `[]`
    /// at every new page. This means:
    ///
    /// - Rows **within the same leaf page** must be inserted in strictly increasing
    ///   key order so that the delta chain is contiguous and decodable.
    /// - After a **page split**, the new right-leaf starts a fresh delta chain from
    ///   `prev=[]`. Since `split_leaf` copies already-encoded payloads verbatim,
    ///   the right-leaf's first cell was encoded relative to some *mid-page* prev_key,
    ///   **not** relative to `[]` — this would cause incorrect decode.
    ///
    /// Therefore `insert_compressed` is **only safe for append-only / bulk-load index
    /// builds** where all keys arrive in sorted order AND no page split occurs mid-stream
    /// for already-compressed pages. For general-purpose index inserts use `btree.insert`
    /// with the standard (uncompressed) serialization instead.
    ///
    /// `prev_key`: the raw text bytes of the previous row's first key column.
    /// Returns `(new_root, new_prev_key)`.
    pub fn insert_compressed(
        &mut self,
        root_page: u32,
        rowid: i64,
        row: &Row,
        prev_key: &[u8],
    ) -> Result<(u32, Vec<u8>)> {
        use crate::types::serialize_index_row_compressed;
        let (payload, new_prev) = serialize_index_row_compressed(row, prev_key);
        let new_root = match self.insert_into_page(root_page, rowid, &payload)? {
            InsertResult::Done => root_page,
            InsertResult::Split {
                divider_key,
                new_page,
            } => {
                // A page split copies already-encoded delta cells verbatim into the
                // right leaf.  The first cell on that new page was encoded relative to
                // a mid-page predecessor, but `scan_all_compressed` resets prev_key to
                // `[]` at every leaf boundary.  Accepting the split would silently
                // corrupt the prefix-compressed index.  Return an explicit error
                // instead.
                //
                // For resilience we still materialise the split so the pager state
                // stays consistent (the right-leaf was already written), but we surface
                // the problem to the caller.
                let new_root = self.pager.allocate_page()?;
                self.init_interior_page(new_root, new_page)?;
                self.insert_interior_cell(new_root, divider_key, root_page)?;
                return Err(KkdbError::BTreeError(
                    "page split occurred during prefix-compressed insert; \
                     compressed index may be corrupt — rebuild the index"
                        .into(),
                ));
            }
        };
        Ok((new_root, new_prev))
    }

    /// Find a row by rowid
    pub fn find_by_rowid(
        &mut self,
        root_page: u32,
        target_rowid: i64,
    ) -> Result<Option<(i64, Row)>> {
        // Single page access: read header + binary search + deserialize
        let page = self.pager.get_page(root_page)?;
        let data = &page.data;
        let hdr_offset = Self::header_offset(root_page);
        let page_type = data[hdr_offset];
        let cell_count =
            u16::from_le_bytes(data[hdr_offset + 1..hdr_offset + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?) as usize;

        match page_type {
            LEAF_TABLE => {
                let ptr_base = hdr_offset + LEAF_HEADER_SIZE;
                let mut lo = 0usize;
                let mut hi = cell_count;
                let mut found_cell: Option<(usize, u32)> = None;
                while lo < hi {
                    let mid = lo + (hi - lo) / 2;
                    let mid_ptr = ptr_base + mid * 2;
                    let mid_cell_off =
                        u16::from_le_bytes(data[mid_ptr..mid_ptr + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?) as usize;
                    validate_cell_offset(mid_cell_off, 12)?;
                    let mid_rowid = i64::from_le_bytes(
                        data[mid_cell_off + 4..mid_cell_off + 12]
                            .try_into()
                            .map_err(|_| KkdbError::CorruptDatabase("invalid rowid field".into()))?,
                    );
                    if mid_rowid == target_rowid {
                        let raw_size = u32::from_le_bytes(
                            data[mid_cell_off..mid_cell_off + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid payload size field".into()))?,
                        );
                        found_cell = Some((mid_cell_off, raw_size));
                        break;
                    } else if mid_rowid < target_rowid {
                        lo = mid + 1;
                    } else {
                        hi = mid;
                    }
                }
                let _ = page;
                if let Some((cell_off, raw_size)) = found_cell {
                    let page2 = self.pager.get_page(root_page)?;
                    let page_data = page2.data;
                    let _ = page2;
                    let payload = self.read_cell_payload(raw_size, cell_off + 12, &page_data)?;
                    let row = deserialize_row(&payload)?;
                    return Ok(Some((target_rowid, row)));
                }
                Ok(None)
            }
            INTERIOR_TABLE => {
                let child = self.find_child_page(root_page, target_rowid)?;
                self.find_by_rowid(child, target_rowid)
            }
            _ => Err(KkdbError::BTreeError(format!(
                "unexpected page type: 0x{:02x}",
                page_type
            ))),
        }
    }

    /// Delete a row by rowid. Returns (deleted, root_page).
    /// root_page may change in future if rebalancing is implemented.
    pub fn delete_by_rowid(&mut self, root_page: u32, target_rowid: i64) -> Result<(bool, u32)> {
        let deleted = self.delete_from_page(root_page, target_rowid)?;
        // Future: if root becomes empty interior, collapse to child
        Ok((deleted, root_page))
    }

    /// Internal delete - returns whether the row was found and removed
    fn delete_from_page(&mut self, page_num: u32, target_rowid: i64) -> Result<bool> {
        // Read page type to decide branch
        let page = self.pager.get_page(page_num)?;
        let hdr_offset = Self::header_offset(page_num);
        let page_type = page.data[hdr_offset];

        match page_type {
            LEAF_TABLE => {
                // Single page access: binary search + remove in place
                let page = self.pager.get_page_mut(page_num)?;
                let off = hdr_offset;
                let cell_count =
                    u16::from_le_bytes(page.data[off + 1..off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?) as usize;
                let ptr_base = hdr_offset + LEAF_HEADER_SIZE;

                let mut lo = 0usize;
                let mut hi = cell_count;
                while lo < hi {
                    let mid = lo + (hi - lo) / 2;
                    let mid_ptr = ptr_base + mid * 2;
                    let mid_cell_off =
                        u16::from_le_bytes(page.data[mid_ptr..mid_ptr + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?)
                            as usize;
                    validate_cell_offset(mid_cell_off, 12)?;
                    let mid_rowid = i64::from_le_bytes(
                        page.data[mid_cell_off + 4..mid_cell_off + 12]
                            .try_into()
                            .map_err(|_| KkdbError::CorruptDatabase("invalid rowid field".into()))?,
                    );
                    if mid_rowid == target_rowid {
                        // Check if cell has overflow chain — need to free it
                        let raw_size = u32::from_le_bytes(
                            page.data[mid_cell_off..mid_cell_off + 4]
                                .try_into()
                                .map_err(|_| KkdbError::CorruptDatabase("invalid payload size field".into()))?,
                        );
                        let overflow_first = if raw_size & OVERFLOW_FLAG != 0 {
                            Some(u32::from_le_bytes(
                                page.data[mid_cell_off + 16..mid_cell_off + 20]
                                    .try_into()
                                    .map_err(|_| KkdbError::CorruptDatabase("invalid overflow page pointer".into()))?,
                            ))
                        } else {
                            None
                        };

                        // Remove cell from pointer array + update header
                        for i in mid..cell_count - 1 {
                            let src = ptr_base + (i + 1) * 2;
                            let dst = ptr_base + i * 2;
                            let val =
                                u16::from_le_bytes(page.data[src..src + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?);
                            page.data[dst..dst + 2].copy_from_slice(&val.to_le_bytes());
                        }
                        page.data[off + 1..off + 3]
                            .copy_from_slice(&((cell_count - 1) as u16).to_le_bytes());

                        // Must drop mutable borrow of page before calling free_overflow_chain
                        let _ = page;

                        // Free overflow pages (S2: implemented via pager.free_page)
                        if let Some(first_overflow) = overflow_first {
                            self.free_overflow_chain(first_overflow)?;
                        }

                        return Ok(true);
                    } else if mid_rowid < target_rowid {
                        lo = mid + 1;
                    } else {
                        hi = mid;
                    }
                }
                Ok(false)
            }
            INTERIOR_TABLE => {
                let child = self.find_child_page(page_num, target_rowid)?;
                self.delete_from_page(child, target_rowid)
            }
            _ => Err(KkdbError::BTreeError(format!(
                "unexpected page type: 0x{:02x}",
                page_type
            ))),
        }
    }

    /// Update a row (delete + re-insert), returns the (possibly new) root page
    pub fn update_row(&mut self, root_page: u32, rowid: i64, new_row: &Row) -> Result<u32> {
        let (_, current_root) = self.delete_by_rowid(root_page, rowid)?;
        self.insert(current_root, rowid, new_row)
    }

    /// Update a row using a reusable serialize buffer
    pub fn update_row_with_buf(
        &mut self,
        root_page: u32,
        rowid: i64,
        new_row: &Row,
        buf: &mut Vec<u8>,
    ) -> Result<u32> {
        let (_, current_root) = self.delete_by_rowid(root_page, rowid)?;
        self.insert_with_buf(current_root, rowid, new_row, buf)
    }

    /// Get the maximum rowid in a table (for autoincrement)
    pub fn max_rowid(&mut self, root_page: u32) -> Result<i64> {
        let page = self.pager.get_page(root_page)?;
        let data = &page.data;
        let off = Self::header_offset(root_page);
        let page_type = data[off];
        let cell_count = u16::from_le_bytes(data[off + 1..off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?) as usize;

        match page_type {
            LEAF_TABLE => {
                if cell_count == 0 {
                    return Ok(0);
                }
                let ptr_base = off + LEAF_HEADER_SIZE;
                let last_ptr = ptr_base + (cell_count - 1) * 2;
                let cell_off =
                    u16::from_le_bytes(data[last_ptr..last_ptr + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?) as usize;
                validate_cell_offset(cell_off, 12)?;
                Ok(i64::from_le_bytes(
                    data[cell_off + 4..cell_off + 12].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid rowid field".into()))?,
                ))
            }
            INTERIOR_TABLE => {
                let right_child = u32::from_le_bytes(data[off + 6..off + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid right_child field".into()))?);
                self.max_rowid(right_child)
            }
            _ => Err(KkdbError::BTreeError(format!(
                "unexpected page type: 0x{:02x}",
                page_type
            ))),
        }
    }

    /// Count total rows
    pub fn count_rows(&mut self, root_page: u32) -> Result<u64> {
        let page = self.pager.get_page(root_page)?;
        let data = &page.data;
        let off = Self::header_offset(root_page);
        let page_type = data[off];
        let cell_count = u16::from_le_bytes(data[off + 1..off + 3].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell_count field".into()))?) as usize;

        match page_type {
            LEAF_TABLE => Ok(cell_count as u64),
            INTERIOR_TABLE => {
                let mut children = vec![0u32; MAX_INTERIOR_CHILDREN];
                let child_count = cell_count + 1;
                for (i, child) in children.iter_mut().enumerate().take(cell_count) {
                    let ptr_offset = off + INTERIOR_HEADER_SIZE + i * 2;
                    let cell_offset =
                        u16::from_le_bytes(data[ptr_offset..ptr_offset + 2].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid cell pointer".into()))?)
                            as usize;
                    validate_cell_offset(cell_offset, 4)?;
                    *child =
                        u32::from_le_bytes(data[cell_offset..cell_offset + 4].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid child page pointer".into()))?);
                }
                children[cell_count] =
                    u32::from_le_bytes(data[off + 6..off + 10].try_into().map_err(|_| KkdbError::CorruptDatabase("invalid right_child field".into()))?);

                let mut total = 0u64;
                for child in children.iter().take(child_count) {
                    total += self.count_rows(*child)?;
                }
                Ok(total)
            }
            _ => Ok(0),
        }
    }

    // ── VACUUM / Defragmentation ─────────────────────────────────────────

    /// Collect fragmentation statistics for a B-Tree rooted at `root_page`.
    ///
    /// Returns `(total_leaf_pages, total_fragmented_bytes, total_overflow_pages,
    ///           free_space_bytes)`.
    pub fn fragmentation_stats(
        &mut self,
        root_page: u32,
    ) -> Result<(u64, u64, u64, u64)> {
        let mut total_leaves = 0u64;
        let mut total_frag = 0u64;
        let mut total_overflow = 0u64;
        let mut total_free = 0u64;
        self.collect_frag_stats(root_page, &mut total_leaves, &mut total_frag, &mut total_overflow, &mut total_free)?;
        Ok((total_leaves, total_frag, total_overflow, total_free))
    }

    fn collect_frag_stats(
        &mut self,
        page_num: u32,
        leaves: &mut u64,
        frag: &mut u64,
        overflow: &mut u64,
        free: &mut u64,
    ) -> Result<()> {
        let off = Self::header_offset(page_num);
        let (page_type, cell_count, cco, frag_bytes) = {
            let page = self.pager.get_page(page_num)?;
            let pt = page.data[off];
            let cc = u16::from_le_bytes(
                page.data[off + 1..off + 3]
                    .try_into()
                    .map_err(|_| KkdbError::CorruptDatabase("bad cc".into()))?,
            );
            let co = u16_to_page_size(u16::from_le_bytes(
                page.data[off + 3..off + 5]
                    .try_into()
                    .map_err(|_| KkdbError::CorruptDatabase("bad cco".into()))?,
            ));
            let fb = page.data[off + 5];
            (pt, cc as usize, co, fb as u64)
        };

        if page_type == LEAF_TABLE {
            *leaves += 1;
            *frag += frag_bytes;
            let hdr_size = LEAF_HEADER_SIZE;
            let ptr_end = off + hdr_size + cell_count * 2;
            let gap = cco.saturating_sub(ptr_end);
            *free += gap as u64;

            // Count overflow pages per cell
            let mut overflow_starts: Vec<u32> = Vec::new();
            {
                let page = self.pager.get_page(page_num)?;
                for i in 0..cell_count {
                    let ptr_offset = off + hdr_size + i * 2;
                    if ptr_offset + 2 > PAGE_SIZE {
                        break;
                    }
                    let cell_off = u16_to_page_size(u16::from_le_bytes(
                        page.data[ptr_offset..ptr_offset + 2]
                            .try_into()
                            .map_err(|_| KkdbError::CorruptDatabase("bad ptr".into()))?,
                    ));
                    if cell_off + 12 > PAGE_SIZE {
                        continue;
                    }
                    let payload_size =
                        u32::from_le_bytes(page.data[cell_off..cell_off + 4].try_into().unwrap())
                            as usize;
                    if payload_size > PAGE_SIZE - 12 {
                        let first_overflow = u32::from_le_bytes(
                            page.data[cell_off + 8..cell_off + 12].try_into().unwrap(),
                        );
                        overflow_starts.push(first_overflow);
                    }
                }
            }
            for first in overflow_starts {
                *overflow += self.count_overflow_pages(first)?;
            }
        } else if page_type == INTERIOR_TABLE {
            // Recurse into children
            let page = self.pager.get_page(page_num)?;
            let mut children = Vec::with_capacity(cell_count + 1);
            for i in 0..cell_count {
                let ptr_offset = off + INTERIOR_HEADER_SIZE + i * 2;
                if ptr_offset + 2 > PAGE_SIZE {
                    break;
                }
                let cell_off = u16_to_page_size(u16::from_le_bytes(
                    page.data[ptr_offset..ptr_offset + 2]
                        .try_into()
                        .map_err(|_| KkdbError::CorruptDatabase("bad ptr".into()))?,
                ));
                if cell_off + 4 > PAGE_SIZE {
                    continue;
                }
                let child = u32::from_le_bytes(
                    page.data[cell_off..cell_off + 4].try_into().unwrap(),
                );
                children.push(child);
            }
            // Right child
            let rc = u32::from_le_bytes(
                page.data[off + 6..off + 10]
                    .try_into()
                    .map_err(|_| KkdbError::CorruptDatabase("bad rc".into()))?,
            );
            children.push(rc);

            for child in children {
                self.collect_frag_stats(child, leaves, frag, overflow, free)?;
            }
        }
        Ok(())
    }

    fn count_overflow_pages(&mut self, first_page: u32) -> Result<u64> {
        let mut count = 0;
        let mut cur = first_page;
        while cur != 0 {
            count += 1;
            let page = self.pager.get_page(cur)?;
            cur = u32::from_le_bytes(
                page.data[0..4]
                    .try_into()
                    .map_err(|_| KkdbError::CorruptDatabase("bad overflow ptr".into()))?,
            );
        }
        Ok(count)
    }

    /// Defragment a single leaf page by compacting its cell content area.
    ///
    /// Returns `true` if the page was actually defragmented (had fragments),
    /// `false` if it was already compact.
    pub fn defragment_leaf(&mut self, page_num: u32) -> Result<bool> {
        let off = Self::header_offset(page_num);

        // Read header
        let (page_type, cell_count, frag_bytes) = {
            let page = self.pager.get_page(page_num)?;
            let pt = page.data[off];
            let cc = u16::from_le_bytes(
                page.data[off + 1..off + 3]
                    .try_into()
                    .map_err(|_| KkdbError::CorruptDatabase("bad cc".into()))?,
            ) as usize;
            let fb = page.data[off + 5];
            (pt, cc, fb)
        };

        if page_type != LEAF_TABLE || frag_bytes == 0 {
            return Ok(false);
        }

        // Collect all cells: (ptr_index, cell_offset, cell_data)
        let mut cells: Vec<(usize, Vec<u8>)> = Vec::with_capacity(cell_count);
        {
            let page = self.pager.get_page(page_num)?;
            for i in 0..cell_count {
                let ptr_off = off + LEAF_HEADER_SIZE + i * 2;
                if ptr_off + 2 > PAGE_SIZE {
                    break;
                }
                let cell_off = u16_to_page_size(u16::from_le_bytes(
                    page.data[ptr_off..ptr_off + 2]
                        .try_into()
                        .map_err(|_| KkdbError::CorruptDatabase("bad ptr".into()))?,
                ));
                // Read cell size: payload_size (4 bytes) tells us the cell length
                if cell_off + 4 > PAGE_SIZE {
                    continue;
                }
                let payload_size =
                    u32::from_le_bytes(page.data[cell_off..cell_off + 4].try_into().unwrap())
                        as usize;
                // Cell format: [payload_size:4][rowid:8][payload or overflow stub]
                let inline_payload = if payload_size > PAGE_SIZE - 12 {
                    4 // overflow stub: just the 4-byte overflow page pointer is inline
                } else {
                    payload_size
                };
                let cell_len = 4 + 8 + inline_payload; // payload_size + rowid + inline data
                let end = (cell_off + cell_len).min(PAGE_SIZE);
                cells.push((i, page.data[cell_off..end].to_vec()));
            }
        }

        // Rewrite the page with compacted cells
        let page = self.pager.get_page_mut(page_num)?;
        // Clear the cell content area (from after ptr array to end of page)
        let ptr_end = off + LEAF_HEADER_SIZE + cell_count * 2;
        page.data[ptr_end..PAGE_SIZE].fill(0);

        // Write cells from the end of the page, compactly
        let mut write_offset = PAGE_SIZE;
        for (i, cell_data) in &cells {
            write_offset -= cell_data.len();
            page.data[write_offset..write_offset + cell_data.len()].copy_from_slice(cell_data);
            // Update pointer
            let ptr_off = off + LEAF_HEADER_SIZE + i * 2;
            page.data[ptr_off..ptr_off + 2]
                .copy_from_slice(&page_size_to_u16_val(write_offset).to_le_bytes());
        }

        // Update header: new cell_content_offset, clear fragmented_free_bytes
        page.data[off + 3..off + 5]
            .copy_from_slice(&page_size_to_u16_val(write_offset).to_le_bytes());
        page.data[off + 5] = 0; // fragmented bytes = 0

        Ok(true)
    }

    /// Defragment all leaf pages in the B-Tree rooted at `root_page`.
    /// Returns the number of pages actually defragmented.
    pub fn defragment_all(&mut self, root_page: u32) -> Result<u64> {
        let off = Self::header_offset(root_page);
        let page_type = {
            let page = self.pager.get_page(root_page)?;
            page.data[off]
        };

        if page_type == LEAF_TABLE {
            Ok(if self.defragment_leaf(root_page)? { 1 } else { 0 })
        } else if page_type == INTERIOR_TABLE {
            let page = self.pager.get_page(root_page)?;
            let cell_count = u16::from_le_bytes(
                page.data[off + 1..off + 3]
                    .try_into()
                    .map_err(|_| KkdbError::CorruptDatabase("bad cc".into()))?,
            ) as usize;
            let mut children = Vec::with_capacity(cell_count + 1);
            for i in 0..cell_count {
                let ptr_off = off + INTERIOR_HEADER_SIZE + i * 2;
                if ptr_off + 2 > PAGE_SIZE {
                    break;
                }
                let cell_off = u16_to_page_size(u16::from_le_bytes(
                    page.data[ptr_off..ptr_off + 2]
                        .try_into()
                        .map_err(|_| KkdbError::CorruptDatabase("bad ptr".into()))?,
                ));
                if cell_off + 4 > PAGE_SIZE {
                    continue;
                }
                let child = u32::from_le_bytes(
                    page.data[cell_off..cell_off + 4].try_into().unwrap(),
                );
                children.push(child);
            }
            let rc = u32::from_le_bytes(
                page.data[off + 6..off + 10]
                    .try_into()
                    .map_err(|_| KkdbError::CorruptDatabase("bad rc".into()))?,
            );
            children.push(rc);

            let mut total = 0;
            for child in children {
                total += self.defragment_all(child)?;
            }
            Ok(total)
        } else {
            Ok(0)
        }
    }
}

/// Result of an internal insert operation
enum InsertResult {
    /// Insert completed without splitting
    Done,
    /// Page was split: divider_key should be promoted, new_page is the right half
    Split { divider_key: i64, new_page: u32 },
}

#[derive(Debug)]
struct PageHeader {
    page_type: u8,
    cell_count: u16,
    cell_content_offset: u16,
    right_child: Option<u32>,
}

