        file.write_all(&page3).unwrap();
        file.flush().unwrap();
    }

    match Pager::open(&path) {
        Err(KkdbError::CorruptDatabase(msg)) => {
            assert!(msg.contains("does not fit file len") || msg.contains("openable superblock"))
