            );
        }
        Err(other) => panic!("expected CorruptDatabase(too short), got {}", other),
        Ok(_) => panic!("expected short buffer to be rejected"),
    }

    // Exactly 67 bytes (one byte short of COW_SUPERBLOCK_SIZE=68)
