#[cfg(test)]
mod tests {
    use super::*;
    use crate::types::Value;

    #[test]
    fn test_pool_creation() {
        let pool = ConnectionPool::new_memory(4);
        assert_eq!(pool.max_connections(), 4);
        assert_eq!(pool.active_connections(), 0);
    }

    #[test]
    fn test_pool_checkout_and_drop() {
        let pool = ConnectionPool::new_memory(4);
        assert_eq!(pool.active_connections(), 0);

        {
            let _conn = pool.checkout().unwrap();
            assert_eq!(pool.active_connections(), 1);
        }
        // After drop, slot is released
        assert_eq!(pool.active_connections(), 0);
        assert_eq!(pool.total_checkouts(), 1);
    }

    #[test]
    fn test_pool_multiple_connections() {
        let pool = ConnectionPool::new_memory(4);

        let c1 = pool.checkout().unwrap();
        let c2 = pool.checkout().unwrap();
        let c3 = pool.checkout().unwrap();
        assert_eq!(pool.active_connections(), 3);

        drop(c2);
        assert_eq!(pool.active_connections(), 2);

        drop(c1);
        drop(c3);
        assert_eq!(pool.active_connections(), 0);
    }

    #[test]
    fn test_pool_execute_sql() {
        let pool = ConnectionPool::new_memory(4);
        let conn = pool.checkout().unwrap();

        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, v TEXT)").unwrap();
        conn.execute("INSERT INTO t VALUES (1, 'hello')").unwrap();

        match conn.execute("SELECT * FROM t").unwrap() {
            ExecResult::QueryResult { columns, rows } => {
                assert_eq!(columns, vec!["id", "v"]);
                assert_eq!(rows.len(), 1);
                assert_eq!(rows[0][1], Value::Text("hello".into()));
            }
            _ => panic!("expected QueryResult"),
        }
    }

    #[test]
    fn test_pool_exhaustion_timeout() {
        let pool = ConnectionPool::new(
            Arc::new(Mutex::new(VM::new_memory())),
            PoolConfig {
                max_connections: 1,
                checkout_timeout: Some(Duration::from_millis(50)),
            },
        );

        let _c1 = pool.checkout().unwrap();
        // Pool is full — second checkout should timeout
        let result = pool.checkout();
        assert!(result.is_err());
        assert_eq!(pool.total_timeout_errors(), 1);
    }

    #[test]
    fn test_pool_connection_id_monotonic() {
        let pool = ConnectionPool::new_memory(4);
        let c1 = pool.checkout().unwrap();
        let c2 = pool.checkout().unwrap();
        assert!(c2.id() > c1.id());
    }

    #[test]
    fn test_pool_multithreaded_access() {
        use std::thread;
        let pool = Arc::new(ConnectionPool::new_memory(4));

        // Setup: create table
        {
            let conn = pool.checkout().unwrap();
            conn.execute("CREATE TABLE mt (id INTEGER PRIMARY KEY, v INTEGER)").unwrap();
        }

        // Spawn threads that each insert a row
        let handles: Vec<_> = (0..4)
            .map(|i| {
                let pool_clone = Arc::clone(&pool);
                thread::spawn(move || {
                    let conn = pool_clone.checkout().unwrap();
                    conn.execute(&format!("INSERT INTO mt VALUES ({}, {})", i + 1, i * 10))
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        // Verify all rows are inserted
        let conn = pool.checkout().unwrap();
        match conn.execute("SELECT COUNT(*) FROM mt").unwrap() {
            ExecResult::QueryResult { rows, .. } => {
                assert_eq!(rows[0][0], Value::Integer(4));
            }
            _ => panic!("expected QueryResult"),
        }
    }

    #[test]
    fn test_pool_session_vars_per_connection() {
        let pool = ConnectionPool::new_memory(4);
        let mut c1 = pool.checkout().unwrap();
        let mut c2 = pool.checkout().unwrap();

        c1.session_vars.insert("role".into(), "admin".into());
        c2.session_vars.insert("role".into(), "user".into());

        assert_eq!(c1.session_vars.get("role"), Some(&"admin".to_string()));
        assert_eq!(c2.session_vars.get("role"), Some(&"user".to_string()));
    }

    #[test]
    fn test_pool_drop_releases_slot_for_waiting() {
        use std::thread;
        use std::sync::Arc;

        let pool = Arc::new(ConnectionPool::new(
            Arc::new(Mutex::new(VM::new_memory())),
            PoolConfig {
                max_connections: 1,
                checkout_timeout: Some(Duration::from_secs(5)),
            },
        ));

        let conn = pool.checkout().unwrap();
        assert_eq!(pool.active_connections(), 1);

        // Spawn a thread that tries to checkout (will block)
        let pool2 = Arc::clone(&pool);
        let handle = thread::spawn(move || {
            let _conn = pool2.checkout().unwrap();
            assert_eq!(pool2.active_connections(), 1);
        });

        // Small delay to let the thread start waiting
        thread::sleep(Duration::from_millis(50));

        // Release our connection — waiting thread should unblock
        drop(conn);

        handle.join().unwrap();
        assert_eq!(pool.active_connections(), 0);
    }
}

use std::fs::File;
use std::io::{BufRead, BufReader, BufWriter, Write};

use crate::error::{KkdbError, Result};
use crate::storage::btree::BTree;
use crate::types::Value;
use crate::vm::execute::{ExecResult, VM};

impl VM {
    /// Backup the entire database to a SQL dump file.
    pub fn backup(&mut self, file_path: &str) -> Result<()> {
        let mut file = BufWriter::new(File::create(file_path).map_err(KkdbError::Io)?);

        writeln!(file, "BEGIN TRANSACTION;").map_err(KkdbError::Io)?;

        // 1. Scan catalog for all DDL definitions
        let mut obj_sqls = Vec::new();
        {
            let schema_root = self.pager.schema_root_page();
            let mut btree = BTree::new(&mut self.pager);
            let rows = btree.scan_all(schema_root)?;
            for (_, row) in rows {
                if row.len() >= 5 {
                    if let Value::Text(sql) = &row[4] {
                        let obj_type = match &row[0] {
                            Value::Text(t) => t.to_string(),
                            _ => continue,
                        };
                        let name = match &row[1] {
                            Value::Text(n) => n.to_string(),
                            _ => continue,
                        };

                        // I23 fix: only include user-visible object types.
                        // Filter out internal catalog rows like `rls_enabled`.
                        const ALLOWED_TYPES: &[&str] = &[
                            "table",
                            "index",
                            "view",
                            "trigger",
                            "fts_table",
                            "fulltext_index",
                        ];
                        if !ALLOWED_TYPES
                            .iter()
                            .any(|t| obj_type.eq_ignore_ascii_case(t))
                        {
                            continue;
                        }

                        obj_sqls.push((obj_type, name, sql.to_string()));
                    }
                }
            }
        }

        // 2. Write tables first, then data, then indexes/views
        for (obj_type, name, sql) in &obj_sqls {
            if obj_type == "table" {
                writeln!(file, "{};", sql).map_err(KkdbError::Io)?;

                // Dump data for this table
                let query = format!("SELECT * FROM {};", name);
                let result = self.execute_sql(&query)?;
                if let ExecResult::QueryResult { columns, rows } = result {
                    // M23 fix: emit explicit column names so that restoring to a table with
                    // different column order still works correctly.
                    let col_names_str = columns
                        .iter()
                        .map(|c| format!("\"{}\"", c.replace('"', "\"\"")))
                        .collect::<Vec<_>>()
                        .join(", ");
                    for row in rows {
                        let values_str = row
                            .iter()
                            .map(|v| match v {
                                Value::Null => "NULL".to_string(),
                                Value::Integer(i) => i.to_string(),
                                Value::Real(f) => format!("{}", f),
                                Value::Text(t) => {
                                    // Escape single quotes
                                    format!("'{}'", t.replace('\'', "''"))
                                }
                                Value::Blob(b) => {
                                    let hex: String =
                                        b.iter().map(|byte| format!("{:02X}", byte)).collect();
                                    format!("X'{}'", hex)
                                }
                            })
                            .collect::<Vec<_>>()
                            .join(", ");
                        writeln!(
                            file,
                            "INSERT INTO {} ({}) VALUES ({});",
                            name, col_names_str, values_str
                        )
                        .map_err(KkdbError::Io)?;
                    }
                }
            }
        }

        // Write indexes, views, FTS tables, fulltext indexes
        for (obj_type, _name, sql) in &obj_sqls {
            if obj_type == "index"
                || obj_type == "view"
                || obj_type == "fts_table"
                || obj_type == "fulltext_index"
            {
                writeln!(file, "{};", sql).map_err(KkdbError::Io)?;
            }
        }

        // Write triggers last (they depend on tables existing)
        for (obj_type, _name, sql) in &obj_sqls {
            if obj_type == "trigger" {
                writeln!(file, "{};", sql).map_err(KkdbError::Io)?;
            }
        }

        writeln!(file, "COMMIT;").map_err(KkdbError::Io)?;
        file.flush().map_err(KkdbError::Io)?;

        Ok(())
    }

    /// Restore the database from a SQL dump file.
    pub fn restore(&mut self, file_path: &str) -> Result<()> {
        let file = File::open(file_path).map_err(KkdbError::Io)?;
        let reader = BufReader::new(file);

        let mut current_stmt = String::new();
        // M12 fix: track whether we are inside a single-quoted string so that
        // ';' characters within string values don't prematurely terminate a statement.
        let mut in_string = false;

        for line in reader.lines() {
            let line = line.map_err(KkdbError::Io)?;
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with("--") {
                continue;
            }

            // Walk each character to track quote state and detect end-of-statement
            let mut stmt_ended = false;
            let chars: Vec<char> = line.chars().collect();
            let mut i = 0;
            while i < chars.len() {
                let ch = chars[i];
                if ch == '\'' {
                    // Check for escaped quote ('') inside a string
                    if in_string && i + 1 < chars.len() && chars[i + 1] == '\'' {
                        current_stmt.push('\'');
                        current_stmt.push('\'');
                        i += 2;
                        continue;
                    }
                    in_string = !in_string;
                } else if ch == ';' && !in_string {
                    current_stmt.push(';');
                    stmt_ended = true;
                    break; // Execute this statement immediately
                }
                current_stmt.push(ch);
                i += 1;
            }
            if !stmt_ended {
                current_stmt.push('\n'); // preserve newlines within multi-line values
            }

            if stmt_ended && !current_stmt.trim().is_empty() {
                // M21 fix: skip statements that are just ";" (after trimming),
                // which can appear as artifacts of the multi-line parsing.
                let effective = current_stmt.trim().trim_end_matches(';').trim();
                if !effective.is_empty() {
                    self.execute_sql(&current_stmt)?;
                }
                current_stmt.clear();
            }
        }

        // Execute any remaining statement without a final semicolon
        if !current_stmt.trim().is_empty() {
            self.execute_sql(&current_stmt)?;
        }

        Ok(())
    }

    /// Export a table to a CSV file.
    pub fn export_csv(&mut self, table_name: &str, file_path: &str) -> Result<()> {
        let query = format!("SELECT * FROM {};", table_name);
        if let ExecResult::QueryResult { columns, rows } = self.execute_sql(&query)? {
            let mut file = BufWriter::new(File::create(file_path).map_err(KkdbError::Io)?);

            // Write Header
            // M9 fix: always double-quote column headers to handle spaces/commas/quotes
            let header = columns
                .iter()
                .map(|c| format!("\"{}\"", c.replace('"', "\"\"")))
                .collect::<Vec<_>>()
                .join(",");
            writeln!(file, "{}", header).map_err(KkdbError::Io)?;

            // Write Rows
            for row in rows {
                let csv_line = row
                    .iter()
                    .map(|v| match v {
                        Value::Null => "".to_string(),
                        Value::Integer(i) => i.to_string(),
                        Value::Real(f) => format!("{}", f),
                        Value::Text(t) => {
                            if t.contains(',') || t.contains('"') || t.contains('\n') {
                                format!("\"{}\"", t.replace("\"", "\"\""))
                            } else {
                                t.to_string()
                            }
                        }
                        Value::Blob(b) => {
                            let hex: String =
                                b.iter().map(|byte| format!("{:02X}", byte)).collect();
                            format!("X'{}'", hex)
                        }
                    })
                    .collect::<Vec<_>>()
                    .join(",");
                writeln!(file, "{}", csv_line).map_err(KkdbError::Io)?;
            }
            file.flush().map_err(KkdbError::Io)?;
            Ok(())
        } else {
            Err(KkdbError::Internal("Export query failed".into()))
        }
    }

    /// Import a CSV file into a table.
    /// Very basic CSV parser: assumes comma-delimited and double-quote escaping.
    pub fn import_csv(&mut self, file_path: &str, table_name: &str) -> Result<()> {
        let file = File::open(file_path).map_err(KkdbError::Io)?;
        let reader = BufReader::new(file);
        let mut lines = reader.lines();

        let _header_line = match lines.next() {
            Some(Ok(l)) => l,
            _ => return Err(KkdbError::Internal("Empty CSV file".into())),
        };

        // For simplicity, we assume the CSV header exactly matches the table schema columns in order.
        // We will insert by positional values.
        self.execute_sql("BEGIN TRANSACTION;")?;

        let mut insert_sql = format!("INSERT INTO {} VALUES (", table_name);
        let schema = self.schema.get_table(table_name)?;
        let expected_cols = schema.columns.len();

        for _ in 0..expected_cols {
            insert_sql.push_str("?, ");
        }

        for line in lines {
            let line = line.map_err(KkdbError::Io)?;
            if line.trim().is_empty() {
                continue;
            }

            // Very naive split.
            let mut fields = Vec::new();
            let mut current = String::new();
            let mut in_quotes = false;
            let mut chars = line.chars().peekable();
            let mut was_quoted = false; // I12: track if the current field was double-quoted
            let mut field_quoted_flags: Vec<bool> = Vec::new();

            while let Some(c) = chars.next() {
                if c == '"' {
                    if in_quotes && chars.peek() == Some(&'"') {
                        current.push('"');
                        chars.next();
                    } else {
                        if !in_quotes {
                            was_quoted = true;
                        }
                        in_quotes = !in_quotes;
                    }
                } else if c == ',' && !in_quotes {
                    fields.push(current.clone());
                    field_quoted_flags.push(was_quoted);
                    current.clear();
                    was_quoted = false;
                } else {
                    current.push(c);
                }
            }
            fields.push(current);
            field_quoted_flags.push(was_quoted);

            // Construct VALUES clause literal
            // I12 fix: only use numeric literal if field was NOT quoted AND looks numeric
            let val_literals = fields
                .into_iter()
                .zip(field_quoted_flags)
                .map(|(f, quoted)| {
                    if f.is_empty() {
                        "NULL".to_string()
                    } else if !quoted
                        && (f.parse::<i64>().is_ok()
                            || (f.parse::<f64>().is_ok()
                                && (f.contains('.') || f.to_ascii_lowercase().contains('e'))))
                    {
                        f // Unquoted numeric: use as numeric
                    } else {
                        format!("'{}'", f.replace("'", "''")) // Everything else: string literal
                    }
                })
                .collect::<Vec<_>>()
                .join(", ");

            let stmt = format!("INSERT INTO {} VALUES ({});", table_name, val_literals);
            if let Err(e) = self.execute_sql(&stmt) {
                let _ = self.execute_sql("ROLLBACK;");
                return Err(e);
            }
        }

        self.execute_sql("COMMIT;")?;
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use crate::vm::execute::{ExecResult, VM};
    use std::fs;

    #[test]
    fn test_csv_export_import_edge_cases() {
        let mut vm = VM::new_memory();
        vm.execute_sql("CREATE TABLE test_csv (id INTEGER PRIMARY KEY, msg TEXT, amt REAL);")
            .unwrap();

        // CSV Edge cases
        vm.execute_sql("INSERT INTO test_csv VALUES (1, 'Hello, world', 10.5);")
            .unwrap();
        vm.execute_sql("INSERT INTO test_csv VALUES (2, 'Quotes \"inside\" correctly', 20.0);")
            .unwrap();
        vm.execute_sql("INSERT INTO test_csv VALUES (3, NULL, NULL);")
            .unwrap();

        let csv_path = "unit_test_edge_cases.csv";
        let _ = fs::remove_file(csv_path);

        assert!(vm.export_csv("test_csv", csv_path).is_ok());

        let mut vm2 = VM::new_memory();
        vm2.execute_sql("CREATE TABLE test_csv (id INTEGER PRIMARY KEY, msg TEXT, amt REAL);")
            .unwrap();
        assert!(vm2.import_csv(csv_path, "test_csv").is_ok());

        let res = vm2
            .execute_sql("SELECT msg, amt FROM test_csv ORDER BY id;")
            .unwrap();
        if let ExecResult::QueryResult { rows, .. } = res {
            assert_eq!(rows.len(), 3);
            assert!(
                matches!(&rows[0][0], crate::types::Value::Text(t) if t.as_ref() == "Hello, world")
            );
            assert!(
                matches!(&rows[1][0], crate::types::Value::Text(t) if t.as_ref() == "Quotes \"inside\" correctly")
            );
            assert!(matches!(&rows[2][0], crate::types::Value::Null));
        } else {
            panic!("Expected query result");
        }

        let _ = fs::remove_file(csv_path);
    }

    #[test]
    fn test_backup_restore_in_memory() {
        let mut vm = VM::new_memory();
        vm.execute_sql("CREATE TABLE units (val INTEGER);").unwrap();
        vm.execute_sql("INSERT INTO units VALUES (999);").unwrap();

        let backup_path = "unit_test_backup.sql";
        let _ = fs::remove_file(backup_path);

        assert!(vm.backup(backup_path).is_ok());

        let mut vm2 = VM::new_memory();
        assert!(vm2.restore(backup_path).is_ok());

        let res = vm2.execute_sql("SELECT * FROM units;").unwrap();
        if let ExecResult::QueryResult { rows, .. } = res {
            assert_eq!(rows.len(), 1);
            assert!(matches!(&rows[0][0], crate::types::Value::Integer(999)));
        } else {
            panic!("Expected query result");
        }

        let _ = fs::remove_file(backup_path);
    }
}

use super::execute::{ExecResult, VM};
use crate::error::{KkdbError, Result};
use crate::sql::ast::*;
use crate::types::{Row, Value};
use std::collections::HashMap;

impl VM {
    // ---- Expression Evaluation ----

    #[inline]
    pub fn eval_expr(
        &mut self,
        expr: &Expr,
        row: &Row,
        col_map: &HashMap<String, usize>,
    ) -> Result<Value> {
        match expr {
            Expr::IntegerLiteral(v) => Ok(Value::Integer(*v)),
            Expr::RealLiteral(v) => Ok(Value::Real(*v)),
            Expr::StringLiteral(v) => Ok(Value::Text(v.clone().into())),
            Expr::BlobLiteral(v) => Ok(Value::Blob(v.clone())),
            Expr::Null => Ok(Value::Null),

            Expr::Placeholder(idx) => self
                .current_params
                .get(*idx)
                .cloned()
                .ok_or_else(|| {
                    KkdbError::RuntimeError(format!(
                        "parameter index {} out of range ({} parameter{} supplied)",
                        idx,
                        self.current_params.len(),
                        if self.current_params.len() == 1 { "" } else { "s" }
                    ))
                }),

            Expr::ColumnRef { table, column } => {
                // If table qualifier is specified, try qualified lookup first
                if let Some(t) = table {
                    // Build "table.column" key on the stack to avoid heap allocation
                    let mut buf = String::with_capacity(t.len() + 1 + column.len());
                    for c in t.as_bytes() {
                        buf.push(c.to_ascii_lowercase() as char);
                    }
                    buf.push('.');
                    for c in column.as_bytes() {
                        buf.push(c.to_ascii_lowercase() as char);
                    }
                    if let Some(&idx) = col_map.get(buf.as_str()) {
                        return if idx < row.len() {
                            Ok(row[idx].clone())
                        } else {
                            Ok(Value::Null)
                        };
                    }
                    // Try outer rows (correlated subquery): search from innermost to outermost
                    for (outer_row, outer_col_map) in self.outer_rows.iter().rev() {
                        if let Some(&idx) = outer_col_map.get(buf.as_str()) {
                            return if idx < outer_row.len() {
                                Ok(outer_row[idx].clone())
                            } else {
                                Ok(Value::Null)
                            };
                        }
                    }
                }
                // Fast path: try direct lookup (col_map keys are already lowercase)
                if let Some(&idx) = col_map.get(column.as_str()) {
                    return if idx < row.len() {
                        Ok(row[idx].clone())
                    } else {
                        Ok(Value::Null)
                    };
                }
                // Slow path: try case-insensitive lookup
                let lower = column.to_ascii_lowercase();
                if lower != column.as_str() {
                    if let Some(&idx) = col_map.get(lower.as_str()) {
                        return if idx < row.len() {
                            Ok(row[idx].clone())
                        } else {
                            Ok(Value::Null)
                        };
                    }
                }
                // Final fallback: search outer rows for unqualified column name
                for (outer_row, outer_col_map) in self.outer_rows.iter().rev() {
                    if let Some(&idx) = outer_col_map.get(column.as_str()) {
                        return if idx < outer_row.len() {
                            Ok(outer_row[idx].clone())
                        } else {
                            Ok(Value::Null)
                        };
                    }
                    let lower_col = column.to_ascii_lowercase();
                    if let Some(&idx) = outer_col_map.get(lower_col.as_str()) {
                        return if idx < outer_row.len() {
                            Ok(outer_row[idx].clone())
                        } else {
                            Ok(Value::Null)
                        };
                    }
                }
                Err(KkdbError::ColumnNotFound(column.clone()))
            }

            Expr::BinaryOp { left, op, right } => {
                // Short-circuit AND/OR: avoid evaluating right side when unnecessary
                match op {
                    BinaryOperator::And => {
                        let l = self.eval_expr(left, row, col_map)?;
                        if !matches!(l, Value::Null) && !l.is_truthy() {
                            return Ok(Value::Integer(0));
                        }
                        let r = self.eval_expr(right, row, col_map)?;
                        if !matches!(r, Value::Null) && !r.is_truthy() {
                            return Ok(Value::Integer(0));
                        }
                        if matches!(l, Value::Null) || matches!(r, Value::Null) {
                            return Ok(Value::Null);
                        }
                        Ok(Value::Integer(1))
                    }
                    BinaryOperator::Or => {
                        let l = self.eval_expr(left, row, col_map)?;
                        if !matches!(l, Value::Null) && l.is_truthy() {
                            return Ok(Value::Integer(1));
                        }
                        let r = self.eval_expr(right, row, col_map)?;
                        if !matches!(r, Value::Null) && r.is_truthy() {
                            return Ok(Value::Integer(1));
                        }
                        if matches!(l, Value::Null) || matches!(r, Value::Null) {
                            return Ok(Value::Null);
                        }
                        Ok(Value::Integer(0))
                    }
                    BinaryOperator::FtsMatch => {
                        // `left` is the table name (not a column), so just evaluate the
                        // keyword from `right` and check if any TEXT column in the row
                        // contains all tokens.
                        let keyword_val = match self.eval_expr(right, row, col_map) {
                            Ok(v) => v,
                            Err(_) => return Ok(Value::Integer(0)),
                        };
                        if let Value::Text(keyword) = keyword_val {
                            let tokens = VM::tokenize(&keyword);
                            if tokens.is_empty() {
                                return Ok(Value::Integer(0));
                            }
                            // Concatenate all text-valued cells in the row
                            let haystack: String = row
                                .iter()
                                .filter_map(|v| {
                                    if let Value::Text(t) = v {
                                        Some(t.to_lowercase())
                                    } else {
                                        None
                                    }
                                })
                                .collect::<Vec<_>>()
                                .join(" ");
                            let matched = tokens.iter().all(|tok| haystack.contains(tok.as_str()));
                            return Ok(Value::Integer(if matched { 1 } else { 0 }));
                        }
                        Ok(Value::Integer(0))
                    }
                    _ => {
                        let l = self.eval_expr(left, row, col_map)?;
                        let r = self.eval_expr(right, row, col_map)?;
                        self.apply_binary_op(op, &l, &r)
                    }
                }
            }

            Expr::UnaryOp { op, expr } => {
                let val = self.eval_expr(expr, row, col_map)?;
                match op {
                    UnaryOperator::Minus => match val {
                        Value::Integer(v) => Ok(Value::Integer(v.wrapping_neg())),
                        Value::Real(v) => Ok(Value::Real(-v)),
                        Value::Null => Ok(Value::Null),
                        _ => Err(KkdbError::TypeError(
                            "cannot negate non-numeric value".into(),
                        )),
                    },
                    UnaryOperator::Not => {
                        if matches!(val, Value::Null) {
                            Ok(Value::Null)
                        } else {
                            Ok(Value::Integer(if val.is_truthy() { 0 } else { 1 }))
                        }
                    }
                }
            }

            Expr::IsNull { expr, negated } => {
                let val = self.eval_expr(expr, row, col_map)?;
                let is_null = matches!(val, Value::Null);
                Ok(Value::Integer(if is_null != *negated { 1 } else { 0 }))
            }

            Expr::InList {
                expr,
                list,
                negated,
            } => {
                let val = self.eval_expr(expr, row, col_map)?;
                // SQL NULL semantics: NULL IN (...) => NULL
                if matches!(val, Value::Null) {
                    return Ok(Value::Null);
                }
                let mut found = false;
                let mut has_null = false;
                for item in list {
                    let item_val = self.eval_expr(item, row, col_map)?;
                    if matches!(item_val, Value::Null) {
                        has_null = true;
                        continue;
                    }
                    if val == item_val {
                        found = true;
                        break;
                    }
                }
                if found {
                    Ok(Value::Integer(if !*negated { 1 } else { 0 }))
                } else if has_null {
                    // val NOT IN list but list contains NULL => NULL
                    Ok(Value::Null)
                } else {
                    Ok(Value::Integer(if *negated { 1 } else { 0 }))
                }
            }

            Expr::Like {
                expr,
                pattern,
                escape_char,
                case_insensitive,
                negated,
            } => {
                let val = self.eval_expr(expr, row, col_map)?;
                let pat = self.eval_expr(pattern, row, col_map)?;
                if matches!(val, Value::Null) || matches!(pat, Value::Null) {
                    return Ok(Value::Null);
                }
                match (&val, &pat) {
                    (Value::Text(s), Value::Text(p)) => {
                        let matches = like_match(s, p, *escape_char, *case_insensitive);
                        Ok(Value::Integer(if matches != *negated { 1 } else { 0 }))
                    }
                    _ => Ok(Value::Integer(0)),
                }
            }

            Expr::Between {
                expr,
                low,
                high,
                negated,
            } => {
                let val = self.eval_expr(expr, row, col_map)?;
                let lo = self.eval_expr(low, row, col_map)?;
                let hi = self.eval_expr(high, row, col_map)?;
                if matches!(val, Value::Null)
                    || matches!(lo, Value::Null)
                    || matches!(hi, Value::Null)
                {
                    return Ok(Value::Null);
                }
                let in_range = val
                    .partial_cmp(&lo)
                    .is_some_and(|o| o != std::cmp::Ordering::Less)
                    && val
                        .partial_cmp(&hi)
                        .is_some_and(|o| o != std::cmp::Ordering::Greater);
                Ok(Value::Integer(if in_range != *negated { 1 } else { 0 }))
            }

            Expr::Function {
                name,
                args,
                distinct: _,
            } => {
                // Use eq_ignore_ascii_case to avoid to_uppercase() String allocation
                let n = name.as_str();
                if n.eq_ignore_ascii_case("COUNT")
                    || n.eq_ignore_ascii_case("SUM")
                    || n.eq_ignore_ascii_case("AVG")
                    || n.eq_ignore_ascii_case("MIN")
                    || n.eq_ignore_ascii_case("MAX")
                {
                    if args.is_empty() {
                        Ok(Value::Integer(1))
                    } else {
                        self.eval_expr(&args[0], row, col_map)
                    }
                } else if n.eq_ignore_ascii_case("ABS") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    match val {
                        Value::Integer(v) => Ok(Value::Integer(v.wrapping_abs())),
                        Value::Real(v) => Ok(Value::Real(v.abs())),
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("UPPER") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    match val {
                        Value::Text(s) => Ok(Value::Text(s.to_uppercase().into())),
                        _ => Ok(val),
                    }
                } else if n.eq_ignore_ascii_case("LOWER") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    match val {
                        Value::Text(s) => Ok(Value::Text(s.to_lowercase().into())),
                        _ => Ok(val),
                    }
                } else if n.eq_ignore_ascii_case("LENGTH") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    match val {
                        // I9 fix: return Unicode char count, not byte count
                        Value::Text(s) => Ok(Value::Integer(s.chars().count() as i64)),
                        Value::Blob(b) => Ok(Value::Integer(b.len() as i64)),
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Integer(format!("{}", val).chars().count() as i64)),
                    }
                } else if n.eq_ignore_ascii_case("TYPEOF") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    let type_name = match val {
                        Value::Null => "null",
                        Value::Integer(_) => "integer",
                        Value::Real(_) => "real",
                        Value::Text(_) => "text",
                        Value::Blob(_) => "blob",
                    };
                    Ok(Value::Text(type_name.into()))
                } else if n.eq_ignore_ascii_case("COALESCE") {
                    for arg in args {
                        let val = self.eval_expr(arg, row, col_map)?;
                        if !matches!(val, Value::Null) {
                            return Ok(val);
                        }
                    }
                    Ok(Value::Null)
                } else if n.eq_ignore_ascii_case("IFNULL") {
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    if matches!(val, Value::Null) {
                        self.eval_expr(&args[1], row, col_map)
                    } else {
                        Ok(val)
                    }
                } else if n.eq_ignore_ascii_case("SUBSTR") || n.eq_ignore_ascii_case("SUBSTRING") {
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let s = match self.eval_expr(&args[0], row, col_map)? {
                        Value::Text(s) => s,
                        _ => return Ok(Value::Null),
                    };
                    let start = match self.eval_expr(&args[1], row, col_map)? {
                        Value::Integer(v) => (v - 1).max(0) as usize,
                        _ => return Ok(Value::Null),
                    };
                    let len = if args.len() > 2 {
                        match self.eval_expr(&args[2], row, col_map)? {
                            Value::Integer(v) => Some(v.max(0) as usize),
                            _ => None,
                        }
                    } else {
                        None
                    };
                    let chars: Vec<char> = s.chars().collect();
                    let end = match len {
                        Some(l) => (start + l).min(chars.len()),
                        None => chars.len(),
                    };
                    if start >= chars.len() {
                        Ok(Value::Text("".into()))
                    } else {
                        let s: String = chars[start..end].iter().collect();
                        Ok(Value::Text(s.into()))
                    }
                } else if n.eq_ignore_ascii_case("REPLACE") {
                    if args.len() < 3 {
                        return Ok(Value::Null);
                    }
                    let s = match self.eval_expr(&args[0], row, col_map)? {
                        Value::Text(s) => s,
                        _ => return Ok(Value::Null),
                    };
                    let from = match self.eval_expr(&args[1], row, col_map)? {
                        Value::Text(s) => s,
                        _ => return Ok(Value::Null),
                    };
                    let to = match self.eval_expr(&args[2], row, col_map)? {
                        Value::Text(s) => s,
                        _ => return Ok(Value::Null),
                    };
                    Ok(Value::Text(s.replace(&*from, &to).into()))
                } else if n.eq_ignore_ascii_case("TRIM") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    // Bug #4 fix: optional second arg = characters to trim
                    if args.len() > 1 {
                        match (val, self.eval_expr(&args[1], row, col_map)?) {
                            (Value::Text(s), Value::Text(chars)) => {
                                let chars_set: Vec<char> = chars.chars().collect();
                                Ok(Value::Text(s.trim_matches(chars_set.as_slice()).into()))
                            }
                            (v, _) => Ok(v),
                        }
                    } else {
                        match val {
                            Value::Text(s) => Ok(Value::Text(s.trim().into())),
                            v => Ok(v),
                        }
                    }
                } else if n.eq_ignore_ascii_case("LTRIM") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    if args.len() > 1 {
                        match (val, self.eval_expr(&args[1], row, col_map)?) {
                            (Value::Text(s), Value::Text(chars)) => {
                                let chars_set: Vec<char> = chars.chars().collect();
                                Ok(Value::Text(
                                    s.trim_start_matches(chars_set.as_slice()).into(),
                                ))
                            }
                            (v, _) => Ok(v),
                        }
                    } else {
                        match val {
                            Value::Text(s) => Ok(Value::Text(s.trim_start().into())),
                            v => Ok(v),
                        }
                    }
                } else if n.eq_ignore_ascii_case("RTRIM") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    if args.len() > 1 {
                        match (val, self.eval_expr(&args[1], row, col_map)?) {
                            (Value::Text(s), Value::Text(chars)) => {
                                let chars_set: Vec<char> = chars.chars().collect();
                                Ok(Value::Text(s.trim_end_matches(chars_set.as_slice()).into()))
                            }
                            (v, _) => Ok(v),
                        }
                    } else {
                        match val {
                            Value::Text(s) => Ok(Value::Text(s.trim_end().into())),
                            v => Ok(v),
                        }
                    }
                } else if n.eq_ignore_ascii_case("NULLIF") {
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let a = self.eval_expr(&args[0], row, col_map)?;
                    let b = self.eval_expr(&args[1], row, col_map)?;
                    if a == b {
                        Ok(Value::Null)
                    } else {
                        Ok(a)
                    }
                } else if n.eq_ignore_ascii_case("ROUND") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    let digits = if args.len() > 1 {
                        match self.eval_expr(&args[1], row, col_map)? {
                            Value::Integer(v) => v.max(0) as u32,
                            _ => 0,
                        }
                    } else {
                        0
                    };
                    match val {
                        Value::Integer(v) => Ok(Value::Integer(v)),
                        Value::Real(v) => {
                            let factor = 10f64.powi(digits as i32);
                            Ok(Value::Real((v * factor).round() / factor))
                        }
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("CEIL") || n.eq_ignore_ascii_case("CEILING") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    match self.eval_expr(&args[0], row, col_map)? {
                        Value::Integer(v) => Ok(Value::Integer(v)),
                        Value::Real(v) => Ok(Value::Real(v.ceil())),
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("FLOOR") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    match self.eval_expr(&args[0], row, col_map)? {
                        Value::Integer(v) => Ok(Value::Integer(v)),
                        Value::Real(v) => Ok(Value::Real(v.floor())),
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("INSTR") {
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let haystack = self.eval_expr(&args[0], row, col_map)?;
                    let needle = self.eval_expr(&args[1], row, col_map)?;
                    match (haystack, needle) {
                        (Value::Text(s), Value::Text(p)) => {
                            let pos = s
                                .find(p.as_ref())
                                .map(|b| s[..b].chars().count() as i64 + 1)
                                .unwrap_or(0);
                            Ok(Value::Integer(pos))
                        }
                        (Value::Null, _) | (_, Value::Null) => Ok(Value::Null),
                        _ => Ok(Value::Integer(0)),
                    }
                } else if n.eq_ignore_ascii_case("OVERLAY") {
                    // OVERLAY(s, placing, from[, for])
                    // Result = SUBSTR(s, 1, from-1) || placing || SUBSTR(s, from + length(for_or_placing))
                    if args.len() < 3 {
                        return Ok(Value::Null);
                    }
                    let s = match self.eval_expr(&args[0], row, col_map)? {
                        Value::Text(s) => s,
                        _ => return Ok(Value::Null),
                    };
                    let placing = match self.eval_expr(&args[1], row, col_map)? {
                        Value::Text(s) => s,
                        _ => return Ok(Value::Null),
                    };
                    let from = match self.eval_expr(&args[2], row, col_map)? {
                        Value::Integer(v) => (v - 1).max(0) as usize,
                        _ => return Ok(Value::Null),
                    };
                    let chars: Vec<char> = s.chars().collect();
                    let replace_len = if args.len() > 3 {
                        match self.eval_expr(&args[3], row, col_map)? {
                            Value::Integer(v) => v.max(0) as usize,
                            _ => placing.chars().count(),
                        }
                    } else {
                        placing.chars().count()
                    };
                    let before: String = chars[..from.min(chars.len())].iter().collect();
                    let after_start = (from + replace_len).min(chars.len());
                    let after: String = chars[after_start..].iter().collect();
                    Ok(Value::Text(format!("{before}{placing}{after}").into()))
                } else if n.eq_ignore_ascii_case("SIGN") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    match self.eval_expr(&args[0], row, col_map)? {
                        Value::Integer(v) => Ok(Value::Integer(v.signum())),
                        Value::Real(v) => Ok(Value::Real(v.signum())),
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                // ---- R1: NULL-safe equality operators ----
                } else if n.eq_ignore_ascii_case("__IS_DISTINCT_FROM__") {
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let a = self.eval_expr(&args[0], row, col_map)?;
                    let b = self.eval_expr(&args[1], row, col_map)?;
                    Ok(Value::Integer(match (&a, &b) {
                        (Value::Null, Value::Null) => 0, // NULL IS DISTINCT FROM NULL = FALSE
                        (Value::Null, _) | (_, Value::Null) => 1,
                        _ => {
                            if a == b {
                                0
                            } else {
                                1
                            }
                        }
                    }))
                } else if n.eq_ignore_ascii_case("__IS_NOT_DISTINCT_FROM__") {
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let a = self.eval_expr(&args[0], row, col_map)?;
                    let b = self.eval_expr(&args[1], row, col_map)?;
                    Ok(Value::Integer(match (&a, &b) {
                        (Value::Null, Value::Null) => 1, // NULL IS NOT DISTINCT FROM NULL = TRUE
                        (Value::Null, _) | (_, Value::Null) => 0,
                        _ => {
                            if a == b {
                                1
                            } else {
                                0
                            }
                        }
                    }))
                // ---- R3: Bitwise / math functions ----
                } else if n.eq_ignore_ascii_case("BITWISE_NOT") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    match self.eval_expr(&args[0], row, col_map)? {
                        Value::Integer(v) => Ok(Value::Integer(!v)),
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("CBRT") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    match self.eval_expr(&args[0], row, col_map)? {
                        Value::Integer(v) => Ok(Value::Real((v as f64).cbrt())),
                        Value::Real(v) => Ok(Value::Real(v.cbrt())),
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("FACTORIAL") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    match self.eval_expr(&args[0], row, col_map)? {
                        Value::Integer(v) if v < 0 => Err(KkdbError::RuntimeError(
                            "FACTORIAL requires a non-negative integer".into(),
                        )),
                        Value::Integer(v) if v > 20 => {
                            // S2 fix: 21! > i64::MAX — return error rather than silently truncating.
                            // Callers that need big factorials should cast to REAL first.
                            Err(KkdbError::RuntimeError(format!(
                                "FACTORIAL({v}) overflows i64; maximum supported value is 20"
                            )))
                        }
                        Value::Integer(v) => {
                            let result: i64 = (1..=v).product();
                            Ok(Value::Integer(result))
                        }
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("POWER") || n.eq_ignore_ascii_case("POW") {
                    // POWER(base, exp) — a ^ b
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let base = self.eval_expr(&args[0], row, col_map)?;
                    let exp = self.eval_expr(&args[1], row, col_map)?;
                    match (base, exp) {
                        (Value::Integer(a), Value::Integer(b)) if b >= 0 => {
                            // M8 fix: check for overflow, promote to Real if needed
                            let bu = b as u32;
                            match a.checked_pow(bu) {
                                Some(v) => Ok(Value::Integer(v)),
                                None => Ok(Value::Real((a as f64).powi(b as i32))),
                            }
                        }
                        (Value::Integer(a), Value::Integer(b)) => {
                            Ok(Value::Real((a as f64).powi(b as i32)))
                        }
                        (Value::Real(a), Value::Integer(b)) => Ok(Value::Real(a.powi(b as i32))),
                        (Value::Integer(a), Value::Real(b)) => Ok(Value::Real((a as f64).powf(b))),
                        (Value::Real(a), Value::Real(b)) => Ok(Value::Real(a.powf(b))),
                        (Value::Null, _) | (_, Value::Null) => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                } else if n == "__win" {
                    let idx = match args.first() {
                        Some(Expr::IntegerLiteral(i)) => *i as usize,
                        _ => 0,
                    };
                    Ok(self.window_results.as_ref().map_or(Value::Null, |res| {
                        res[self.current_window_row_idx][idx].clone()
                    }))
                } else if n.eq_ignore_ascii_case("JSON_EXTRACT")
                    || n.eq_ignore_ascii_case("JSON_EXTRACT_TEXT")
                {
                    // Simple JSON extraction: JSON_EXTRACT(json_str, '$.key') or JSON_EXTRACT(json_str, 'key')
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let json_val = self.eval_expr(&args[0], row, col_map)?;
                    let path_val = self.eval_expr(&args[1], row, col_map)?;
                    match (json_val, path_val) {
                        (Value::Text(s), Value::Text(p)) => {
                            if let Some(extracted) = json_extract_primitive(&s, &p) {
                                // Return properly typed value based on JSON content
                                Ok(json_scalar_to_value(&extracted))
                            } else {
                                Ok(Value::Null)
                            }
                        }
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("JSON_ARRAY") {
                    let mut elements = Vec::with_capacity(args.len());
                    for arg in args {
                        let val = self.eval_expr(arg, row, col_map)?;
                        let s = match val {
                            Value::Null => "null".to_string(),
                            Value::Integer(i) => i.to_string(),
                            Value::Real(f) => f.to_string(),
                            Value::Text(t) => {
                                let escaped = t.replace('\\', "\\\\").replace('"', "\\\"");
                                format!("\"{escaped}\"")
                            }
                            Value::Blob(_) => "\"<blob>\"".to_string(),
                        };
                        elements.push(s);
                    }
                    Ok(Value::Text(format!("[{}]", elements.join(", ")).into()))
                } else if n.eq_ignore_ascii_case("ARRAY_GET") {
                    // Placeholder: arrays not natively supported yet
                    Ok(Value::Null)
                } else if n.eq_ignore_ascii_case("JSON_MEMBER_OF") {
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    let arr = self.eval_expr(&args[1], row, col_map)?;
                    match (val, arr) {
                        (v, Value::Text(s)) => {
                            let v_str = match v {
                                Value::Text(t) => format!("\"{}\"", t),
                                Value::Integer(i) => i.to_string(),
                                Value::Real(f) => f.to_string(),
                                Value::Null => "null".to_string(),
                                Value::Blob(_) => return Ok(Value::Null),
                            };
                            if json_array_contains(&s, &v_str) {
                                Ok(Value::Integer(1))
                            } else {
                                Ok(Value::Integer(0))
                            }
                        }
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("JSON_OBJECT") {
                    let mut elements = Vec::with_capacity(args.len() / 2);
                    let mut i = 0;
                    while i + 1 < args.len() {
                        let k = self.eval_expr(&args[i], row, col_map)?;
                        let v = self.eval_expr(&args[i + 1], row, col_map)?;
                        let k_str = match k {
                            Value::Text(t) => t.replace('\\', "\\\\").replace('"', "\\\""),
                            // JSON keys must be strings
                            _ => k.to_string().replace('\\', "\\\\").replace('"', "\\\""),
                        };
                        let v_str = match v {
                            Value::Null => "null".to_string(),
                            Value::Integer(num) => num.to_string(),
                            Value::Real(f) => f.to_string(),
                            Value::Text(t) => {
                                let escaped = t.replace('\\', "\\\\").replace('"', "\\\"");
                                format!("\"{escaped}\"")
                            }
                            Value::Blob(_) => "\"<blob>\"".to_string(),
                        };
                        elements.push(format!("\"{k_str}\": {v_str}"));
                        i += 2;
                    }
                    Ok(Value::Text(format!("{{{}}}", elements.join(", ")).into()))
                } else if n.eq_ignore_ascii_case("JSON_TYPE") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let v = self.eval_expr(&args[0], row, col_map)?;
                    let type_str = match &v {
                        Value::Null => return Ok(Value::Null),
                        Value::Text(s) => {
                            let t = s.trim();
                            if t.starts_with('{') {
                                "OBJECT"
                            } else if t.starts_with('[') {
                                "ARRAY"
                            } else if t == "true" || t == "false" {
                                "BOOLEAN"
                            } else if t == "null" {
                                "NULL"
                            } else if t.parse::<i64>().is_ok() {
                                "INTEGER"
                            } else if t.parse::<f64>().is_ok() {
                                "DOUBLE"
                            } else {
                                "STRING"
                            }
                        }
                        Value::Integer(_) => "INTEGER",
                        Value::Real(_) => "DOUBLE",
                        Value::Blob(_) => "BLOB",
                    };
                    Ok(Value::Text(type_str.into()))
                } else if n.eq_ignore_ascii_case("JSON_VALID") {
                    if args.is_empty() {
                        return Ok(Value::Integer(0));
                    }
                    let v = self.eval_expr(&args[0], row, col_map)?;
                    let valid = match &v {
                        Value::Text(s) => json_is_valid(s.as_ref()),
                        _ => false,
                    };
                    Ok(Value::Integer(if valid { 1 } else { 0 }))
                } else if n.eq_ignore_ascii_case("JSON_LENGTH") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let v = self.eval_expr(&args[0], row, col_map)?;
                    let path = if args.len() >= 2 {
                        match self.eval_expr(&args[1], row, col_map)? {
                            Value::Text(p) => Some(p.to_string()),
                            _ => None,
                        }
                    } else {
                        None
                    };
                    let json_str = match &v {
                        Value::Text(s) => s.as_ref().to_string(),
                        _ => return Ok(Value::Null),
                    };
                    let target = if let Some(p) = path {
                        json_extract_primitive(&json_str, &p).unwrap_or_default()
                    } else {
                        json_str
                    };
                    Ok(Value::Integer(json_length(&target) as i64))
                } else if n.eq_ignore_ascii_case("JSON_KEYS") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let v = self.eval_expr(&args[0], row, col_map)?;
                    match &v {
                        Value::Text(s) => Ok(Value::Text(json_keys(s.as_ref()).into())),
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("JSON_CONTAINS") {
                    // JSON_CONTAINS(json, val, [path])
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let json_v = self.eval_expr(&args[0], row, col_map)?;
                    let needle_v = self.eval_expr(&args[1], row, col_map)?;
                    let path = if args.len() >= 3 {
                        match self.eval_expr(&args[2], row, col_map)? {
                            Value::Text(p) => Some(p.to_string()),
                            _ => None,
                        }
                    } else {
                        None
                    };
                    match (json_v, needle_v) {
                        (Value::Text(json), needle) => {
                            let doc = if let Some(p) = path {
                                json_extract_primitive(&json, &p).unwrap_or_default()
                            } else {
                                json.to_string()
                            };
                            let needle_str = match &needle {
                                Value::Text(t) => format!("\"{}\"", t),
                                Value::Integer(i) => i.to_string(),
                                Value::Real(f) => f.to_string(),
                                Value::Null => "null".to_string(),
                                _ => return Ok(Value::Integer(0)),
                            };
                            Ok(Value::Integer(
                                if json_array_contains(&doc, &needle_str)
                                    || json_contains_value(&doc, &needle_str)
                                {
                                    1
                                } else {
                                    0
                                },
                            ))
                        }
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("JSON_REMOVE") {
                    // JSON_REMOVE(json, path, ...)
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let v = self.eval_expr(&args[0], row, col_map)?;
                    let mut json_str = match v {
                        Value::Text(s) => s.to_string(),
                        _ => return Ok(Value::Null),
                    };
                    for arg in args.iter().skip(1) {
                        let path = match self.eval_expr(arg, row, col_map)? {
                            Value::Text(p) => p.to_string(),
                            _ => continue,
                        };
                        json_str = json_remove_path(&json_str, &path).unwrap_or(json_str);
                    }
                    Ok(Value::Text(json_str.into()))
                } else if n.eq_ignore_ascii_case("JSON_SET")
                    || n.eq_ignore_ascii_case("JSON_INSERT")
                    || n.eq_ignore_ascii_case("JSON_REPLACE")
                {
                    // JSON_SET(json, path, val, [path2, val2, ...])
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let v = self.eval_expr(&args[0], row, col_map)?;
                    let mut json_str = match v {
                        Value::Text(s) => s.to_string(),
                        _ => return Ok(Value::Null),
                    };
                    let mut i = 1;
                    while i + 1 < args.len() {
                        let path = match self.eval_expr(&args[i], row, col_map)? {
                            Value::Text(p) => p.to_string(),
                            _ => {
                                i += 2;
                                continue;
                            }
                        };
                        let val = self.eval_expr(&args[i + 1], row, col_map)?;
                        let val_str = match &val {
                            Value::Null => "null".to_string(),
                            Value::Integer(x) => x.to_string(),
                            Value::Real(x) => x.to_string(),
                            Value::Text(t) => format!("\"{}\"", t.replace('"', "\\\"")),
                            Value::Blob(_) => "null".to_string(),
                        };
                        json_str = json_set_path(&json_str, &path, &val_str).unwrap_or(json_str);
                        i += 2;
                    }
                    Ok(Value::Text(json_str.into()))
                } else if n.eq_ignore_ascii_case("JSON_QUOTE") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let v = self.eval_expr(&args[0], row, col_map)?;
                    let s = match v {
                        Value::Text(t) => {
                            format!("\"{}\"", t.replace('\\', "\\\\").replace('"', "\\\""))
                        }
                        Value::Integer(i) => i.to_string(),
                        Value::Real(f) => f.to_string(),
                        Value::Null => "null".to_string(),
                        _ => return Ok(Value::Null),
                    };
                    Ok(Value::Text(s.into()))
                } else if n.eq_ignore_ascii_case("JSON_UNQUOTE") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let v = self.eval_expr(&args[0], row, col_map)?;
                    match v {
                        Value::Text(s) => {
                            let t = s.trim();
                            if t.starts_with('"') && t.ends_with('"') && t.len() >= 2 {
                                let inner = t[1..t.len() - 1]
                                    .replace("\\\"", "\"")
                                    .replace("\\\\", "\\");
                                Ok(Value::Text(inner.into()))
                            } else {
                                Ok(Value::Text(s.clone()))
                            }
                        }
                        other => Ok(other),
                    }
                } else if n.eq_ignore_ascii_case("REGEXP_LIKE") {
                    // I10: implement basic regex via Rust's std (no external crate needed for simple patterns)
                    if args.len() < 2 {
                        return Ok(Value::Integer(0));
                    }
                    let subject = self.eval_expr(&args[0], row, col_map)?;
                    let pattern = self.eval_expr(&args[1], row, col_map)?;
                    let (Value::Text(s), Value::Text(p)) = (subject, pattern) else {
                        return Ok(Value::Integer(0));
                    };
                    // Translate simple SQL LIKE-style wildcards to a basic pattern check.
                    // Full POSIX ERE support would require the `regex` crate; for now we
                    // support: `.` (any char), `.*` (any sequence), `^`/`$` anchors, and
                    // character literals by walking the pattern character-by-character.
                    fn regex_matches(text: &str, pat: &str) -> bool {
                        // Very lightweight: convert pattern to a vec of segments and try to match
                        let pat = pat.trim_start_matches('^');
                        let (anchored_end, pat) = if let Some(stripped) = pat.strip_suffix('$') {
                            (true, stripped)
                        } else {
                            (false, pat)
                        };
                        // Split on '.*' to get required literal fragments
                        let parts: Vec<&str> = pat.split(".*").collect();
                        let mut remaining = text;
                        for (i, part) in parts.iter().enumerate() {
                            let sub = part.replace('.', "\x00"); // placeholder for any-char
                                                                 // replace \x00 with actual any-char matching — simple char-by-char
                            let _ = sub; // just do a contains check for now
                            if i == 0 {
                                // First part: must match at start
                                if part.is_empty() {
                                    continue;
                                }
                                if !remaining.to_lowercase().starts_with(&part.to_lowercase()) {
                                    return false;
                                }
                                remaining = &remaining[part.len().min(remaining.len())..];
                            } else if i == parts.len() - 1 && anchored_end {
                                if !remaining.to_lowercase().ends_with(&part.to_lowercase()) {
                                    return false;
                                }
                            } else {
                                if part.is_empty() {
                                    continue;
                                }
                                if let Some(pos) =
                                    remaining.to_lowercase().find(&part.to_lowercase())
                                {
                                    remaining = &remaining[pos + part.len()..];
                                } else {
                                    return false;
                                }
                            }
                        }
                        true
                    }
                    Ok(Value::Integer(if regex_matches(&s, &p) { 1 } else { 0 }))
                } else if n.eq_ignore_ascii_case("MATCH_AGAINST") {
                    // FTS MATCH_AGAINST: stub returning 0 (FTS is handled at the AST level)
                    Ok(Value::Integer(0))
                } else if n.eq_ignore_ascii_case("STARTS_WITH") {
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let s = self.eval_expr(&args[0], row, col_map)?;
                    let prefix = self.eval_expr(&args[1], row, col_map)?;
                    match (s, prefix) {
                        (Value::Text(s), Value::Text(p)) => {
                            Ok(Value::Integer(if s.starts_with(p.as_ref()) {
                                1
                            } else {
                                0
                            }))
                        }
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("HEX") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    match self.eval_expr(&args[0], row, col_map)? {
                        Value::Blob(b) => {
                            let hex: String = b.iter().map(|b| format!("{b:02X}")).collect();
                            Ok(Value::Text(hex.into()))
                        }
                        Value::Integer(v) => Ok(Value::Text(format!("{v:X}").into())),
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("UNICODE") {
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    match self.eval_expr(&args[0], row, col_map)? {
                        Value::Text(s) => match s.chars().next() {
                            Some(c) => Ok(Value::Integer(c as i64)),
                            None => Ok(Value::Null),
                        },
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("CHAR") {
                    let mut result = String::with_capacity(args.len());
                    for arg in args {
                        if let Value::Integer(v) = self.eval_expr(arg, row, col_map)? {
                            if let Some(c) = char::from_u32(v as u32) {
                                result.push(c);
                            }
                        }
                    }
                    Ok(Value::Text(result.into()))
                } else if n.eq_ignore_ascii_case("DATE_EXTRACT") {
                    // EXTRACT(field FROM expr) — args: [field_str, value_expr]
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let field = match self.eval_expr(&args[0], row, col_map)? {
                        Value::Text(s) => s.to_ascii_uppercase(),
                        _ => return Ok(Value::Null),
                    };
                    let val = self.eval_expr(&args[1], row, col_map)?;
                    // Parse value: accept Text (ISO date/datetime), Integer (unix epoch), Real
                    let text_val = match &val {
                        Value::Text(s) => s.clone(),
                        Value::Integer(v) => {
                            // Treat as unix timestamp seconds — derive as YYYY-MM-DD HH:MM:SS
                            let ts = *v;
                            let secs_per_day: i64 = 86400;
                            let epoch_days: i64 = ts / secs_per_day;
                            let day_secs: i64 = ts.rem_euclid(secs_per_day);
                            // Days since unix epoch → Gregorian date (simple algorithm)
                            let n_days = epoch_days + 719468;
                            let era = if n_days >= 0 { n_days } else { n_days - 146096 } / 146097;
                            let doe = n_days - era * 146097;
                            let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
                            let y = yoe + era * 400;
                            let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
                            let mp = (5 * doy + 2) / 153;
                            let d = doy - (153 * mp + 2) / 5 + 1;
                            let m = if mp < 10 { mp + 3 } else { mp - 9 };
                            let y = if m <= 2 { y + 1 } else { y };
                            let h = day_secs / 3600;
                            let min = (day_secs % 3600) / 60;
                            let s = day_secs % 60;
                            format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", y, m, d, h, min, s)
                                .into()
                        }
                        _ => return Ok(Value::Null),
                    };
                    let t: &str = &text_val;
                    let result: Option<i64> = match field.as_str() {
                        "YEAR" => t.get(0..4).and_then(|s| s.parse().ok()),
                        "MONTH" => t.get(5..7).and_then(|s| s.parse().ok()),
                        "DAY" => t.get(8..10).and_then(|s| s.parse().ok()),
                        "HOUR" => t.get(11..13).and_then(|s| s.parse().ok()),
                        "MINUTE" => t.get(14..16).and_then(|s| s.parse().ok()),
                        "SECOND" => t.get(17..19).and_then(|s| s.parse().ok()),
                        _ => None,
                    };
                    Ok(result.map(Value::Integer).unwrap_or(Value::Null))
                } else if n.eq_ignore_ascii_case("RANDOM") || n.eq_ignore_ascii_case("RAND") {
                    // RANDOM() / RAND() — Bug #6 fix: use atomic counter xorshifted with
                    // system time nanos to avoid collision on same-millisecond calls
                    use std::sync::atomic::{AtomicU64, Ordering as AO};
                    use std::time::{SystemTime, UNIX_EPOCH};
                    static SEQ: AtomicU64 = AtomicU64::new(1);
                    let n = SystemTime::now()
                        .duration_since(UNIX_EPOCH)
                        .map(|d| d.subsec_nanos() as u64)
                        .unwrap_or(0);
                    let seq = SEQ.fetch_add(1, AO::Relaxed);
                    let mut x = n.wrapping_add(seq).wrapping_add(0x9e3779b97f4a7c15);
                    // XorShift64 one round
                    x ^= x << 13;
                    x ^= x >> 7;
                    x ^= x << 17;
                    Ok(Value::Integer(x as i64))
                // ---- RLS/Auth session variable functions (Supabase-style) ----
                } else if n.eq_ignore_ascii_case("auth.uid") || n.eq_ignore_ascii_case("auth_uid") {
                    // auth.uid() → reads request.jwt.sub from session_vars (set by HTTP API on login)
                    let uid = self
                        .session_vars
                        .get("request.jwt.sub")
                        .cloned()
                        .unwrap_or_default();
                    if uid.is_empty() {
                        Ok(Value::Null)
                    } else {
                        Ok(Value::Text(uid.into()))
                    }
                } else if n.eq_ignore_ascii_case("current_setting") {
                    // current_setting('key') → reads from session_vars
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let key_val = self.eval_expr(&args[0], row, col_map)?;
                    let key = match &key_val {
                        Value::Text(s) => s.to_string(),
                        _ => return Ok(Value::Null),
                    };
                    match self.session_vars.get(&key) {
                        Some(v) => Ok(Value::Text(v.clone().into())),
                        None => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("current_user") {
                    // current_user() → MySQL-compat alias for session current user
                    let user = self
                        .session_vars
                        .get("request.jwt.sub")
                        .or_else(|| self.session_vars.get("kkdb.current_user"))
                        .cloned()
                        .unwrap_or_default();
                    if user.is_empty() {
                        Ok(Value::Null)
                    } else {
                        Ok(Value::Text(user.into()))
                    }
                // ── Vector Search functions ────────────────────────────────────────────────
                } else if n.eq_ignore_ascii_case("VEC") {
                    // VEC(json_array_string) → BLOB (encoded f32 array)
                    // Accepts: VEC('[0.1, 0.2, ...]')  or  VEC(text_column)
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    let s = match &val {
                        Value::Text(s) => s.to_string(),
                        Value::Blob(b) => return Ok(Value::Blob(b.clone())), // already encoded
                        _ => return Ok(Value::Null),
                    };
                    match crate::vector::parse_vec_json(&s) {
                        Some(f32s) => {
                            let blob = crate::vector::index::encode_vector(&f32s);
                            Ok(Value::Blob(blob))
                        }
                        None => Err(KkdbError::RuntimeError(format!(
                            "VEC(): cannot parse '{}' as a float array",
                            s
                        ))),
                    }
                } else if n.eq_ignore_ascii_case("VEC_SEARCH") {
                    // VEC_SEARCH(table_name, index_name, query_vec_blob) → REAL similarity score
                    //
                    // Returns the similarity for the *current row* (identified by its rowid).
                    // This function does a full HNSW search over the index for the query vector,
                    // then looks up the score for this row's rowid from the result list.
                    if args.len() < 3 {
                        return Ok(Value::Real(0.0));
                    }
                    let _table_arg = self.eval_expr(&args[0], row, col_map)?;
                    let index_arg = self.eval_expr(&args[1], row, col_map)?;
                    let query_arg = self.eval_expr(&args[2], row, col_map)?;

                    let index_name = match &index_arg {
                        Value::Text(s) => s.to_string(),
                        _ => return Ok(Value::Real(0.0)),
                    };
                    let query_blob = match &query_arg {
                        Value::Blob(b) => b.clone(),
                        Value::Text(s) => {
                            // Accept text JSON as fallback
                            match crate::vector::parse_vec_json(s) {
                                Some(v) => crate::vector::index::encode_vector(&v),
                                None => return Ok(Value::Real(0.0)),
                            }
                        }
                        _ => return Ok(Value::Real(0.0)),
                    };
                    let query_vec = match crate::vector::index::decode_vector(&query_blob) {
                        Some(v) => v,
                        None => return Ok(Value::Real(0.0)),
                    };

                    // Look up the vector index.
                    let vi = match self.schema.vector_indexes.get(&index_name) {
                        Some(vi) => vi.clone(),
                        None => {
                            return Err(KkdbError::RuntimeError(format!(
                                "VEC_SEARCH(): vector index '{}' not found",
                                index_name
                            )))
                        }
                    };

                    // We need the rowid of the current row.
                    // Rowids are set on self.current_rowid by exec_select before each eval_expr
                    // call so we don't need to inject _rowid_ into the actual row data.
                    let cur_rowid = self.current_rowid as u64;

                    // Perform HNSW search (returns top-N by default).
                    let top_k = if args.len() >= 4 {
                        self.eval_expr(&args[3], row, col_map)?
                            .to_i64()
                            .unwrap_or(100) as usize
                    } else {
                        100
                    };
                    // Respect SET kkdb.vec_ef_search = N session variable.
                    let results = if let Some(ef_str) = self.session_vars.get("kkdb.vec_ef_search")
                    {
                        let ef: usize = ef_str.parse().unwrap_or(0);
                        if ef > 0 {
                            vi.search_with_ef(&query_vec, top_k, ef)
                        } else {
                            vi.search(&query_vec, top_k)
                        }
                    } else {
                        vi.search(&query_vec, top_k)
                    };

                    // Find this row's score in the result list.
                    let score = results
                        .iter()
                        .find(|(rowid, _)| *rowid == cur_rowid)
                        .map(|(_, s)| *s as f64)
                        .unwrap_or(0.0);

                    Ok(Value::Real(score))
                } else if n.eq_ignore_ascii_case("VEC_DIM") {
                    // VEC_DIM(blob) → INTEGER dimension count
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    match val {
                        Value::Blob(b) => {
                            let dim = crate::vector::index::decode_vector(&b)
                                .map(|v| v.len() as i64)
                                .unwrap_or(0);
                            Ok(Value::Integer(dim))
                        }
                        _ => Ok(Value::Null),
                    }
                } else if n.eq_ignore_ascii_case("VEC_DISTANCE") {
                    // VEC_DISTANCE(blob1, blob2, 'cosine'|'l2') → REAL distance
                    if args.len() < 2 {
                        return Ok(Value::Null);
                    }
                    let a_val = self.eval_expr(&args[0], row, col_map)?;
                    let b_val = self.eval_expr(&args[1], row, col_map)?;
                    let metric_str = if args.len() >= 3 {
                        match self.eval_expr(&args[2], row, col_map)? {
                            Value::Text(s) => s.to_string(),
                            _ => "cosine".to_string(),
                        }
                    } else {
                        "cosine".to_string()
                    };
                    let metric = crate::vector::distance::DistanceMetric::from_str(&metric_str)
                        .unwrap_or(crate::vector::distance::DistanceMetric::Cosine);
                    let decode = |v: Value| -> Option<Vec<f32>> {
                        match v {
                            Value::Blob(b) => crate::vector::index::decode_vector(&b),
                            Value::Text(s) => crate::vector::parse_vec_json(&s),
                            _ => None,
                        }
                    };
                    let a = match decode(a_val) {
                        Some(v) => v,
                        None => return Ok(Value::Null),
                    };
                    let b = match decode(b_val) {
                        Some(v) => v,
                        None => return Ok(Value::Null),
                    };
                    Ok(Value::Real(metric.distance(&a, &b) as f64))
                } else if n.eq_ignore_ascii_case("VEC_NORMALIZE") {
                    // VEC_NORMALIZE(blob) → blob (L2-normalised)
                    if args.is_empty() {
                        return Ok(Value::Null);
                    }
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    let blob = match val {
                        Value::Blob(b) => b,
                        Value::Text(s) => match crate::vector::parse_vec_json(&s) {
                            Some(v) => crate::vector::index::encode_vector(&v),
                            None => return Ok(Value::Null),
                        },
                        _ => return Ok(Value::Null),
                    };
                    let mut v = match crate::vector::index::decode_vector(&blob) {
                        Some(v) => v,
                        None => return Ok(Value::Null),
                    };
                    crate::vector::distance::normalize_l2(&mut v);
                    Ok(Value::Blob(crate::vector::index::encode_vector(&v)))
                } else {
                    Err(KkdbError::RuntimeError(format!(
                        "unknown function: {}",
                        name
                    )))
                }
            }

            Expr::Nested(inner) => self.eval_expr(inner, row, col_map),

            Expr::Subquery(query) => {
                // Scalar subquery: returns first column of first row, or NULL if empty
                // Push outer row context for correlated references inside the subquery
                self.outer_rows.push((row.to_vec(), col_map.clone()));
                let result = self.exec_select(query);
                self.outer_rows.pop();
                match result? {
                    ExecResult::QueryResult { rows, .. } => {
                        if let Some(first_row) = rows.first() {
                            Ok(first_row.first().cloned().unwrap_or(Value::Null))
                        } else {
                            Ok(Value::Null)
                        }
                    }
                    _ => Err(KkdbError::Internal("subquery did not return rows".into())),
                }
            }

            Expr::InSubquery {
                expr: inner,
                subquery,
                negated,
            } => {
                let val = self.eval_expr(inner, row, col_map)?;
                if matches!(val, Value::Null) {
                    return Ok(Value::Null);
                }
                // Push outer row for correlated references in the subquery
                self.outer_rows.push((row.to_vec(), col_map.clone()));
                let result = self.exec_select(subquery);
                self.outer_rows.pop();
                match result? {
                    ExecResult::QueryResult { rows, .. } => {
                        let mut found = false;
                        let mut has_null = false;
                        for sub_row in &rows {
                            if let Some(sub_val) = sub_row.first() {
                                if matches!(sub_val, Value::Null) {
                                    has_null = true;
                                    continue;
                                }
                                if val == *sub_val {
                                    found = true;
                                    break;
                                }
                            }
                        }
                        if found {
                            Ok(Value::Integer(if !*negated { 1 } else { 0 }))
                        } else if has_null {
                            Ok(Value::Null)
                        } else {
                            Ok(Value::Integer(if *negated { 1 } else { 0 }))
                        }
                    }
                    _ => Err(KkdbError::Internal("subquery did not return rows".into())),
                }
            }

            Expr::AnyOp {
                expr: inner,
                op,
                subquery,
            } => {
                let val = self.eval_expr(inner, row, col_map)?;
                if matches!(val, Value::Null) {
                    return Ok(Value::Null);
                }
                self.outer_rows.push((row.to_vec(), col_map.clone()));
                let result = self.exec_select(subquery);
                self.outer_rows.pop();
                match result? {
                    ExecResult::QueryResult { rows, .. } => {
                        let mut found = false;
                        let mut has_null = false;
                        for sub_row in &rows {
                            if let Some(sub_val) = sub_row.first() {
                                if matches!(sub_val, Value::Null) {
                                    has_null = true;
                                    continue;
                                }
                                let cmp = self.apply_binary_op(op, &val, sub_val)?;
                                if cmp.is_truthy() {
                                    found = true;
                                    break;
                                }
                            }
                        }
                        if found {
                            Ok(Value::Integer(1))
                        } else if has_null {
                            Ok(Value::Null)
                        } else {
                            Ok(Value::Integer(0))
                        }
                    }
                    _ => Err(KkdbError::Internal(
                        "subquery in ANY did not return rows".into(),
                    )),
                }
            }

            Expr::AllOp {
                expr: inner,
                op,
                subquery,
            } => {
                let val = self.eval_expr(inner, row, col_map)?;
                if matches!(val, Value::Null) {
                    return Ok(Value::Null);
                }
                self.outer_rows.push((row.to_vec(), col_map.clone()));
                let result = self.exec_select(subquery);
                self.outer_rows.pop();
                match result? {
                    ExecResult::QueryResult { rows, .. } => {
                        let mut all_match = true;
                        let mut has_null = false;
                        for sub_row in &rows {
                            if let Some(sub_val) = sub_row.first() {
                                if matches!(sub_val, Value::Null) {
                                    has_null = true;
                                    continue;
                                }
                                let cmp = self.apply_binary_op(op, &val, sub_val)?;
                                if !cmp.is_truthy() {
                                    all_match = false;
                                    break;
                                }
                            }
                        }
                        if !all_match {
                            Ok(Value::Integer(0))
                        } else if has_null {
                            Ok(Value::Null)
                        } else {
                            Ok(Value::Integer(1)) // Vacuously true for empty sets as per SQL standard
                        }
                    }
                    _ => Err(KkdbError::Internal(
                        "subquery in ALL did not return rows".into(),
                    )),
                }
            }

            Expr::Exists(subquery) => {
                // Push outer row for correlated references (e.g. WHERE t.col = outer.col)
                self.outer_rows.push((row.to_vec(), col_map.clone()));
                let result = self.exec_select(subquery);
                self.outer_rows.pop();
                match result? {
                    ExecResult::QueryResult { rows, .. } => {
                        Ok(Value::Integer(if rows.is_empty() { 0 } else { 1 }))
                    }
                    _ => Err(KkdbError::Internal("subquery did not return rows".into())),
                }
            }

            Expr::Case {
                operand,
                when_clauses,
                else_clause,
            } => {
                if let Some(ref op_expr) = operand {
                    // Simple CASE: CASE <operand> WHEN val THEN result ...
                    let op_val = self.eval_expr(op_expr, row, col_map)?;
                    for (when_val_expr, then_expr) in when_clauses {
                        let when_val = self.eval_expr(when_val_expr, row, col_map)?;
                        // NULL never equals anything
                        if !matches!(op_val, Value::Null)
                            && !matches!(when_val, Value::Null)
                            && op_val == when_val
                        {
                            return self.eval_expr(then_expr, row, col_map);
                        }
                    }
                } else {
                    // Searched CASE: CASE WHEN cond THEN result ...
                    for (cond_expr, then_expr) in when_clauses {
                        let cond_val = self.eval_expr(cond_expr, row, col_map)?;
                        if cond_val.is_truthy() {
                            return self.eval_expr(then_expr, row, col_map);
                        }
                    }
                }
                // No WHEN matched — evaluate ELSE or return NULL
                if let Some(ref else_expr) = else_clause {
                    self.eval_expr(else_expr, row, col_map)
                } else {
                    Ok(Value::Null)
                }
            }

            Expr::Cast {
                expr,
                to_type,
                try_cast,
            } => {
                use crate::sql::ast::CastTargetType;
                let val = self.eval_expr(expr, row, col_map)?;
                match to_type {
                    CastTargetType::Integer => match val {
                        Value::Integer(v) => Ok(Value::Integer(v)),
                        Value::Real(v) => Ok(Value::Integer(v as i64)),
                        Value::Text(s) => {
                            if let Ok(i) = s.trim().parse::<i64>() {
                                Ok(Value::Integer(i))
                            } else if let Ok(f) = s.trim().parse::<f64>() {
                                Ok(Value::Integer(f as i64))
                            } else if *try_cast {
                                Ok(Value::Null)
                            } else {
                                // M11 fix: non-numeric CAST should error, not silently return 0
                                Err(crate::error::KkdbError::RuntimeError(format!(
                                    "cannot cast '{}' to INTEGER",
                                    s
                                )))
                            }
                        }
                        Value::Blob(_) => {
                            if *try_cast {
                                Ok(Value::Null)
                            } else {
                                Err(crate::error::KkdbError::RuntimeError(
                                    "cannot cast BLOB to INTEGER".into(),
                                ))
                            }
                        }
                        Value::Null => Ok(Value::Null),
                    },
                    CastTargetType::Real => match val {
                        Value::Real(v) => Ok(Value::Real(v)),
                        Value::Integer(v) => Ok(Value::Real(v as f64)),
                        Value::Text(s) => {
                            if let Ok(f) = s.trim().parse::<f64>() {
                                Ok(Value::Real(f))
                            } else if *try_cast {
                                Ok(Value::Null)
                            } else {
                                // M11 fix: non-numeric CAST should error
                                Err(crate::error::KkdbError::RuntimeError(format!(
                                    "cannot cast '{}' to REAL",
                                    s
                                )))
                            }
                        }
                        Value::Blob(_) => {
                            if *try_cast {
                                Ok(Value::Null)
                            } else {
                                Err(crate::error::KkdbError::RuntimeError(
                                    "cannot cast BLOB to REAL".into(),
                                ))
                            }
                        }
                        Value::Null => Ok(Value::Null),
                    },
                    CastTargetType::Numeric => match val {
                        Value::Integer(v) => Ok(Value::Integer(v)),
                        Value::Real(v) => {
                            if v.fract() == 0.0 && v.abs() < 9.2e18 {
                                Ok(Value::Integer(v as i64))
                            } else {
                                Ok(Value::Real(v))
                            }
                        }
                        Value::Text(s) => {
                            let t = s.trim();
                            if let Ok(i) = t.parse::<i64>() {
                                Ok(Value::Integer(i))
                            } else if let Ok(f) = t.parse::<f64>() {
                                Ok(Value::Real(f))
                            } else if *try_cast {
                                Ok(Value::Null)
                            } else {
                                // D-NEW-3 fix: report error instead of silently returning 0
                                Err(crate::error::KkdbError::RuntimeError(format!(
                                    "cannot cast '{}' to NUMERIC",
                                    s
                                )))
                            }
                        }
                        Value::Blob(_) => {
                            if *try_cast {
                                Ok(Value::Null)
                            } else {
                                Err(crate::error::KkdbError::RuntimeError(
                                    "cannot cast BLOB to NUMERIC".into(),
                                ))
                            }
                        }
                        Value::Null => Ok(Value::Null),
                    },
                    CastTargetType::Text => match val {
                        Value::Text(s) => Ok(Value::Text(s)),
                        Value::Integer(v) => Ok(Value::Text(v.to_string().into())),
                        Value::Real(v) => Ok(Value::Text(format!("{v}").into())),
                        Value::Blob(b) => match String::from_utf8(b.clone()) {
                            Ok(s) => Ok(Value::Text(s.into())),
                            Err(_) => {
                                let hex: String = b.iter().map(|x| format!("{x:02X}")).collect();
                                Ok(Value::Text(hex.into()))
                            }
                        },
                        Value::Null => Ok(Value::Null),
                    },
                    CastTargetType::Blob => match val {
                        Value::Blob(b) => Ok(Value::Blob(b)),
                        Value::Text(s) => Ok(Value::Blob(s.as_bytes().to_vec())),
                        Value::Integer(v) => Ok(Value::Blob(v.to_string().into_bytes())),
                        Value::Real(v) => Ok(Value::Blob(format!("{v}").into_bytes())),
                        Value::Null => Ok(Value::Null),
                    },
                    // Temporal types — store as Text (ISO 8601 string), validate format
                    CastTargetType::Date | CastTargetType::Time | CastTargetType::Timestamp => {
                        match val {
                            Value::Text(s) => Ok(Value::Text(s)),
                            Value::Integer(v) => Ok(Value::Text(v.to_string().into())),
                            Value::Real(v) => Ok(Value::Text(format!("{v}").into())),
                            Value::Null => Ok(Value::Null),
                            _ => Ok(Value::Null),
                        }
                    }
                    // JSON — store as Text
                    CastTargetType::Json => match val {
                        Value::Text(s) => Ok(Value::Text(s)),
                        Value::Integer(v) => Ok(Value::Text(v.to_string().into())),
                        Value::Real(v) => Ok(Value::Text(format!("{v}").into())),
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    },
                }
            }

            Expr::Collate { expr, collation: _ } => {
                // Ignore collation sorting rules during scalar evaluation for now
                self.eval_expr(expr, row, col_map)
            }

            Expr::Interval {
                value,
                leading_field,
            } => {
                let val = self.eval_expr(value, row, col_map)?;
                if let Some(field) = leading_field {
                    match val {
                        Value::Text(s) => Ok(Value::Text(format!("{} {}", s.trim(), field).into())),
                        Value::Integer(v) => Ok(Value::Text(format!("{} {}", v, field).into())),
                        Value::Real(v) => Ok(Value::Text(format!("{} {}", v, field).into())),
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                } else {
                    Ok(val)
                }
            }

            // Batch F: Window functions — evaluated in exec_select, not individual row eval
            Expr::WindowFunction { .. } => Err(KkdbError::RuntimeError(
                "window function cannot be evaluated in scalar context".into(),
            )),

            // BM25 Full-Text Search: MATCH (col1, col2) AGAINST ('query')
            // Phase 4 stub: performs a simple substring token match across the specified columns.
            // Phase 4 (inverted index) will replace this with a proper BM25 scored lookup.
            Expr::MatchAgainst { columns, query } => {
                if query.trim().is_empty() {
                    return Ok(Value::Real(0.0));
                }
                // Tokenize the query using Unicode-aware split
                let tokens: Vec<String> = query
                    .split(|c: char| !c.is_alphanumeric())
                    .map(|s| s.trim().to_lowercase())
                    .filter(|s| !s.is_empty())
                    .collect();
                if tokens.is_empty() {
                    return Ok(Value::Real(0.0));
                }

                // Build a search haystack from the matched columns (or all TEXT columns if none matched by name).
                let mut haystack = String::new();
                if columns.is_empty() {
                    // Fall back to all TEXT values in the row
                    for val in row {
                        if let Value::Text(t) = val {
                            haystack.push(' ');
                            haystack.push_str(t);
                        }
                    }
                } else {
                    for col_name in columns {
                        let col_lower = col_name.to_ascii_lowercase();
                        if let Some(&idx) = col_map.get(col_lower.as_str()) {
                            if let Some(Value::Text(t)) = row.get(idx) {
                                haystack.push(' ');
                                haystack.push_str(t);
                            }
                        }
                    }
                }
                let haystack = haystack.to_lowercase();

                // Score = fraction of query tokens found in the haystack
                let matched = tokens
                    .iter()
                    .filter(|tok| haystack.contains(tok.as_str()))
                    .count();
                if matched == 0 {
                    Ok(Value::Real(0.0))
                } else {
                    // Simple TF-style score: matched_fraction (BM25 will replace this in Phase 4)
                    Ok(Value::Real(matched as f64 / tokens.len() as f64))
                }
            }
        }
    }

    #[inline]
    pub(crate) fn apply_binary_op(
        &self,
        op: &BinaryOperator,
        left: &Value,
        right: &Value,
    ) -> Result<Value> {
        // NULL propagation for most operators
        if matches!(left, Value::Null) || matches!(right, Value::Null) {
            match op {
                BinaryOperator::And => {
                    // NULL AND false = false (any falsy non-NULL)
                    if !matches!(left, Value::Null) && !left.is_truthy() {
                        return Ok(Value::Integer(0));
                    }
                    if !matches!(right, Value::Null) && !right.is_truthy() {
                        return Ok(Value::Integer(0));
                    }
                    return Ok(Value::Null);
                }
                BinaryOperator::Or => {
                    // NULL OR true = true
                    if left.is_truthy() || right.is_truthy() {
                        return Ok(Value::Integer(1));
                    }
                    return Ok(Value::Null);
                }
                _ => return Ok(Value::Null),
            }
        }

        match op {
            BinaryOperator::FtsMatch => match (left, right) {
                (Value::Text(t), Value::Text(pattern)) => {
                    let tokens = VM::tokenize(pattern);
                    if tokens.is_empty() {
                        return Ok(Value::Integer(0));
                    }
                    let t_lower = t.to_ascii_lowercase();
                    let mut matched = true;
                    // L4 minimal implementation: text must contain all tokens
                    for token in tokens {
                        if !t_lower.contains(&token) {
                            matched = false;
                            break;
                        }
                    }
                    Ok(Value::Integer(if matched { 1 } else { 0 }))
                }
                _ => Ok(Value::Integer(0)),
            },
            BinaryOperator::Add => match (left, right) {
                (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a.wrapping_add(*b))),
                (Value::Real(a), Value::Real(b)) => Ok(Value::Real(a + b)),
                (Value::Integer(a), Value::Real(b)) => Ok(Value::Real(*a as f64 + b)),
                (Value::Real(a), Value::Integer(b)) => Ok(Value::Real(a + *b as f64)),
                // D-NEW-2 fix: return Null for incompatible types, not Integer(0)
                _ => Ok(Value::Null),
            },
            BinaryOperator::Subtract => match (left, right) {
                (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a.wrapping_sub(*b))),
                (Value::Real(a), Value::Real(b)) => Ok(Value::Real(a - b)),
                (Value::Integer(a), Value::Real(b)) => Ok(Value::Real(*a as f64 - b)),
                (Value::Real(a), Value::Integer(b)) => Ok(Value::Real(a - *b as f64)),
                _ => Ok(Value::Null),
            },
            BinaryOperator::Multiply => match (left, right) {
                (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a.wrapping_mul(*b))),
                (Value::Real(a), Value::Real(b)) => Ok(Value::Real(a * b)),
                (Value::Integer(a), Value::Real(b)) => Ok(Value::Real(*a as f64 * b)),
                (Value::Real(a), Value::Integer(b)) => Ok(Value::Real(a * *b as f64)),
                _ => Ok(Value::Null),
            },
            BinaryOperator::Divide => {
                match (left, right) {
                    (Value::Integer(a), Value::Integer(b)) => {
                        if *b == 0 {
                            Ok(Value::Null) // SQLite returns NULL for division by zero
                        } else {
                            Ok(Value::Integer(a.wrapping_div(*b)))
                        }
                    }
                    (Value::Real(a), Value::Real(b)) => {
                        if *b == 0.0 {
                            Ok(Value::Null)
                        } else {
                            Ok(Value::Real(a / b))
                        }
                    }
                    (Value::Integer(a), Value::Real(b)) => {
                        if *b == 0.0 {
                            Ok(Value::Null)
                        } else {
                            Ok(Value::Real(*a as f64 / b))
                        }
                    }
                    (Value::Real(a), Value::Integer(b)) => {
                        if *b == 0 {
                            Ok(Value::Null)
                        } else {
                            Ok(Value::Real(a / *b as f64))
                        }
                    }
                    _ => Ok(Value::Null),
                }
            }
            BinaryOperator::Modulo => match (left, right) {
                (Value::Integer(a), Value::Integer(b)) => {
                    if *b == 0 {
                        Ok(Value::Null)
                    } else {
                        Ok(Value::Integer(a.wrapping_rem(*b)))
                    }
                }
                _ => Ok(Value::Null),
            },
            BinaryOperator::Equal => Ok(Value::Integer(if left == right { 1 } else { 0 })),
            BinaryOperator::NotEqual => Ok(Value::Integer(if left != right { 1 } else { 0 })),
            BinaryOperator::LessThan => Ok(Value::Integer(
                if left.partial_cmp(right) == Some(std::cmp::Ordering::Less) {
                    1
                } else {
                    0
                },
            )),
            BinaryOperator::LessThanOrEqual => Ok(Value::Integer(
                if left
                    .partial_cmp(right)
                    .is_some_and(|o| o != std::cmp::Ordering::Greater)
                {
                    1
                } else {
                    0
                },
            )),
            BinaryOperator::GreaterThan => Ok(Value::Integer(
                if left.partial_cmp(right) == Some(std::cmp::Ordering::Greater) {
                    1
                } else {
                    0
                },
            )),
            BinaryOperator::GreaterThanOrEqual => Ok(Value::Integer(
                if left
                    .partial_cmp(right)
                    .is_some_and(|o| o != std::cmp::Ordering::Less)
                {
                    1
                } else {
                    0
                },
            )),
            BinaryOperator::And => Ok(Value::Integer(if left.is_truthy() && right.is_truthy() {
                1
            } else {
                0
            })),
            BinaryOperator::Or => Ok(Value::Integer(if left.is_truthy() || right.is_truthy() {
                1
            } else {
                0
            })),
            BinaryOperator::Concat => {
                let l_str = left.to_string();
                let r_str = right.to_string();
                let mut s = String::with_capacity(l_str.len() + r_str.len());
                s.push_str(&l_str);
                s.push_str(&r_str);
                Ok(Value::Text(s.into()))
            }
            BinaryOperator::Xor => {
                // Logical XOR: true iff exactly one is truthy
                let lt = left.is_truthy();
                let rt = right.is_truthy();
                Ok(Value::Integer(if lt ^ rt { 1 } else { 0 }))
            }
            BinaryOperator::BitwiseOr => match (left, right) {
                (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a | b)),
                _ => Ok(Value::Null),
            },
            BinaryOperator::BitwiseAnd => match (left, right) {
                (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a & b)),
                _ => Ok(Value::Null),
            },
            BinaryOperator::BitwiseXor => match (left, right) {
                (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a ^ b)),
                _ => Ok(Value::Null),
            },
            BinaryOperator::ShiftLeft => match (left, right) {
                (Value::Integer(a), Value::Integer(b)) if *b >= 0 && *b < 64 => {
                    Ok(Value::Integer(a.wrapping_shl(*b as u32)))
                }
                _ => Ok(Value::Null),
            },
            BinaryOperator::ShiftRight => match (left, right) {
                (Value::Integer(a), Value::Integer(b)) if *b >= 0 && *b < 64 => {
                    Ok(Value::Integer(a.wrapping_shr(*b as u32)))
                }
                _ => Ok(Value::Null),
            },
        }
    }
}

/// SQL LIKE pattern matching — Unicode-aware character-level matching
/// % matches any sequence of characters (including empty)
/// _ matches any single Unicode character
pub(crate) fn like_match(
    text: &str,
    pattern: &str,
    escape_char: Option<char>,
    case_insensitive: bool,
) -> bool {
    // Collect to char vecs to properly handle multi-byte Unicode (CJK etc.)
    let t_chars: Vec<char> = if case_insensitive {
        text.chars().map(|c| c.to_ascii_lowercase()).collect()
    } else {
        text.chars().collect()
    };
    let p_chars: Vec<char> = if case_insensitive {
        pattern.chars().map(|c| c.to_ascii_lowercase()).collect()
    } else {
        pattern.chars().collect()
    };

    let (tlen, plen) = (t_chars.len(), p_chars.len());
    let mut ti = 0usize;
    let mut pi = 0usize;
    let mut star_pi: Option<usize> = None;
    let mut star_ti = 0usize;

    while ti < tlen {
        let ec = escape_char.map(|c| {
            if case_insensitive {
                c.to_ascii_lowercase()
            } else {
                c
            }
        });
        if pi < plen && Some(p_chars[pi]) == ec {
            // Escape character — next char matches literally
            pi += 1;
            if pi < plen {
                if t_chars[ti] == p_chars[pi] {
                    ti += 1;
                    pi += 1;
                } else if let Some(sp) = star_pi {
                    pi = sp + 1;
                    star_ti += 1;
                    ti = star_ti;
                } else {
                    return false;
                }
            } else {
                return false;
            }
        } else if pi < plen && p_chars[pi] == '_' {
            // _ matches any single Unicode character
            ti += 1;
            pi += 1;
        } else if pi < plen && p_chars[pi] == '%' {
            // % — record position and try matching zero characters
            star_pi = Some(pi);
            star_ti = ti;
            pi += 1;
        } else if pi < plen {
            if t_chars[ti] == p_chars[pi] {
                ti += 1;
                pi += 1;
            } else if let Some(sp) = star_pi {
                pi = sp + 1;
                star_ti += 1;
                ti = star_ti;
            } else {
                return false;
            }
        } else if let Some(sp) = star_pi {
            pi = sp + 1;
            star_ti += 1;
            ti = star_ti;
        } else {
            return false;
        }
    }

    // Skip trailing % in pattern
    while pi < plen && p_chars[pi] == '%' {
        pi += 1;
    }

    pi == plen
}

fn json_extract_primitive(json: &str, path: &str) -> Option<String> {
    let mut parts = Vec::new();
    let p = path.trim_start_matches("$.").trim_start_matches('$');
    let mut current = String::new();
    for c in p.chars() {
        if c == '.' || c == '[' {
            if !current.is_empty() {
                parts.push(current.clone());
                current.clear();
            }
        } else if c == ']' {
            if !current.is_empty() {
                parts.push(format!("[{}]", current));
                current.clear();
            }
        } else {
            current.push(c);
        }
    }
    if !current.is_empty() {
        parts.push(current);
    }

    let mut current_json = json.trim().to_string();
    for part in parts {
        if part.starts_with('[') && part.ends_with(']') {
            let idx: usize = part[1..part.len() - 1].parse().ok()?;
            current_json = json_array_get(&current_json, idx)?;
        } else {
            let search = format!("\"{part}\":");
            let pos = current_json.find(&search)?;
            let rest = current_json[pos + search.len()..].trim_start();
            current_json = json_value_at_start(rest)?;
        }
    }
    Some(current_json)
}

fn json_value_at_start(rest: &str) -> Option<String> {
    if let Some(stripped) = rest.strip_prefix('"') {
        let mut end = 1;
        let mut escape = false;
        for (i, c) in stripped.char_indices() {
            if escape {
                escape = false;
                continue;
            }
            if c == '\\' {
                escape = true;
                continue;
            }
            if c == '"' {
                end = i + 2;
                break;
            }
        }
        Some(rest[..end].to_string())
    } else if rest.starts_with('{') {
        let mut depth = 0;
        for (i, c) in rest.char_indices() {
            if c == '{' {
                depth += 1;
            }
            if c == '}' {
                depth -= 1;
                if depth == 0 {
                    return Some(rest[..=i].to_string());
                }
            }
        }
        None
    } else if rest.starts_with('[') {
        let mut depth = 0;
        for (i, c) in rest.char_indices() {
            if c == '[' {
                depth += 1;
            }
            if c == ']' {
                depth -= 1;
                if depth == 0 {
                    return Some(rest[..=i].to_string());
                }
            }
        }
        None
    } else {
        let end = rest
            .find([',', '}', ']', ' ', '\n', '\t'])
            .unwrap_or(rest.len());
        Some(rest[..end].to_string())
    }
}

fn json_array_get(json: &str, target_idx: usize) -> Option<String> {
    let json = json.trim();
    if !json.starts_with('[') {
        return None;
    }
    let inner = &json[1..json.len() - 1].trim();
    if inner.is_empty() {
        return None;
    }

    let mut depth = 0;
    let mut idx = 0;
    let mut start = 0;
    let mut in_string = false;
    let mut escape = false;

    for (i, c) in inner.char_indices() {
        if escape {
            escape = false;
            continue;
        }
        if c == '\\' {
            escape = true;
            continue;
        }
        if c == '"' {
            in_string = !in_string;
            continue;
        }
        if in_string {
            continue;
        }

        if c == '{' || c == '[' {
            depth += 1;
        } else if c == '}' || c == ']' {
            depth -= 1;
        } else if c == ',' && depth == 0 {
            if idx == target_idx {
                return Some(inner[start..i].trim().to_string());
            }
            idx += 1;
            start = i + 1;
        }
    }
    if idx == target_idx && start < inner.len() {
        return Some(inner[start..].trim().to_string());
    }
    None
}

fn json_array_contains(json: &str, target_val: &str) -> bool {
    let json = json.trim();
    if !json.starts_with('[') {
        return false;
    }
    let inner = &json[1..json.len() - 1].trim();
    if inner.is_empty() {
        return false;
    }

    let mut depth = 0;
    let mut start = 0;
    let mut in_string = false;
    let mut escape = false;

    for (i, c) in inner.char_indices() {
        if escape {
            escape = false;
            continue;
        }
        if c == '\\' {
            escape = true;
            continue;
        }
        if c == '"' {
            in_string = !in_string;
            continue;
        }
        if in_string {
            continue;
        }

        if c == '{' || c == '[' {
            depth += 1;
        } else if c == '}' || c == ']' {
            depth -= 1;
        } else if c == ',' && depth == 0 {
            let elem = inner[start..i].trim();
            if elem == target_val {
                return true;
            }
            start = i + 1;
        }
    }
    if start < inner.len() {
        let elem = inner[start..].trim();
        if elem == target_val {
            return true;
        }
    }
    false
}

/// Convert a raw JSON scalar string to a typed Value.
fn json_scalar_to_value(s: &str) -> crate::types::Value {
    use crate::types::Value;
    let t = s.trim();
    if t == "null" {
        return Value::Null;
    }
    if t == "true" {
        return Value::Integer(1);
    }
    if t == "false" {
        return Value::Integer(0);
    }
    if t.starts_with('"') && t.ends_with('"') && t.len() >= 2 {
        let inner = t[1..t.len() - 1]
            .replace("\\\"", "\"")
            .replace("\\\\", "\\");
        return Value::Text(inner.into());
    }
    if let Ok(i) = t.parse::<i64>() {
        return Value::Integer(i);
    }
    if let Ok(f) = t.parse::<f64>() {
        return Value::Real(f);
    }
    // Objects/arrays stay as Text
    Value::Text(t.into())
}

/// Check if a string is valid JSON (basic check)
fn json_is_valid(s: &str) -> bool {
    let t = s.trim();
    if t.is_empty() {
        return false;
    }
    // Must start and end with matching brackets or be a scalar
    (t.starts_with('{') && t.ends_with('}'))
        || (t.starts_with('[') && t.ends_with(']'))
        || t.starts_with('"')
        || t == "null"
        || t == "true"
        || t == "false"
        || t.parse::<f64>().is_ok()
}

/// Count the number of elements (array) or key-value pairs (object) in a JSON value.
fn json_length(s: &str) -> usize {
    let t = s.trim();
    if t == "null" || t.is_empty() {
        return 0;
    }
    if t.starts_with('[') || t.starts_with('{') {
        let inner = if t.len() > 1 { &t[1..t.len() - 1] } else { "" };
        if inner.trim().is_empty() {
            return 0;
        }
        // Count top-level comma-separated elements
        let mut count = 1;
        let mut depth = 0i32;
        let mut in_string = false;
        let mut escape = false;
        for c in inner.chars() {
            if escape {
                escape = false;
                continue;
            }
            if c == '\\' && in_string {
                escape = true;
                continue;
            }
            if c == '"' {
                in_string = !in_string;
                continue;
            }
            if in_string {
                continue;
            }
            if c == '{' || c == '[' {
                depth += 1;
            } else if c == '}' || c == ']' {
                depth -= 1;
            } else if c == ':' && depth == 0 && t.starts_with('{') { /* skip object key:val separator */
            } else if c == ',' && depth == 0 {
                if t.starts_with('[') {
                    count += 1;
                } else {
                    // For objects, count key:val pairs = commas + 1; divide by 1 (each comma between pairs)
                    count += 1;
                }
            }
        }
        // For objects, each "pair" is key:value, so commas separate pairs
        if t.starts_with('{') {
            // count is number of commas+1, which equals number of key-value pairs
            count
        } else {
            count
        }
    } else {
        1 // Scalar
    }
}

/// Return a JSON array of keys from a JSON object. Returns "[]" if not an object.
fn json_keys(s: &str) -> String {
    let t = s.trim();
    if !t.starts_with('{') {
        return "[]".to_string();
    }
    let inner = if t.len() > 1 { &t[1..t.len() - 1] } else { "" };
    if inner.trim().is_empty() {
        return "[]".to_string();
    }

    let mut keys = Vec::new();
    let mut depth = 0i32;
    let mut in_string = false;
    let mut escape = false;
    let mut start = 0usize;
    let chars: Vec<char> = inner.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];
        if escape {
            escape = false;
            i += 1;
            continue;
        }
        if c == '\\' && in_string {
            escape = true;
            i += 1;
            continue;
        }
        if c == '"' {
            if !in_string {
                in_string = true;
                start = i;
            } else {
                in_string = false;
                if depth == 0 {
                    // This is a top-level key
                    let key_raw: String = chars[start..=i].iter().collect();
                    // Find ':' after key
                    let mut j = i + 1;
                    while j < chars.len() && chars[j].is_whitespace() {
                        j += 1;
                    }
                    if j < chars.len() && chars[j] == ':' {
                        keys.push(key_raw);
                        // Skip to after next top-level ','
                        let mut depth2 = 0i32;
                        let mut in_s2 = false;
                        let mut esc2 = false;
                        j += 1;
                        while j < chars.len() {
                            let cc = chars[j];
                            if esc2 {
                                esc2 = false;
                                j += 1;
                                continue;
                            }
                            if cc == '\\' && in_s2 {
                                esc2 = true;
                                j += 1;
                                continue;
                            }
                            if cc == '"' {
                                in_s2 = !in_s2;
                                j += 1;
                                continue;
                            }
                            if in_s2 {
                                j += 1;
                                continue;
                            }
                            if cc == '{' || cc == '[' {
                                depth2 += 1;
                            } else if cc == '}' || cc == ']' {
                                depth2 -= 1;
                            } else if cc == ',' && depth2 == 0 {
                                j += 1;
                                break;
                            }
                            j += 1;
                        }
                        i = j;
                        continue;
                    }
                }
            }
            i += 1;
            continue;
        }
        if in_string {
            i += 1;
            continue;
        }
        if c == '{' || c == '[' {
            depth += 1;
        } else if c == '}' || c == ']' {
            depth -= 1;
        }
        i += 1;
    }

    if keys.is_empty() {
        return "[]".to_string();
    }
    format!("[{}]", keys.join(", "))
}

/// Check if a JSON document (object or scalar) contains a value.
fn json_contains_value(json: &str, needle: &str) -> bool {
    let t = json.trim();
    // Check scalar equality
    if t == needle {
        return true;
    }
    // For objects, check all values recursively
    if t.starts_with('{') {
        // Simple: search for needle as substring (good enough for primitive values)
        return t.contains(needle);
    }
    false
}

/// Remove a key from a JSON object at a given path like '$.key'.
fn json_remove_path(json: &str, path: &str) -> Option<String> {
    let t = json.trim();
    let key = path.trim_start_matches("$.").trim_start_matches('$');
    if key.is_empty() {
        return Some(t.to_string());
    }
    if !t.starts_with('{') {
        return Some(t.to_string());
    }

    let inner = &t[1..t.len() - 1];
    let search_key = format!("\"{key}\":");
    let alt_key = format!("\"{key}\" :");

    if let Some(pos) = inner.find(&search_key).or_else(|| inner.find(&alt_key)) {
        // Find end of value
        let val_start = pos + search_key.len();
        let rest = inner[val_start..].trim_start();
        let val_len = {
            let mut depth = 0i32;
            let mut in_str = false;
            let mut esc = false;
            let mut end = rest.len();
            for (ci, c) in rest.char_indices() {
                if esc {
                    esc = false;
                    continue;
                }
                if c == '\\' && in_str {
                    esc = true;
                    continue;
                }
                if c == '"' {
                    in_str = !in_str;
                    continue;
                }
                if in_str {
                    continue;
                }
                if c == '{' || c == '[' {
                    depth += 1;
                } else if c == '}' || c == ']' {
                    depth -= 1;
                } else if c == ',' && depth == 0 {
                    end = ci;
                    break;
                }
            }
            end
        };
        // Remove: delete from start of key to after comma/nothing
        let before = inner[..pos].trim_end_matches(',').trim_end();
        let _after = inner[val_start..].trim_start();
        let after_val = &rest[val_len..];
        let new_inner = if before.is_empty() {
            after_val.trim_start_matches(',').trim().to_string()
        } else if after_val.trim_start().is_empty() {
            before.to_string()
        } else {
            format!("{before}, {}", after_val.trim_start_matches(',').trim())
        };
        Some(format!("{{{new_inner}}}"))
    } else {
        Some(t.to_string())
    }
}

/// Set/insert a key at a given path like '$.key' in a JSON object.
fn json_set_path(json: &str, path: &str, value: &str) -> Option<String> {
    let t = json.trim();
    let key = path.trim_start_matches("$.").trim_start_matches('$');
    if key.is_empty() {
        return Some(value.to_string());
    }
    if !t.starts_with('{') {
        // Can't set key on non-object, just return a new object
        return Some(format!("{{\"{key}\": {value}}}"));
    }
    let inner = if t.len() > 2 { &t[1..t.len() - 1] } else { "" };
    let search_key = format!("\"{key}\":");

    if let Some(pos) = inner.find(&search_key) {
        // Replace existing value
        let val_start = pos + search_key.len();
        let rest = inner[val_start..].trim_start();
        let val_len = {
            let mut depth = 0i32;
            let mut in_str = false;
            let mut esc = false;
            let mut end = rest.len();
            for (ci, c) in rest.char_indices() {
                if esc {
                    esc = false;
                    continue;
                }
                if c == '\\' && in_str {
                    esc = true;
                    continue;
                }
                if c == '"' {
                    in_str = !in_str;
                    continue;
                }
                if in_str {
                    continue;
                }
                if c == '{' || c == '[' {
                    depth += 1;
                } else if c == '}' || c == ']' {
                    depth -= 1;
                } else if c == ',' && depth == 0 {
                    end = ci;
                    break;
                }
            }
            end
        };
        let suffix = &rest[val_len..];
        let new_inner = format!("{}\"{key}\": {value}{suffix}", &inner[..pos]);
        Some(format!("{{{new_inner}}}"))
    } else {
        // Add new key
        if inner.trim().is_empty() {
            Some(format!("{{\"{key}\": {value}}}"))
        } else {
            Some(format!("{{{inner}, \"{key}\": {value}}}"))
        }
    }
}

//! DDL statement execution for KKDB.
//!
//! This module implements all Data Definition Language (DDL) operations on the
//! [`VM`]: `CREATE TABLE`, `DROP TABLE`, `ALTER TABLE`, `CREATE INDEX`,
//! `DROP INDEX`, `CREATE VIEW`, `CREATE TRIGGER`, `CREATE FULLTEXT INDEX`,
//! `VACUUM`, `ANALYZE TABLE`, and `EXPLAIN`.
//!
//! ## Multi-file vs. single-file (in-memory) mode
//!
//! KKDB can store each table in its own `.kkdb` file (multi-file mode) or keep
//! all data in a single pager (single-file / in-memory mode).  Most DDL helpers
//! branch on `self.table_pagers.contains_key(...)` to handle both cases.
//!
//! ## Unsafe double-borrow pattern
//!
//! Several helpers need **two `&mut` borrows** of the same `Pager` simultaneously
//! (one for the schema catalog B-tree, one for the table data B-tree).  Because
//! Rust's borrow checker does not allow this, we use a raw-pointer alias:
//!
//! ```ignore
//! let p  = &mut self.pager as *mut _;
//! let p2 = unsafe { &mut *p }; // disjoint logical access, same physical object
//! ```
//!
//! This is safe because the two B-tree operations never touch the same page
//! simultaneously; the schema B-tree root and the data B-tree root are distinct.

use super::execute::{ExecResult, VM};
use crate::error::Result;
use crate::sql::ast::*;
use crate::storage::btree::BTree;
use crate::types::Value;

/// Helper struct for EXPLAIN (FORMAT TREE) rendering.
struct TreeNode {
    label: String,
    children: Vec<TreeNode>,
}

impl TreeNode {
    fn new(label: &str) -> Self {
        Self { label: label.to_string(), children: Vec::new() }
    }
}

impl VM {
    // ---- CREATE TABLE ----

    /// Execute a `CREATE TABLE` statement.
    ///
    /// Supports three variants:
    /// - **Regular `CREATE TABLE`**: allocates a schema catalog entry and a data
    ///   B-tree root page.  In multi-file mode a dedicated `.kkdb` file is
    ///   created for the table.
    /// - **`CREATE TABLE AS SELECT`**: delegates to [`Self::exec_create_table_as_select`]
    ///   which first executes the SELECT, infers column types, then creates the
    ///   table and bulk-inserts the rows inside an implicit transaction.
    /// - **`CREATE TABLE IF NOT EXISTS`**: silently succeeds when the table
    ///   already exists (handled inside [`crate::schema::Schema::create_table`]).
    ///
    /// After creation the index caches are invalidated and the pager is
    /// auto-flushed to persist the change.
    pub(crate) fn exec_create_table(
        &mut self,
        create: &CreateTableStmt,
        original_sql: &str,
    ) -> Result<ExecResult> {
        // CREATE TABLE AS SELECT
        if let Some(ref query) = create.source {
            return self.exec_create_table_as_select(create, query.as_ref().clone());
        }

        // In multi-file mode: open/create a separate pager file for this table.
        if let Some(ref db_dir) = self.db_dir.clone() {
            if VM::is_safe_table_name(&create.table_name) {
                VM::open_or_create_table_pager(
                    &mut self.table_pagers,
                    db_dir,
                    &create.table_name,
                    self.pager.in_transaction(),
                )?;
            }
        }

        // Get the two pagers: catalog (schema B-tree) and table (data B-tree).
        let table_name = create.table_name.clone();
        let tbl_key = table_name.to_ascii_lowercase();
        if self.table_pagers.contains_key(&tbl_key) {
            // Multi-file: temporarily split borrow by extracting table_pager.
            // SAFETY: contains_key check above guarantees the key exists
            let table_pager = self.table_pagers.get_mut(&tbl_key).unwrap() as *mut _;
            // SAFETY: table_pager and self.pager are disjoint fields.
            let table_pager: &mut crate::storage::pager::Pager = unsafe { &mut *table_pager };
            self.schema.create_table(
                &mut self.pager,
                table_pager,
                &create.table_name,
                &create.columns,
                create.if_not_exists,
                original_sql,
                &create.checks,
                create.is_fts,
            )?;
        } else {
            // Single-file / memory mode: catalog pager is also table pager.
            // We need two &mut borrows of self.pager 鈥?split via raw ptr.
            let p = &mut self.pager as *mut _;
            let p2: &mut crate::storage::pager::Pager = unsafe { &mut *p };
            self.schema.create_table(
                &mut self.pager,
                p2,
                &create.table_name,
                &create.columns,
                create.if_not_exists,
                original_sql,
                &create.checks,
                create.is_fts,
            )?;
        }

        self.clear_index_caches();
        self.auto_flush()?;
        Ok(ExecResult::Ok {
            message: format!("Table '{}' created", create.table_name),
        })
    }

    fn exec_create_table_as_select(
        &mut self,
        create: &CreateTableStmt,
        query: crate::sql::ast::SelectStmt,
    ) -> Result<ExecResult> {
        use crate::sql::ast::ColumnDef;
        use crate::types::{DataType, Value};

        // Phase 1: Execute SELECT and materialise all rows + column names.
        let (col_names, rows) = match self.exec_select(&query)? {
            crate::vm::execute::ExecResult::QueryResult { columns, rows } => (columns, rows),
            _ => {
                return Err(crate::error::KkdbError::Internal(
                    "CTAS: exec_select did not return rows".into(),
                ))
            }
        };

        // Infer column types from the first non-NULL value in each column.
        // Falls back to Text if column is all-NULL or result set is empty.
        let mut col_types: Vec<DataType> = vec![DataType::Text; col_names.len()];
        'outer: for row in &rows {
            let mut all_inferred = true;
            for (i, val) in row.iter().enumerate() {
                if matches!(col_types[i], DataType::Text) {
                    if !matches!(val, Value::Null) {
                        col_types[i] = match val {
                            Value::Integer(_) => DataType::Integer,
                            Value::Real(_) => DataType::Real,
                            Value::Blob(_) => DataType::Blob,
                            _ => DataType::Text,
                        };
                    } else {
                        all_inferred = false;
                    }
                }
            }
            if all_inferred {
                break 'outer;
            }
        }

        // Build column definitions with auto-names for expressions without alias.
        let columns: Vec<ColumnDef> = col_names
            .iter()
            .zip(col_types)
            .enumerate()
            .map(|(i, (name, dt))| {
                let col_name = if name.is_empty() || name == "?" {
                    format!("col_{}", i + 1)
                } else {
                    name.to_ascii_lowercase()
                };
                ColumnDef {
                    name: col_name,
                    data_type: dt,
                    primary_key: false,
                    autoincrement: false,
                    not_null: false,
                    unique: false,
                    default: None,
                    references: None,
                    check_expr: None,
                }
            })
            .collect();

        // Generate DDL SQL string to store in schema.
        let cols_sql: String = columns
            .iter()
            .map(|c| format!("{} {}", c.name, c.data_type))
            .collect::<Vec<_>>()
            .join(", ");
        let ddl_sql = format!("CREATE TABLE {} ({})", create.table_name, cols_sql);

        if create.if_not_exists
            && self
                .schema
                .tables
                .contains_key(&create.table_name.to_lowercase())
        {
            return Ok(ExecResult::Ok {
                message: format!("Table '{}' already exists", create.table_name),
            });
        }

        // Phase 2: Create table + bulk-insert with implicit transaction (atomicity).
        let need_auto_txn = !self.pager.in_transaction();
        if need_auto_txn {
            self.pager.begin_transaction()?;
            self.schema_snapshot = Some(self.schema.clone());
        }

        let result = (|| -> Result<ExecResult> {
            // In multi-file mode: open/create a separate pager file for this table.
            if let Some(ref db_dir) = self.db_dir.clone() {
                if VM::is_safe_table_name(&create.table_name) {
                    VM::open_or_create_table_pager(
                        &mut self.table_pagers,
                        db_dir,
                        &create.table_name,
                        self.pager.in_transaction(),
                    )?;
                }
            }
            let tbl_key = create.table_name.to_ascii_lowercase();
            if self.table_pagers.contains_key(&tbl_key) {
                // SAFETY: contains_key check above guarantees the key exists
                let table_pager = self.table_pagers.get_mut(&tbl_key).unwrap() as *mut _;
                let table_pager: &mut crate::storage::pager::Pager = unsafe { &mut *table_pager };
                self.schema.create_table(
                    &mut self.pager,
                    table_pager,
                    &create.table_name,
                    &columns,
                    create.if_not_exists,
                    &ddl_sql,
                    &[],
                    create.is_fts,
                )?;
            } else {
                let p = &mut self.pager as *mut _;
                let p2: &mut crate::storage::pager::Pager = unsafe { &mut *p };
                self.schema.create_table(
                    &mut self.pager,
                    p2,
                    &create.table_name,
                    &columns,
                    create.if_not_exists,
                    &ddl_sql,
                    &[],
                    create.is_fts,
                )?;
            }
            self.clear_index_caches();

            // Insert every row from the SELECT result.
            let insert_stmt = crate::sql::ast::InsertStmt {
                table_name: create.table_name.clone(),
                columns: None,
                source: crate::sql::ast::InsertSource::Values(
                    rows.iter()
                        .map(|r| {
                            r.iter()
                                .map(|v| crate::sql::ast::Expr::from_value(v.clone()))
                                .collect()
                        })
                        .collect(),
                ),
                conflict: crate::sql::ast::ConflictPolicy::Error,
                returning: None,
            };
            self.exec_insert(&insert_stmt)?;

            Ok(ExecResult::Ok {
                message: format!(
                    "Table '{}' created with {} row(s)",
                    create.table_name,
                    rows.len()
                ),
            })
        })();

        if need_auto_txn {
            match result {
                Ok(r) => {
                    // B13-1 fix: if commit fails, rollback and return error (same as B12-6)
                    match self.pager.commit_transaction() {
                        Ok(()) => {
                            self.schema_snapshot = None;
                            Ok(r)
                        }
                        Err(e) => {
                            let _ = self.pager.rollback_transaction();
                            for tbl_pager in self.table_pagers.values_mut() {
                                if tbl_pager.in_transaction() {
                                    let _ = tbl_pager.rollback_transaction();
                                }
                            }
                            if let Some(snap) = self.schema_snapshot.take() {
                                self.schema = snap;
                            }
                            self.clear_index_caches();
                            Err(e)
                        }
                    }
                }
                Err(e) => {
                    let _ = self.pager.rollback_transaction();
                    if let Some(snap) = self.schema_snapshot.take() {
                        self.schema = snap;
                    }
                    self.clear_index_caches();
                    Err(e)
                }
            }
        } else {
            result
        }
    }

    // ---- DROP TABLE ----

    /// Execute a `DROP TABLE [IF EXISTS]` statement.
    ///
    /// In addition to removing the table's schema entry and data B-tree, this
    /// method performs a **cascade drop** for the associated FTS internal table
    /// (`<name>_fts_idx`) when the table was created with `CREATE FULLTEXT INDEX`.
    ///
    /// If `drop.if_exists` is `true` and the table does not exist, the method
    /// succeeds silently.
    pub(crate) fn exec_drop_table(&mut self, drop: &DropTableStmt) -> Result<ExecResult> {
        let is_fts = self
            .schema
            .tables
            .get(&drop.table_name.to_lowercase())
            .map(|t| t.is_fts)
            .unwrap_or(false);
        self.schema
            .drop_table(&mut self.pager, &drop.table_name, drop.if_exists)?;

        // L4: Cascade drop for FTS internal table
        if is_fts {
            let fts_tbl = format!("{}_fts_idx", drop.table_name);
            let _ = self.exec_drop_table(&DropTableStmt {
                table_name: fts_tbl,
                if_exists: true,
            });
        }

        self.clear_index_caches();
        self.auto_flush()?;
        Ok(ExecResult::Ok {
            message: format!("Table '{}' dropped", drop.table_name),
        })
    }

    // ---- ALTER TABLE ----

    /// Execute an `ALTER TABLE` statement.
    ///
    /// Supported actions:
    /// - `ADD COLUMN col_def` — appends a new column to the schema; existing
    ///   rows implicitly get `NULL` for the new column.
    /// - `DROP COLUMN col_name` — removes the column metadata; physical row
    ///   data is not rewritten (lazy schema evolution).
    /// - `RENAME TO new_name` — renames the table in both the in-memory schema
    ///   and the catalog B-tree.
    /// - `RENAME COLUMN old TO new` — renames a single column.
    /// - `ENABLE ROW LEVEL SECURITY` — sets `rls_enabled = true` on the table
    ///   and persists an `rls_enabled` marker row to the schema catalog so the
    ///   flag survives a process restart.
    pub(crate) fn exec_alter_table(&mut self, alter: &AlterTableStmt) -> Result<ExecResult> {
        let msg = match &alter.action {
            AlterTableAction::AddColumn(col_def) => {
                self.schema
                    .alter_add_column(&mut self.pager, &alter.table_name, col_def)?;
                format!(
                    "Column '{}' added to table '{}'",
                    col_def.name, alter.table_name
                )
            }
            AlterTableAction::DropColumn(col_name) => {
                self.schema
                    .alter_drop_column(&mut self.pager, &alter.table_name, col_name)?;
                format!(
                    "Column '{}' dropped from table '{}'",
                    col_name, alter.table_name
                )
            }
            AlterTableAction::RenameTable(new_name) => {
                self.schema
                    .alter_rename_table(&mut self.pager, &alter.table_name, new_name)?;
                format!("Table '{}' renamed to '{}'", alter.table_name, new_name)
            }
            AlterTableAction::RenameColumn { old_name, new_name } => {
                self.schema.alter_rename_column(
                    &mut self.pager,
                    &alter.table_name,
                    old_name,
                    new_name,
                )?;
                format!(
                    "Column '{}' renamed to '{}' in table '{}'",
                    old_name, new_name, alter.table_name
                )
            }
            AlterTableAction::EnableRowLevelSecurity => {
                let tbl_key = alter.table_name.to_ascii_lowercase();
                if let Some(tbl) = self.schema.tables.get_mut(&tbl_key) {
                    tbl.rls_enabled = true;
                } else {
                    return Err(crate::error::KkdbError::RuntimeError(format!(
                        "table '{}' not found",
                        alter.table_name
                    )));
                }
                // M5 fix: persist the RLS flag to the catalog so it survives a restart
                let schema_root = self.pager.schema_root_page();
                let next_rowid = {
                    let mut bt = BTree::new(&mut self.pager);
                    bt.max_rowid(schema_root).unwrap_or(0) + 1
                };
                let rls_row = vec![
                    Value::Text("rls_enabled".into()),   // type
                    Value::Text(tbl_key.clone().into()), // name
                    Value::Text(tbl_key.clone().into()), // tbl_name
                    Value::Integer(0),                   // root_page (unused)
                    Value::Text("ALTER TABLE ... ENABLE ROW LEVEL SECURITY".into()), // sql
                ];
                let mut btree = BTree::new(&mut self.pager);
                let new_schema_root = btree.insert(schema_root, next_rowid, &rls_row)?;
                if new_schema_root != schema_root {
                    self.pager.set_schema_root_page(new_schema_root)?;
                }
                format!("RLS enabled on table '{}'", alter.table_name)
            }
        };

        self.clear_index_caches();
        self.auto_flush()?;
        Ok(ExecResult::Ok { message: msg })
    }

    // ---- CREATE INDEX ----

    /// Execute a `CREATE [UNIQUE] INDEX` statement.
    ///
    /// Allocates a new B-tree root page for the index, scans the parent table
    /// to build the initial index entries, and persists both the index schema
    /// row and the root page to disk.
    ///
    /// In multi-file mode the index B-tree lives in the same pager file as its
    /// parent table.  In single-file / in-memory mode the catalog pager doubles
    /// as the index pager (safe double-borrow via raw pointer, see module docs).
    pub(crate) fn exec_create_index(&mut self, create_idx: &CreateIndexStmt) -> Result<ExecResult> {
        // Reconstruct the original SQL for schema storage
        let unique_str = if create_idx.unique { "UNIQUE " } else { "" };
        let cols_str = create_idx.columns.join(", ");
        let sql = format!(
            "CREATE {}INDEX {} ON {} ({})",
            unique_str, create_idx.index_name, create_idx.table_name, cols_str
        );

        let tbl_key = create_idx.table_name.to_ascii_lowercase();
        if self.table_pagers.contains_key(&tbl_key) {
            // SAFETY: contains_key check above guarantees the key exists
            let table_pager = self.table_pagers.get_mut(&tbl_key).unwrap() as *mut _;
            let table_pager: &mut crate::storage::pager::Pager = unsafe { &mut *table_pager };
            self.schema.create_index(
                &mut self.pager,
                table_pager,
                &create_idx.index_name,
                &create_idx.table_name,
                &create_idx.columns,
                create_idx.unique,
                create_idx.if_not_exists,
                &sql,
            )?;
        } else {
            let p = &mut self.pager as *mut _;
            let p2: &mut crate::storage::pager::Pager = unsafe { &mut *p };
            self.schema.create_index(
                &mut self.pager,
                p2,
                &create_idx.index_name,
                &create_idx.table_name,
                &create_idx.columns,
                create_idx.unique,
                create_idx.if_not_exists,
                &sql,
            )?;
        }
        self.clear_index_caches();
        self.auto_flush()?;

        Ok(ExecResult::Ok {
            message: format!("Index created: {}", create_idx.index_name),
        })
    }

    // ---- DROP INDEX ----

    /// Execute a `DROP INDEX [IF EXISTS]` statement.
    ///
    /// Removes the index from the schema catalog and frees the associated B-tree
    /// root page.  The index cache is invalidated so subsequent queries do not
    /// attempt to use the stale entry.
    pub(crate) fn exec_drop_index(&mut self, drop: &DropIndexStmt) -> Result<ExecResult> {
        self.schema
            .drop_index(&mut self.pager, &drop.index_name, drop.if_exists)?;
        self.clear_index_caches();
        self.auto_flush()?;
        Ok(ExecResult::Ok {
            message: format!("Index '{}' dropped", drop.index_name),
        })
    }

    // ---- CREATE FULLTEXT INDEX (BM25) ----
    /// Phase 4: Register a full-text index in the schema and backfill existing rows.
    pub(crate) fn exec_create_fulltext_index(
        &mut self,
        stmt: &CreateFulltextIndexStmt,
    ) -> Result<ExecResult> {
        use crate::storage::btree::BTree;
        use std::collections::HashMap;

        // 1. Validate table exists
        let tbl = self.schema.get_table(&stmt.table_name)?.clone();

        // 2. Validate columns exist in table
        let col_indices: Vec<usize> = stmt
            .columns
            .iter()
            .map(|col_name| {
                tbl.columns
                    .iter()
                    .find(|c| c.name.eq_ignore_ascii_case(col_name))
                    .map(|c| c.col_index)
                    .ok_or_else(|| {
                        crate::error::KkdbError::ColumnNotFound(format!(
                            "{}.{}",
                            stmt.table_name, col_name
                        ))
                    })
            })
            .collect::<Result<Vec<_>>>()?;

        // 3. Check IF NOT EXISTS
        let idx_lower = stmt.index_name.to_lowercase();
        if self.schema.indexes.contains_key(&idx_lower) {
            if stmt.if_not_exists {
                return Ok(ExecResult::Ok {
                    message: format!("FULLTEXT INDEX '{}' already exists", stmt.index_name),
                });
            }
            return Err(crate::error::KkdbError::Internal(format!(
                "FULLTEXT INDEX '{}' already exists",
                stmt.index_name
            )));
        }

        // 4. Allocate a real BTree root page for FTS postings storage.
        // This avoids execute_sql (schema.create_table unsafe double-borrow) entirely.
        let fts_root = {
            let mut btree = BTree::new(&mut self.pager);
            btree.create_table()?
        };

        // 5. Persist FTS index metadata to schema catalog.
        // Store fts_root (a small valid page number) as the root_page field.
        let original_sql = format!(
            "CREATE FULLTEXT INDEX {} ON {} ({})",
            stmt.index_name,
            stmt.table_name,
            stmt.columns.join(", ")
        );
        let schema_row: crate::types::Row = vec![
            crate::types::Value::Text("fulltext_index".into()),
            crate::types::Value::Text(stmt.index_name.clone().into()),
            crate::types::Value::Text(stmt.table_name.clone().into()),
            crate::types::Value::Integer(fts_root as i64), // valid page number, no UB
            crate::types::Value::Text(original_sql.into()),
        ];
        let schema_root = self.pager.schema_root_page();
        {
            let mut btree = BTree::new(&mut self.pager);
            let max_id = btree.max_rowid(schema_root).unwrap_or(0);
            let new_root = btree.insert(schema_root, max_id + 1, &schema_row)?;
            if new_root != schema_root {
                self.pager.set_schema_root_page(new_root)?;
            }
        }

        // 6. Register in in-memory schema (root_page = fts_root, the real BTree page)
        self.schema.register_fts_index(
            &stmt.index_name,
            &stmt.table_name,
            stmt.columns.clone(),
            fts_root, // root_page IS the FTS BTree root page
        );

        // 7. Backfill: scan existing rows and build inverted index directly via BTree
        let rows = {
            let pager = self.get_table_pager_mut(&stmt.table_name);
            let mut btree = BTree::new(pager);
            btree.scan_all(tbl.root_page)?
        };

        let mut total_docs: u64 = 0;
        let mut total_field_len: u64 = 0;
        let mut postings: HashMap<String, HashMap<u64, (u32, u32)>> = HashMap::new();
        let mut doc_freq: HashMap<String, u64> = HashMap::new();

        for (rowid, row) in &rows {
            total_docs += 1;
            let mut field_tokens: Vec<String> = Vec::new();
            for &ci in &col_indices {
                if let Some(crate::types::Value::Text(s)) = row.get(ci) {
                    let tok = crate::fulltext::tokenizer::simple_tokenize(s);
                    field_tokens.extend(tok);
                }
            }
            let field_len = field_tokens.len() as u32;
            total_field_len += field_len as u64;
            let mut tf_map: HashMap<String, u32> = HashMap::new();
            for token in field_tokens {
                *tf_map.entry(token).or_insert(0) += 1;
            }
            let rid = *rowid as u64;
            for (token, tf) in tf_map {
                *doc_freq.entry(token.clone()).or_insert(0) += 1;
                postings
                    .entry(token)
                    .or_default()
                    .insert(rid, (tf, field_len));
            }
        }

        // Write postings directly to the FTS BTree root page (no execute_sql)
        self.write_fts_postings_raw(fts_root, &postings, &doc_freq, total_docs, total_field_len)?;

        self.auto_flush()?;
        Ok(ExecResult::Ok {
            message: format!(
                "FULLTEXT INDEX '{}' created on {}.({}) with {} tokens across {} rows",
                stmt.index_name,
                stmt.table_name,
                stmt.columns.join(", "),
                doc_freq.len(),
                total_docs
            ),
        })
    }

    // ---- CREATE VECTOR INDEX (HNSW) ----

    /// Execute `CREATE VECTOR INDEX name ON table(col) DIM N [DISTANCE COSINE|L2]`.
    ///
    /// Phase 2 implementation:
    /// 1. Validates the target table and column.
    /// 2. Allocates a B-Tree root page (for future persistence in Phase 3+).
    /// 3. Persists a `vector_index` row to the schema catalog.
    /// 4. Registers a live `VectorIndex` (HNSW graph) in `schema.vector_indexes`.
    /// 5. Backfills all existing rows that have non-NULL BLOB values in the column.
    pub(crate) fn exec_create_vector_index(
        &mut self,
        stmt: &CreateVectorIndexStmt,
    ) -> Result<ExecResult> {
        use crate::vector::index::decode_vector;
        use crate::vector::{distance::DistanceMetric, VectorIndex};

        // 1. Validate table exists
        let tbl = self.schema.get_table(&stmt.table_name)?.clone();

        // 2. Validate column exists and find its index
        let col_lower = stmt.column.to_lowercase();
        let col_meta = tbl
            .columns
            .iter()
            .find(|c| c.name.eq_ignore_ascii_case(&col_lower))
            .ok_or_else(|| {
                crate::error::KkdbError::ColumnNotFound(format!(
                    "{}.{}",
                    stmt.table_name, stmt.column
                ))
            })?;
        let col_idx = col_meta.col_index;

        // 3. Check IF NOT EXISTS
        let idx_lower = stmt.index_name.to_lowercase();
        if self.schema.vector_indexes.get(&idx_lower).is_some() {
            if stmt.if_not_exists {
                return Ok(ExecResult::Ok {
                    message: format!("VECTOR INDEX '{}' already exists", stmt.index_name),
                });
            }
            return Err(crate::error::KkdbError::RuntimeError(format!(
                "VECTOR INDEX '{}' already exists",
                stmt.index_name
            )));
        }

        // 4. Allocate a B-Tree root page for future persistence
        let vec_root = {
            let mut btree = BTree::new(&mut self.pager);
            btree.create_table()?
        };

        // 5. Persist vector_index metadata to schema catalog
        let distance_str = match stmt.distance {
            crate::sql::ast::VecDistanceType::Cosine => "COSINE",
            crate::sql::ast::VecDistanceType::L2 => "L2",
        };
        let original_sql = format!(
            "CREATE VECTOR INDEX {} ON {} ({}) DIM {} DISTANCE {}",
            stmt.index_name, stmt.table_name, stmt.column, stmt.dim, distance_str
        );
        let schema_root = self.pager.schema_root_page();
        {
            let schema_row: crate::types::Row = vec![
                Value::Text("vector_index".into()),
                Value::Text(stmt.index_name.clone().into()),
                Value::Text(stmt.table_name.clone().into()),
                Value::Integer(vec_root as i64),
                Value::Text(original_sql.into()),
            ];
            let mut btree = BTree::new(&mut self.pager);
            let max_id = btree.max_rowid(schema_root).unwrap_or(0);
            let new_root = btree.insert(schema_root, max_id + 1, &schema_row)?;
            if new_root != schema_root {
                self.pager.set_schema_root_page(new_root)?;
            }
        }

        // 6. Register in-memory VectorIndex (HNSW graph)
        let metric = match stmt.distance {
            crate::sql::ast::VecDistanceType::Cosine => DistanceMetric::Cosine,
            crate::sql::ast::VecDistanceType::L2 => DistanceMetric::L2,
        };
        let index_id = self.schema.vector_indexes.alloc_index_id();
        let vi = VectorIndex::new(
            stmt.index_name.clone(),
            stmt.table_name.clone(),
            stmt.column.clone(),
            col_idx,
            stmt.dim,
            metric,
            index_id,
        );
        self.schema.vector_indexes.register(vi);

        // 7. Backfill: scan existing rows and insert their vectors into HNSW
        let rows = {
            let pager = self.get_table_pager_mut(&stmt.table_name);
            let mut btree = BTree::new(pager);
            btree.scan_all(tbl.root_page)?
        };

        let mut backfill_count = 0u64;
        let mut error_count = 0u64;
        let dim = stmt.dim;

        // SAFETY: the VectorIndex was just registered above; get() always returns Some
        let vi_ref = self
            .schema
            .vector_indexes
            .get(&stmt.index_name)
            .unwrap()
            .clone();
        for (rowid, row) in &rows {
            if let Some(Value::Blob(blob)) = row.get(col_idx) {
                if let Some(vec) = decode_vector(blob) {
                    if vec.len() as u32 == dim {
                        if vi_ref.insert_vec(*rowid as u64, vec).is_ok() {
                            backfill_count += 1;
                        } else {
                            error_count += 1;
                        }
                    } else {
                        error_count += 1;
                    }
                }
            }
        }

        self.auto_flush()?;
        Ok(ExecResult::Ok {
            message: format!(
                "VECTOR INDEX '{}' created on {}.{} (dim={}, distance={}, backfilled={}, errors={})",
                stmt.index_name, stmt.table_name, stmt.column,
                dim, distance_str, backfill_count, error_count
            ),
        })
    }

    /// Execute `DROP VECTOR INDEX [IF EXISTS] name`.
    ///
    /// Removes the index from the in-memory registry and from the schema catalog.
    pub(crate) fn exec_drop_vector_index(
        &mut self,
        index_name: &str,
        if_exists: bool,
    ) -> Result<ExecResult> {
        let lower = index_name.to_lowercase();
        if self.schema.vector_indexes.get(&lower).is_none() {
            if if_exists {
                return Ok(ExecResult::Ok {
                    message: format!("VECTOR INDEX '{}' does not exist", index_name),
                });
            }
            return Err(crate::error::KkdbError::RuntimeError(format!(
                "VECTOR INDEX '{}' not found",
                index_name
            )));
        }

        // Remove from in-memory registry
        self.schema.vector_indexes.drop(&lower);

        // Remove from schema catalog (scan for the vector_index row)
        let schema_root = self.pager.schema_root_page();
        let schema_rows = {
            let mut btree = BTree::new(&mut self.pager);
            btree.scan_all(schema_root)?
        };
        for (rowid, row) in schema_rows {
            if row.len() >= 2 {
                if let (Value::Text(ref typ), Value::Text(ref name)) = (&row[0], &row[1]) {
                    if typ.as_ref() == "vector_index" && name.eq_ignore_ascii_case(&lower) {
                        let mut btree = BTree::new(&mut self.pager);
                        let (_, new_root) = btree.delete_by_rowid(schema_root, rowid)?;
                        if new_root != schema_root {
                            self.pager.set_schema_root_page(new_root)?;
                        }
                        break;
                    }
                }
            }
        }

        self.auto_flush()?;
        Ok(ExecResult::Ok {
            message: format!("VECTOR INDEX '{}' dropped", index_name),
        })
    }

    /// Update the root page number in the schema table for a table or index object.
    pub(crate) fn update_schema_object_root_page(
        &mut self,
        object_name: &str,
        new_root: u32,
    ) -> Result<()> {
        let schema_root = self.pager.schema_root_page();
        let mut btree = BTree::new(&mut self.pager);
        let schema_rows = btree.scan_all(schema_root)?;

        for (rowid, row) in schema_rows {
            if row.len() >= 5 {
                if let Value::Text(ref name) = row[1] {
                    if name.eq_ignore_ascii_case(object_name) {
                        let mut new_row = row.clone();
                        new_row[3] = Value::Integer(new_root as i64);
                        let mut btree = BTree::new(&mut self.pager);
                        let new_schema_root = btree.update_row(schema_root, rowid, &new_row)?;
                        if new_schema_root != schema_root {
                            btree.pager.set_schema_root_page(new_schema_root)?;
                        }
                        break;
                    }
                }
            }
        }
        Ok(())
    }

    /// Update the root page number for a table.
    pub(crate) fn update_schema_root_page(
        &mut self,
        table_name: &str,
        new_root: u32,
    ) -> Result<()> {
        self.update_schema_object_root_page(table_name, new_root)
    }

    // ---- EXPLAIN ----

    /// Execute an `EXPLAIN` statement and return a human-readable query plan.
    ///
    /// The current implementation produces a simple textual plan that lists the
    /// top-level operations (SCAN, FILTER, SORT, LIMIT).  It does **not** yet
    /// perform cost-based optimisation or index selection analysis.
    pub(crate) fn exec_explain(&mut self, stmt: &Statement) -> Result<ExecResult> {
        let plan = match stmt {
            Statement::Select(select) => {
                let mut plan = String::new();
                plan.push_str("QUERY PLAN\n");
                if let Some(ref from) = select.from {
                    self.explain_from_plan(from, &mut plan, 1);
                }
                if select.where_clause.is_some() {
                    plan.push_str("  FILTER (WHERE clause)\n");
                    if let Some(ref from) = select.from {
                        self.explain_index_decision(
                            from,
                            select.where_clause.as_ref().unwrap(),
                            &mut plan,
                        );
                    }
                }
                if !select.order_by.is_empty() {
                    plan.push_str("  SORT (ORDER BY)\n");
                }
                if select.limit.is_some() {
                    plan.push_str("  LIMIT\n");
                }
                plan
            }
            Statement::Insert(insert) => {
                format!("INSERT INTO {}\n", insert.table_name)
            }
            Statement::Update(update) => {
                let mut plan = format!("UPDATE {}\n", update.table_name);
                plan.push_str("  SCAN table\n");
                if update.where_clause.is_some() {
                    plan.push_str("  FILTER (WHERE clause)\n");
                }
                plan
            }
            Statement::Delete(delete) => {
                let mut plan = format!("DELETE FROM {}\n", delete.table_name);
                plan.push_str("  SCAN table\n");
                if delete.where_clause.is_some() {
                    plan.push_str("  FILTER (WHERE clause)\n");
                }
                plan
            }
            _ => "No plan available for this statement type\n".to_string(),
        };
        Ok(ExecResult::Explain { plan })
    }

    /// Execute `EXPLAIN ANALYZE`: run the query, then report the plan with
    /// CBO decisions and actual execution statistics (row counts, timing).
    pub(crate) fn exec_explain_analyze(&mut self, stmt: &Statement) -> Result<ExecResult> {
        let mut plan = String::new();
        plan.push_str("QUERY PLAN (ANALYZE)\n");

        match stmt {
            Statement::Select(select) => {
                // ── Phase 1: Collect CBO statistics pre-execution ─────────
                if let Some(ref from) = select.from {
                    self.explain_from_plan(from, &mut plan, 1);
                }

                // Report WHERE clause analysis
                if let Some(ref where_expr) = select.where_clause {
                    plan.push_str("  FILTER (WHERE clause)\n");
                    // Check for index-eligible predicates
                    if let Some(ref from) = select.from {
                        self.explain_index_decision(from, where_expr, &mut plan);
                    }
                }

                if !select.order_by.is_empty() {
                    plan.push_str("  SORT (ORDER BY)\n");
                }
                if select.limit.is_some() {
                    plan.push_str("  LIMIT\n");
                }

                // ── Phase 2: Execute and measure ─────────────────────────
                let start = std::time::Instant::now();
                let result = self.exec_select(select);
                let elapsed = start.elapsed();

                match result {
                    Ok(ExecResult::QueryResult { rows, columns }) => {
                        plan.push_str(&format!(
                            "  Actual rows: {}, columns: {}\n",
                            rows.len(),
                            columns.len()
                        ));
                        plan.push_str(&format!("  Execution time: {:.3} ms\n", elapsed.as_secs_f64() * 1000.0));
                    }
                    Ok(_) => {
                        plan.push_str(&format!("  Execution time: {:.3} ms\n", elapsed.as_secs_f64() * 1000.0));
                    }
                    Err(e) => {
                        plan.push_str(&format!("  ERROR: {}\n", e));
                    }
                }
            }
            _ => {
                // For non-SELECT, produce basic EXPLAIN then execute
                let start = std::time::Instant::now();
                let result = self.exec_explain(stmt);
                let elapsed = start.elapsed();
                match result {
                    Ok(ExecResult::Explain { plan: ref p }) => {
                        plan.push_str(p);
                    }
                    Ok(_) => {}
                    Err(e) => {
                        plan.push_str(&format!("  ERROR: {}\n", e));
                    }
                }
                plan.push_str(&format!("  Execution time: {:.3} ms\n", elapsed.as_secs_f64() * 1000.0));
            }
        }

        Ok(ExecResult::Explain { plan })
    }

    /// Execute `EXPLAIN (FORMAT TREE)`: tree-style plan output using
    /// box-drawing characters (├──, └──, │) for visual hierarchy.
    pub(crate) fn exec_explain_format_tree(&mut self, stmt: &Statement) -> Result<ExecResult> {
        let mut lines: Vec<String> = Vec::new();
        lines.push("QUERY PLAN (TREE)".to_string());

        match stmt {
            Statement::Select(select) => {
                let mut children: Vec<TreeNode> = Vec::new();

                // FROM clause → scan / join tree
                if let Some(ref from) = select.from {
                    children.push(self.tree_from_plan(from));
                }

                // WHERE
                if let Some(ref where_expr) = select.where_clause {
                    let mut filter = TreeNode::new("FILTER (WHERE clause)");
                    if let Some(ref from) = select.from {
                        if let crate::sql::ast::FromClause::Table { name, .. } = from {
                            let table_lower = name.to_lowercase();
                            let indexes = self.schema.indexes_for_table(&table_lower);
                            if !indexes.is_empty() {
                                for idx in &indexes {
                                    let sel_info = self.estimate_selectivity_label(
                                        &table_lower,
                                        idx,
                                        where_expr,
                                    );
                                    filter.children.push(TreeNode::new(&sel_info));
                                }
                            } else {
                                filter.children.push(TreeNode::new("Seq Scan (no index)"));
                            }
                        }
                    }
                    children.push(filter);
                }

                // ORDER BY
                if !select.order_by.is_empty() {
                    children.push(TreeNode::new("SORT (ORDER BY)"));
                }

                // GROUP BY
                if !select.group_by.is_empty() {
                    children.push(TreeNode::new("AGGREGATE (GROUP BY)"));
                }

                // HAVING
                if select.having.is_some() {
                    children.push(TreeNode::new("HAVING FILTER"));
                }

                // LIMIT
                if select.limit.is_some() {
                    children.push(TreeNode::new("LIMIT"));
                }

                // Render tree
                let root = TreeNode { label: "SELECT".to_string(), children };
                self.render_tree_node(&root, &mut lines, "", true);
            }
            Statement::Insert(insert) => {
                let node = TreeNode::new(&format!("INSERT INTO {}", insert.table_name));
                self.render_tree_node(&node, &mut lines, "", true);
            }
            Statement::Update(update) => {
                let mut node = TreeNode::new(&format!("UPDATE {}", update.table_name));
                node.children.push(TreeNode::new("SCAN table"));
                if update.where_clause.is_some() {
                    node.children.push(TreeNode::new("FILTER (WHERE clause)"));
                }
                self.render_tree_node(&node, &mut lines, "", true);
            }
            Statement::Delete(delete) => {
                let mut node = TreeNode::new(&format!("DELETE FROM {}", delete.table_name));
                node.children.push(TreeNode::new("SCAN table"));
                if delete.where_clause.is_some() {
                    node.children.push(TreeNode::new("FILTER (WHERE clause)"));
                }
                self.render_tree_node(&node, &mut lines, "", true);
            }
            _ => {
                lines.push("└── No plan available for this statement type".to_string());
            }
        }

        let plan = lines.join("\n") + "\n";
        Ok(ExecResult::Explain { plan })
    }

    /// Execute `EXPLAIN (FORMAT JSON)`: JSON-formatted query plan output.
    pub(crate) fn exec_explain_format_json(&mut self, stmt: &Statement) -> Result<ExecResult> {
        let root = match stmt {
            Statement::Select(select) => {
                let mut children: Vec<TreeNode> = Vec::new();

                if let Some(ref from) = select.from {
                    children.push(self.tree_from_plan(from));
                }

                if select.where_clause.is_some() {
                    children.push(TreeNode::new("FILTER (WHERE clause)"));
                }

                if !select.order_by.is_empty() {
                    children.push(TreeNode::new("SORT (ORDER BY)"));
                }

                if !select.group_by.is_empty() {
                    children.push(TreeNode::new("AGGREGATE (GROUP BY)"));
                }

                if select.having.is_some() {
                    children.push(TreeNode::new("HAVING FILTER"));
                }

                if select.limit.is_some() {
                    children.push(TreeNode::new("LIMIT"));
                }

                TreeNode { label: "SELECT".to_string(), children }
            }
            Statement::Insert(insert) => {
                TreeNode::new(&format!("INSERT INTO {}", insert.table_name))
            }
            Statement::Update(update) => {
                let mut node = TreeNode::new(&format!("UPDATE {}", update.table_name));
                node.children.push(TreeNode::new("SCAN table"));
                if update.where_clause.is_some() {
                    node.children.push(TreeNode::new("FILTER (WHERE clause)"));
                }
                node
            }
            Statement::Delete(delete) => {
                let mut node = TreeNode::new(&format!("DELETE FROM {}", delete.table_name));
                node.children.push(TreeNode::new("SCAN table"));
                if delete.where_clause.is_some() {
                    node.children.push(TreeNode::new("FILTER (WHERE clause)"));
                }
                node
            }
            _ => TreeNode::new("UNKNOWN"),
        };

        let plan = self.tree_node_to_json(&root, 0);
        Ok(ExecResult::Explain { plan })
    }

    /// Serialize a `TreeNode` into indented JSON.
    fn tree_node_to_json(&self, node: &TreeNode, depth: usize) -> String {
        let indent = "  ".repeat(depth);
        let inner = "  ".repeat(depth + 1);
        if node.children.is_empty() {
            format!("{indent}{{\n{inner}\"operation\": \"{}\"\n{indent}}}\n", node.label)
        } else {
            let children_json: Vec<String> = node.children
                .iter()
                .map(|c| self.tree_node_to_json(c, depth + 2))
                .collect();
            let joined = children_json.join(&format!("{inner}  ,\n"));
            format!(
                "{indent}{{\n{inner}\"operation\": \"{}\",\n{inner}\"children\": [\n{joined}{inner}]\n{indent}}}\n",
                node.label
            )
        }
    }

    /// Build a `TreeNode` from a FROM clause (recursive for JOINs).
    fn tree_from_plan(&self, from: &crate::sql::ast::FromClause) -> TreeNode {
        use crate::sql::ast::FromClause;
        match from {
            FromClause::Table { name, alias } => {
                let table_name = name.to_lowercase();
                let card_str = if let Ok(table) = self.schema.get_table(&table_name) {
                    if let Some(ref stats) = table.columns.first().and_then(|c| c.stats.as_ref()) {
                        format!(" (estimated rows: {})", stats.total_count)
                    } else {
                        " (no stats)".to_string()
                    }
                } else {
                    String::new()
                };
                let alias_str = alias.as_ref().map(|a| format!(" AS {}", a)).unwrap_or_default();
                TreeNode::new(&format!("SCAN {name}{alias_str}{card_str}"))
            }
            FromClause::Join { left, join_type, right, on } => {
                let jt = match join_type {
                    crate::sql::ast::JoinType::Inner => "INNER JOIN",
                    crate::sql::ast::JoinType::Left => "LEFT JOIN",
                    crate::sql::ast::JoinType::Right => "RIGHT JOIN",
                    crate::sql::ast::JoinType::Full => "FULL OUTER JOIN",
                    crate::sql::ast::JoinType::Cross => "CROSS JOIN",
                    crate::sql::ast::JoinType::LeftSemi => "LEFT SEMI JOIN",
                    crate::sql::ast::JoinType::RightSemi => "RIGHT SEMI JOIN",
                    crate::sql::ast::JoinType::Natural => "NATURAL JOIN",
                };
                let left_card = self.estimate_from_row_count(left);
                let right_card = self.estimate_from_row_count(right);
                let is_equi = on.is_some();
                let (left_sorted, right_sorted) = if let Some(ref on_expr) = on {
                    self.check_join_key_sorted(left, right, on_expr)
                } else {
                    (false, false)
                };
                let algo = super::exec_select::choose_join_algorithm(
                    left_card, right_card, is_equi, left_sorted, right_sorted,
                );
                let mut node = TreeNode::new(&format!(
                    "{jt} ({algo}) [left≈{left_card}, right≈{right_card}]"
                ));
                node.children.push(self.tree_from_plan(left));
                node.children.push(self.tree_from_plan(right));
                node
            }
            FromClause::Subquery { alias, .. } => {
                TreeNode::new(&format!("SUBQUERY AS {alias}"))
            }
            _ => TreeNode::new("SCAN (complex source)"),
        }
    }

    /// Render a `TreeNode` into lines with box-drawing characters.
    fn render_tree_node(
        &self,
        node: &TreeNode,
        lines: &mut Vec<String>,
        prefix: &str,
        is_last: bool,
    ) {
        // Connector for this node
        let connector = if prefix.is_empty() {
            "└── ".to_string()
        } else if is_last {
            format!("{prefix}└── ")
        } else {
            format!("{prefix}├── ")
        };
        lines.push(format!("{connector}{}", node.label));

        // Child prefix extends the tree lines
        let child_prefix = if prefix.is_empty() {
            "    ".to_string()
        } else if is_last {
            format!("{prefix}    ")
        } else {
            format!("{prefix}│   ")
        };

        for (i, child) in node.children.iter().enumerate() {
            let child_is_last = i == node.children.len() - 1;
            self.render_tree_node(child, lines, &child_prefix, child_is_last);
        }
    }

    /// Format a selectivity label for a WHERE-clause index decision.
    fn estimate_selectivity_label(
        &self,
        table_name: &str,
        idx: &crate::schema::IndexSchema,
        _where_expr: &crate::sql::ast::Expr,
    ) -> String {
        if idx.columns.is_empty() {
            return format!("INDEX {} (no columns)", idx.name);
        }
        let col_name = &idx.columns[0];
        if let Ok(table) = self.schema.get_table(table_name) {
            for col in &table.columns {
                if col.name == *col_name {
                    if let Some(ref stats) = col.stats {
                        let ndv = stats.ndv.max(1);
                        let sel = 1.0 / ndv as f64;
                        return format!(
                            "INDEX SCAN {} on .{} (selectivity: {:.2})",
                            idx.name, col_name, sel
                        );
                    }
                }
            }
        }
        format!("INDEX SCAN {} on .{} (no stats)", idx.name, col_name)
    }

    /// Generate plan description for a FROM clause (recursive for JOINs).
    fn explain_from_plan(&self, from: &crate::sql::ast::FromClause, plan: &mut String, depth: usize) {
        use crate::sql::ast::FromClause;
        let indent = "  ".repeat(depth);
        match from {
            FromClause::Table { name, alias } => {
                let table_name = name.to_lowercase();
                let card_str = if let Ok(table) = self.schema.get_table(&table_name) {
                    if let Some(ref stats) = table.columns.first().and_then(|c| c.stats.as_ref()) {
                        format!(" (estimated rows: {})", stats.total_count)
                    } else {
                        " (no stats — run ANALYZE TABLE)".to_string()
                    }
                } else {
                    String::new()
                };
                let alias_str = alias.as_ref().map(|a| format!(" AS {}", a)).unwrap_or_default();
                plan.push_str(&format!("{indent}SCAN {name}{alias_str}{card_str}\n"));
            }
            FromClause::Join { left, join_type, right, on } => {
                let jt = match join_type {
                    crate::sql::ast::JoinType::Inner => "INNER JOIN",
                    crate::sql::ast::JoinType::Left => "LEFT JOIN",
                    crate::sql::ast::JoinType::Right => "RIGHT JOIN",
                    crate::sql::ast::JoinType::Full => "FULL OUTER JOIN",
                    crate::sql::ast::JoinType::Cross => "CROSS JOIN",
                    crate::sql::ast::JoinType::LeftSemi => "LEFT SEMI JOIN",
                    crate::sql::ast::JoinType::RightSemi => "RIGHT SEMI JOIN",
                    crate::sql::ast::JoinType::Natural => "NATURAL JOIN",
                };
                // CBO: estimate cardinalities and choose join algorithm
                let left_card = self.estimate_from_row_count(left);
                let right_card = self.estimate_from_row_count(right);
                let is_equi = on.is_some();
                // Check if either side is sorted on join key (simplified check)
                let (left_sorted, right_sorted) = if let Some(ref on_expr) = on {
                    self.check_join_key_sorted(left, right, on_expr)
                } else {
                    (false, false)
                };
                let algo = super::exec_select::choose_join_algorithm(
                    left_card, right_card, is_equi, left_sorted, right_sorted,
                );
                plan.push_str(&format!(
                    "{indent}{jt} ({algo}) [left≈{left_card}, right≈{right_card}]\n"
                ));
                self.explain_from_plan(left, plan, depth + 1);
                self.explain_from_plan(right, plan, depth + 1);
            }
            FromClause::Subquery { alias, .. } => {
                plan.push_str(&format!("{indent}SUBQUERY AS {alias}\n"));
            }
            _ => {
                plan.push_str(&format!("{indent}SCAN (complex source)\n"));
            }
        }
    }

    /// Report CBO index vs seq-scan decision for a WHERE clause.
    fn explain_index_decision(
        &self,
        from: &crate::sql::ast::FromClause,
        _where_expr: &crate::sql::ast::Expr,
        plan: &mut String,
    ) {
        // Only for simple single-table scans
        if let crate::sql::ast::FromClause::Table { name, .. } = from {
            let table_name = name.to_lowercase();
            if let Ok(table) = self.schema.get_table(&table_name) {
                // Check each column for index + stats
                let indexes = self.schema.indexes_for_table(&table_name);
                if !indexes.is_empty() {
                    for idx in &indexes {
                        if idx.columns.is_empty() {
                            continue;
                        }
                        let col_name = &idx.columns[0];
                        let has_stats = table
                            .columns
                            .iter()
                            .find(|c| c.name.eq_ignore_ascii_case(col_name))
                            .and_then(|c| c.stats.as_ref())
                            .is_some();
                        let hist_info = if let Some(col) = table
                            .columns
                            .iter()
                            .find(|c| c.name.eq_ignore_ascii_case(col_name))
                        {
                            if let Some(ref stats) = col.stats {
                                if stats.histogram.is_some() {
                                    " [histogram available]"
                                } else {
                                    " [no histogram]"
                                }
                            } else {
                                " [no stats]"
                            }
                        } else {
                            ""
                        };
                        plan.push_str(&format!(
                            "    Index: {} on ({}) — stats: {}{}\n",
                            idx.name,
                            idx.columns.join(", "),
                            if has_stats { "yes" } else { "no" },
                            hist_info,
                        ));
                    }
                } else {
                    plan.push_str("    No indexes available — seq scan\n");
                }
            }
        }
    }

    // ---- CREATE VIEW ----

    /// Execute a `CREATE [OR REPLACE] VIEW` statement.
    ///
    /// Views are stored as [`crate::schema::TableSchema`] entries with
    /// `root_page = 0` and `view_select` populated.  When a view is referenced
    /// in a `FROM` clause, [`super::exec_select::VM::eval_from`] detects the
    /// `view_select` field and evaluates the stored query transparently.
    ///
    /// A view definition row is also written to the schema catalog B-tree so
    /// that the view survives a process restart.
    ///
    /// If `CREATE OR REPLACE VIEW` is used and the view already exists, the old
    /// catalog entry is dropped first (B-NEW-1 fix).
    pub(crate) fn exec_create_view(&mut self, create: &CreateViewStmt) -> Result<ExecResult> {
        use crate::schema::TableSchema;
        use crate::storage::btree::BTree;
        let exists = self.schema.get_table(&create.name).is_ok();
        if exists {
            if create.or_replace {
                // B-NEW-1 fix: drop from catalog before replacing
                self.schema
                    .drop_table(&mut self.pager, &create.name, true)?;
            } else if create.if_not_exists {
                return Ok(ExecResult::Ok {
                    message: format!("VIEW {} already exists", create.name),
                });
            } else {
                return Err(crate::error::KkdbError::RuntimeError(format!(
                    "view '{}' already exists",
                    create.name
                )));
            }
        }
        // Views are stored as TableSchema in-memory with root_page=0 and view_select set
        let view_schema = TableSchema {
            name: create.name.clone(),
            columns: Vec::new(),
            col_names: create.columns.clone(),
            root_page: 0,
            next_rowid: 0,
            view_select: Some(create.query.as_ref().clone()),
            is_fts: false,
            foreign_keys: Vec::new(),
            check_constraints: Vec::new(),
            rls_enabled: false,
            policies: Vec::new(),
            clustered_index: false, // views have no storage
        };
        self.schema.add_view(view_schema);

        // B-NEW-1 fix: persist view definition to catalog BTree so it survives restarts
        let view_sql = format!("CREATE VIEW {} AS (view query)", create.name);
        let schema_root = self.pager.schema_root_page();
        let schema_row = vec![
            crate::types::Value::Text("view".into()),
            crate::types::Value::Text(create.name.clone().into()),
            crate::types::Value::Text(create.name.clone().into()),
            crate::types::Value::Integer(0),
            crate::types::Value::Text(view_sql.into()),
        ];
        let mut btree = BTree::new(&mut self.pager);
        let max_id = btree.max_rowid(schema_root).unwrap_or(0);
        let new_root = btree.insert(schema_root, max_id + 1, &schema_row)?;
        if new_root != schema_root {
            self.pager.set_schema_root_page(new_root)?;
        }

        self.auto_flush()?;
        Ok(ExecResult::Ok {
            message: format!("VIEW {} created", create.name),
        })
    }

    /// Return a concise display name for a `FROM` clause (used by `EXPLAIN`).
    #[allow(clippy::wrong_self_convention)]
    pub(crate) fn from_name(&self, from: &FromClause) -> String {
        match from {
            FromClause::Table { name, .. } => name.clone(),
            FromClause::Join { left, right, .. } => {
                format!("{} JOIN {}", self.from_name(left), self.from_name(right))
            }
            FromClause::Subquery { alias, .. } => format!("(subquery) AS {}", alias),
            FromClause::SetOp { alias, .. } => format!("(setop) AS {}", alias),
            FromClause::TableFunction { name, alias, .. } => {
                alias.as_deref().unwrap_or(name.as_str()).to_string()
            }
        }
    }

    // ---- VACUUM ----
    /// VACUUM: merge pending-free pages into the active freelist, then flush.
    /// Reclaims storage space by making deleted / overflow pages available for reuse.
    /// In multi-file mode, applies to every open pager.
    /// Enhanced: defragments leaf pages and collects fragmentation statistics.
    pub(crate) fn exec_vacuum(&mut self) -> Result<ExecResult> {
        let mut report = Vec::new();
        let mut total_defragged = 0u64;
        let mut total_leaves = 0u64;
        let mut total_frag_bytes = 0u64;
        let mut total_overflow = 0u64;

        // Defragment each table's B-Tree
        let table_names: Vec<String> = self.schema.list_tables();
        for name in &table_names {
            let root_page = {
                let ts = self.schema.get_table(name)?;
                if ts.view_select.is_some() {
                    continue; // Skip views
                }
                ts.root_page
            };

            let tbl_pager = self.get_table_pager_mut(name);
            let mut btree = BTree::new(tbl_pager);

            // Collect pre-defrag stats
            let (leaves, frag, overflow, free) = btree.fragmentation_stats(root_page)?;
            total_leaves += leaves;
            total_frag_bytes += frag;
            total_overflow += overflow;

            // Defragment leaf pages
            let defragged = btree.defragment_all(root_page)?;
            total_defragged += defragged;

            if defragged > 0 || frag > 0 || overflow > 0 {
                report.push(format!(
                    "  {} : {} leaves, {} frag bytes reclaimed, {} overflow pages, {} free bytes",
                    name, leaves, frag, overflow, free
                ));
            }
        }

        // Flush all pagers
        self.pager.flush()?;
        for pager in self.table_pagers.values_mut() {
            pager.flush()?;
        }

        let msg = if report.is_empty() {
            format!(
                "VACUUM completed: {} tables, {} leaves scanned, no fragmentation found",
                table_names.len(),
                total_leaves,
            )
        } else {
            format!(
                "VACUUM completed: {} pages defragmented, {} frag bytes reclaimed, {} overflow pages\n{}",
                total_defragged,
                total_frag_bytes,
                total_overflow,
                report.join("\n"),
            )
        };

        Ok(ExecResult::Ok { message: msg })
    }

    /// O1: ANALYZE TABLE — scan table data and compute per-column statistics.
    pub(crate) fn exec_analyze_table(&mut self, table_name: String) -> Result<ExecResult> {
        use crate::schema::{ColumnStats, HistogramBucket};
        use crate::types::Value;
        use std::collections::HashSet;

        let root_page = self.schema.get_table(&table_name)?.root_page;
        let col_count = self.schema.get_table(&table_name)?.columns.len();

        // Scan all rows
        let tbl_pager = self.get_table_pager_mut(&table_name);
        let mut btree = crate::storage::btree::BTree::new(tbl_pager);
        let all_rows = btree.scan_all(root_page)?;

        // Per-column accumulators
        let total_count = all_rows.len() as i64;
        let mut null_counts = vec![0i64; col_count];
        let mut mins: Vec<Option<Value>> = vec![None; col_count];
        let mut maxs: Vec<Option<Value>> = vec![None; col_count];
        let mut ndvs: Vec<HashSet<String>> = (0..col_count).map(|_| HashSet::new()).collect();
        // Collect non-null values per column for histogram construction
        let mut col_values: Vec<Vec<Value>> = (0..col_count).map(|_| Vec::new()).collect();

        for (_rowid, row) in &all_rows {
            for (ci, val) in row.iter().enumerate() {
                if ci >= col_count {
                    break;
                }
                match val {
                    Value::Null => {
                        null_counts[ci] += 1;
                    }
                    v => {
                        // Track NDV via string repr (fast enough for ANALYZE)
                        ndvs[ci].insert(format!("{:?}", v));
                        col_values[ci].push(v.clone());

                        // Min tracking
                        if mins[ci].is_none() {
                            mins[ci] = Some(v.clone());
                        } else if let Some(ref cur_min) = mins[ci].clone() {
                            if val_lt(v, cur_min) {
                                mins[ci] = Some(v.clone());
                            }
                        }

                        // Max tracking
                        if maxs[ci].is_none() {
                            maxs[ci] = Some(v.clone());
                        } else if let Some(ref cur_max) = maxs[ci].clone() {
                            if val_lt(cur_max, v) {
                                maxs[ci] = Some(v.clone());
                            }
                        }
                    }
                }
            }
        }

        // Write stats back to schema
        let tbl = self.schema.get_table_mut(&table_name)?;
        for ci in 0..col_count {
            if let Some(col) = tbl.columns.get_mut(ci) {
                // Build equi-depth histogram (up to 64 buckets)
                let histogram = Self::build_histogram(&mut col_values[ci], 64);
                col.stats = Some(ColumnStats {
                    total_count,
                    null_count: null_counts[ci],
                    ndv: ndvs[ci].len() as i64,
                    min: mins[ci].clone(),
                    max: maxs[ci].clone(),
                    histogram,
                });
            }
        }

        Ok(ExecResult::Ok {
            message: format!(
                "ANALYZE TABLE {} complete: {} rows, {} columns",
                table_name, total_count, col_count
            ),
        })
    }

    /// O2: Build equi-depth histogram from a list of non-null values.
    /// Returns `None` if fewer than 2 values, otherwise up to `max_buckets` buckets.
    fn build_histogram(
        values: &mut Vec<crate::types::Value>,
        max_buckets: usize,
    ) -> Option<Vec<crate::schema::HistogramBucket>> {
        use crate::schema::HistogramBucket;

        if values.len() < 2 {
            return None;
        }

        // Sort values (Integer < Float < Text < Blob)
        values.sort_by(|a, b| val_cmp(a, b));

        let n = values.len();
        let num_buckets = max_buckets.min(n);
        let bucket_size = n / num_buckets;
        let remainder = n % num_buckets;

        let mut buckets = Vec::with_capacity(num_buckets);
        let mut pos = 0;
        let mut cumulative = 0i64;

        for bi in 0..num_buckets {
            let this_size = bucket_size + if bi < remainder { 1 } else { 0 };
            let end = pos + this_size;
            cumulative += this_size as i64;

            // Count distinct values in this bucket
            let mut distinct = std::collections::HashSet::new();
            for v in &values[pos..end] {
                distinct.insert(format!("{:?}", v));
            }

            buckets.push(HistogramBucket {
                upper_bound: values[end - 1].clone(),
                cumulative_count: cumulative,
                ndv_in_bucket: distinct.len() as i64,
            });
            pos = end;
        }

        Some(buckets)
    }

    /// L3: CREATE TRIGGER — persist trigger definition and register in memory schema
    pub(crate) fn exec_create_trigger(&mut self, trig: &CreateTriggerStmt) -> Result<ExecResult> {
        use crate::schema::TriggerSchema;
        let trig_name_lower = trig.name.to_lowercase();
        // Check if trigger already exists
        let exists = self
            .schema
            .triggers
            .values()
            .any(|v| v.iter().any(|t| t.name.to_lowercase() == trig_name_lower));
        if exists {
            if trig.or_replace {
                // drop existing first
                self.schema
                    .drop_trigger_by_name(&mut self.pager, &trig.name, true)?;
            } else {
                return Err(crate::error::KkdbError::RuntimeError(format!(
                    "trigger '{}' already exists",
                    trig.name
                )));
            }
        }
        // Verify the table exists
        let _ = self.schema.get_table(&trig.table_name)?;
        let schema_trigger = TriggerSchema {
            name: trig.name.clone(),
            timing: trig.timing.clone(),
            event: trig.event.clone(),
            table_name: trig.table_name.clone(),
            body_sql: trig.body_sql.clone(),
            rowid: 0, // will be assigned in save_trigger
        };
        self.schema.save_trigger(&mut self.pager, schema_trigger)?;
        Ok(ExecResult::Ok {
            message: format!("TRIGGER {} created", trig.name),
        })
    }

    /// L3: DROP TRIGGER [IF EXISTS] name
    pub(crate) fn exec_drop_trigger(&mut self, name: &str, if_exists: bool) -> Result<ExecResult> {
        self.schema
            .drop_trigger_by_name(&mut self.pager, name, if_exists)?;
        Ok(ExecResult::Ok {
            message: format!("TRIGGER {} dropped", name),
        })
    }

    // ---- USER MANAGEMENT ----
    pub(crate) fn exec_create_user(&mut self, stmt: &CreateUserStmt) -> Result<ExecResult> {
        // S-NEW-1 fix: use parameterized insert to avoid SQL injection
        use crate::sql::ast::{ConflictPolicy, Expr, InsertSource, InsertStmt};
        let pw_hash = stmt.password.as_deref().unwrap_or("").to_string();
        let insert = InsertStmt {
            table_name: "kkdb_users".to_string(),
            columns: Some(vec!["username".to_string(), "password_hash".to_string()]),
            source: InsertSource::Values(vec![vec![
                Expr::StringLiteral(stmt.username.clone()),
                Expr::StringLiteral(pw_hash),
            ]]),
            conflict: ConflictPolicy::Error,
            returning: None,
        };
        self.exec_insert(&insert)?;
        Ok(ExecResult::Ok {
            message: format!("User '{}' created", stmt.username),
        })
    }

    pub(crate) fn exec_alter_user(&mut self, stmt: &AlterUserStmt) -> Result<ExecResult> {
        if let Some(ref pw) = stmt.password {
            // S-NEW-1 fix: use parameterized update to avoid SQL injection
            use crate::sql::ast::BinaryOperator;
            use crate::sql::ast::{Expr, UpdateStmt};
            let update = UpdateStmt {
                table_name: "kkdb_users".to_string(),
                assignments: vec![(
                    "password_hash".to_string(),
                    Expr::StringLiteral(pw.clone()),
                )],
                where_clause: Some(Expr::BinaryOp {
                    left: Box::new(Expr::ColumnRef {
                        table: None,
                        column: "username".to_string(),
                    }),
                    op: BinaryOperator::Equal,
                    right: Box::new(Expr::StringLiteral(stmt.username.clone())),
                }),
                returning: None,
            };
            self.exec_update(&update)?;
        }
        Ok(ExecResult::Ok {
            message: format!("User '{}' altered", stmt.username),
        })
    }

    pub(crate) fn exec_drop_user(&mut self, stmt: &DropUserStmt) -> Result<ExecResult> {
        // S-NEW-1 fix: use parameterized delete for each username
        use crate::sql::ast::{BinaryOperator, DeleteStmt, Expr};
        for username in &stmt.usernames {
            let where_clause = Expr::BinaryOp {
                left: Box::new(Expr::ColumnRef {
                    table: None,
                    column: "username".to_string(),
                }),
                op: BinaryOperator::Equal,
                right: Box::new(Expr::StringLiteral(username.clone())),
            };
            let del_user = DeleteStmt {
                table_name: "kkdb_users".to_string(),
                where_clause: Some(where_clause.clone()),
                returning: None,
            };
            let _ = self.exec_delete(&del_user);
            let del_privs = DeleteStmt {
                table_name: "kkdb_privileges".to_string(),
                where_clause: Some(Expr::BinaryOp {
                    left: Box::new(Expr::ColumnRef {
                        table: None,
                        column: "username".to_string(),
                    }),
                    op: BinaryOperator::Equal,
                    right: Box::new(Expr::StringLiteral(username.clone())),
                }),
                returning: None,
            };
            let _ = self.exec_delete(&del_privs);
        }
        Ok(ExecResult::Ok {
            message: "Dropped user(s)".to_string(),
        })
    }

    pub(crate) fn exec_grant(&mut self, stmt: &GrantStmt) -> Result<ExecResult> {
        let privs = match &stmt.privileges {
            PrivilegeList::All => vec!["ALL".to_string()],
            PrivilegeList::Specific(list) => list.clone(),
        };
        let obj_str = match &stmt.object {
            GrantObject::Table(t) => t.clone(),
            GrantObject::Database(d) => d.clone(),
            GrantObject::Global => "GLOBAL".to_string(),
        };

        for grantee in &stmt.grantees {
            for priv_type in &privs {
                let sql = format!(
                    "INSERT INTO kkdb_privileges (username, obj_name, priv_type) VALUES ('{}', '{}', '{}')",
                    grantee, obj_str, priv_type
                );
                self.execute_sql(&sql)?;
            }
        }
        Ok(ExecResult::Ok {
            message: "Privileges granted".into(),
        })
    }

    pub(crate) fn exec_revoke(&mut self, stmt: &RevokeStmt) -> Result<ExecResult> {
        let privs = match &stmt.privileges {
            PrivilegeList::All => vec!["ALL".to_string()],
            PrivilegeList::Specific(list) => list.clone(),
        };
        let obj_str = match &stmt.object {
            GrantObject::Table(t) => t.clone(),
            GrantObject::Database(d) => d.clone(),
            GrantObject::Global => "GLOBAL".to_string(),
        };

        for grantee in &stmt.grantees {
            for priv_type in &privs {
                let sql = format!(
                    "DELETE FROM kkdb_privileges WHERE username = '{}' AND obj_name = '{}' AND priv_type = '{}'",
                    grantee, obj_str, priv_type
                );
                self.execute_sql(&sql)?;
            }
        }
        Ok(ExecResult::Ok {
            message: "Privileges revoked".into(),
        })
    }

    // ---- RLS POLICIES ----
    pub(crate) fn exec_create_policy(&mut self, stmt: &CreatePolicyStmt) -> Result<ExecResult> {
        let tbl_key = stmt.table_name.to_ascii_lowercase();
        let tbl = self.schema.tables.get_mut(&tbl_key).ok_or_else(|| {
            crate::error::KkdbError::RuntimeError(format!("table '{}' not found", stmt.table_name))
        })?;

        // Remove existing policy with same name if any
        tbl.policies.retain(|p| p.name != stmt.name);
        tbl.policies.push(crate::schema::PolicySchema {
            name: stmt.name.clone(),
            role: stmt.role.clone(),
            using_expr: stmt.using_expr.clone(),
            check_expr: stmt.check_expr.clone(),
        });

        Ok(ExecResult::Ok {
            message: format!("POLICY '{}' on '{}' created", stmt.name, stmt.table_name),
        })
    }

    pub(crate) fn exec_drop_policy(&mut self, stmt: &DropPolicyStmt) -> Result<ExecResult> {
        let tbl_key = stmt.table_name.to_ascii_lowercase();
        let tbl = self.schema.tables.get_mut(&tbl_key).ok_or_else(|| {
            crate::error::KkdbError::RuntimeError(format!("table '{}' not found", stmt.table_name))
        })?;

        let before = tbl.policies.len();
        tbl.policies.retain(|p| p.name != stmt.name);
        if tbl.policies.len() == before && !stmt.if_exists {
            return Err(crate::error::KkdbError::RuntimeError(format!(
                "policy '{}' not found on '{}'",
                stmt.name, stmt.table_name
            )));
        }

        Ok(ExecResult::Ok {
            message: format!("POLICY '{}' on '{}' dropped", stmt.name, stmt.table_name),
        })
    }

    /// Write FTS postings directly to the given BTree root page (no execute_sql, no schema table).
    /// Row format: (token TEXT, doc_id INTEGER, tf INTEGER, field_len INTEGER, meta_key TEXT)
    ///  - posting: meta_key = Null
    ///  - doc-freq: meta_key = "DF"
    ///  - global stats: meta_key = "GLOBAL"
    pub(crate) fn write_fts_postings_raw(
        &mut self,
        fts_root: u32,
        postings: &std::collections::HashMap<String, std::collections::HashMap<u64, (u32, u32)>>,
        doc_freq: &std::collections::HashMap<String, u64>,
        total_docs: u64,
        total_field_len: u64,
    ) -> Result<()> {
        use crate::types::Value;
        // Get next rowid from in-memory sequence (atomic, race-free even across pagers).
        // Re-seed from btree if our cached value would collide with existing rows
        // (e.g., after CREATE FULLTEXT INDEX wrote rows before any DML).
        let actual_max = {
            let mut btree = BTree::new(&mut self.pager);
            btree.max_rowid(fts_root).unwrap_or(0)
        };
        let mut next_rowid = {
            let seq = self
                .fts_rowid_sequences
                .entry(fts_root)
                .or_insert(actual_max + 1);
            // If the cached value is stale (behind actual max), re-sync it.
            if *seq <= actual_max {
                *seq = actual_max + 1;
            }
            *seq
        };
        let mut current_root = fts_root;

        // Write posting entries
        for (token, row_map) in postings {
            for (&doc_id, &(tf, field_len)) in row_map {
                let row = vec![
                    Value::Text(token.as_str().into()),
                    Value::Integer(doc_id as i64),
                    Value::Integer(tf as i64),
                    Value::Integer(field_len as i64),
                    Value::Null,
                ];
                let mut btree = BTree::new(&mut self.pager);
                current_root = btree.insert(current_root, next_rowid, &row)?;
                next_rowid += 1;
            }
        }

        // Write DF entries
        for (token, &df) in doc_freq {
            let row = vec![
                Value::Text(token.as_str().into()),
                Value::Integer(df as i64),
                Value::Integer(0),
                Value::Integer(0),
                Value::Text("DF".into()),
            ];
            let mut btree = BTree::new(&mut self.pager);
            current_root = btree.insert(current_root, next_rowid, &row)?;
            next_rowid += 1;
        }

        // Write GLOBAL stats row (total_docs in col1, total_field_len in col2)
        let global_row = vec![
            Value::Text("_GLOBAL".into()),
            Value::Integer(total_docs as i64),
            Value::Integer(total_field_len as i64),
            Value::Integer(0),
            Value::Text("GLOBAL".into()),
        ];
        let mut btree = BTree::new(&mut self.pager);
        let final_root = btree.insert(current_root, next_rowid, &global_row)?;

        // If root changed (tree split), update schema
        if final_root != fts_root {
            // Update the root_page in IndexSchema for this FTS index
            for idx in self.schema.indexes.values_mut() {
                if idx.is_fts && idx.root_page == fts_root {
                    idx.root_page = final_root;
                    break;
                }
            }
            // Reset sequence so it will be reseeded on next open (avoids stale key)
            self.fts_rowid_sequences.remove(&fts_root);
            self.fts_rowid_sequences.insert(final_root, next_rowid + 1);
        } else {
            // Persist the incremented counter for this fts_root
            self.fts_rowid_sequences.insert(fts_root, next_rowid + 1);
        }
        Ok(())
    }

    /// Convenience wrapper that finds the fts_root from the schema for a given index_id.
    /// Here index_id IS the fts_root (stored in IndexSchema.root_page).
    pub(crate) fn write_fts_postings(
        &mut self,
        fts_root: u32,
        postings: &std::collections::HashMap<String, std::collections::HashMap<u64, (u32, u32)>>,
        doc_freq: &std::collections::HashMap<String, u64>,
        total_docs: u64,
        total_field_len: u64,
    ) -> Result<()> {
        self.write_fts_postings_raw(fts_root, postings, doc_freq, total_docs, total_field_len)
    }

    /// Drain the pending FTS inserts collected during the last statement execution.
    /// Called at the end of execute_sql to avoid reentrant execute_sql during DML.
    pub(crate) fn drain_pending_fts_inserts(&mut self) {
        if self.pending_fts_inserts.is_empty() {
            return;
        }
        let pending = std::mem::take(&mut self.pending_fts_inserts);

        for (stale_fts_root, doc_id, tfs, field_len) in pending {
            if stale_fts_root == 0 {
                continue;
            }

            // Re-read the CURRENT root_page from schema in case a previous write split
            // the B-Tree and updated the root (the queued value may now be stale).
            let fts_root = self
                .schema
                .indexes
                .values()
                .find(|idx| {
                    idx.is_fts
                        && (idx.root_page == stale_fts_root || {
                            // After a split the old root may no longer match; fall back to
                            // locating the FTS index whose columns cover the same pages.
                            // For now we trust that root_page==stale means no split yet;
                            // if not found, keep using stale_fts_root (best effort).
                            false
                        })
                })
                .map(|idx| idx.root_page)
                .unwrap_or(stale_fts_root);

            let (cur_docs, cur_field_len) = self.read_fts_global_stats(fts_root);
            let new_total_docs = cur_docs + 1;
            let new_total_field_len = cur_field_len + field_len as u64;

            let mut postings: std::collections::HashMap<
                String,
                std::collections::HashMap<u64, (u32, u32)>,
            > = std::collections::HashMap::new();
            let mut doc_freq: std::collections::HashMap<String, u64> =
                std::collections::HashMap::new();

            for (token, tf) in tfs {
                postings
                    .entry(token.clone())
                    .or_default()
                    .insert(doc_id as u64, (tf, field_len));
                let existing_df = self.get_fts_doc_freq(fts_root, &token);
                doc_freq.insert(token, existing_df + 1);
            }

            let _ = self.write_fts_postings_raw(
                fts_root,
                &postings,
                &doc_freq,
                new_total_docs,
                new_total_field_len,
            );
        }
    }

    /// Read global FTS stats (total_docs, total_field_len) directly from BTree.
    /// fts_root is the IndexSchema.root_page for the FTS index.
    /// Returns the stats from the LAST GLOBAL row found (most recent).
    pub(crate) fn read_fts_global_stats(&mut self, fts_root: u32) -> (u64, u64) {
        use crate::types::Value;
        if fts_root == 0 {
            return (0, 0);
        }
        let mut btree = BTree::new(&mut self.pager);
        let rows = btree.scan_rows(fts_root).unwrap_or_default();
        let mut result = (0u64, 0u64);
        for row in &rows {
            if row.get(4) == Some(&Value::Text("GLOBAL".into())) {
                let total_docs = if let Some(Value::Integer(v)) = row.get(1) {
                    *v as u64
                } else {
                    0
                };
                let total_field_len = if let Some(Value::Integer(v)) = row.get(2) {
                    *v as u64
                } else {
                    0
                };
                result = (total_docs, total_field_len); // take latest (last) GLOBAL row
            }
        }
        result
    }

    /// Scan all posting entries for a given token in the FTS index (direct BTree).
    pub(crate) fn scan_fts_postings(&mut self, fts_root: u32, token: &str) -> Vec<(u64, u32, u32)> {
        use crate::types::Value;
        if fts_root == 0 {
            return Vec::new();
        }
        let mut btree = BTree::new(&mut self.pager);
        let rows = btree.scan_rows(fts_root).unwrap_or_default();
        rows.into_iter()
            .filter_map(|row| {
                if row.get(4) != Some(&Value::Null) {
                    return None;
                }
                let row_token = if let Some(Value::Text(s)) = row.first() {
                    s.to_string()
                } else {
                    return None;
                };
                if row_token != token {
                    return None;
                }
                let doc_id = if let Some(Value::Integer(v)) = row.get(1) {
                    *v as u64
                } else {
                    return None;
                };
                let tf = if let Some(Value::Integer(v)) = row.get(2) {
                    *v as u32
                } else {
                    0
                };
                let fl = if let Some(Value::Integer(v)) = row.get(3) {
                    *v as u32
                } else {
                    0
                };
                Some((doc_id, tf, fl))
            })
            .collect()
    }

    /// Get doc_freq for a token directly from BTree.
    pub(crate) fn get_fts_doc_freq(&mut self, fts_root: u32, token: &str) -> u64 {
        use crate::types::Value;
        if fts_root == 0 {
            return 0;
        }
        let mut btree = BTree::new(&mut self.pager);
        let rows = btree.scan_rows(fts_root).unwrap_or_default();
        for row in &rows {
            if row.get(4) == Some(&Value::Text("DF".into())) {
                if let Some(Value::Text(t)) = row.first() {
                    if t.as_ref() == token {
                        return if let Some(Value::Integer(v)) = row.get(1) {
                            *v as u64
                        } else {
                            0
                        };
                    }
                }
            }
        }
        0
    }
}

fn val_lt(a: &crate::types::Value, b: &crate::types::Value) -> bool {
    use crate::types::Value;
    match (a, b) {
        (Value::Integer(x), Value::Integer(y)) => x < y,
        (Value::Real(x), Value::Real(y)) => x < y,
        (Value::Integer(x), Value::Real(y)) => (*x as f64) < *y,
        (Value::Real(x), Value::Integer(y)) => *x < (*y as f64),
        (Value::Text(x), Value::Text(y)) => x < y,
        _ => false,
    }
}

/// O2: Total ordering for sorting values (used by histogram builder).
fn val_cmp(a: &crate::types::Value, b: &crate::types::Value) -> std::cmp::Ordering {
    use crate::types::Value;
    match (a, b) {
        (Value::Null, Value::Null) => std::cmp::Ordering::Equal,
        (Value::Null, _) => std::cmp::Ordering::Less,
        (_, Value::Null) => std::cmp::Ordering::Greater,
        (Value::Integer(x), Value::Integer(y)) => x.cmp(y),
        (Value::Real(x), Value::Real(y)) => x.partial_cmp(y).unwrap_or(std::cmp::Ordering::Equal),
        (Value::Integer(x), Value::Real(y)) => (*x as f64)
            .partial_cmp(y)
            .unwrap_or(std::cmp::Ordering::Equal),
        (Value::Real(x), Value::Integer(y)) => x
            .partial_cmp(&(*y as f64))
            .unwrap_or(std::cmp::Ordering::Equal),
        (Value::Text(x), Value::Text(y)) => x.cmp(y),
        (Value::Blob(x), Value::Blob(y)) => x.cmp(y),
        // Type ordering: Integer/Real < Text < Blob
        (Value::Integer(_) | Value::Real(_), _) => std::cmp::Ordering::Less,
        (_, Value::Integer(_) | Value::Real(_)) => std::cmp::Ordering::Greater,
        (Value::Text(_), _) => std::cmp::Ordering::Less,
        (_, Value::Text(_)) => std::cmp::Ordering::Greater,
    }
}

impl VM {
    /// SHOW ENGINE STATUS — InnoDB-style status report.
    pub(crate) fn exec_show_engine_status(&self) -> Result<ExecResult> {
        let cfg = &self.pager.engine_config;
        let mut lines: Vec<String> = Vec::new();

        lines.push("===== InnoDB Engine Status =====".to_string());
        lines.push(String::new());

        // Buffer pool
        let bp = self.pager.buffer_pool_stats();
        lines.push(format!(
            "Buffer pool pages  : {} ({})",
            bp.max_pages,
            if bp.max_pages == 0 { "unlimited" } else { "limited" }
        ));
        lines.push(format!(
            "Buffer pool usage  : {} loaded, {} dirty, {} clean",
            bp.loaded_pages, bp.dirty_pages, bp.clean_pages
        ));
        lines.push(format!(
            "Buffer pool hit%   : {:.1}%",
            bp.hit_rate_approx * 100.0
        ));
        lines.push(format!(
            "LRU queue length   : {}",
            bp.lru_queue_len
        ));

        // WAL
        lines.push(format!("WAL enabled        : {}", self.pager.is_wal_enabled()));
        lines.push(format!("WAL auto-checkpoint: {} frames", cfg.wal_auto_checkpoint));
        if let Some(ref wal) = self.pager.wal {
            lines.push(format!(
                "WAL committed      : {} frames",
                wal.committed_frame_count()
            ));
            lines.push(format!(
                "WAL uncommitted    : {} frames",
                wal.uncommitted_frame_count()
            ));
            lines.push(format!("WAL sync mode      : {:?}", wal.sync_mode()));
            let ws = wal.wal_stats();
            lines.push(format!("WAL total commits  : {}", ws.total_commits));
            lines.push(format!("WAL total fsyncs   : {}", ws.total_fsyncs));
            lines.push(format!("WAL group syncs    : {}", ws.group_syncs));
            lines.push(format!("WAL frames written : {}", ws.total_frames_written));
            if ws.pending_sync_commits > 0 {
                lines.push(format!("WAL pending sync   : {} commits", ws.pending_sync_commits));
            }
        }
        lines.push(format!("Current LSN        : {}", self.pager.current_lsn()));

        // Compression
        lines.push(format!("LZ4 compression    : {}", cfg.use_lz4));

        // Flush method
        lines.push(format!("Flush method       : {:?}", cfg.flush_method));

        // Pages (from header)
        lines.push(format!("Total pages        : {}", self.pager.header.total_pages));

        // MVCC status
        lines.push(String::new());
        lines.push("--- MVCC ---".to_string());
        lines.push(format!("Current txn ID     : {}", self.current_txn_id));
        lines.push(format!("Next txn ID        : {}", self.txn_registry.next_id()));
        lines.push(format!("Active transactions: {}", self.txn_registry.active_count()));
        // Snapshot status
        if let Some(ref snap) = self.mvcc_snapshot {
            lines.push(format!("Snapshot reader    : txn {}", snap.reader_txn_id));
            lines.push(format!("Snapshot max commit: {}", snap.max_committed_txn_id));
            lines.push(format!("Snapshot active    : {:?}", snap.active_txn_ids));
        } else {
            lines.push("Snapshot           : none (autocommit)".to_string());
        }
        let undo_stats = self.mvcc_undo_log.stats();
        lines.push(format!("Undo log entries   : {}", undo_stats.total_entries));
        lines.push(format!("Undo log size      : {} bytes", undo_stats.size_bytes));
        lines.push(format!(
            "Undo breakdown     : {} inserts, {} updates, {} deletes, {} savepoints",
            undo_stats.inserts, undo_stats.updates, undo_stats.deletes, undo_stats.savepoints
        ));

        // Query Cache
        lines.push(String::new());
        lines.push("--- Query Cache ---".to_string());
        lines.push(format!("Cache enabled      : {}", self.query_cache.is_enabled()));
        lines.push(format!("Cache entries      : {} / {}", self.query_cache.len(), self.query_cache.max_entries()));
        lines.push(format!("Cache lookups      : {}", self.query_cache.stat_lookups));
        lines.push(format!("Cache hits         : {}", self.query_cache.stat_hits));
        lines.push(format!("Cache misses       : {}", self.query_cache.stat_misses));
        lines.push(format!("Cache hit rate     : {:.1}%", self.query_cache.hit_rate()));
        lines.push(format!("Cache invalidations: {}", self.query_cache.stat_invalidations));
        lines.push(format!("Cache evictions    : {}", self.query_cache.stat_evictions));

        // Clustered index info
        lines.push(String::new());
        lines.push("--- Clustered Index ---".to_string());
        let tables = self.schema.list_tables();
        let clustered_count = tables.iter().filter(|t| {
            self.schema.get_table(t).map(|s| s.clustered_index).unwrap_or(false)
        }).count();
        lines.push(format!("Tables (clustered) : {} / {}", clustered_count, tables.len()));
        let pk_clustered = tables.iter().filter(|t| {
            self.schema.get_table(t).map(|s| s.pk_is_integer_clustered()).unwrap_or(false)
        }).count();
        lines.push(format!("PK integer cluster : {} tables", pk_clustered));

        // Per-table pagers
        if !self.table_pagers.is_empty() {
            lines.push(String::new());
            lines.push(format!("--- Per-Table Pagers ({}) ---", self.table_pagers.len()));
            for (name, tp) in &self.table_pagers {
                let wal_str = if tp.is_wal_enabled() { "WAL" } else { "direct" };
                lines.push(format!(
                    "  {} : {} pages, mode={}, lsn={}",
                    name,
                    tp.header.total_pages,
                    wal_str,
                    tp.current_lsn()
                ));
            }
        }

        lines.push(String::new());
        lines.push("================================".to_string());

        Ok(ExecResult::Explain {
            plan: lines.join("\n"),
        })
    }
}

//! DML statement execution for KKDB.
//!
//! This module implements `INSERT`, `UPDATE`, and `DELETE` operations, including:
//!
//! - **INSERT** — column alignment, rowid assignment, `AUTOINCREMENT`,
//!   `ON CONFLICT DO NOTHING / REPLACE / UPDATE SET`, `RETURNING` clause,
//!   trigger firing (BEFORE / AFTER), constraint checking (NOT NULL, CHECK, FK,
//!   UNIQUE), FTS index maintenance, and binlog appending.
//! - **UPDATE** — index-accelerated lookup for simple `WHERE col = value` predicates,
//!   full-scan fallback, constraint re-validation, FTS and secondary index delta,
//!   MVCC undo entry recording, FK cascade (ON UPDATE), and `RETURNING`.
//! - **DELETE** — index-accelerated or full-scan row collection, FK restrict check
//!   (ON DELETE RESTRICT), FTS and secondary index cleanup, and `RETURNING`.
//!
//! ## Constraint checking order (INSERT)
//!
//! ```text
//! BEFORE trigger → NOT NULL → FK child-side → CHECK → UNIQUE → insert row
//! → update FTS / secondary indexes → add to binlog → add undo entry → AFTER trigger
//! ```
//!
//! ## MVCC / rollback
//!
//! Within an explicit `BEGIN` transaction each DML operation appends an entry to
//! [`VM::mvcc_undo_log`].  On `ROLLBACK` the COW pager physically reverts pages;
//! the undo log is preserved for potential non-COW future backends.

use super::execute::{ExecResult, VM};
use crate::error::{KkdbError, Result};
use crate::sql::ast::*;
use crate::storage::btree::BTree;
use crate::types::{Row, Value};
use std::collections::{HashMap, HashSet};

impl VM {
    // ---- INSERT ----

    /// Fast programmatic bulk insert bypassing SQL parsing/AST
    pub fn insert_batch_raw(
        &mut self,
        table_name: &str,
        value_rows: Vec<Vec<Value>>,
    ) -> Result<ExecResult> {
        let insert = InsertStmt {
            table_name: table_name.to_string(),
            columns: None,
            source: InsertSource::Values(vec![]),
            conflict: ConflictPolicy::Error,
            returning: None,
        };

        let need_auto_txn = !self.pager.in_transaction();
        if need_auto_txn {
            self.pager.begin_transaction()?;
            self.schema_snapshot = Some(self.schema.clone());
        }

        let result = self.insert_value_rows(&insert, value_rows);

        if need_auto_txn {
            match result {
                Ok(r) => {
                    // B12-6 fix: if commit fails, rollback and return error
                    match self.pager.commit_transaction() {
                        Ok(()) => {
                            self.schema_snapshot = None;
                            return Ok(r);
                        }
                        Err(e) => {
                            let _ = self.pager.rollback_transaction();
                            if let Some(snap) = self.schema_snapshot.take() {
                                self.schema = snap;
                            }
                            self.clear_index_caches();
                            return Err(e);
                        }
                    }
                }
                Err(e) => {
                    let _ = self.pager.rollback_transaction();
                    if let Some(snap) = self.schema_snapshot.take() {
                        self.schema = snap;
                    }
                    self.clear_index_caches();
                    return Err(e);
                }
            }
        }
        result
    }

    #[inline]
    pub(crate) fn exec_insert(&mut self, insert: &InsertStmt) -> Result<ExecResult> {
        // Resolve the rows to insert. For InsertSource::Select we materialize
        // all result rows first to avoid borrow-checker conflicts with &mut self.
        let value_rows: Vec<Vec<Value>> = match &insert.source {
            InsertSource::Values(expr_rows) => {
                let empty_row: Vec<Value> = Vec::new();
                let empty_col_map: HashMap<String, usize> = HashMap::new();
                let mut out = Vec::with_capacity(expr_rows.len());
                for expr_row in expr_rows {
                    let mut row = Vec::with_capacity(expr_row.len());
                    for expr in expr_row {
                        row.push(self.eval_expr(expr, &empty_row, &empty_col_map)?);
                    }
                    out.push(row);
                }
                out
            }
            InsertSource::Select(query) => {
                // Clone the query to release borrow on `insert` before calling exec_select.
                let query = query.as_ref().clone();
                match self.exec_select(&query)? {
                    ExecResult::QueryResult { rows, .. } => rows,
                    _ => {
                        return Err(crate::error::KkdbError::Internal(
                            "INSERT SELECT: exec_select did not return rows".into(),
                        ))
                    }
                }
            }
        };

        // Wrap in implicit transaction if not already in one (atomicity guarantee).
        let need_auto_txn = !self.pager.in_transaction();
        if need_auto_txn {
            self.pager.begin_transaction()?;
            self.schema_snapshot = Some(self.schema.clone());
        }

        let result = self.insert_value_rows(insert, value_rows);

        if need_auto_txn {
            match result {
                Ok(r) => {
                    // B12-6 fix: if commit fails, rollback and return error
                    match self.pager.commit_transaction() {
                        Ok(()) => {
                            self.schema_snapshot = None;
                            return Ok(r);
                        }
                        Err(e) => {
                            let _ = self.pager.rollback_transaction();
                            for tbl_pager in self.table_pagers.values_mut() {
                                if tbl_pager.in_transaction() {
                                    let _ = tbl_pager.rollback_transaction();
                                }
                            }
                            if let Some(snap) = self.schema_snapshot.take() {
                                self.schema = snap;
                            }
                            self.clear_index_caches();
                            return Err(e);
                        }
                    }
                }
                Err(e) => {
                    let _ = self.pager.rollback_transaction();
                    if let Some(snap) = self.schema_snapshot.take() {
                        self.schema = snap;
                    }
                    self.clear_index_caches();
                    return Err(e);
                }
            }
        }
        result
    }

    /// Inner loop: inserts already-evaluated rows into the target table.
    fn insert_value_rows(
        &mut self,
        insert: &InsertStmt,
        value_rows: Vec<Vec<Value>>,
    ) -> Result<ExecResult> {
        let (col_count, col_indices, pk_col_idx, not_null_cols, table_name_owned, original_root);
        let mut root_page;
        let mut next_rowid;
        {
            let table = self.schema.get_table(&insert.table_name)?;
            col_count = table.columns.len();
            table_name_owned = table.name.clone();
            root_page = table.root_page;
            original_root = table.root_page;
            next_rowid = table.next_rowid;

            col_indices = if let Some(ref cols) = insert.columns {
                cols.iter()
                    .map(|c| {
                        table
                            .columns
                            .iter()
                            .position(|tc| tc.name.eq_ignore_ascii_case(c))
                            .ok_or_else(|| KkdbError::ColumnNotFound(c.clone()))
                    })
                    .collect::<Result<Vec<_>>>()?
            } else {
                (0..col_count).collect()
            };

            pk_col_idx = table
                .columns
                .iter()
                .find(|c| c.primary_key)
                .map(|c| c.col_index);

            not_null_cols = table
                .columns
                .iter()
                .filter(|c| c.not_null && !c.primary_key)
                .map(|c| (c.col_index, c.name.clone()))
                .collect::<Vec<_>>();
        }

        let mut rows_inserted = 0;
        // Tracks rows that were successfully inserted, used for RETURNING evaluation
        let mut inserted_rows_for_returning: Vec<Row> = Vec::new();
        let mut serialize_buf: Vec<u8> = Vec::new();
        let mut row = vec![Value::Null; col_count];

        for value_row in &value_rows {
            if value_row.len() != col_indices.len() {
                return Err(KkdbError::ColumnCountMismatch {
                    expected: col_indices.len(),
                    got: value_row.len(),
                });
            }

            for v in row.iter_mut() {
                *v = Value::Null;
            }
            for (val_idx, &col_idx) in col_indices.iter().enumerate() {
                row[col_idx] = value_row[val_idx].clone();
            }

            let rowid = if let Some(pk_idx) = pk_col_idx {
                match &row[pk_idx] {
                    Value::Integer(v) => {
                        let rid = *v;
                        if rid >= next_rowid {
                            next_rowid = rid + 1;
                        }
                        rid
                    }
                    Value::Null => {
                        let rid = next_rowid;
                        row[pk_idx] = Value::Integer(rid);
                        next_rowid = rid + 1;
                        rid
                    }
                    _ => {
                        let rid = next_rowid;
                        next_rowid += 1;
                        rid
                    }
                }
            } else {
                let rid = next_rowid;
                next_rowid += 1;
                rid
            };

            // --- L3: BEFORE INSERT triggers ---
            self.fire_triggers(
                &insert.table_name,
                &crate::sql::ast::TriggerTiming::Before,
                &crate::sql::ast::TriggerEvent::Insert,
            )?;

            for (col_idx, col_name) in &not_null_cols {
                if matches!(row[*col_idx], Value::Null) {
                    return Err(KkdbError::ConstraintViolation(format!(
                        "NOT NULL constraint failed: {}.{}",
                        table_name_owned, col_name
                    )));
                }
            }

            // --- L1: Foreign Key constraint check (RESTRICT on insert) ---
            self.check_fk_on_insert(&insert.table_name, &row)?;

            // --- L2: CHECK constraint validation ---
            self.check_constraints_for_row(&insert.table_name, &row, &[])?;

            // --- Conflict resolution ---
            match &insert.conflict {
                ConflictPolicy::Error => {
                    self.validate_unique_indexes_for_row(&insert.table_name, rowid, &row, None)?;
                    let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                    let mut btree = BTree::new(tbl_pager);
                    let new_root =
                        btree.insert_with_buf(root_page, rowid, &row, &mut serialize_buf)?;
                    root_page = new_root;
                    self.insert_index_entries(&insert.table_name, rowid, &row)?;
                    // L4: Maintain FTS + vector indexes
                    self.maintain_fts_insert(&insert.table_name, rowid, &row)?;
                    self.maintain_vec_insert(&insert.table_name, rowid, &row)?;

                    // Add to binlog
                    let txid = self.pager.active_txid().unwrap_or(0);
                    let _ = self.binlog.append(&crate::binlog::LogRecord::Insert {
                        txid,
                        table_name: insert.table_name.clone(),
                        rowid,
                        row: row.clone(),
                    });

                    // C1: Record undo entry for ROLLBACK
                    if self.pager.in_transaction() && self.current_txn_id != 0 {
                        self.mvcc_undo_log.push(crate::vm::mvcc::UndoEntry::Insert {
                            table: insert.table_name.clone(),
                            rowid,
                            txn_id: self.current_txn_id,
                        });
                    }
                    // --- L3: AFTER INSERT triggers ---
                    self.fire_triggers(
                        &insert.table_name,
                        &crate::sql::ast::TriggerTiming::After,
                        &crate::sql::ast::TriggerEvent::Insert,
                    )?;
                    rows_inserted += 1;
                    inserted_rows_for_returning.push(row.clone());
                }
                ConflictPolicy::Ignore => {
                    // Check for conflicts; skip row on any constraint violation
                    let conflict = self
                        .validate_unique_indexes_for_row(&insert.table_name, rowid, &row, None)
                        .err()
                        .filter(|e| matches!(e, KkdbError::ConstraintViolation(_)));
                    // Also check if rowid already exists (PK conflict)
                    let pk_exists = if pk_col_idx.is_some() {
                        let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                        let mut btree = BTree::new(tbl_pager);
                        btree.find_by_rowid(root_page, rowid)?.is_some()
                    } else {
                        false
                    };
                    if conflict.is_none() && !pk_exists {
                        let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                        let mut btree = BTree::new(tbl_pager);
                        let new_root =
                            btree.insert_with_buf(root_page, rowid, &row, &mut serialize_buf)?;
                        root_page = new_root;
                        self.insert_index_entries(&insert.table_name, rowid, &row)?;

                        // Add to binlog
                        let txid = self.pager.active_txid().unwrap_or(0);
                        let _ = self.binlog.append(&crate::binlog::LogRecord::Insert {
                            txid,
                            table_name: insert.table_name.clone(),
                            rowid,
                            row: row.clone(),
                        });

                        // --- L3: AFTER INSERT triggers ---
                        self.fire_triggers(
                            &insert.table_name,
                            &crate::sql::ast::TriggerTiming::After,
                            &crate::sql::ast::TriggerEvent::Insert,
                        )?;
                        rows_inserted += 1;
                    }
                    // else: silently skip this row
                }
                ConflictPolicy::Replace => {
                    // ── Find any existing row whose PK *value* matches ──────────────
                    // We cannot rely on `find_by_rowid(rowid)` alone because the rowid
                    // is always an auto-incrementing integer, while the PRIMARY KEY may
                    // be TEXT or REAL.  So we must look up the old row by its PK *value*.
                    let existing_rowid_for_pk: Option<i64> = if let Some(pk_idx) = pk_col_idx {
                        let pk_val = row.get(pk_idx).cloned().unwrap_or(Value::Null);
                        // Fast path: integer PK → the b-tree rowid IS the PK value
                        if let Value::Integer(pk_int) = &pk_val {
                            let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                            let mut btree = BTree::new(tbl_pager);
                            if btree.find_by_rowid(root_page, *pk_int)?.is_some() {
                                Some(*pk_int)
                            } else {
                                None
                            }
                        } else {
                            // Slow path: non-integer PK (TEXT, REAL) → full scan to find
                            // the row whose PK column equals pk_val.
                            let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                            let mut btree = BTree::new(tbl_pager);
                            let all_rows = btree.scan_all(root_page)?;
                            all_rows.into_iter().find_map(|(rid, r)| {
                                if r.get(pk_idx) == Some(&pk_val) {
                                    Some(rid)
                                } else {
                                    None
                                }
                            })
                        }
                    } else {
                        None
                    };

                    if let Some(existing_rid) = existing_rowid_for_pk {
                        // B-NEW-5 fix: fetch old row before deletion so we can record undo entry
                        let old_row_for_undo = {
                            let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                            let mut btree = BTree::new(tbl_pager);
                            btree.find_by_rowid(root_page, existing_rid)?.map(|(_, r)| r)
                        };
                        self.maintain_fts_delete(&insert.table_name, existing_rid)?;
                        self.delete_index_entries(&insert.table_name, existing_rid)?;
                        let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                        let mut btree = BTree::new(tbl_pager);
                        let (_, new_root) = btree.delete_by_rowid(root_page, existing_rid)?;
                        root_page = new_root;
                        // Record undo entry for this deletion
                        if self.pager.in_transaction() && self.current_txn_id != 0 {
                            if let Some(old_row) = old_row_for_undo {
                                self.mvcc_undo_log.push(crate::vm::mvcc::UndoEntry::Delete {
                                    table: insert.table_name.clone(),
                                    rowid: existing_rid,
                                    old_row,
                                    txn_id: self.current_txn_id,
                                });
                            }
                        }
                    }
                    // Also remove any rows that would conflict on UNIQUE indexes
                    let conflict_rowids: Vec<i64> = {
                        // Clone indexes to release the schema borrow before calling get_table_pager_mut.
                        let indexes: Vec<_> = self
                            .schema
                            .indexes_for_table(&insert.table_name)
                            .into_iter()
                            .cloned()
                            .collect();
                        let mut cids: Vec<i64> = Vec::new();
                        for idx in indexes {
                            if !idx.unique {
                                continue;
                            }
                            // Pre-compute key_vals from schema (drops schema borrow) before touching pager.
                            let key_vals: Vec<Value> = {
                                let tbl_schema = self.schema.get_table(&insert.table_name)?;
                                idx.columns
                                    .iter()
                                    .filter_map(|c| {
                                        tbl_schema
                                            .columns
                                            .iter()
                                            .find(|col| col.name.eq_ignore_ascii_case(c))
                                            .map(|col| row[col.col_index].clone())
                                    })
                                    .collect()
                            };
                            // Skip if any key part is NULL (unique index doesn't cover NULLs)
                            if key_vals.iter().any(|v| matches!(v, Value::Null)) {
                                continue;
                            }
                            let key = crate::schema::Schema::index_key(&key_vals);
                            // Scan index BTree via table pager (schema borrow dropped above).
                            let idx_rows = {
                                let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                                let mut btree = BTree::new(tbl_pager);
                                btree.scan_all(idx.root_page)?
                            };
                            for (_, idx_row) in idx_rows {
                                if let Some(Value::Integer(tbl_rowid)) = idx_row.last() {
                                    if *tbl_rowid != rowid {
                                        let entry_key = crate::schema::Schema::index_key(
                                            &idx_row[..idx_row.len() - 1],
                                        );
                                        if entry_key == key {
                                            cids.push(*tbl_rowid);
                                        }
                                    }
                                }
                            }
                        }
                        cids
                    };
                    for conflict_rid in conflict_rowids {
                        self.maintain_fts_delete(&insert.table_name, conflict_rid)?;
                        self.delete_index_entries(&insert.table_name, conflict_rid)?;
                        let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                        let mut btree = BTree::new(tbl_pager);
                        let (_, new_root) = btree.delete_by_rowid(root_page, conflict_rid)?;
                        root_page = new_root;
                    }
                    let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                    let mut btree = BTree::new(tbl_pager);
                    let new_root =
                        btree.insert_with_buf(root_page, rowid, &row, &mut serialize_buf)?;
                    root_page = new_root;
                    self.insert_index_entries(&insert.table_name, rowid, &row)?;
                    // L4: Maintain FTS + vector indexes
                    self.maintain_fts_insert(&insert.table_name, rowid, &row)?;
                    self.maintain_vec_insert(&insert.table_name, rowid, &row)?;

                    // Add to binlog
                    let txid = self.pager.active_txid().unwrap_or(0);
                    let _ = self.binlog.append(&crate::binlog::LogRecord::Insert {
                        txid,
                        table_name: insert.table_name.clone(),
                        rowid,
                        row: row.clone(),
                    });

                    // --- L3: AFTER INSERT triggers ---
                    self.fire_triggers(
                        &insert.table_name,
                        &crate::sql::ast::TriggerTiming::After,
                        &crate::sql::ast::TriggerEvent::Insert,
                    )?;
                    rows_inserted += 1;
                }
                // Batch G: ON CONFLICT DO UPDATE SET col = expr ...
                ConflictPolicy::Update(assignments) => {
                    // Find conflicting row by PK using scan_all which returns (rowid, row) pairs
                    let pk_idx = pk_col_idx.unwrap_or(0);
                    let pk_val = row.get(pk_idx).cloned().unwrap_or(Value::Null);
                    let existing = {
                        let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                        let mut btree = BTree::new(tbl_pager);
                        btree.scan_all(root_page)?
                    };
                    let existing_rowid = existing.iter().find_map(|(id, r)| {
                        if r.get(pk_idx) == Some(&pk_val) {
                            Some(*id)
                        } else {
                            None
                        }
                    });
                    if let Some(conflict_rowid) = existing_rowid {
                        // B-NEW-2 fix: fetch old row in a block so borrow ends before &mut self calls
                        let old_row = {
                            let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                            let mut bt = BTree::new(tbl_pager);
                            bt.find_by_rowid(root_page, conflict_rowid)?
                                .map(|(_, r)| r)
                                .unwrap_or_default()
                        };
                        // Build updated row by applying assignments
                        let col_map_tmp: std::collections::HashMap<String, usize> = {
                            let table_schema = self.schema.get_table(&insert.table_name)?;
                            table_schema
                                .col_names
                                .iter()
                                .enumerate()
                                .map(|(i, n)| (n.to_ascii_lowercase(), i))
                                .collect()
                        };
                        let mut new_row = old_row.clone();
                        for (col_name, expr) in assignments.iter() {
                            if let Ok(idx) = self.schema.find_column(&insert.table_name, col_name) {
                                let new_val = self.eval_expr(expr, &old_row, &col_map_tmp)?;
                                if idx < new_row.len() {
                                    new_row[idx] = new_val;
                                }
                            }
                        }

                        // B-NEW-2 fix #1: CHECK constraint validation
                        self.check_constraints_for_row(&insert.table_name, &new_row, &[])?;
                        // B-NEW-2 fix #2: FK child-side constraint check
                        self.check_fk_on_insert(&insert.table_name, &new_row)?;
                        // B-NEW-2 fix #3 & #4: Remove old FTS/index entries
                        self.maintain_fts_delete(&insert.table_name, conflict_rowid)?;
                        self.delete_index_entries(&insert.table_name, conflict_rowid)?;
                        // B-NEW-2 fix #5: UNIQUE index re-validation (exclude current row)
                        self.validate_unique_indexes_for_row(
                            &insert.table_name,
                            conflict_rowid,
                            &new_row,
                            Some(conflict_rowid),
                        )?;

                        // Perform the actual row update
                        let new_root = {
                            let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                            let mut btree = BTree::new(tbl_pager);
                            btree.update_row(root_page, conflict_rowid, &new_row)?
                        };
                        root_page = new_root;

                        // B-NEW-2 fix #6, #7: Insert new FTS/index + vec entries
                        self.insert_index_entries(&insert.table_name, conflict_rowid, &new_row)?;
                        self.maintain_fts_insert(&insert.table_name, conflict_rowid, &new_row)?;
                        self.maintain_vec_delete(&insert.table_name, conflict_rowid);
                        self.maintain_vec_insert(&insert.table_name, conflict_rowid, &new_row)?;

                        // B-NEW-2 fix #8: Write Update to binlog
                        let txid = self.pager.active_txid().unwrap_or(0);
                        let _ = self.binlog.append(&crate::binlog::LogRecord::Update {
                            txid,
                            table_name: insert.table_name.clone(),
                            rowid: conflict_rowid,
                            old_row: old_row.clone(),
                            new_row: new_row.clone(),
                        });
                        // B-NEW-2 fix #9: MVCC undo log for rollback
                        if self.pager.in_transaction() && self.current_txn_id != 0 {
                            // R5: Acquire row-level lock for upsert update
                            self.row_lock_manager.try_lock_row(
                                &insert.table_name, conflict_rowid, self.current_txn_id,
                            )?;
                            self.mvcc_undo_log.push(crate::vm::mvcc::UndoEntry::Update {
                                table: insert.table_name.clone(),
                                rowid: conflict_rowid,
                                old_row,
                                txn_id: self.current_txn_id,
                            });
                        }
                        // B-NEW-2 fix #10: count the upsert
                        rows_inserted += 1;
                    } else {
                        // No conflict: plain insert
                        let new_root = {
                            let tbl_pager = self.get_table_pager_mut(&table_name_owned);
                            let mut btree = BTree::new(tbl_pager);
                            btree.insert_with_buf(root_page, rowid, &row, &mut serialize_buf)?
                        };
                        root_page = new_root;
                        let _ = self.insert_index_entries(&insert.table_name, rowid, &row);
                        // L4: Maintain FTS + vector indexes
                        self.maintain_fts_insert(&insert.table_name, rowid, &row)?;
                        self.maintain_vec_insert(&insert.table_name, rowid, &row)?;
                        // --- L3: AFTER INSERT triggers ---
                        self.fire_triggers(
                            &insert.table_name,
                            &crate::sql::ast::TriggerTiming::After,
                            &crate::sql::ast::TriggerEvent::Insert,
                        )?;
                        rows_inserted += 1;
                    }
                }
            }
        }

        {
            let table_schema = self.schema.get_table_mut(&insert.table_name)?;
            table_schema.root_page = root_page;
            table_schema.next_rowid = next_rowid;
        }

        if root_page != original_root {
            self.update_schema_root_page(&insert.table_name, root_page)?;
        }

        self.auto_flush()?;

        // --- RETURNING clause ---
        if let Some(ref returning_exprs) = insert.returning {
            let col_map = self.build_table_col_map(&insert.table_name)?;
            // We need to re-read inserted rows; for simplicity, use the captured rows_inserted_data
            let mut result_rows: Vec<Row> = Vec::new();
            for inserted_row in &inserted_rows_for_returning {
                let mut result_row = Vec::new();
                for expr in returning_exprs {
                    if let Expr::ColumnRef { table: _, column } = expr {
                        if column == "*" {
                            result_row.extend_from_slice(inserted_row);
                            continue;
                        }
                    }
                    let v = self.eval_expr(expr, inserted_row, &col_map)?;
                    result_row.push(v);
                }
                result_rows.push(result_row);
            }
            let col_names: Vec<String> = returning_exprs
                .iter()
                .enumerate()
                .map(|(i, e)| match e {
                    Expr::ColumnRef { table: _, column } => column.clone(),
                    _ => format!("col{}", i),
                })
                .collect();
            return Ok(ExecResult::QueryResult {
                columns: col_names,
                rows: result_rows,
            });
        }

        Ok(ExecResult::RowsAffected {
            count: rows_inserted,
            message: format!("{} row(s) inserted", rows_inserted),
        })
    }

    // ---- UPDATE ----
    pub(crate) fn exec_update(&mut self, update: &UpdateStmt) -> Result<ExecResult> {
        let (col_map, original_root) = {
            let table = self.schema.get_table(&update.table_name)?;
            let mut cm: HashMap<String, usize> = HashMap::with_capacity(table.columns.len());
            for (i, c) in table.columns.iter().enumerate() {
                if c.name.bytes().any(|b| b.is_ascii_uppercase()) {
                    let mut lower = String::with_capacity(c.name.len());
                    for b in c.name.bytes() {
                        lower.push(b.to_ascii_lowercase() as char);
                    }
                    cm.insert(lower, i);
                } else {
                    cm.insert(c.name.clone(), i);
                }
            }
            (cm, table.root_page)
        };

        // Pre-resolve assignment column indices (avoids per-row to_lowercase allocation)
        let assignment_indices: Vec<(usize, &Expr)> = update
            .assignments
            .iter()
            .map(|(col_name, expr)| {
                let lower = col_name.to_ascii_lowercase();
                let idx = *col_map
                    .get(lower.as_str())
                    .ok_or_else(|| KkdbError::ColumnNotFound(col_name.clone()))?;
                Ok((idx, expr))
            })
            .collect::<Result<Vec<_>>>()?;

        // Try index-accelerated path for simple WHERE col = value
        let index_rowids = if let Some(ref where_expr) = update.where_clause {
            self.try_dml_index_rowids(&update.table_name, where_expr)?
        } else {
            None
        };

        let mut rows_to_update: Vec<(i64, Row, Row)> = Vec::new();

        if let Some(rowids) = index_rowids {
            // Index path: fetch only matching rows by rowid (bulk-capable helper).
            let fetched_rows =
                self.fetch_rows_by_rowids(&update.table_name, original_root, &rowids)?;
            for (rid, row) in fetched_rows {
                let mut new_row = row.clone();
                for &(col_idx, expr) in &assignment_indices {
                    let val = self.eval_expr(expr, &row, &col_map)?;
                    new_row[col_idx] = val;
                }
                rows_to_update.push((rid, row, new_row));
            }
        } else {
            // Full scan path
            let tbl_pager = self.get_table_pager_mut(&update.table_name);
            let mut btree = BTree::new(tbl_pager);
            let all_rows = btree.scan_all(original_root)?;

            for (rowid, row) in all_rows {
                let should_update = if let Some(ref where_expr) = update.where_clause {
                    self.eval_expr(where_expr, &row, &col_map)?.is_truthy()
                } else {
                    true
                };

                if should_update {
                    let mut new_row = row.clone();
                    for &(col_idx, expr) in &assignment_indices {
                        let val = self.eval_expr(expr, &row, &col_map)?;
                        new_row[col_idx] = val;
                    }
                    rows_to_update.push((rowid, row, new_row));
                }
            }
        }

        let count = rows_to_update.len();
        let mut root_page = original_root;
        let mut serialize_buf: Vec<u8> = Vec::new();
        // I1: collect updated rows when a RETURNING clause is present
        let mut returning_rows: Vec<crate::types::Row> = if update.returning.is_some() {
            Vec::with_capacity(count)
        } else {
            Vec::new()
        };

        for (rowid, old_row_pre, new_row) in rows_to_update {
            // --- L3: BEFORE UPDATE triggers ---
            self.fire_triggers(
                &update.table_name,
                &crate::sql::ast::TriggerTiming::Before,
                &crate::sql::ast::TriggerEvent::Update,
            )?;

            // --- L2: CHECK constraint validation ---
            self.check_constraints_for_row(&update.table_name, &new_row, &[])?;

            // Update indexes: delete old entry, insert new entry
            self.maintain_fts_delete(&update.table_name, rowid)?;
            self.maintain_vec_delete(&update.table_name, rowid);
            self.delete_index_entries(&update.table_name, rowid)?;
            self.validate_unique_indexes_for_row(&update.table_name, rowid, &new_row, Some(rowid))?;

            let tbl_pager = self.get_table_pager_mut(&update.table_name);
            let mut btree = BTree::new(tbl_pager);
            let new_root =
                btree.update_row_with_buf(root_page, rowid, &new_row, &mut serialize_buf)?;
            root_page = new_root;

            self.insert_index_entries(&update.table_name, rowid, &new_row)?;
            // L4 + Vec: Maintain FTS and vector indexes
            self.maintain_fts_insert(&update.table_name, rowid, &new_row)?;
            self.maintain_vec_insert(&update.table_name, rowid, &new_row)?;

            // Log Update to Binlog (use old_row_pre captured before the row was modified)
            let txid = self.pager.active_txid().unwrap_or(0);
            let _ = self.binlog.append(&crate::binlog::LogRecord::Update {
                txid,
                table_name: update.table_name.clone(),
                rowid,
                old_row: old_row_pre.clone(),
                new_row: new_row.clone(),
            });
            // C1: Record undo entry (use old_row_pre captured before update)
            if self.pager.in_transaction() && self.current_txn_id != 0 {
                // R5: Acquire row-level lock for write-write conflict detection
                self.row_lock_manager.try_lock_row(
                    &update.table_name, rowid, self.current_txn_id,
                )?;
                self.mvcc_undo_log.push(crate::vm::mvcc::UndoEntry::Update {
                    table: update.table_name.clone(),
                    rowid,
                    old_row: old_row_pre.clone(),
                    txn_id: self.current_txn_id,
                });
            }

            // --- I1: Collect for RETURNING ---
            if update.returning.is_some() {
                returning_rows.push(new_row.clone());
            }

            // --- I2: FK ON UPDATE enforcement ---
            self.enforce_fk_parent_update(&update.table_name, &old_row_pre, &new_row)?;

            // --- L3: AFTER UPDATE triggers ---
            self.fire_triggers(
                &update.table_name,
                &crate::sql::ast::TriggerTiming::After,
                &crate::sql::ast::TriggerEvent::Update,
            )?;
        }

        // Update root page if changed
        if root_page != original_root {
            let table_schema = self.schema.get_table_mut(&update.table_name)?;
            table_schema.root_page = root_page;
            self.update_schema_root_page(&update.table_name, root_page)?;
        }

        self.auto_flush()?;

        // --- I1: RETURNING clause for UPDATE ---
        if let Some(ref returning_exprs) = update.returning {
            let col_map2 = self.build_table_col_map(&update.table_name)?;
            let mut result_rows = Vec::new();
            for new_row in &returning_rows {
                let mut result_row = Vec::new();
                for expr in returning_exprs {
                    if let crate::sql::ast::Expr::ColumnRef { table: _, column } = expr {
                        if column == "*" {
                            result_row.extend_from_slice(new_row);
                            continue;
                        }
                    }
                    let v = self.eval_expr(expr, new_row, &col_map2)?;
                    result_row.push(v);
                }
                result_rows.push(result_row);
            }
            let col_names: Vec<String> = returning_exprs
                .iter()
                .enumerate()
                .map(|(i, e)| match e {
                    crate::sql::ast::Expr::ColumnRef { column, .. } => column.clone(),
                    _ => format!("col{}", i),
                })
                .collect();
            return Ok(ExecResult::QueryResult {
                columns: col_names,
                rows: result_rows,
            });
        }

        Ok(ExecResult::RowsAffected {
            count,
            message: format!("{} row(s) updated", count),
        })
    }

    // ---- DELETE ----
    pub(crate) fn exec_delete(&mut self, delete: &DeleteStmt) -> Result<ExecResult> {
        let (col_map, original_root) = {
            let table = self.schema.get_table(&delete.table_name)?;
            let mut cm: HashMap<String, usize> = HashMap::with_capacity(table.columns.len());
            for (i, c) in table.columns.iter().enumerate() {
                if c.name.bytes().any(|b| b.is_ascii_uppercase()) {
                    let mut lower = String::with_capacity(c.name.len());
                    for b in c.name.bytes() {
                        lower.push(b.to_ascii_lowercase() as char);
                    }
                    cm.insert(lower, i);
                } else {
                    cm.insert(c.name.clone(), i);
                }
            }
            (cm, table.root_page)
        };

        // Try index-accelerated path for simple WHERE col = value
        let index_rowids = if let Some(ref where_expr) = delete.where_clause {
            self.try_dml_index_rowids(&delete.table_name, where_expr)?
        } else {
            None
        };

        let rowids_to_delete: Vec<i64> = if let Some(rowids) = index_rowids {
            rowids
        } else {
            // Scan all rows first (releases pager borrow), then filter.
            let all_rows = {
                let tbl_pager = self.get_table_pager_mut(&delete.table_name);
                let mut btree = BTree::new(tbl_pager);
                btree.scan_all(original_root)?
            };
            let mut ids = Vec::new();
            for (rowid, row) in &all_rows {
                let should_delete = if let Some(ref where_expr) = delete.where_clause {
                    self.eval_expr(where_expr, row, &col_map)?.is_truthy()
                } else {
                    true
                };
                if should_delete {
                    ids.push(*rowid);
                }
            }
            ids
        };

        let count = rowids_to_delete.len();
        let mut root_page = original_root;
        // I1: collect deleted rows for RETURNING clause
        let mut deleted_rows_for_returning: Vec<crate::types::Row> = if delete.returning.is_some() {
            Vec::with_capacity(count)
        } else {
            Vec::new()
        };

        for rowid in rowids_to_delete {
            // --- L3: BEFORE DELETE triggers ---
            self.fire_triggers(
                &delete.table_name,
                &crate::sql::ast::TriggerTiming::Before,
                &crate::sql::ast::TriggerEvent::Delete,
            )?;

            // --- L1: FK CASCADE / SET NULL enforcement (parent delete) ---
            {
                // B12-5 fix: use root_page (updated per loop iteration), not original_root
                // which becomes stale after the first B-Tree rebalance.
                let parent_row_opt = {
                    let tbl_pager = self.get_table_pager_mut(&delete.table_name);
                    let mut btree = BTree::new(tbl_pager);
                    btree.find_by_rowid(root_page, rowid)?.map(|(_, r)| r)
                };
                if let Some(ref parent_row) = parent_row_opt {
                    self.enforce_fk_parent_delete(&delete.table_name, parent_row)?;
                }
            }

            // Delete index entries before deleting the row
            self.maintain_fts_delete(&delete.table_name, rowid)?;
            self.maintain_vec_delete(&delete.table_name, rowid);
            self.delete_index_entries(&delete.table_name, rowid)?;

            let tbl_pager = self.get_table_pager_mut(&delete.table_name);
            let mut btree = BTree::new(tbl_pager);

            // Fetch old row for binlog + RETURNING before deleting
            let old_row = btree.find_by_rowid(root_page, rowid)?.map(|(_, r)| r);
            // I1: collect old row for RETURNING clause
            if delete.returning.is_some() {
                if let Some(ref r) = old_row {
                    deleted_rows_for_returning.push(r.clone());
                }
            }

            let (_, new_root) = btree.delete_by_rowid(root_page, rowid)?;
            root_page = new_root;

            // Log Delete to Binlog
            let txid = self.pager.active_txid().unwrap_or(0);
            // C1: DELETE undo — record old row for rollback (before binlog consumes old_row)
            if self.pager.in_transaction() && self.current_txn_id != 0 {
                // R5: Acquire row-level lock for write-write conflict detection
                self.row_lock_manager.try_lock_row(
                    &delete.table_name, rowid, self.current_txn_id,
                )?;
                if let Some(ref old_r) = old_row {
                    self.mvcc_undo_log.push(crate::vm::mvcc::UndoEntry::Delete {
                        table: delete.table_name.clone(),
                        rowid,
                        old_row: old_r.clone(),
                        txn_id: self.current_txn_id,
                    });
                }
            }
            let _ = self.binlog.append(&crate::binlog::LogRecord::Delete {
                txid,
                table_name: delete.table_name.clone(),
                rowid,
                row: old_row,
            });

            // --- L3: AFTER DELETE triggers ---
            self.fire_triggers(
                &delete.table_name,
                &crate::sql::ast::TriggerTiming::After,
                &crate::sql::ast::TriggerEvent::Delete,
            )?;
        }

        // Update root page if changed (future: rebalancing may change root)
        if root_page != original_root {
            let table_schema = self.schema.get_table_mut(&delete.table_name)?;
            table_schema.root_page = root_page;
            self.update_schema_root_page(&delete.table_name, root_page)?;
        }

        self.auto_flush()?;

        // --- I1: RETURNING clause for DELETE ---
        if let Some(ref returning_exprs) = delete.returning {
            let col_map2 = self.build_table_col_map(&delete.table_name)?;
            let mut result_rows = Vec::new();
            for old_row in &deleted_rows_for_returning {
                let mut result_row = Vec::new();
                for expr in returning_exprs {
                    if let crate::sql::ast::Expr::ColumnRef { table: _, column } = expr {
                        if column == "*" {
                            result_row.extend_from_slice(old_row);
                            continue;
                        }
                    }
                    let v = self.eval_expr(expr, old_row, &col_map2)?;
                    result_row.push(v);
                }
                result_rows.push(result_row);
            }
            let col_names: Vec<String> = returning_exprs
                .iter()
                .enumerate()
                .map(|(i, e)| match e {
                    crate::sql::ast::Expr::ColumnRef { column, .. } => column.clone(),
                    _ => format!("col{}", i),
                })
                .collect();
            // I19 fix: write binlog Commit record before returning so binlog followers
            // can correctly apply the transaction boundary for DELETE RETURNING.
            {
                let txid = self.pager.active_txid().unwrap_or(0);
                let _ = self.binlog.append(&crate::binlog::LogRecord::Commit(txid));
            }
            return Ok(ExecResult::QueryResult {
                columns: col_names,
                rows: result_rows,
            });
        }

        Ok(ExecResult::RowsAffected {
            count,
            message: format!("{} row(s) deleted", count),
        })
    }

    /// Try to use an index to find matching rowids for a simple WHERE col = value.
    /// Used by UPDATE/DELETE to avoid full table scan.
    /// Returns Some(vec of rowids) if index was used, None otherwise.
    fn try_dml_index_rowids(
        &mut self,
        table_name: &str,
        where_expr: &Expr,
    ) -> Result<Option<Vec<i64>>> {
        enum Lookup {
            Eq(Value),
            In(Vec<Value>),
            Comparison(BinaryOperator, Value),
            Between(Value, Value),
        }

        let (col_name, lookup) = match where_expr {
            Expr::BinaryOp { left, op, right } => {
                let Some(op_normalized) = (match (left.as_ref(), right.as_ref()) {
                    (Expr::ColumnRef { .. }, _) => Some(op.clone()),
                    (_, Expr::ColumnRef { .. }) => VM::flip_comparison_operator(op),
                    _ => None,
                }) else {
                    return Ok(None);
                };

                let Some(val) = (match (left.as_ref(), right.as_ref()) {
                    (Expr::ColumnRef { .. }, rhs) => self.eval_constant_expr(rhs),
                    (lhs, Expr::ColumnRef { .. }) => self.eval_constant_expr(lhs),
                    _ => None,
                }) else {
                    return Ok(None);
                };

                let column = match (left.as_ref(), right.as_ref()) {
                    (Expr::ColumnRef { column, .. }, _) => column.clone(),
                    (_, Expr::ColumnRef { column, .. }) => column.clone(),
                    _ => return Ok(None),
                };

                let lookup = if op_normalized == BinaryOperator::Equal {
                    Lookup::Eq(val)
                } else if matches!(
                    op_normalized,
                    BinaryOperator::LessThan
                        | BinaryOperator::LessThanOrEqual
                        | BinaryOperator::GreaterThan
                        | BinaryOperator::GreaterThanOrEqual
                ) {
                    Lookup::Comparison(op_normalized, val)
                } else {
                    return Ok(None);
                };
                (column, lookup)
            }
            Expr::InList {
                expr,
                list,
                negated,
            } if !negated => {
                let Expr::ColumnRef { column, .. } = expr.as_ref() else {
                    return Ok(None);
                };
                let mut values = Vec::with_capacity(list.len());
                for item in list {
                    let Some(v) = self.eval_constant_expr(item) else {
                        return Ok(None);
                    };
                    // NULL in IN-list can never make predicate TRUE in WHERE context.
                    if !matches!(v, Value::Null) {
                        values.push(v);
                    }
                }
                (column.clone(), Lookup::In(values))
            }
            Expr::Between {
                expr,
                low,
                high,
                negated,
            } if !negated => {
                let Expr::ColumnRef { column, .. } = expr.as_ref() else {
                    return Ok(None);
                };
                let Some(low_v) = self.eval_constant_expr(low) else {
                    return Ok(None);
                };
                let Some(high_v) = self.eval_constant_expr(high) else {
                    return Ok(None);
                };
                (column.clone(), Lookup::Between(low_v, high_v))
            }
            _ => return Ok(None),
        };

        // Find an index that starts with this column
        let indexes: Vec<_> = self
            .schema
            .indexes_for_table(table_name)
            .into_iter()
            .cloned()
            .collect();
        let idx = match indexes
            .iter()
            .find(|idx| !idx.columns.is_empty() && idx.columns[0].eq_ignore_ascii_case(&col_name))
        {
            Some(i) => i.clone(),
            None => return Ok(None),
        };

        match lookup {
            Lookup::Eq(search_val) => {
                // SQL '=' with NULL is unknown, so WHERE never matches.
                if matches!(search_val, Value::Null) {
                    return Ok(Some(Vec::new()));
                }
                Ok(Some(self.index_rowids_for_value(&idx, &search_val)?))
            }
            Lookup::In(search_vals) => {
                if search_vals.is_empty() {
                    return Ok(Some(Vec::new()));
                }
                let mut seen = HashSet::new();
                let mut out = Vec::new();
                for v in search_vals {
                    for rid in self.index_rowids_for_value(&idx, &v)? {
                        if seen.insert(rid) {
                            out.push(rid);
                        }
                    }
                }
                Ok(Some(out))
            }
            Lookup::Comparison(op, search_val) => Ok(Some(self.index_rowids_for_comparison(
                &idx,
                &op,
                &search_val,
            )?)),
            Lookup::Between(low, high) => {
                Ok(Some(self.index_rowids_for_between(&idx, &low, &high)?))
            }
        }
    }

    // ---- INDEX MAINTENANCE ----

    /// Insert index entries for all indexes on a table after a row is inserted
    pub(crate) fn insert_index_entries(
        &mut self,
        table_name: &str,
        rowid: i64,
        row: &Row,
    ) -> Result<()> {
        if !self.schema.has_indexes_for_table(table_name) {
            return Ok(());
        }
        let table = self.schema.get_table(table_name)?.clone();
        let indexes: Vec<_> = self
            .schema
            .indexes_for_table(table_name)
            .into_iter()
            .cloned()
            .collect();

        for idx in &indexes {
            // Build column indices for this index
            let col_indices: Vec<usize> = idx
                .columns
                .iter()
                .filter_map(|col_name| {
                    table
                        .columns
                        .iter()
                        .find(|c| c.name.eq_ignore_ascii_case(col_name))
                        .map(|c| c.col_index)
                })
                .collect();

            // Build index entry: [col_val_1, ..., col_val_n, table_rowid]
            let mut index_row: Row = Vec::with_capacity(col_indices.len() + 1);
            for &ci in &col_indices {
                index_row.push(if ci < row.len() {
                    row[ci].clone()
                } else {
                    Value::Null
                });
            }

            if idx.unique
                && !index_row.iter().any(|v| matches!(v, Value::Null))
                && self.unique_index_conflict_exists(idx, &index_row, Some(rowid))?
            {
                return Err(KkdbError::ConstraintViolation(format!(
                    "UNIQUE constraint failed: {}.{}",
                    table_name,
                    idx.columns.join(", ")
                )));
            }

            let first_col_value = index_row.first().cloned();
            index_row.push(Value::Integer(rowid));

            let current_root = idx.root_page;
            let tbl_pager = self.get_table_pager_mut(table_name);
            let mut btree = BTree::new(tbl_pager);
            let idx_next = btree.max_rowid(current_root).unwrap_or(0) + 1;
            let new_root = btree.insert(current_root, idx_next, &index_row)?;

            if let Some(ref first_val) = first_col_value {
                self.index_cache_insert(idx, first_val, rowid, idx_next);
            }

            if new_root != current_root {
                if let Some(schema_idx) = self.schema.indexes.get_mut(&idx.name.to_lowercase()) {
                    schema_idx.root_page = new_root;
                }
                let _ = self.update_schema_object_root_page(&idx.name, new_root);
            }
        }
        Ok(())
    }

    /// Delete index entries for all indexes on a table when a row is deleted
    pub(crate) fn delete_index_entries(&mut self, table_name: &str, rowid: i64) -> Result<()> {
        if !self.schema.has_indexes_for_table(table_name) {
            return Ok(());
        }
        let indexes: Vec<_> = self
            .schema
            .indexes_for_table(table_name)
            .into_iter()
            .cloned()
            .collect();

        for idx in &indexes {
            let mut first_col_value: Option<Value> = None;
            if let Some(idx_rowid) = self.index_entry_rowid_for_table_rowid(idx, rowid)? {
                let tbl_pager = self.get_table_pager_mut(table_name);
                let mut btree = BTree::new(tbl_pager);
                if let Some((_rid, idx_row)) = btree.find_by_rowid(idx.root_page, idx_rowid)? {
                    first_col_value = idx_row.first().cloned();
                }
                let (_deleted, new_root) = btree.delete_by_rowid(idx.root_page, idx_rowid)?;

                if new_root != idx.root_page {
                    if let Some(schema_idx) = self.schema.indexes.get_mut(&idx.name.to_lowercase())
                    {
                        schema_idx.root_page = new_root;
                    }
                    self.update_schema_object_root_page(&idx.name, new_root)?;
                }

                if let Some(ref first_val) = first_col_value {
                    self.index_cache_delete(idx, first_val, rowid);
                }
            }
        }
        Ok(())
    }

    /// Validate UNIQUE indexes for an incoming table row.
    /// `ignore_rowid` is used when checking updates to avoid self-collision.
    fn validate_unique_indexes_for_row(
        &mut self,
        table_name: &str,
        rowid: i64,
        row: &Row,
        ignore_rowid: Option<i64>,
    ) -> Result<()> {
        if !self.schema.has_indexes_for_table(table_name) {
            return Ok(());
        }

        let table = self.schema.get_table(table_name)?.clone();
        let indexes: Vec<_> = self
            .schema
            .indexes_for_table(table_name)
            .into_iter()
            .cloned()
            .collect();

        for idx in &indexes {
            if !idx.unique {
                continue;
            }

            let mut key_values: Row = Vec::with_capacity(idx.columns.len());
            for col_name in &idx.columns {
                let col_idx = table
                    .columns
                    .iter()
                    .find(|c| c.name.eq_ignore_ascii_case(col_name))
                    .map(|c| c.col_index)
                    .ok_or_else(|| {
                        KkdbError::ColumnNotFound(format!("{}.{}", table_name, col_name))
                    })?;
                key_values.push(if col_idx < row.len() {
                    row[col_idx].clone()
                } else {
                    Value::Null
                });
            }

            // SQLite UNIQUE allows multiple NULL keys.
            if key_values.iter().any(|v| matches!(v, Value::Null)) {
                continue;
            }

            if self.unique_index_conflict_exists(idx, &key_values, ignore_rowid.or(Some(rowid)))? {
                return Err(KkdbError::ConstraintViolation(format!(
                    "UNIQUE constraint failed: {}.{}",
                    table_name,
                    idx.columns.join(", ")
                )));
            }
        }

        Ok(())
    }

    /// Returns true if any index entry with the same key already exists.
    fn unique_index_conflict_exists(
        &mut self,
        index: &crate::schema::IndexSchema,
        key_values: &[Value],
        ignore_rowid: Option<i64>,
    ) -> Result<bool> {
        if key_values.is_empty() {
            return Ok(false);
        }

        // Use index cache by first key column to narrow candidate table rowids,
        // then verify full composite key by reading corresponding index entries.
        let candidate_table_rowids = self.index_rowids_for_value(index, &key_values[0])?;
        if candidate_table_rowids.is_empty() {
            return Ok(false);
        }

        let mut candidate_index_rowids = Vec::with_capacity(candidate_table_rowids.len());
        for table_rowid in candidate_table_rowids {
            if Some(table_rowid) == ignore_rowid {
                continue;
            }
            if let Some(idx_rowid) = self.index_entry_rowid_for_table_rowid(index, table_rowid)? {
                candidate_index_rowids.push(idx_rowid);
            }
        }

        if candidate_index_rowids.is_empty() {
            return Ok(false);
        }

        // B12-1 fix: use the table's own pager (not catalog pager) to read index entries.
        // In multi-file mode, index data lives in the table's .kkdb file, not catalog.kkdb.
        let idx_table = index.table_name.clone();
        let mut btree = BTree::new(self.get_table_pager_mut(&idx_table));
        for idx_rowid in candidate_index_rowids {
            let Some((_rid, idx_row)) = btree.find_by_rowid(index.root_page, idx_rowid)? else {
                continue;
            };
            if idx_row.len() < key_values.len() + 1 {
                continue;
            }

            let mut all_equal = true;
            for (i, key_val) in key_values.iter().enumerate() {
                if idx_row[i] != *key_val {
                    all_equal = false;
                    break;
                }
            }
            if !all_equal {
                continue;
            }

            if let Some(Value::Integer(existing_rowid)) = idx_row.last() {
                if Some(*existing_rowid) == ignore_rowid {
                    continue;
                }
            }
            return Ok(true);
        }

        Ok(false)
    }
}

// Extension trait for FK validation
impl VM {
    // 鈹€鈹€ L1: FOREIGN KEY Validation 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€

    /// On INSERT: verify that each FK column value exists in the referenced parent table.
    pub(crate) fn check_fk_on_insert(
        &mut self,
        table_name: &str,
        row: &[crate::types::Value],
    ) -> crate::error::Result<()> {
        use crate::error::KkdbError;
        let fks: Vec<crate::schema::ForeignKey> =
            self.schema.get_table(table_name)?.foreign_keys.clone();
        for fk in fks {
            let fk_value = row
                .get(fk.col_index)
                .cloned()
                .unwrap_or(crate::types::Value::Null);
            if matches!(fk_value, crate::types::Value::Null) {
                // NULL FK values always pass (SQL standard)
                continue;
            }
            // Resolve referenced column: default to first PK column
            let parent_col = fk.ref_col.as_deref();
            let found = self.fk_value_exists_in_parent(&fk.ref_table, parent_col, &fk_value)?;
            if !found {
                return Err(KkdbError::ConstraintViolation(format!(
                    "FOREIGN KEY constraint failed: {}.{} references {}",
                    table_name, fk.col_name, fk.ref_table
                )));
            }
        }
        Ok(())
    }

    /// Returns true if `value` exists in `col_name` (or PK) of `table`.
    fn fk_value_exists_in_parent(
        &mut self,
        table: &str,
        col_name: Option<&str>,
        value: &crate::types::Value,
    ) -> crate::error::Result<bool> {
        use crate::storage::btree::BTree;
        let (root_page, col_idx) = {
            let ts = self.schema.get_table(table)?;
            let idx = if let Some(col) = col_name {
                ts.columns
                    .iter()
                    .find(|c| c.name.eq_ignore_ascii_case(col))
                    .map(|c| c.col_index)
                    .unwrap_or(0)
            } else {
                // Default: PK column
                ts.columns
                    .iter()
                    .find(|c| c.primary_key)
                    .map(|c| c.col_index)
                    .unwrap_or(0)
            };
            (ts.root_page, idx)
        };
        let pager = self.get_table_pager_mut(table);
        let mut btree = BTree::new(pager);
        let rows = btree.scan_rows(root_page)?;
        for row in &rows {
            if row.get(col_idx) == Some(value) {
                return Ok(true);
            }
        }
        Ok(false)
    }
}

// ── Helpers used by RETURNING and FK cascade ───────────────────────────────
impl VM {
    /// Build a {column_name -> index} map for a table (lowercase keys).
    pub(crate) fn build_table_col_map(
        &mut self,
        table_name: &str,
    ) -> crate::error::Result<std::collections::HashMap<String, usize>> {
        let cols = self.schema.get_table(table_name)?.columns.clone();
        let mut map = std::collections::HashMap::new();
        for col in &cols {
            map.insert(col.name.to_ascii_lowercase(), col.col_index);
        }
        Ok(map)
    }

    /// Enforce FK referential actions for a parent table DELETE.
    ///
    /// For each child table that references `parent_table`, look up the FK action:
    /// - `Cascade`  → DELETE matching child rows recursively.
    /// - `SetNull`  → UPDATE matching child rows SET fk_col = NULL.
    /// - `Restrict` → Return ConstraintViolation if any child row exists.
    pub(crate) fn enforce_fk_parent_delete(
        &mut self,
        parent_table: &str,
        deleted_row: &[crate::types::Value],
    ) -> crate::error::Result<()> {
        use crate::sql::ast::FkAction;
        let all_tables: Vec<String> = self.schema.list_tables();
        for child_table in all_tables {
            let fks: Vec<crate::schema::ForeignKey> = {
                let ts = match self.schema.get_table(&child_table) {
                    Ok(t) => t,
                    Err(_) => continue,
                };
                ts.foreign_keys.clone()
            };
            for fk in fks {
                if !fk.ref_table.eq_ignore_ascii_case(parent_table) {
                    continue;
                }
                // Find the referenced value in the parent row
                let parent_pk_idx = {
                    let ts = self.schema.get_table(parent_table)?;
                    ts.columns
                        .iter()
                        .find(|c| c.primary_key)
                        .map(|c| c.col_index)
                };
                let ref_val = if let Some(col_name) = &fk.ref_col {
                    let ts = self.schema.get_table(parent_table)?;
                    let col_idx = ts
                        .columns
                        .iter()
                        .find(|c| c.name.eq_ignore_ascii_case(col_name))
                        .map(|c| c.col_index);
                    col_idx.and_then(|i| deleted_row.get(i)).cloned()
                } else {
                    parent_pk_idx.and_then(|i| deleted_row.get(i)).cloned()
                };
                let Some(ref_val) = ref_val else {
                    continue;
                };
                if matches!(ref_val, crate::types::Value::Null) {
                    continue;
                }

                match fk.on_delete {
                    FkAction::Cascade => {
                        // DELETE all child rows that have this FK value
                        let sql = format!(
                            "DELETE FROM {} WHERE {} = {}",
                            child_table,
                            fk.col_name,
                            match &ref_val {
                                crate::types::Value::Integer(i) => i.to_string(),
                                crate::types::Value::Real(f) => f.to_string(),
                                crate::types::Value::Text(t) =>
                                    format!("'{}'", t.replace('\'', "''")),
                                _ => continue,
                            }
                        );
                        self.execute_sql(&sql)?;
                    }
                    FkAction::SetNull => {
                        // UPDATE child SET fk_col = NULL WHERE fk_col = ref_val
                        let sql = format!(
                            "UPDATE {} SET {} = NULL WHERE {} = {}",
                            child_table,
                            fk.col_name,
                            fk.col_name,
                            match &ref_val {
                                crate::types::Value::Integer(i) => i.to_string(),
                                crate::types::Value::Real(f) => f.to_string(),
                                crate::types::Value::Text(t) =>
                                    format!("'{}'", t.replace('\'', "''")),
                                _ => continue,
                            }
                        );
                        self.execute_sql(&sql)?;
                    }
                    FkAction::Restrict => {
                        let has_child = self.fk_value_exists_in_parent(
                            &child_table,
                            Some(fk.col_name.as_str()),
                            &ref_val,
                        )?;
                        if has_child {
                            return Err(KkdbError::ConstraintViolation(format!(
                                "FOREIGN KEY constraint failed: deleting from {} has dependent rows in {}",
                                parent_table, child_table
                            )));
                        }
                    }
                }
            }
        }
        Ok(())
    }

    /// I2: On UPDATE to a parent table: enforce FK ON UPDATE actions in child tables.
    ///
    /// `parent_table`  — the table being updated.  
    /// `old_row` / `new_row` — before and after the UPDATE for a single row.
    pub(crate) fn enforce_fk_parent_update(
        &mut self,
        parent_table: &str,
        old_row: &[crate::types::Value],
        new_row: &[crate::types::Value],
    ) -> crate::error::Result<()> {
        use crate::sql::ast::FkAction;
        let all_tables: Vec<String> = self.schema.list_tables();
        for child_table in all_tables {
            let fks: Vec<crate::schema::ForeignKey> = {
                let ts = match self.schema.get_table(&child_table) {
                    Ok(t) => t,
                    Err(_) => continue,
                };
                ts.foreign_keys.clone()
            };
            for fk in fks {
                if !fk.ref_table.eq_ignore_ascii_case(parent_table) {
                    continue;
                }
                // Find old and new value of the referenced column in the parent row
                let parent_col_idx = if let Some(col_name) = &fk.ref_col {
                    let ts = self.schema.get_table(parent_table)?;
                    ts.columns
                        .iter()
                        .find(|c| c.name.eq_ignore_ascii_case(col_name))
                        .map(|c| c.col_index)
                        .unwrap_or(0)
                } else {
                    let ts = self.schema.get_table(parent_table)?;
                    ts.columns
                        .iter()
                        .find(|c| c.primary_key)
                        .map(|c| c.col_index)
                        .unwrap_or(0)
                };
                let old_val = old_row
                    .get(parent_col_idx)
                    .cloned()
                    .unwrap_or(crate::types::Value::Null);
                let new_val = new_row
                    .get(parent_col_idx)
                    .cloned()
                    .unwrap_or(crate::types::Value::Null);
                // Only act if the referenced value actually changed
                if old_val == new_val {
                    continue;
                }
                if matches!(old_val, crate::types::Value::Null) {
                    continue;
                }

                let old_lit = match &old_val {
                    crate::types::Value::Integer(i) => i.to_string(),
                    crate::types::Value::Real(f) => f.to_string(),
                    crate::types::Value::Text(t) => format!("'{}'", t.replace('\'', "''")),
                    _ => continue,
                };
                let new_lit = match &new_val {
                    crate::types::Value::Integer(i) => i.to_string(),
                    crate::types::Value::Real(f) => f.to_string(),
                    crate::types::Value::Text(t) => format!("'{}'", t.replace('\'', "''")),
                    crate::types::Value::Null => "NULL".to_string(),
                    _ => continue,
                };

                match fk.on_update {
                    FkAction::Cascade => {
                        let sql = format!(
                            "UPDATE {} SET {} = {} WHERE {} = {}",
                            child_table, fk.col_name, new_lit, fk.col_name, old_lit
                        );
                        self.execute_sql(&sql)?;
                    }
                    FkAction::SetNull => {
                        let sql = format!(
                            "UPDATE {} SET {} = NULL WHERE {} = {}",
                            child_table, fk.col_name, fk.col_name, old_lit
                        );
                        self.execute_sql(&sql)?;
                    }
                    FkAction::Restrict => {
                        let has_child = self.fk_value_exists_in_parent(
                            &child_table,
                            Some(fk.col_name.as_str()),
                            &old_val,
                        )?;
                        if has_child {
                            return Err(KkdbError::ConstraintViolation(format!(
                                "FOREIGN KEY constraint failed: updating {} changes referenced value \
                                 in {}.{}",
                                parent_table, child_table, fk.col_name
                            )));
                        }
                    }
                }
            }
        }
        Ok(())
    }
}

// 鈹€鈹€ L2: CHECK Constraint Validation 鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€鈹€
impl VM {
    /// Evaluate CHECK constraints for a row before INSERT.
    pub(crate) fn check_constraints_for_row(
        &mut self,
        table_name: &str,
        row: &[crate::types::Value],
        _hint: &[String],
    ) -> crate::error::Result<()> {
        use crate::error::KkdbError;
        use crate::sql::ast::Expr;
        use crate::types::Value;
        let (checks, col_names): (Vec<(Option<String>, Expr)>, Vec<String>) = {
            let ts = self.schema.get_table(table_name)?;
            (ts.check_constraints.clone(), ts.col_names.clone())
        };
        for (name, check_expr) in checks {
            let val = self.eval_check_expr_simple(&check_expr, row, &col_names)?;
            // SQL standard: NULL (UNKNOWN) in CHECK → not a violation; only explicit FALSE/0 fails
            let passed = !matches!(val, Value::Integer(0));
            if !passed {
                let id = name.as_deref().unwrap_or("CHECK");
                return Err(KkdbError::ConstraintViolation(format!(
                    "CHECK constraint {} failed for table {}",
                    id, table_name
                )));
            }
        }
        Ok(())
    }

    fn eval_check_expr_simple(
        &mut self,
        expr: &crate::sql::ast::Expr,
        row: &[crate::types::Value],
        col_names: &[String],
    ) -> crate::error::Result<crate::types::Value> {
        use crate::sql::ast::{BinaryOperator as BOp, Expr, UnaryOperator as UOp};
        use crate::types::Value;
        Ok(match expr {
            Expr::IntegerLiteral(i) => Value::Integer(*i),
            Expr::RealLiteral(r) => Value::Real(*r),
            Expr::StringLiteral(s) => Value::Text(s.as_str().into()),
            Expr::Null => Value::Null,
            Expr::ColumnRef { column, .. } => {
                let lc = column.to_lowercase();
                col_names
                    .iter()
                    .position(|n| n.to_lowercase() == lc)
                    .and_then(|i| row.get(i))
                    .cloned()
                    .unwrap_or(Value::Null)
            }
            Expr::BinaryOp { left, op, right } => {
                let l = self.eval_check_expr_simple(left, row, col_names)?;
                let r = self.eval_check_expr_simple(right, row, col_names)?;
                match op {
                    // NULL propagation: any comparison involving NULL → UNKNOWN (passes CHECK)
                    BOp::Equal
                    | BOp::NotEqual
                    | BOp::LessThan
                    | BOp::LessThanOrEqual
                    | BOp::GreaterThan
                    | BOp::GreaterThanOrEqual
                        if matches!(l, Value::Null) || matches!(r, Value::Null) =>
                    {
                        Value::Null
                    }
                    BOp::Equal => Value::Integer(if l == r { 1 } else { 0 }),
                    BOp::NotEqual => Value::Integer(if l != r { 1 } else { 0 }),
                    BOp::LessThan => Value::Integer(if chk_cmp(&l, &r) < 0 { 1 } else { 0 }),
                    BOp::LessThanOrEqual => {
                        Value::Integer(if chk_cmp(&l, &r) <= 0 { 1 } else { 0 })
                    }
                    BOp::GreaterThan => Value::Integer(if chk_cmp(&l, &r) > 0 { 1 } else { 0 }),
                    BOp::GreaterThanOrEqual => {
                        Value::Integer(if chk_cmp(&l, &r) >= 0 { 1 } else { 0 })
                    }
                    BOp::Add => chk_arith(&l, &r, |a, b| a + b, |a, b| a + b),
                    BOp::Subtract => chk_arith(&l, &r, |a, b| a - b, |a, b| a - b),
                    BOp::Multiply => chk_arith(&l, &r, |a, b| a * b, |a, b| a * b),
                    BOp::Divide => match (&l, &r) {
                        (Value::Integer(a), Value::Integer(b)) if *b != 0 => Value::Integer(a / b),
                        _ => Value::Null,
                    },
                    BOp::And => Value::Integer(if chk_truthy(&l) && chk_truthy(&r) {
                        1
                    } else {
                        0
                    }),
                    BOp::Or => Value::Integer(if chk_truthy(&l) || chk_truthy(&r) {
                        1
                    } else {
                        0
                    }),
                    _ => Value::Null,
                }
            }
            Expr::IsNull {
                expr: inner,
                negated,
            } => {
                let v = self.eval_check_expr_simple(inner, row, col_names)?;
                let is_null = matches!(v, Value::Null);
                Value::Integer(if is_null != *negated { 1 } else { 0 })
            }
            Expr::UnaryOp { op, expr: inner } => {
                let v = self.eval_check_expr_simple(inner, row, col_names)?;
                match op {
                    UOp::Not => Value::Integer(if chk_truthy(&v) { 0 } else { 1 }),
                    UOp::Minus => match v {
                        Value::Integer(i) => Value::Integer(-i),
                        Value::Real(r) => Value::Real(-r),
                        _ => Value::Null,
                    },
                }
            }
            // Complex exprs (functions, subqueries, etc.) 鈫?Null 鈫?check passes
            _ => Value::Null,
        })
    }

    /// L3: Fire triggers for (table_name, timing, event).
    /// body_sql is re-parsed from the persisted trigger definition and executed.
    pub(crate) fn fire_triggers(
        &mut self,
        table_name: &str,
        timing: &crate::sql::ast::TriggerTiming,
        event: &crate::sql::ast::TriggerEvent,
    ) -> crate::error::Result<()> {
        // Collect body SQLs to avoid borrow issues
        let body_sqls: Vec<String> = self
            .schema
            .get_triggers(table_name, timing, event)
            .into_iter()
            .map(|t| t.body_sql.clone())
            .collect();

        for body_sql in body_sqls {
            let mut inner_sql = body_sql.trim();
            if inner_sql.eq_ignore_ascii_case("BEGIN") || inner_sql.eq_ignore_ascii_case("END") {
                continue;
            }
            if inner_sql.to_uppercase().starts_with("BEGIN")
                && inner_sql.to_uppercase().ends_with("END")
            {
                inner_sql = inner_sql[5..inner_sql.len() - 3].trim();
            }

            // Each body_sql may be a semicolon-separated list of statements
            for stmt_sql in inner_sql.split(';') {
                let trimmed = stmt_sql.trim();
                if trimmed.is_empty() {
                    continue;
                }
                let _ = self.execute_sql(trimmed);
            }
        }
        Ok(())
    }

    // L4: Maintain FTS inverted index (Phase 4 — real B-Tree postings)
    pub(crate) fn maintain_fts_insert(
        &mut self,
        table_name: &str,
        rowid: i64,
        row: &[Value],
    ) -> Result<()> {
        // Guard: skip FTS system tables to prevent infinite recursion
        if table_name.starts_with("_kkdb_fts_") {
            return Ok(());
        }

        // --- New Path: CREATE FULLTEXT INDEX (IndexSchema.is_fts) ---
        // Collect all FTS indexes for this table
        let fts_indexes: Vec<(u32, Vec<usize>)> = {
            let fts_idxs: Vec<_> = self
                .schema
                .indexes_for_table(table_name)
                .into_iter()
                .filter(|idx| idx.is_fts)
                .cloned()
                .collect();
            if fts_idxs.is_empty() {
                return Ok(());
            }
            let tbl = self.schema.get_table(table_name)?.clone();
            fts_idxs
                .into_iter()
                .map(|idx| {
                    let col_indices: Vec<usize> = idx
                        .columns
                        .iter()
                        .filter_map(|col_name| {
                            tbl.columns
                                .iter()
                                .find(|c| c.name.eq_ignore_ascii_case(col_name))
                                .map(|c| c.col_index)
                        })
                        .collect();
                    (idx.root_page, col_indices) // root_page is repurposed as index_id for FTS
                })
                .collect()
        };

        for (index_id, col_indices) in fts_indexes {
            // Tokenize the relevant columns
            let mut tf_map: std::collections::HashMap<String, u32> =
                std::collections::HashMap::new();
            let mut field_len: u32 = 0;
            for &ci in &col_indices {
                if let Some(Value::Text(s)) = row.get(ci) {
                    let tokens = crate::fulltext::tokenizer::simple_tokenize(s);
                    field_len += tokens.len() as u32;
                    for token in tokens {
                        *tf_map.entry(token).or_insert(0) += 1;
                    }
                }
            }
            if tf_map.is_empty() {
                continue;
            }

            // Enqueue for deferred write at execute_sql boundary (avoid reentrant execute_sql)
            let tfs: Vec<(String, u32)> = tf_map.into_iter().collect();
            self.pending_fts_inserts
                .push((index_id, rowid, tfs, field_len));
        }
        Ok(())
    }

    pub(crate) fn maintain_fts_delete(&mut self, table_name: &str, rowid: i64) -> Result<()> {
        use crate::storage::btree::BTree;
        // Guard: skip FTS system tables to prevent infinite recursion
        if table_name.starts_with("_kkdb_fts_") {
            return Ok(());
        }

        // --- New Path: CREATE FULLTEXT INDEX ---
        // FTS data is stored directly in B-Tree pages (via self.pager) identified
        // by the FTS index's root_page (= index_id). There is NO schema table for
        // _kkdb_fts_N in the new path; we scan self.pager directly, mirroring
        // how scan_fts_postings / write_fts_postings_raw work.
        let fts_indexes: Vec<u32> = self
            .schema
            .indexes_for_table(table_name)
            .into_iter()
            .filter(|idx| idx.is_fts)
            .map(|idx| idx.root_page) // root_page == index_id for FTS
            .collect();

        for index_id in fts_indexes {
            if index_id == 0 {
                continue;
            }

            // Scan ALL rows in the FTS B-Tree for this index
            let all_fts_rows = {
                let mut btree = BTree::new(&mut self.pager);
                btree.scan_all(index_id).unwrap_or_default()
            };

            let mut rowids_to_delete: Vec<i64> = Vec::new();
            let mut tokens_deleted: std::collections::HashSet<String> =
                std::collections::HashSet::new();
            let mut field_len_deleted: u32 = 0;

            // Row format: [token, doc_id, tf, field_len, meta_key]
            // Posting rows have meta_key = NULL
            // DF rows have meta_key = "DF:<token>"
            // GLOBAL row has meta_key = "GLOBAL"
            for (fts_rowid, fts_row) in &all_fts_rows {
                if let Some(Value::Integer(doc_id)) = fts_row.get(1) {
                    if *doc_id == rowid {
                        // This is a posting row for our doc — mark for deletion
                        if fts_row.get(4) == Some(&Value::Null) {
                            rowids_to_delete.push(*fts_rowid);
                            if let Some(Value::Text(token)) = fts_row.first() {
                                tokens_deleted.insert(token.to_string());
                            }
                            if let Some(Value::Integer(fl)) = fts_row.get(3) {
                                field_len_deleted = *fl as u32;
                            }
                        }
                    }
                }
            }

            // Delete posting rows one by one (root may change after each deletion)
            let mut current_root = index_id;
            for fts_rowid in rowids_to_delete {
                let mut btree = BTree::new(&mut self.pager);
                let (_, new_root) = btree.delete_by_rowid(current_root, fts_rowid)?;
                current_root = new_root;
            }
            // Update the FTS index root_page if it changed after deletion
            if current_root != index_id {
                // Patch the in-memory index schema so future scans use the new root.
                for idx in self.schema.indexes.values_mut() {
                    if idx.is_fts && idx.root_page == index_id {
                        idx.root_page = current_root;
                        break;
                    }
                }
            }

            // Update DF and GLOBAL stats (decrement by 1 doc)
            if !tokens_deleted.is_empty() {
                let (cur_docs, cur_fl) = self.read_fts_global_stats(index_id);
                let new_docs = cur_docs.saturating_sub(1);
                let new_fl = cur_fl.saturating_sub(field_len_deleted as u64);

                let mut new_df_map: std::collections::HashMap<String, u64> =
                    std::collections::HashMap::new();
                for token in &tokens_deleted {
                    let df = self.get_fts_doc_freq(index_id, token);
                    new_df_map.insert(token.clone(), df.saturating_sub(1));
                }

                // Write updated stats (appended — query reads latest)
                let empty_postings = std::collections::HashMap::new();
                self.write_fts_postings(index_id, &empty_postings, &new_df_map, new_docs, new_fl)?;
            }
        }
        Ok(())
    }

    pub(crate) fn tokenize(text: &str) -> Vec<String> {
        crate::fulltext::tokenizer::query_tokenize(text)
    }

    // ── Vector index DML maintenance ──────────────────────────────────────────

    /// Insert a vector from `row` into every HNSW graph registered on `table_name`.
    pub(crate) fn maintain_vec_insert(
        &mut self,
        table_name: &str,
        rowid: i64,
        row: &[Value],
    ) -> Result<()> {
        use crate::vector::index::decode_vector;

        let indexes: Vec<_> = self
            .schema
            .vector_indexes
            .for_table(table_name)
            .into_iter()
            .map(|vi| (vi.col_idx, vi.dim, vi.clone()))
            .collect();

        for (col_idx, dim, vi) in indexes {
            if let Some(Value::Blob(blob)) = row.get(col_idx) {
                if let Some(vec) = decode_vector(blob) {
                    if vec.len() as u32 == dim {
                        let _ = vi.insert_vec(rowid as u64, vec);
                    }
                }
            }
        }
        Ok(())
    }

    /// Lazily delete `rowid` from every HNSW graph registered on `table_name`.
    pub(crate) fn maintain_vec_delete(&mut self, table_name: &str, rowid: i64) {
        let indexes: Vec<_> = self
            .schema
            .vector_indexes
            .for_table(table_name)
            .into_iter().cloned()
            .collect();

        for vi in indexes {
            vi.delete_vec(rowid as u64);
        }
    }
}

fn chk_cmp(l: &crate::types::Value, r: &crate::types::Value) -> i32 {
    use crate::types::Value;
    match (l, r) {
        (Value::Integer(a), Value::Integer(b)) => a.cmp(b) as i32,
        (Value::Real(a), Value::Real(b)) => {
            if a < b {
                -1
            } else if a > b {
                1
            } else {
                0
            }
        }
        (Value::Integer(a), Value::Real(b)) => {
            let af = *a as f64;
            if af < *b {
                -1
            } else if af > *b {
                1
            } else {
                0
            }
        }
        (Value::Real(a), Value::Integer(b)) => {
            let bf = *b as f64;
            if *a < bf {
                -1
            } else if *a > bf {
                1
            } else {
                0
            }
        }
        (Value::Text(a), Value::Text(b)) => {
            if a < b {
                -1
            } else if a > b {
                1
            } else {
                0
            }
        }
        _ => 0,
    }
}

fn chk_arith(
    l: &crate::types::Value,
    r: &crate::types::Value,
    int_op: impl Fn(i64, i64) -> i64,
    float_op: impl Fn(f64, f64) -> f64,
) -> crate::types::Value {
    use crate::types::Value;
    match (l, r) {
        (Value::Integer(a), Value::Integer(b)) => Value::Integer(int_op(*a, *b)),
        (Value::Real(a), Value::Real(b)) => Value::Real(float_op(*a, *b)),
        (Value::Integer(a), Value::Real(b)) => Value::Real(float_op(*a as f64, *b)),
        (Value::Real(a), Value::Integer(b)) => Value::Real(float_op(*a, *b as f64)),
        _ => Value::Null,
    }
}

fn chk_truthy(v: &crate::types::Value) -> bool {
    use crate::types::Value;
    !matches!(v, Value::Integer(0) | Value::Null)
}

//! SELECT statement execution for KKDB.
//!
//! This module implements the full `SELECT` pipeline, including:
//! - **FROM / JOIN evaluation** — table scans, view expansion, hash/nested-loop JOINs,
//!   and subquery materialisation.
//! - **CTE support** — `WITH` (non-recursive) and `WITH RECURSIVE` (UNION ALL loop).
//! - **WHERE / RLS filtering** — predicate pushdown and Row-Level Security policy injection.
//! - **Aggregation** — `GROUP BY`, `HAVING`, implicit aggregation; window functions.
//! - **Projection** — column aliases, expression evaluation via [`super::eval_expr`].
//! - **DISTINCT**, **ORDER BY** (with precomputed sort keys and Top-N optimisation),
//!   **LIMIT / OFFSET**.
//! - **Full-Text Search** — BM25 index scan short-circuit for `FTS_MATCH(...)`.
//! - **Correlated subqueries** — via the [`VM::outer_rows`] stack pushed/popped
//!   during `Exists` / `InSubquery` / scalar subquery evaluation.
//!
//! ## Execution order
//!
//! ```text
//! FROM / JOIN  →  WHERE (+ RLS)  →  GROUP BY + HAVING  →  SELECT (projections)
//!              →  DISTINCT  →  ORDER BY  →  OFFSET  →  LIMIT
//! ```
//!
//! Simple (non-aggregate) queries are sorted **before** projection so that
//! `ORDER BY` can reference any source column, not just the selected ones.

use super::eval_expr::like_match;
use super::execute::{ExecResult, VM};
use crate::error::{KkdbError, Result};
use crate::sql::ast::*;
use crate::storage::btree::BTree;
use crate::types::{Row, Value};
use std::collections::{HashMap, HashSet};

// ── CBO: Join Algorithm Cost Model ──────────────────────────────────────────

/// Supported join algorithms (module-level for cross-module access).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum JoinAlgorithm {
    /// Build a hash table on the smaller side, probe with the larger — O(n+m).
    HashJoin,
    /// For each row in the left, scan all rows in the right — O(n*m).
    NestedLoop,
    /// Both sides sorted on join key; merge in O(n+m).
    SortMergeJoin,
}

impl std::fmt::Display for JoinAlgorithm {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            JoinAlgorithm::HashJoin => write!(f, "Hash Join"),
            JoinAlgorithm::NestedLoop => write!(f, "Nested Loop"),
            JoinAlgorithm::SortMergeJoin => write!(f, "Sort-Merge Join"),
        }
    }
}

/// Nested-loop size threshold: below this, NL is preferred over hash join.
const NL_SIZE_THRESHOLD: usize = 64;

/// Choose the optimal join algorithm using a cost model.
///
/// Parameters:
/// - `left_rows` / `right_rows`: estimated cardinalities
/// - `is_equi`: true if the ON clause is a simple equi-join (a.x = b.y)
/// - `left_sorted_on_key` / `right_sorted_on_key`: true if the scan naturally
///   produces rows in join-key order (e.g. clustered index scan on PK)
pub(crate) fn choose_join_algorithm(
    left_rows: usize,
    right_rows: usize,
    is_equi: bool,
    left_sorted_on_key: bool,
    right_sorted_on_key: bool,
) -> JoinAlgorithm {
    // Non-equi join: can only use nested loop
    if !is_equi {
        return JoinAlgorithm::NestedLoop;
    }

    // Very small tables: nested loop is fine (cache-friendly, no hash overhead)
    if left_rows <= NL_SIZE_THRESHOLD && right_rows <= NL_SIZE_THRESHOLD {
        return JoinAlgorithm::NestedLoop;
    }

    // Both sides sorted on join key: sort-merge is optimal (no extra sort cost)
    if left_sorted_on_key && right_sorted_on_key {
        return JoinAlgorithm::SortMergeJoin;
    }

    // Cost comparison
    let n = left_rows.max(1) as f64;
    let m = right_rows.max(1) as f64;

    let hash_cost = n + m;
    let nl_cost = n * m;
    let sort_merge_cost = if left_sorted_on_key || right_sorted_on_key {
        let unsorted = if left_sorted_on_key { m } else { n };
        unsorted * unsorted.log2() + n + m
    } else {
        n * n.log2() + m * m.log2() + n + m
    };

    if hash_cost <= sort_merge_cost && hash_cost <= nl_cost {
        JoinAlgorithm::HashJoin
    } else if sort_merge_cost <= hash_cost && sort_merge_cost <= nl_cost {
        JoinAlgorithm::SortMergeJoin
    } else {
        JoinAlgorithm::NestedLoop
    }
}

impl VM {
    // ---- SELECT ----

    pub(crate) fn exec_select(&mut self, select_ref: &SelectStmt) -> Result<ExecResult> {
        let mut select_mut = select_ref.clone();
        let mut window_funcs = Vec::new();

        // L7: Evaluate CTEs (WITH clause) — store results in cte_cache
        let ctes_to_eval: Vec<CteDefinition> = std::mem::take(&mut select_mut.ctes);
        for cte in &ctes_to_eval {
            let key = cte.name.to_ascii_lowercase();
            let (mut col_names, rows) = if cte.is_recursive {
                // Recursive CTE: query must be `anchor UNION ALL recursive_part`
                self.eval_recursive_cte(cte)?
            } else {
                // Non-recursive CTE: just evaluate the query once
                match self.exec_select(&cte.query)? {
                    ExecResult::QueryResult { columns, rows } => (columns, rows),
                    _ => (Vec::new(), Vec::new()),
                }
            };
            // Apply declared column name aliases from `cte_name(col1, col2, ...)`
            if !cte.columns.is_empty() {
                for (i, alias) in cte.columns.iter().enumerate() {
                    if i < col_names.len() {
                        col_names[i] = alias.clone();
                    }
                }
            }
            self.cte_cache.insert(key, (col_names, rows));
        }

        for col in &mut select_mut.columns {
            if let SelectColumn::Expr { expr, .. } = col {
                Self::extract_window_funcs(expr, &mut window_funcs);
            }
        }
        for item in &mut select_mut.order_by {
            Self::extract_window_funcs(&mut item.expr, &mut window_funcs);
        }

        // ── O2: Join reordering for INNER JOINs ────────────────────────────
        // Reorder inner joins to put smaller tables first (build side = smaller).
        if let Some(ref mut from) = select_mut.from {
            self.reorder_joins(from);
        }

        let select = &select_mut;

        // Cleanup CTEs from cache after we're done with this SELECT
        // (deferred — we clean up after exec to allow nested references)

        // Check if LIMIT pushdown is safe:
        // no WHERE, no ORDER BY, no GROUP BY, no DISTINCT, no HAVING, simple table FROM
        let limit_pushdown = select.where_clause.is_none()
            && select.order_by.is_empty()
            && select.group_by.is_empty()
            && !select.distinct
            && select.having.is_none()
            && select.limit.is_some()
            && !Self::has_aggregate(&select.columns);

        // Track if a FTS index scan handled the full WHERE so we can skip post-scan re-eval.
        let mut fts_index_scan_used = false;

        // Get the source rows
        let (mut rows, col_names) = if let Some(ref from) = select.from {
            // ── Q3: COUNT(*) fast path ──────────────────────────────────────────
            // Detect: SELECT COUNT(*) FROM t  (no WHERE, GROUP BY, DISTINCT, HAVING)
            let is_count_star = select.where_clause.is_none()
                && select.group_by.is_empty()
                && !select.distinct
                && select.having.is_none()
                && select.columns.len() == 1
                && {
                    {
                        let col = &select.columns[0];
                        if let SelectColumn::Expr {
                            expr: Expr::Function { name, args, .. },
                            ..
                        } = col
                        {
                            name.eq_ignore_ascii_case("count")
                                && (args.is_empty()
                                    || matches!(args.first(), Some(Expr::IntegerLiteral(1))))
                        } else {
                            false
                        }
                    }
                };
            if is_count_star {
                if let FromClause::Table { name, .. } = from {
                    // S-NEW-2 fix: skip fast path if RLS is enabled on this table
                    let rls_on = self
                        .schema
                        .get_table(name)
                        .map(|t| t.rls_enabled)
                        .unwrap_or(false);
                    if !rls_on {
                        let table_root = self.schema.get_table(name)?.root_page;
                        let mut btree = BTree::new(self.get_table_pager_mut(name));
                        let count = btree.count_rows(table_root)? as i64;
                        return Ok(ExecResult::QueryResult {
                            columns: vec!["COUNT(*)".to_string()],
                            rows: vec![vec![Value::Integer(count)]],
                        });
                    }
                }
            }
            // ────────────────────────────────────────────────────────────────────
            if limit_pushdown {
                // LIMIT pushdown: scan only as many rows as needed
                if let FromClause::Table { name, .. } = from {
                    // S-NEW-3 fix: skip fast path if RLS is enabled on this table
                    let rls_on = self
                        .schema
                        .get_table(name)
                        .map(|t| t.rls_enabled)
                        .unwrap_or(false);
                    if !rls_on {
                        let empty = Vec::new();
                        let empty_map = HashMap::new();
                        // SAFETY: `limit_pushdown` is true only when `select.limit.is_some()`
                        let limit_val = match self.eval_expr(
                            select.limit.as_ref().unwrap(),
                            &empty,
                            &empty_map,
                        )? {
                            Value::Integer(v) if v >= 0 => v as usize,
                            _ => usize::MAX,
                        };
                        let offset_val = if let Some(ref offset_expr) = select.offset {
                            match self.eval_expr(offset_expr, &empty, &empty_map)? {
                                Value::Integer(v) if v > 0 => v as usize,
                                _ => 0,
                            }
                        } else {
                            0
                        };
                        let total_needed = limit_val.saturating_add(offset_val);
                        let (col_names, root_page) = {
                            let table = self.schema.get_table(name)?;
                            (table.col_names.clone(), table.root_page)
                        };
                        let mut btree = BTree::new(self.get_table_pager_mut(name));
                        let rows = btree.scan_rows_limit(root_page, total_needed)?;
                        (rows, col_names)
                    } else {
                        self.eval_from(from)?
                    }
                } else {
                    self.eval_from(from)?
                }
            } else if let Some(ref where_expr) = select.where_clause {
                // Try index-accelerated scan for simple WHERE conditions.
                // For FTS MATCH queries the index scan already filters and ranks rows;
                // we MUST NOT re-apply the WHERE clause (that path does literal string
                // containment, which would incorrectly drop OR-matched rows).
                let fts_handled = Self::where_is_fts_match(where_expr);
                if let Some(result) = self.try_index_scan(from, where_expr)? {
                    if fts_handled {
                        fts_index_scan_used = true;
                    }
                    (result.0, result.1)
                } else {
                    self.eval_from(from)?
                }
            } else {
                self.eval_from(from)?
            }
        } else {
            // SELECT without FROM - single row with no columns
            (vec![Vec::new()], Vec::new())
        };
        // For simple single-table FROM (no JOIN), extract rowids in parallel so that
        // VEC_SEARCH can look up each row's score by setting self.current_rowid.
        // JOINs / subqueries / CTEs get rowid 0 (VEC_SEARCH simply returns 0 there).
        let row_ids: Vec<i64> = if !rows.is_empty() {
            match &select.from {
                Some(FromClause::Table { name, .. })
                    if !self.cte_cache.contains_key(&name.to_ascii_lowercase()) =>
                {
                    let (root_page, _is_view) = {
                        if let Ok(t) = self.schema.get_table(name.as_str()) {
                            (t.root_page, t.view_select.is_some())
                        } else {
                            (0, false)
                        }
                    };
                    if root_page == 0 {
                        vec![0i64; rows.len()]
                    } else {
                        let with_ids = {
                            let p = self.get_table_pager_mut(name.as_str());
                            let mut bt = crate::storage::btree::BTree::new(p);
                            bt.scan_all(root_page).unwrap_or_default()
                        };
                        with_ids.into_iter().map(|(id, _)| id).collect()
                    }
                }
                _ => vec![0i64; rows.len()],
            }
        } else {
            Vec::new()
        };

        // Build column name mapping (avoid to_lowercase heap alloc)
        let mut col_map: HashMap<String, usize> = HashMap::with_capacity(col_names.len());
        for (i, name) in col_names.iter().enumerate() {
            if name.bytes().any(|b| b.is_ascii_uppercase()) {
                let mut lower = String::with_capacity(name.len());
                for b in name.bytes() {
                    lower.push(b.to_ascii_lowercase() as char);
                }
                col_map.insert(lower, i);
            } else {
                col_map.insert(name.clone(), i);
            }
        }

        // Inject table-qualified names (e.g. "t1.id") for correct column resolution in JOINs
        if let Some(ref from) = select.from {
            let mut offset = 0;
            self.inject_qualified_names(from, &col_names, &mut col_map, &mut offset);
        }

        // ── Q6: Rewrite non-correlated IN (subquery) → IN (list) ──────────────────
        // If InSubquery does not reference any outer columns, run the subquery
        // once and replace with InList to avoid O(rows * subquery) complexity.
        // ── RLS: inject USING predicates for tables with RLS enabled ────────────
        let mut rewritten_where = select.where_clause.clone();
        // If a FTS index scan already produced semantically-correct rows, do NOT
        // re-apply the WHERE clause (eval_expr for FtsMatch does literal containment
        // which would incorrectly drop OR-matched rows).
        if fts_index_scan_used {
            rewritten_where = None;
        }
        if let Some(ref mut where_expr) = rewritten_where {
            self.rewrite_uncorrelated_subqueries(where_expr, &col_names)?;
        }

        // Inject RLS policy USING expressions as additional WHERE conditions.
        // B12-3 fix: collect ALL base tables (including JOIN legs) so RLS cannot be bypassed
        // by wrapping a protected table inside a JOIN expression.
        if let Some(ref from) = select.from {
            let base_tables = Self::collect_base_tables(from);
            let current_user = self
                .session_vars
                .get("request.jwt.sub")
                .or_else(|| self.session_vars.get("kkdb.current_user"))
                .cloned()
                .unwrap_or_default();
            for tname in &base_tables {
                let tbl_key: String = tname.to_ascii_lowercase();
                let rls_exprs: Vec<crate::sql::ast::Expr> =
                    if let Some(tbl) = self.schema.tables.get(&tbl_key) {
                        if tbl.rls_enabled {
                            tbl.policies
                                .iter()
                                .filter(|p| {
                                    p.role.is_none() || p.role.as_deref() == Some(&current_user)
                                })
                                .filter_map(|p| p.using_expr.clone())
                                .collect()
                        } else {
                            Vec::new()
                        }
                    } else {
                        Vec::new()
                    };
                // Combine all USING expressions with AND
                for using_expr in rls_exprs {
                    rewritten_where = Some(match rewritten_where.take() {
                        None => using_expr,
                        Some(existing) => Expr::BinaryOp {
                            left: Box::new(existing),
                            op: BinaryOperator::And,
                            right: Box::new(using_expr),
                        },
                    });
                }
            }
        }

        // R6: Track active row IDs for FOR UPDATE locking
        let mut active_row_ids = row_ids.clone();

        // Apply WHERE filter
        if let Some(ref where_expr) = rewritten_where {
            let mut filtered = Vec::with_capacity(rows.len());
            let mut filtered_ids = Vec::with_capacity(rows.len());
            // Use zip to pair rows with their rowids for VEC_SEARCH support.
            let zipped: Vec<(i64, Vec<Value>)> = if row_ids.len() == rows.len() {
                row_ids.iter().copied().zip(rows).collect()
            } else {
                rows.into_iter().map(|r| (0i64, r)).collect()
            };
            for (rowid, row) in zipped {
                self.current_rowid = rowid;
                let val = self.eval_expr(where_expr, &row, &col_map)?;
                if val.is_truthy() {
                    filtered.push(row);
                    filtered_ids.push(rowid);
                }
            }
            rows = filtered;
            // R6: preserve filtered rowids for FOR UPDATE row-lock acquisition.
            // (also kept for future ORDER BY VEC_SEARCH support)
            active_row_ids = filtered_ids;
        }

        // For simple (non-aggregate, non-group-by) queries, sort source rows BEFORE projection.
        // This lets ORDER BY reference any column in the source table (not just selected ones).
        // For aggregate/group-by, we sort output_rows after projection as before.
        let pre_sort = !select.order_by.is_empty()
            && select.group_by.is_empty()
            && !Self::has_aggregate(&select.columns);

        if pre_sort {
            let order_exprs: Vec<(&Expr, bool)> = select
                .order_by
                .iter()
                .map(|item| (&item.expr, item.ascending))
                .collect();
            let top_n_limit = if let Some(ref limit_expr) = select.limit {
                match self.eval_expr(limit_expr, &Vec::new(), &HashMap::new())? {
                    Value::Integer(v) if v >= 0 => {
                        let offset = if let Some(ref off_expr) = select.offset {
                            match self.eval_expr(off_expr, &Vec::new(), &HashMap::new())? {
                                Value::Integer(v) if v > 0 => v as usize,
                                _ => 0,
                            }
                        } else {
                            0
                        };
                        Some((v as usize).saturating_add(offset))
                    }
                    _ => None,
                }
            } else {
                None
            };

            // Build sort keys (evaluate ORDER BY expressions against source rows).
            // We materialise keys once per row to avoid repeated evaluation in the comparator.
            let mut keyed: Vec<(Vec<Value>, Row)> = rows
                .into_iter()
                .enumerate()
                .map(|(i, row)| {
                    // Set current_rowid so VEC_SEARCH in ORDER BY works correctly.
                    self.current_rowid = *row_ids.get(i).unwrap_or(&0);
                    let keys: Vec<Value> = order_exprs
                        .iter()
                        .map(|(expr, _)| {
                            self.eval_expr(expr, &row, &col_map).unwrap_or(Value::Null)
                        })
                        .collect();
                    (keys, row)
                })
                .collect();

            // B12-4 fix: capture nulls_first info alongside ascending, and use
            // compare_value_pair so that NULLS FIRST/LAST is respected.
            let sort_params: Vec<(bool, Option<bool>)> = select
                .order_by
                .iter()
                .map(|item| (item.ascending, item.nulls_first))
                .collect();

            let cmp_fn = |a: &(Vec<Value>, Row), b: &(Vec<Value>, Row)| {
                for (i, &(ascending, nulls_first)) in sort_params.iter().enumerate() {
                    let ord = Self::compare_value_pair(&a.0[i], &b.0[i], nulls_first, ascending);
                    if ord != std::cmp::Ordering::Equal {
                        return ord;
                    }
                }
                std::cmp::Ordering::Equal
            };

            if let Some(k) = top_n_limit {
                if k == 0 {
                    keyed.clear();
                } else if k < keyed.len() {
                    keyed.select_nth_unstable_by(k - 1, cmp_fn);
                    keyed.truncate(k);
                    keyed.sort_by(cmp_fn);
                } else {
                    keyed.sort_by(cmp_fn);
                }
            } else {
                keyed.sort_by(cmp_fn);
            }

            rows = keyed.into_iter().map(|(_, r)| r).collect();
        }

        let (output_col_names, mut output_rows) = if !select.group_by.is_empty() {
            self.apply_group_by(
                &rows,
                &select.group_by,
                &select.columns,
                &col_names,
                &col_map,
                &select.having,
                &window_funcs,
                &select.window_defs,
            )?
        } else if Self::has_aggregate(&select.columns) {
            // Implicit aggregation: no GROUP BY but SELECT contains aggregates
            // Treat all rows as a single group, return one output row
            self.apply_implicit_aggregate(
                &rows,
                &select.columns,
                &col_names,
                &col_map,
                &window_funcs,
                &select.window_defs,
            )?
        } else {
            self.project_columns(
                &select.columns,
                rows,
                &col_names,
                &col_map,
                false,
                &window_funcs,
                &select.window_defs,
            )?
        };

        // Apply DISTINCT
        if select.distinct {
            let mut seen = std::collections::HashSet::new();
            let mut key_buf = String::with_capacity(128);
            let mut val_buf = String::with_capacity(32);
            output_rows.retain(|row| {
                    key_buf.clear();
                    for v in row {
                        Self::typed_key_into(v, &mut val_buf);
                        key_buf.push_str(&val_buf);
                        key_buf.push('\0');
                    }
                    seen.insert(key_buf.clone())
                });
        }

        // Apply ORDER BY (aggregate/group-by path only — simple SELECT was sorted pre-projection)
        if !select.order_by.is_empty() && !pre_sort {
            let output_col_map: HashMap<String, usize> = output_col_names
                .iter()
                .enumerate()
                .map(|(i, name)| (name.to_lowercase(), i))
                .collect();

            // B-NEW-3 fix: precompute ORDER BY key values to support integer positions,
            // column names, aggregate functions, and arbitrary expressions.
            // We std::mem::take the rows so &mut self is free for eval_expr calls.
            let rows_snapshot = std::mem::take(&mut output_rows);
            let mut keyed_rows: Vec<(Vec<Value>, Vec<Value>)> = rows_snapshot
                .into_iter()
                .map(|row| {
                    let keys: Vec<Value> = select
                        .order_by
                        .iter()
                        .map(|item| match &item.expr {
                            // ORDER BY <integer> — 1-indexed column position
                            Expr::IntegerLiteral(n) => {
                                let idx = (*n as usize).saturating_sub(1);
                                row.get(idx).cloned().unwrap_or(Value::Null)
                            }
                            // ORDER BY <column_name>
                            Expr::ColumnRef { column, .. } => {
                                let lower = column.to_ascii_lowercase();
                                output_col_map
                                    .get(lower.as_str())
                                    .and_then(|&i| row.get(i).cloned())
                                    .unwrap_or(Value::Null)
                            }
                            // ORDER BY <expression> (COUNT(*), SUM, BinaryOp, etc.)
                            expr => self
                                .eval_expr(expr, &row, &output_col_map)
                                .unwrap_or(Value::Null),
                        })
                        .collect();
                    (keys, row)
                })
                .collect();

            let order_by_items = &select.order_by;
            let top_n_limit = if let Some(ref limit_expr) = select.limit {
                let limit_val = match self.eval_expr(limit_expr, &Vec::new(), &HashMap::new())? {
                    Value::Integer(v) if v >= 0 => Some(v as usize),
                    _ => None,
                };
                if let Some(limit) = limit_val {
                    let offset = if let Some(ref offset_expr) = select.offset {
                        match self.eval_expr(offset_expr, &Vec::new(), &HashMap::new())? {
                            Value::Integer(v) if v > 0 => v as usize,
                            _ => 0,
                        }
                    } else {
                        0
                    };
                    Some(limit.saturating_add(offset))
                } else {
                    None
                }
            } else {
                None
            };

            let compare_keyed =
                |(ka, _): &(Vec<Value>, Vec<Value>), (kb, _): &(Vec<Value>, Vec<Value>)| {
                    for (i, item) in order_by_items.iter().enumerate() {
                        let a = ka.get(i).unwrap_or(&Value::Null);
                        let b = kb.get(i).unwrap_or(&Value::Null);
                        let ord = Self::compare_value_pair(a, b, item.nulls_first, item.ascending);
                        if ord != std::cmp::Ordering::Equal {
                            return ord;
                        }
                    }
                    std::cmp::Ordering::Equal
                };

            if let Some(k) = top_n_limit {
                if k == 0 {
                    keyed_rows.clear();
                } else if k < keyed_rows.len() {
                    keyed_rows.select_nth_unstable_by(k - 1, compare_keyed);
                    keyed_rows.truncate(k);
                    keyed_rows.sort_by(compare_keyed);
                } else {
                    keyed_rows.sort_by(compare_keyed);
                }
            } else {
                keyed_rows.sort_by(compare_keyed);
            }

            output_rows = keyed_rows.into_iter().map(|(_, row)| row).collect();
        }

        // Apply OFFSET
        if let Some(ref offset_expr) = select.offset {
            let empty_row: Vec<Value> = Vec::new();
            let empty_map: HashMap<String, usize> = HashMap::new();
            let offset = match self.eval_expr(offset_expr, &empty_row, &empty_map)? {
                Value::Integer(v) if v > 0 => v as usize,
                _ => 0,
            };
            if offset < output_rows.len() {
                output_rows = output_rows.split_off(offset);
            } else {
                output_rows.clear();
            }
        }

        // Apply LIMIT
        if let Some(ref limit_expr) = select.limit {
            let limit = match self.eval_expr(limit_expr, &Vec::new(), &HashMap::new())? {
                Value::Integer(v) if v >= 0 => v as usize,
                _ => output_rows.len(), // negative LIMIT = no limit (SQLite behavior)
            };
            output_rows.truncate(limit);
        }

        // P-NEW-1 fix: clean up only the CTE keys inserted by this SELECT invocation.
        // Do NOT call cte_cache.clear() — nested/recursive CTEs may still be in use.
        for cte in &ctes_to_eval {
            self.cte_cache.remove(&cte.name.to_ascii_lowercase());
        }

        // R6: SELECT ... FOR UPDATE — acquire exclusive row locks on result rows
        if select.for_update && self.current_txn_id != 0 {
            if let Some(FromClause::Table { ref name, .. }) = select.from {
                let txn_id = self.current_txn_id;
                for &rid in &active_row_ids {
                    if rid != 0 {
                        self.row_lock_manager
                            .try_lock_row(name, rid, txn_id)
                            .map_err(|e| crate::error::KkdbError::LockConflict(e.to_string()))?;
                    }
                }
            }
        }

        Ok(ExecResult::QueryResult {
            columns: output_col_names,
            rows: output_rows,
        })
    }

    /// Write a type-prefixed string key for a Value into an existing buffer (zero-alloc)
    #[inline]
    pub(crate) fn typed_key_into(v: &Value, buf: &mut String) {
        buf.clear();
        match v {
            Value::Null => buf.push('N'),
            Value::Integer(i) => {
                buf.push('I');
                use std::fmt::Write;
                let _ = write!(buf, "{}", i);
            }
            Value::Text(t) => {
                buf.push('T');
                buf.push_str(t);
            }
            Value::Real(r) => {
                buf.push('R');
                use std::fmt::Write;
                let _ = write!(buf, "{}", r);
            }
            Value::Blob(b) => {
                buf.push('B');
                for byte in b {
                    use std::fmt::Write;
                    let _ = write!(buf, "{:02x}", byte);
                }
            }
        }
    }

    /// B12-3: Recursively collect all base table names from a FROM clause.
    /// This ensures RLS policies are applied even when tables are accessed via JOINs.
    fn collect_base_tables(from: &FromClause) -> Vec<String> {
        match from {
            FromClause::Table { name, .. } => vec![name.clone()],
            FromClause::Join { left, right, .. } => {
                let mut names = Self::collect_base_tables(left);
                names.extend(Self::collect_base_tables(right));
                names
            }
            // Subqueries/table functions have their own RLS context; skip here.
            _ => vec![],
        }
    }

    #[inline]
    /// Compare a single pair of Values with NULL semantics and direction.
    /// Used by the precomputed ORDER BY key approach (B-NEW-3 fix).
    fn compare_value_pair(
        a: &Value,
        b: &Value,
        nulls_first: Option<bool>,
        ascending: bool,
    ) -> std::cmp::Ordering {
        let a_null = matches!(a, Value::Null);
        let b_null = matches!(b, Value::Null);
        if a_null || b_null {
            if a_null && b_null {
                return std::cmp::Ordering::Equal;
            }
            let nf = nulls_first.unwrap_or(!ascending);
            return if a_null {
                if nf {
                    std::cmp::Ordering::Less
                } else {
                    std::cmp::Ordering::Greater
                }
            } else if nf {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Less
            };
        }
        match a.partial_cmp(b) {
            Some(std::cmp::Ordering::Equal) | None => std::cmp::Ordering::Equal,
            Some(ord) => {
                if ascending {
                    ord
                } else {
                    ord.reverse()
                }
            }
        }
    }

    /// L7: Evaluate a recursive CTE (WITH RECURSIVE name AS (anchor UNION ALL recursive_part))
    ///
    /// The CTE's query is a `SelectStmt` whose `from` is a `SetOp { stmt: UNION ALL, alias: __setop__ }`.
    /// We extract the left (anchor) and right (recursive) parts, evaluate anchor first, then
    /// iterate the recursive part using the last iteration's rows until no new rows are produced.
    fn eval_recursive_cte(
        &mut self,
        cte: &CteDefinition,
    ) -> Result<(Vec<String>, Vec<crate::types::Row>)> {
        use crate::sql::ast::SetOpKind;

        // The CTE query body can be either a SetOp wrapping a UNION ALL, or
        // a SelectStmt whose FROM is a SetOp.  We detect the latter case.
        let (anchor_query, recursive_query) = {
            // Check if the query's FROM is a SetOp(__setop__) — this is what the parser generates
            // for `WITH RECURSIVE t AS (anchor UNION ALL rec_part)`
            let q = &cte.query;
            if let Some(crate::sql::ast::FromClause::SetOp { stmt, .. }) = q.from.as_ref() {
                if matches!(stmt.kind, SetOpKind::UnionAll | SetOpKind::UnionDistinct) {
                    (
                        stmt.left.as_ref().clone(),
                        Some(stmt.right.as_ref().clone()),
                    )
                } else {
                    // Non-union: just evaluate once (non-recursive)
                    return match self.exec_select(&cte.query)? {
                        ExecResult::QueryResult { columns, rows } => Ok((columns, rows)),
                        _ => Ok((Vec::new(), Vec::new())),
                    };
                }
            } else {
                // No SetOp in FROM — treat as non-recursive
                return match self.exec_select(&cte.query)? {
                    ExecResult::QueryResult { columns, rows } => Ok((columns, rows)),
                    _ => Ok((Vec::new(), Vec::new())),
                };
            }
        };

        // 1. Evaluate anchor
        let (mut col_names, mut all_rows) = match self.exec_select(&anchor_query)? {
            ExecResult::QueryResult { columns, rows } => (columns, rows),
            _ => return Ok((Vec::new(), Vec::new())),
        };

        // Apply declared column name aliases from `WITH RECURSIVE name(col1, col2, ...)` clause
        // This must be done early so the recursive part can reference columns by the declared names
        if !cte.columns.is_empty() {
            for (i, alias) in cte.columns.iter().enumerate() {
                if i < col_names.len() {
                    col_names[i] = alias.clone();
                }
            }
        }

        // 2. Install working table in cte_cache so the recursive part can reference `cte.name`
        let cte_key = cte.name.to_ascii_lowercase();

        if let Some(ref rec_q) = recursive_query {
            let mut iteration_rows = all_rows.clone();
            const MAX_RECURSION_DEPTH: usize = 1000;

            for _ in 0..MAX_RECURSION_DEPTH {
                if iteration_rows.is_empty() {
                    break;
                }
                // Expose current iteration as the CTE working table
                self.cte_cache
                    .insert(cte_key.clone(), (col_names.clone(), iteration_rows.clone()));

                let next = match self.exec_select(rec_q)? {
                    ExecResult::QueryResult { rows, .. } => rows,
                    _ => break,
                };

                if next.is_empty() {
                    break;
                }
                all_rows.extend(next.clone());
                iteration_rows = next;
            }
        }

        Ok((col_names, all_rows))
    }

    /// Evaluate FROM clause - returns (rows, column_names)
    fn eval_from(&mut self, from: &FromClause) -> Result<(Vec<Row>, Vec<String>)> {
        match from {
            FromClause::Table { name, alias: _ } => {
                // L7: Check CTE cache first — CTEs shadow real tables by name
                let cte_key = name.to_ascii_lowercase();
                if let Some((cols, rows)) = self.cte_cache.get(&cte_key).cloned() {
                    return Ok((rows, cols));
                }

                // Batch E: if this is a view, expand by calling its stored SELECT
                let (is_view, view_query) = {
                    if let Ok(t) = self.schema.get_table(name) {
                        if let Some(ref qs) = t.view_select {
                            (true, Some(qs.clone()))
                        } else {
                            (false, None)
                        }
                    } else {
                        (false, None)
                    }
                };
                if is_view {
                    if let Some(q) = view_query {
                        let result = self.exec_select(&q)?;
                        return match result {
                            ExecResult::QueryResult { columns, rows } => Ok((rows, columns)),
                            _ => Err(KkdbError::Internal("view did not return rows".into())),
                        };
                    }
                }

                let (col_names, root_page) = {
                    let table = self.schema.get_table(name)?;
                    (table.col_names.clone(), table.root_page)
                };

                // MVCC snapshot-isolation: scan with rowids so we can apply visibility
                let rows = if self.mvcc_snapshot.is_some() {
                    let (invisible, restored) = {
                        let snapshot = self.mvcc_snapshot.as_ref().unwrap();
                        crate::vm::mvcc::compute_visibility_delta(
                            &self.mvcc_undo_log,
                            snapshot,
                            name,
                        )
                    };
                    let mut btree = BTree::new(self.get_table_pager_mut(name));
                    let all_rows = btree.scan_all(root_page)?;
                    let mut visible: Vec<Row> = all_rows
                        .into_iter()
                        .filter(|(rowid, _)| !invisible.contains(rowid))
                        .map(|(_, row)| row)
                        .collect();
                    // Restore rows deleted by invisible transactions
                    for (_rowid, row) in restored {
                        visible.push(row);
                    }
                    visible
                } else {
                    let mut btree = BTree::new(self.get_table_pager_mut(name));
                    btree.scan_rows(root_page)?
                };

                Ok((rows, col_names))
            }
            FromClause::Join {
                left,
                join_type,
                right,
                on,
            } => {
                let (left_rows, left_cols) = self.eval_from(left)?;
                let (right_rows, right_cols) = self.eval_from(right)?;

                let mut combined_cols = Vec::with_capacity(left_cols.len() + right_cols.len());
                combined_cols.extend_from_slice(&left_cols);
                combined_cols.extend_from_slice(&right_cols);

                let mut combined_col_map: HashMap<String, usize> =
                    HashMap::with_capacity(combined_cols.len());
                for (i, name) in combined_cols.iter().enumerate() {
                    if name.bytes().any(|b| b.is_ascii_uppercase()) {
                        let mut lower = String::with_capacity(name.len());
                        for b in name.bytes() {
                            lower.push(b.to_ascii_lowercase() as char);
                        }
                        combined_col_map.insert(lower, i);
                    } else {
                        combined_col_map.insert(name.clone(), i);
                    }
                }

                // Inject table-qualified names for correct column resolution in ON conditions
                let mut offset = 0;
                self.inject_qualified_names(
                    left,
                    &combined_cols,
                    &mut combined_col_map,
                    &mut offset,
                );
                self.inject_qualified_names(
                    right,
                    &combined_cols,
                    &mut combined_col_map,
                    &mut offset,
                );

                let combined_width = left_cols.len() + right_cols.len();
                let mut result_rows = Vec::new();

                // Try hash join for equi-join conditions (ON a.col = b.col)
                let equi_join_indices =
                    Self::detect_equi_join(on.as_ref(), &combined_col_map, left_cols.len());

                match join_type {
                    JoinType::Inner | JoinType::Cross => {
                        if let Some((left_idx, right_idx)) = equi_join_indices {
                            // Hash JOIN: build hash on right, probe with left — O(n+m)
                            let mut key_buf = String::with_capacity(32);
                            let mut hash: HashMap<String, Vec<usize>> =
                                HashMap::with_capacity(right_rows.len());
                            for (ri, right_row) in right_rows.iter().enumerate() {
                                if matches!(right_row[right_idx], Value::Null) {
                                    continue;
                                }
                                Self::typed_key_into(&right_row[right_idx], &mut key_buf);
                                hash.entry(key_buf.clone())
                                    .or_default()
                                    .push(ri);
                            }
                            for left_row in &left_rows {
                                if matches!(left_row[left_idx], Value::Null) {
                                    continue;
                                }
                                Self::typed_key_into(&left_row[left_idx], &mut key_buf);
                                if let Some(indices) = hash.get(key_buf.as_str()) {
                                    for &ri in indices {
                                        let mut combined = Vec::with_capacity(combined_width);
                                        combined.extend_from_slice(left_row);
                                        combined.extend_from_slice(&right_rows[ri]);
                                        result_rows.push(combined);
                                    }
                                }
                            }
                        } else {
                            for left_row in &left_rows {
                                for right_row in &right_rows {
                                    let mut combined = Vec::with_capacity(combined_width);
                                    combined.extend_from_slice(left_row);
                                    combined.extend_from_slice(right_row);
                                    if let Some(ref on_expr) = on {
                                        let val =
                                            self.eval_expr(on_expr, &combined, &combined_col_map)?;
                                        if val.is_truthy() {
                                            result_rows.push(combined);
                                        }
                                    } else {
                                        result_rows.push(combined);
                                    }
                                }
                            }
                        }
                    }
                    JoinType::Left => {
                        let null_right: Vec<Value> = vec![Value::Null; right_cols.len()];
                        if let Some((left_idx, right_idx)) = equi_join_indices {
                            let mut key_buf = String::with_capacity(32);
                            let mut hash: HashMap<String, Vec<usize>> =
                                HashMap::with_capacity(right_rows.len());
                            for (ri, right_row) in right_rows.iter().enumerate() {
                                if matches!(right_row[right_idx], Value::Null) {
                                    continue;
                                }
                                Self::typed_key_into(&right_row[right_idx], &mut key_buf);
                                hash.entry(key_buf.clone())
                                    .or_default()
                                    .push(ri);
                            }
                            for left_row in &left_rows {
                                if matches!(left_row[left_idx], Value::Null) {
                                    let mut combined = Vec::with_capacity(combined_width);
                                    combined.extend_from_slice(left_row);
                                    combined.extend_from_slice(&null_right);
                                    result_rows.push(combined);
                                    continue;
                                }
                                Self::typed_key_into(&left_row[left_idx], &mut key_buf);
                                if let Some(indices) = hash.get(key_buf.as_str()) {
                                    for &ri in indices {
                                        let mut combined = Vec::with_capacity(combined_width);
                                        combined.extend_from_slice(left_row);
                                        combined.extend_from_slice(&right_rows[ri]);
                                        result_rows.push(combined);
                                    }
                                } else {
                                    let mut combined = Vec::with_capacity(combined_width);
                                    combined.extend_from_slice(left_row);
                                    combined.extend_from_slice(&null_right);
                                    result_rows.push(combined);
                                }
                            }
                        } else {
                            for left_row in &left_rows {
                                let mut matched = false;
                                for right_row in &right_rows {
                                    let mut combined = Vec::with_capacity(combined_width);
                                    combined.extend_from_slice(left_row);
                                    combined.extend_from_slice(right_row);
                                    if let Some(ref on_expr) = on {
                                        let val =
                                            self.eval_expr(on_expr, &combined, &combined_col_map)?;
                                        if val.is_truthy() {
                                            result_rows.push(combined);
                                            matched = true;
                                        }
                                    } else {
                                        result_rows.push(combined);
                                        matched = true;
                                    }
                                }
                                if !matched {
                                    let mut combined = Vec::with_capacity(combined_width);
                                    combined.extend_from_slice(left_row);
                                    combined.extend_from_slice(&null_right);
                                    result_rows.push(combined);
                                }
                            }
                        }
                    }
                    JoinType::Right => {
                        let null_left: Vec<Value> = vec![Value::Null; left_cols.len()];
                        if let Some((left_idx, right_idx)) = equi_join_indices {
                            let mut key_buf = String::with_capacity(32);
                            let mut hash: HashMap<String, Vec<usize>> =
                                HashMap::with_capacity(left_rows.len());
                            for (li, left_row) in left_rows.iter().enumerate() {
                                if matches!(left_row[left_idx], Value::Null) {
                                    continue;
                                }
                                Self::typed_key_into(&left_row[left_idx], &mut key_buf);
                                hash.entry(key_buf.clone())
                                    .or_default()
                                    .push(li);
                            }
                            for right_row in &right_rows {
                                if matches!(right_row[right_idx], Value::Null) {
                                    let mut combined = Vec::with_capacity(combined_width);
                                    combined.extend_from_slice(&null_left);
                                    combined.extend_from_slice(right_row);
                                    result_rows.push(combined);
                                    continue;
                                }
                                Self::typed_key_into(&right_row[right_idx], &mut key_buf);
                                if let Some(indices) = hash.get(key_buf.as_str()) {
                                    for &li in indices {
                                        let mut combined = Vec::with_capacity(combined_width);
                                        combined.extend_from_slice(&left_rows[li]);
                                        combined.extend_from_slice(right_row);
                                        result_rows.push(combined);
                                    }
                                } else {
                                    let mut combined = Vec::with_capacity(combined_width);
                                    combined.extend_from_slice(&null_left);
                                    combined.extend_from_slice(right_row);
                                    result_rows.push(combined);
                                }
                            }
                        } else {
                            for right_row in &right_rows {
                                let mut matched = false;
                                for left_row in &left_rows {
                                    let mut combined = Vec::with_capacity(combined_width);
                                    combined.extend_from_slice(left_row);
                                    combined.extend_from_slice(right_row);
                                    if let Some(ref on_expr) = on {
                                        let val =
                                            self.eval_expr(on_expr, &combined, &combined_col_map)?;
                                        if val.is_truthy() {
                                            result_rows.push(combined);
                                            matched = true;
                                        }
                                    } else {
                                        result_rows.push(combined);
                                        matched = true;
                                    }
                                }
                                if !matched {
                                    let mut combined = Vec::with_capacity(combined_width);
                                    combined.extend_from_slice(&null_left);
                                    combined.extend_from_slice(right_row);
                                    result_rows.push(combined);
                                }
                            }
                        }
                    }
                    JoinType::LeftSemi => {
                        // LeftSemi: return left row if it matches AT LEAST ONE right row. Do not join right columns.
                        if let Some((left_idx, right_idx)) = equi_join_indices {
                            let mut key_buf = String::with_capacity(32);
                            let mut hash: HashMap<String, ()> =
                                HashMap::with_capacity(right_rows.len());
                            for right_row in right_rows.iter() {
                                if matches!(right_row[right_idx], Value::Null) {
                                    continue;
                                }
                                Self::typed_key_into(&right_row[right_idx], &mut key_buf);
                                hash.insert(key_buf.clone(), ());
                            }
                            for left_row in &left_rows {
                                if matches!(left_row[left_idx], Value::Null) {
                                    continue;
                                }
                                Self::typed_key_into(&left_row[left_idx], &mut key_buf);
                                if hash.contains_key(key_buf.as_str()) {
                                    result_rows.push(left_row.clone());
                                }
                            }
                        } else {
                            for left_row in &left_rows {
                                for right_row in &right_rows {
                                    let mut combined = Vec::with_capacity(combined_width);
                                    combined.extend_from_slice(left_row);
                                    combined.extend_from_slice(right_row);
                                    if let Some(ref on_expr) = on {
                                        let val =
                                            self.eval_expr(on_expr, &combined, &combined_col_map)?;
                                        if val.is_truthy() {
                                            result_rows.push(left_row.clone());
                                            break; // only need one match for Semi
                                        }
                                    } else {
                                        result_rows.push(left_row.clone());
                                        break;
                                    }
                                }
                            }
                        }
                        // For semi joins, the result schema is ONLY the left side
                        combined_cols.truncate(left_cols.len());
                    }
                    JoinType::RightSemi => {
                        // RightSemi: return right row if it matches AT LEAST ONE left row. Do not join left columns.
                        if let Some((left_idx, right_idx)) = equi_join_indices {
                            let mut key_buf = String::with_capacity(32);
                            let mut hash: HashMap<String, ()> =
                                HashMap::with_capacity(left_rows.len());
                            for left_row in left_rows.iter() {
                                if matches!(left_row[left_idx], Value::Null) {
                                    continue;
                                }
                                Self::typed_key_into(&left_row[left_idx], &mut key_buf);
                                hash.insert(key_buf.clone(), ());
                            }
                            for right_row in &right_rows {
                                if matches!(right_row[right_idx], Value::Null) {
                                    continue;
                                }
                                Self::typed_key_into(&right_row[right_idx], &mut key_buf);
                                if hash.contains_key(key_buf.as_str()) {
                                    result_rows.push(right_row.clone());
                                }
                            }
                        } else {
                            for right_row in &right_rows {
                                for left_row in &left_rows {
                                    let mut combined = Vec::with_capacity(combined_width);
                                    combined.extend_from_slice(left_row);
                                    combined.extend_from_slice(right_row);
                                    if let Some(ref on_expr) = on {
                                        let val =
                                            self.eval_expr(on_expr, &combined, &combined_col_map)?;
                                        if val.is_truthy() {
                                            result_rows.push(right_row.clone());
                                            break;
                                        }
                                    } else {
                                        result_rows.push(right_row.clone());
                                        break;
                                    }
                                }
                            }
                        }
                        // For RightSemi, the result schema is ONLY the right side
                        combined_cols = right_cols.clone();
                    }
                    // Batch C: FULL OUTER JOIN = LEFT JOIN rows + right-side rows not matched
                    JoinType::Full => {
                        let null_left: Vec<Value> = vec![Value::Null; left_cols.len()];
                        let null_right: Vec<Value> = vec![Value::Null; right_cols.len()];
                        let mut right_matched = vec![false; right_rows.len()];
                        for left_row in &left_rows {
                            let mut matched = false;
                            for (ri, right_row) in right_rows.iter().enumerate() {
                                let mut combined = Vec::with_capacity(combined_width);
                                combined.extend_from_slice(left_row);
                                combined.extend_from_slice(right_row);
                                let include = if let Some(ref cond) = on {
                                    self.eval_expr(cond, &combined, &combined_col_map)?
                                        .is_truthy()
                                } else {
                                    true
                                };
                                if include {
                                    result_rows.push(combined);
                                    matched = true;
                                    right_matched[ri] = true;
                                }
                            }
                            if !matched {
                                let mut combined = Vec::with_capacity(combined_width);
                                combined.extend_from_slice(left_row);
                                combined.extend_from_slice(&null_right);
                                result_rows.push(combined);
                            }
                        }
                        for (ri, matched) in right_matched.iter().enumerate() {
                            if !matched {
                                let mut combined = Vec::with_capacity(combined_width);
                                combined.extend_from_slice(&null_left);
                                combined.extend_from_slice(&right_rows[ri]);
                                result_rows.push(combined);
                            }
                        }
                    }
                    // Batch C: NATURAL JOIN — join on all common column names
                    JoinType::Natural => {
                        let common_cols: Vec<(usize, usize)> = left_cols
                            .iter()
                            .enumerate()
                            .filter_map(|(li, lname)| {
                                right_cols
                                    .iter()
                                    .position(|rname| rname.eq_ignore_ascii_case(lname))
                                    .map(|ri| (li, ri))
                            })
                            .collect();
                        // D-NEW-6 fix: right-side columns that duplicate join keys should be excluded
                        let right_shared: std::collections::HashSet<usize> =
                            common_cols.iter().map(|(_, ri)| *ri).collect();
                        for left_row in &left_rows {
                            'outer: for right_row in &right_rows {
                                for (li, ri) in &common_cols {
                                    if left_row[*li] != right_row[*ri] {
                                        continue 'outer;
                                    }
                                }
                                let mut combined = Vec::with_capacity(combined_width);
                                combined.extend_from_slice(left_row);
                                for (ri, val) in right_row.iter().enumerate() {
                                    if !right_shared.contains(&ri) {
                                        combined.push(val.clone());
                                    }
                                }
                                result_rows.push(combined);
                            }
                        }
                        // Build deduplicated column list
                        let cols_fixed: Vec<String> = left_cols
                            .iter()
                            .cloned()
                            .chain(
                                right_cols
                                    .iter()
                                    .enumerate()
                                    .filter(|(ri, _)| !right_shared.contains(ri))
                                    .map(|(_, name)| name.clone()),
                            )
                            .collect();
                        return Ok((result_rows, cols_fixed));
                    }
                }

                Ok((result_rows, combined_cols))
            }
            FromClause::Subquery { query, alias: _ } => {
                let result = self.exec_select(query)?;
                match result {
                    ExecResult::QueryResult { columns, rows } => Ok((rows, columns)),
                    _ => Err(KkdbError::Internal("subquery did not return rows".into())),
                }
            }
            // Batch B: nested UNION / INTERSECT / EXCEPT used as a FROM source
            FromClause::SetOp { stmt, alias: _ } => {
                let result = self.exec_set_op(stmt)?;
                match result {
                    ExecResult::QueryResult { columns, rows } => Ok((rows, columns)),
                    _ => Err(KkdbError::Internal("set-op did not return rows".into())),
                }
            }
            // #15: Table-valued functions — UNNEST / generate_series
            FromClause::TableFunction {
                name,
                args,
                alias,
                column,
            } => {
                let empty_row: Vec<Value> = Vec::new();
                let empty_map: HashMap<String, usize> = HashMap::new();

                // Evaluate all args up front
                let mut eval_args = Vec::with_capacity(args.len());
                for a in args {
                    eval_args.push(self.eval_expr(a, &empty_row, &empty_map)?);
                }

                let func_upper = name.to_ascii_uppercase();
                let col_name = column
                    .as_deref()
                    .unwrap_or(match func_upper.as_str() {
                        "UNNEST" => "unnest",
                        "GENERATE_SERIES" => "generate_series",
                        _ => "value",
                    })
                    .to_string();

                // Optional alias-qualified column name for the col_map (t.col)
                let _qualified = alias
                    .as_ref()
                    .map(|a| format!("{}.{}", a.to_lowercase(), col_name.to_lowercase()));

                let rows: Vec<Row> = match func_upper.as_str() {
                    "UNNEST" => {
                        // UNNEST(array_value) — expand a JSON array or comma-separated list into rows
                        let arr_val = eval_args.into_iter().next().unwrap_or(Value::Null);
                        Self::unnest_value(arr_val)
                            .into_iter()
                            .map(|v| vec![v])
                            .collect()
                    }
                    "GENERATE_SERIES" => {
                        // generate_series(start, stop[, step])
                        let start = match eval_args.first() {
                            Some(Value::Integer(v)) => *v,
                            Some(Value::Real(v)) => *v as i64,
                            _ => {
                                return Err(KkdbError::RuntimeError(
                                    "generate_series: start must be integer".into(),
                                ))
                            }
                        };
                        let stop = match eval_args.get(1) {
                            Some(Value::Integer(v)) => *v,
                            Some(Value::Real(v)) => *v as i64,
                            _ => {
                                return Err(KkdbError::RuntimeError(
                                    "generate_series: stop must be integer".into(),
                                ))
                            }
                        };
                        let step = match eval_args.get(2) {
                            Some(Value::Integer(v)) => *v,
                            Some(Value::Real(v)) => *v as i64,
                            None => 1,
                            _ => 1,
                        };
                        if step == 0 {
                            return Err(KkdbError::RuntimeError(
                                "generate_series: step must not be zero".into(),
                            ));
                        }
                        let mut rows = Vec::new();
                        let mut cur = start;
                        // Cap at 1 million rows for safety
                        while (step > 0 && cur <= stop) || (step < 0 && cur >= stop) {
                            rows.push(vec![Value::Integer(cur)]);
                            cur = match cur.checked_add(step) {
                                Some(v) => v,
                                None => break,
                            };
                            if rows.len() >= 1_000_000 {
                                break;
                            }
                        }
                        rows
                    }
                    other => {
                        return Err(KkdbError::RuntimeError(format!(
                            "unsupported table function `{other}` (supported: UNNEST, generate_series)"
                        )));
                    }
                };

                let col_names = vec![col_name];
                Ok((rows, col_names))
            }
        }
    }

    /// Expand a Value into a list of values for UNNEST:
    /// - JSON array `[1, 2, 3]` → elements
    /// - Comma-separated string `a,b,c` → trimmed parts
    /// - Any scalar → single-element list
    fn unnest_value(val: Value) -> Vec<Value> {
        match val {
            Value::Text(s) => {
                let trimmed = s.trim();
                if trimmed.starts_with('[') && trimmed.ends_with(']') {
                    // Parse JSON array: simple tokenizer (handles strings, numbers, null, bool)
                    let inner = &trimmed[1..trimmed.len() - 1];
                    let mut result = Vec::new();
                    let mut chars = inner.chars().peekable();
                    let mut token = String::new();
                    let mut in_string = false;
                    let mut escape = false;
                    loop {
                        match chars.next() {
                            None => {
                                let t = token.trim();
                                if !t.is_empty() {
                                    result.push(Self::parse_json_scalar(t));
                                }
                                break;
                            }
                            Some('\\') if in_string => {
                                escape = true;
                                token.push('\\');
                            }
                            Some(c) if escape => {
                                escape = false;
                                token.push(c);
                            }
                            Some('"') => {
                                in_string = !in_string;
                                token.push('"');
                            }
                            Some(',') if !in_string => {
                                let t = token.trim();
                                if !t.is_empty() {
                                    result.push(Self::parse_json_scalar(t));
                                }
                                token.clear();
                            }
                            Some(c) => {
                                token.push(c);
                            }
                        }
                    }
                    result
                } else {
                    // CSV: split on commas
                    s.split(',')
                        .map(|p| Value::Text(p.trim().to_string().into()))
                        .collect()
                }
            }
            Value::Null => Vec::new(),
            scalar => vec![scalar],
        }
    }

    /// Parse a single JSON scalar token to a Value.
    fn parse_json_scalar(s: &str) -> Value {
        let s = s.trim();
        if s == "null" {
            return Value::Null;
        }
        if s == "true" {
            return Value::Integer(1);
        }
        if s == "false" {
            return Value::Integer(0);
        }
        // Quoted string
        if s.starts_with('"') && s.ends_with('"') && s.len() >= 2 {
            return Value::Text(s[1..s.len() - 1].replace("\\\"", "\"").into());
        }
        // Number
        if let Ok(i) = s.parse::<i64>() {
            return Value::Integer(i);
        }
        if let Ok(f) = s.parse::<f64>() {
            return Value::Real(f);
        }
        Value::Text(s.to_string().into())
    }

    /// Walk the FROM tree and inject "table.column" qualified entries into col_map.
    /// This enables table-qualified column references like `t1.id` in JOINs.
    fn inject_qualified_names(
        &self,
        from: &FromClause,
        col_names: &[String],
        col_map: &mut HashMap<String, usize>,
        offset: &mut usize,
    ) {
        match from {
            FromClause::Table { name, alias } => {
                if let Ok(table) = self.schema.get_table(name) {
                    let ncols = table.columns.len();
                    let mut buf = String::with_capacity(name.len() + 32);
                    for i in 0..ncols {
                        let idx = *offset + i;
                        if idx < col_names.len() {
                            // Build "name.col" without format!
                            buf.clear();
                            for b in name.bytes() {
                                buf.push(b.to_ascii_lowercase() as char);
                            }
                            buf.push('.');
                            for b in col_names[idx].bytes() {
                                buf.push(b.to_ascii_lowercase() as char);
                            }
                            col_map.insert(buf.clone(), idx);
                            if let Some(a) = alias {
                                buf.clear();
                                for b in a.bytes() {
                                    buf.push(b.to_ascii_lowercase() as char);
                                }
                                buf.push('.');
                                for b in col_names[idx].bytes() {
                                    buf.push(b.to_ascii_lowercase() as char);
                                }
                                col_map.insert(buf.clone(), idx);
                            }
                        }
                    }
                    *offset += ncols;
                }
            }
            FromClause::Join { left, right, .. } => {
                self.inject_qualified_names(left, col_names, col_map, offset);
                self.inject_qualified_names(right, col_names, col_map, offset);
            }
            FromClause::Subquery { query, alias } => {
                if let Some(ncols) = self.count_select_output_columns(query) {
                    let mut buf = String::with_capacity(alias.len() + 32);
                    for i in 0..ncols {
                        let idx = *offset + i;
                        if idx < col_names.len() {
                            buf.clear();
                            for b in alias.bytes() {
                                buf.push(b.to_ascii_lowercase() as char);
                            }
                            buf.push('.');
                            for b in col_names[idx].bytes() {
                                buf.push(b.to_ascii_lowercase() as char);
                            }
                            col_map.insert(buf.clone(), idx);

                            // Also insert unqualified name if not already present
                            // This allows window functions like `PARTITION BY category` to work
                            let unqual = col_names[idx].to_ascii_lowercase();
                            col_map.entry(unqual).or_insert(idx);
                        }
                    }
                    *offset += ncols;
                }
            }
            // Batch B: SetOp - columns unknown statically, skip injection
            FromClause::SetOp { .. } => {}
            // TableFunction: 1 column, qualified as alias.col
            FromClause::TableFunction {
                alias,
                column,
                name,
                ..
            } => {
                let col_label =
                    column
                        .as_deref()
                        .unwrap_or_else(|| match name.to_ascii_uppercase().as_str() {
                            "UNNEST" => "unnest",
                            "GENERATE_SERIES" => "generate_series",
                            _ => "value",
                        });
                let table_ref = alias.as_deref().unwrap_or(name.as_str());
                if *offset < col_names.len() {
                    col_map.insert(
                        format!("{}.{}", table_ref.to_lowercase(), col_label.to_lowercase()),
                        *offset,
                    );
                }
                *offset += 1;
            }
        }
    }

    /// Count the number of output columns a SELECT statement would produce (statically).
    fn count_select_output_columns(&self, query: &SelectStmt) -> Option<usize> {
        let mut count = 0;
        for col in &query.columns {
            match col {
                SelectColumn::Expr { .. } => count += 1,
                SelectColumn::AllColumns => {
                    count += self.count_from_columns(query.from.as_ref()?)?;
                }
                SelectColumn::TableAllColumns(table) => {
                    count += self.schema.get_table(table).ok()?.columns.len();
                }
            }
        }
        Some(count)
    }

    /// Count total columns produced by a FROM clause (statically).
    fn count_from_columns(&self, from: &FromClause) -> Option<usize> {
        match from {
            FromClause::Table { name, .. } => Some(self.schema.get_table(name).ok()?.columns.len()),
            FromClause::Join { left, right, .. } => {
                Some(self.count_from_columns(left)? + self.count_from_columns(right)?)
            }
            FromClause::Subquery { query, .. } => self.count_select_output_columns(query),
            // Batch B: SetOp column count unknown statically
            FromClause::SetOp { .. } => None,
            // TableFunction always emits exactly 1 column
            FromClause::TableFunction { .. } => Some(1),
        }
    }

    /// Returns column indices belonging to a given table name, using qualified names in col_map.
    /// Returns None if no qualified names found (fallback to all columns).
    fn table_column_indices(
        table: &str,
        col_names: &[String],
        col_map: &HashMap<String, usize>,
    ) -> Option<Vec<usize>> {
        let mut buf = String::with_capacity(table.len() + 32);
        let mut indices = Vec::new();
        for (idx, name) in col_names.iter().enumerate() {
            buf.clear();
            for b in table.bytes() {
                buf.push(b.to_ascii_lowercase() as char);
            }
            buf.push('.');
            for b in name.bytes() {
                buf.push(b.to_ascii_lowercase() as char);
            }
            if col_map.get(buf.as_str()) == Some(&idx) {
                indices.push(idx);
            }
        }
        if indices.is_empty() {
            None
        } else {
            Some(indices)
        }
    }

    /// Detect if a JOIN ON condition is a simple equi-join (col_a = col_b).
    /// Returns (left_col_index, right_col_index_in_right_table) if detected.
    fn detect_equi_join(
        on: Option<&Expr>,
        col_map: &HashMap<String, usize>,
        left_col_count: usize,
    ) -> Option<(usize, usize)> {
        let on_expr = on?;
        if let Expr::BinaryOp {
            left,
            op: BinaryOperator::Equal,
            right,
        } = on_expr
        {
            if let (
                Expr::ColumnRef {
                    table: lt,
                    column: lc,
                },
                Expr::ColumnRef {
                    table: rt,
                    column: rc,
                },
            ) = (left.as_ref(), right.as_ref())
            {
                // Try qualified lookup first, then plain name
                let mut buf = String::with_capacity(32);
                let li = lt
                    .as_ref()
                    .and_then(|t| {
                        buf.clear();
                        for b in t.bytes() {
                            buf.push(b.to_ascii_lowercase() as char);
                        }
                        buf.push('.');
                        for b in lc.bytes() {
                            buf.push(b.to_ascii_lowercase() as char);
                        }
                        col_map.get(buf.as_str())
                    })
                    .or_else(|| {
                        buf.clear();
                        for b in lc.bytes() {
                            buf.push(b.to_ascii_lowercase() as char);
                        }
                        col_map.get(buf.as_str())
                    })
                    .or_else(|| col_map.get(lc.as_str()))?;
                let ri = rt
                    .as_ref()
                    .and_then(|t| {
                        buf.clear();
                        for b in t.bytes() {
                            buf.push(b.to_ascii_lowercase() as char);
                        }
                        buf.push('.');
                        for b in rc.bytes() {
                            buf.push(b.to_ascii_lowercase() as char);
                        }
                        col_map.get(buf.as_str())
                    })
                    .or_else(|| {
                        buf.clear();
                        for b in rc.bytes() {
                            buf.push(b.to_ascii_lowercase() as char);
                        }
                        col_map.get(buf.as_str())
                    })
                    .or_else(|| col_map.get(rc.as_str()))?;
                // One index must be in left table, other in right table
                if *li < left_col_count && *ri >= left_col_count {
                    return Some((*li, *ri - left_col_count));
                }
                if *ri < left_col_count && *li >= left_col_count {
                    return Some((*ri, *li - left_col_count));
                }
            }
        }
        None
    }

    /// Check if a table scan can produce rows sorted by a given column
    /// (i.e. the column is the primary key / rowid, which is the clustered index).
    fn is_scan_sorted_on_column(
        &self,
        from: &FromClause,
        col_name: &str,
    ) -> bool {
        if let FromClause::Table { name, .. } = from {
            let table_name = name.to_lowercase();
            if let Ok(table) = self.schema.get_table(&table_name) {
                // In KKDB the B-Tree is keyed by rowid (INTEGER PRIMARY KEY).
                // If the join key IS the primary key column, scan is sorted.
                if let Some(pk) = table.primary_key_column() {
                    return pk.to_ascii_lowercase() == col_name.to_ascii_lowercase();
                }
            }
        }
        false
    }

    /// Estimate the row count of a FROM source using schema stats.
    pub(crate) fn estimate_from_row_count(&self, from: &FromClause) -> usize {
        match from {
            FromClause::Table { name, .. } => {
                let table_name = name.to_lowercase();
                if let Ok(table) = self.schema.get_table(&table_name) {
                    table.columns.first()
                        .and_then(|c| c.stats.as_ref())
                        .map(|s| s.total_count as usize)
                        .unwrap_or(100) // default estimate if no stats
                } else {
                    100
                }
            }
            FromClause::Join { .. } => 1000, // default for sub-joins
            FromClause::Subquery { .. } => 100,
            _ => 100,
        }
    }

    /// Check if both sides of a join are sorted on the join key (simplified).
    /// Returns (left_sorted, right_sorted).
    pub(crate) fn check_join_key_sorted(
        &self,
        left: &FromClause,
        right: &FromClause,
        on_expr: &Expr,
    ) -> (bool, bool) {
        // Extract column names from equi-join condition
        if let Expr::BinaryOp {
            left: ref l_expr,
            op: BinaryOperator::Equal,
            right: ref r_expr,
        } = on_expr
        {
            let l_col = match l_expr.as_ref() {
                Expr::ColumnRef { column, .. } => Some(column.as_str()),
                _ => None,
            };
            let r_col = match r_expr.as_ref() {
                Expr::ColumnRef { column, .. } => Some(column.as_str()),
                _ => None,
            };
            let left_sorted = l_col.map_or(false, |c| self.is_scan_sorted_on_column(left, c))
                || r_col.map_or(false, |c| self.is_scan_sorted_on_column(left, c));
            let right_sorted = r_col.map_or(false, |c| self.is_scan_sorted_on_column(right, c))
                || l_col.map_or(false, |c| self.is_scan_sorted_on_column(right, c));
            (left_sorted, right_sorted)
        } else {
            (false, false)
        }
    }

    /// Project columns from source rows into output rows
    #[allow(clippy::too_many_arguments)]
    fn project_columns(
        &mut self,
        select_cols: &[SelectColumn],
        rows: Vec<Row>,
        col_names: &[String],
        col_map: &HashMap<String, usize>,
        _is_aggregate: bool,
        window_funcs: &[Expr],
        window_defs: &[NamedWindowDefinition],
    ) -> Result<(Vec<String>, Vec<Row>)> {
        // Build a projection plan: either copy by index (cheap) or evaluate expression
        enum Proj<'a> {
            Index(usize),
            Expr(&'a Expr),
        }
        let mut output_names = Vec::new();
        let mut plan: Vec<Proj> = Vec::new();

        for col in select_cols {
            match col {
                SelectColumn::AllColumns => {
                    for (i, name) in col_names.iter().enumerate() {
                        output_names.push(name.clone());
                        plan.push(Proj::Index(i));
                    }
                }
                SelectColumn::TableAllColumns(table) => {
                    if let Some(indices) = Self::table_column_indices(table, col_names, col_map) {
                        for &idx in &indices {
                            output_names.push(col_names[idx].clone());
                            plan.push(Proj::Index(idx));
                        }
                    } else {
                        for (i, name) in col_names.iter().enumerate() {
                            output_names.push(name.clone());
                            plan.push(Proj::Index(i));
                        }
                    }
                }
                SelectColumn::Expr { expr, alias } => {
                    let name = alias
                        .clone()
                        .unwrap_or_else(|| self.expr_display_name(expr));
                    output_names.push(name);
                    plan.push(Proj::Expr(expr));
                }
            }
        }

        // Fast path: if plan is identity projection (all sequential indices 0..N),
        // just move rows directly without cloning any values
        let is_identity = plan.len() == col_names.len()
            && plan
                .iter()
                .enumerate()
                .all(|(i, p)| matches!(p, Proj::Index(idx) if *idx == i));

        if is_identity && window_funcs.is_empty() {
            return Ok((output_names, rows));
        }

        let win_groups: Vec<Vec<&Row>> = rows.iter().map(|r| vec![r]).collect();
        let win_res =
            self.eval_window_functions_for_groups(window_funcs, &win_groups, col_map, window_defs)?;
        self.window_results = Some(win_res);

        let num_out_cols = plan.len();
        let mut output_rows = Vec::with_capacity(rows.len());
        for (idx, row) in rows.iter().enumerate() {
            self.current_window_row_idx = idx;
            let mut out_row = Vec::with_capacity(num_out_cols);
            for p in &plan {
                match p {
                    Proj::Index(idx) => {
                        out_row.push(if *idx < row.len() {
                            row[*idx].clone()
                        } else {
                            Value::Null
                        });
                    }
                    Proj::Expr(expr) => {
                        out_row.push(self.eval_expr(expr, row, col_map)?);
                    }
                }
            }
            output_rows.push(out_row);
        }

        Ok((output_names, output_rows))
    }

    /// Check if any SELECT column contains an aggregate function
    fn has_aggregate(cols: &[SelectColumn]) -> bool {
        for col in cols {
            if let SelectColumn::Expr { expr, .. } = col {
                if Self::expr_has_aggregate(expr) {
                    return true;
                }
            }
        }
        false
    }

    /// Convert a Value back into a literal Expr (for aggregate-aware function evaluation)
    fn value_to_expr(val: Value) -> Expr {
        match val {
            Value::Integer(v) => Expr::IntegerLiteral(v),
            Value::Real(v) => Expr::RealLiteral(v),
            Value::Text(s) => Expr::StringLiteral(s.to_string()),
            Value::Null => Expr::Null,
            Value::Blob(b) => Expr::BlobLiteral(b),
        }
    }

    /// Recursively check if an expression contains an aggregate function
    fn expr_has_aggregate(expr: &Expr) -> bool {
        match expr {
            Expr::Function { name, args, .. } => {
                let n = name.as_str();
                if n.eq_ignore_ascii_case("COUNT")
                    || n.eq_ignore_ascii_case("SUM")
                    || n.eq_ignore_ascii_case("AVG")
                    || n.eq_ignore_ascii_case("MIN")
                    || n.eq_ignore_ascii_case("MAX")
                {
                    return true;
                }
                // Recurse into non-aggregate function args (e.g. ABS(COUNT(*)))
                args.iter().any(Self::expr_has_aggregate)
            }
            Expr::BinaryOp { left, right, .. } => {
                Self::expr_has_aggregate(left) || Self::expr_has_aggregate(right)
            }
            Expr::UnaryOp { expr, .. } => Self::expr_has_aggregate(expr),
            Expr::Nested(inner) => Self::expr_has_aggregate(inner),
            Expr::IsNull { expr, .. } => Self::expr_has_aggregate(expr),
            Expr::InList { expr, list, .. } => {
                Self::expr_has_aggregate(expr) || list.iter().any(Self::expr_has_aggregate)
            }
            Expr::Between {
                expr, low, high, ..
            } => {
                Self::expr_has_aggregate(expr)
                    || Self::expr_has_aggregate(low)
                    || Self::expr_has_aggregate(high)
            }
            Expr::Like { expr, pattern, .. } => {
                Self::expr_has_aggregate(expr) || Self::expr_has_aggregate(pattern)
            }
            Expr::InSubquery { expr, .. } => Self::expr_has_aggregate(expr),
            // Subquery/Exists have their own aggregation context
            _ => false,
        }
    }

    /// Get a display name for an expression
    fn expr_display_name(&self, expr: &Expr) -> String {
        match expr {
            Expr::ColumnRef {
                table: Some(_),
                column,
            } => column.clone(),
            Expr::ColumnRef { column, .. } => column.clone(),
            Expr::Function { name, .. } => name.clone(),
            Expr::IntegerLiteral(v) => format!("{}", v),
            Expr::RealLiteral(v) => format!("{}", v),
            Expr::StringLiteral(v) => format!("'{}'", v),
            _ => "?".to_string(),
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn apply_group_by(
        &mut self,
        rows: &[Row],
        group_exprs: &[Expr],
        select_cols: &[SelectColumn],
        col_names: &[String],
        col_map: &HashMap<String, usize>,
        having: &Option<Expr>,
        window_funcs: &[Expr],
        window_defs: &[NamedWindowDefinition],
    ) -> Result<(Vec<String>, Vec<Row>)> {
        // Build alias → expression map from SELECT column list.
        // This lets GROUP BY reference aliases defined in SELECT (e.g. GROUP BY doubled).
        let alias_map: HashMap<String, &Expr> = select_cols
            .iter()
            .filter_map(|c| {
                if let SelectColumn::Expr {
                    expr,
                    alias: Some(a),
                } = c
                {
                    Some((a.to_ascii_lowercase(), expr))
                } else {
                    None
                }
            })
            .collect();

        // Group rows by the GROUP BY expressions (store references, not clones)
        let mut group_index: HashMap<String, usize> = HashMap::new();
        let mut groups: Vec<Vec<&Row>> = Vec::new();
        let mut key_buf = String::with_capacity(128);
        let mut val_buf = String::with_capacity(32);

        for row in rows {
            key_buf.clear();
            for expr in group_exprs {
                // If the GROUP BY term is a bare column reference that matches a
                // SELECT alias, evaluate the aliased expression instead.
                let resolved: &Expr = if let Expr::ColumnRef {
                    column,
                    table: None,
                } = expr
                {
                    let lower = column.to_ascii_lowercase();
                    alias_map.get(lower.as_str()).copied().unwrap_or(expr)
                } else {
                    expr
                };
                let v = self.eval_expr(resolved, row, col_map)?;
                Self::typed_key_into(&v, &mut val_buf);
                key_buf.push_str(&val_buf);
                key_buf.push('\0');
            }

            if let Some(&idx) = group_index.get(key_buf.as_str()) {
                groups[idx].push(row);
            } else {
                let idx = groups.len();
                group_index.insert(key_buf.clone(), idx);
                groups.push(vec![row]);
            }
        }

        // Build output column names
        let mut output_names = Vec::new();
        for col in select_cols {
            match col {
                SelectColumn::AllColumns => {
                    for name in col_names {
                        output_names.push(name.clone());
                    }
                }
                SelectColumn::TableAllColumns(table) => {
                    if let Some(indices) = Self::table_column_indices(table, col_names, col_map) {
                        for &idx in &indices {
                            output_names.push(col_names[idx].clone());
                        }
                    } else {
                        for name in col_names {
                            output_names.push(name.clone());
                        }
                    }
                }
                SelectColumn::Expr { expr, alias } => {
                    let name = alias
                        .clone()
                        .unwrap_or_else(|| self.expr_display_name(expr));
                    output_names.push(name);
                }
            }
        }

        let win_res =
            self.eval_window_functions_for_groups(window_funcs, &groups, col_map, window_defs)?;
        self.window_results = Some(win_res);

        // For each group, build a fully projected output row
        let mut result = Vec::new();
        for (g_idx, group_rows) in groups.iter().enumerate() {
            self.current_window_row_idx = g_idx;
            let first_row = &group_rows[0];

            // Apply HAVING (uses eval_expr_with_aggregates which correctly computes aggregates)
            if let Some(ref having_expr) = having {
                let val =
                    self.eval_expr_with_aggregates(having_expr, first_row, col_map, group_rows)?;
                if !val.is_truthy() {
                    continue;
                }
            }

            // Project each SELECT column
            let mut out_row = Vec::with_capacity(output_names.len());
            for col in select_cols {
                match col {
                    SelectColumn::AllColumns => {
                        for i in 0..col_names.len() {
                            out_row.push(if i < first_row.len() {
                                first_row[i].clone()
                            } else {
                                Value::Null
                            });
                        }
                    }
                    SelectColumn::TableAllColumns(table) => {
                        if let Some(indices) = Self::table_column_indices(table, col_names, col_map)
                        {
                            for &idx in &indices {
                                out_row.push(if idx < first_row.len() {
                                    first_row[idx].clone()
                                } else {
                                    Value::Null
                                });
                            }
                        } else {
                            for i in 0..col_names.len() {
                                out_row.push(if i < first_row.len() {
                                    first_row[i].clone()
                                } else {
                                    Value::Null
                                });
                            }
                        }
                    }
                    SelectColumn::Expr { expr, .. } => {
                        let val =
                            self.eval_expr_with_aggregates(expr, first_row, col_map, group_rows)?;
                        out_row.push(val);
                    }
                }
            }

            result.push(out_row);
        }

        Ok((output_names, result))
    }

    /// Handle implicit aggregation (SELECT with aggregates but no GROUP BY)
    /// Treats all rows as a single group, returns one output row
    fn apply_implicit_aggregate(
        &mut self,
        rows: &[Row],
        select_cols: &[SelectColumn],
        col_names: &[String],
        col_map: &HashMap<String, usize>,
        window_funcs: &[Expr],
        window_defs: &[NamedWindowDefinition],
    ) -> Result<(Vec<String>, Vec<Row>)> {
        // Build output column names
        let mut output_names = Vec::new();
        for col in select_cols {
            match col {
                SelectColumn::AllColumns => {
                    for name in col_names {
                        output_names.push(name.clone());
                    }
                }
                SelectColumn::TableAllColumns(table) => {
                    if let Some(indices) = Self::table_column_indices(table, col_names, col_map) {
                        for &idx in &indices {
                            output_names.push(col_names[idx].clone());
                        }
                    } else {
                        for name in col_names {
                            output_names.push(name.clone());
                        }
                    }
                }
                SelectColumn::Expr { expr, alias } => {
                    let name = alias
                        .clone()
                        .unwrap_or_else(|| self.expr_display_name(expr));
                    output_names.push(name);
                }
            }
        }

        let row_refs: Vec<&Row> = rows.iter().collect();
        let win_groups = vec![row_refs.clone()];
        let win_res =
            self.eval_window_functions_for_groups(window_funcs, &win_groups, col_map, window_defs)?;
        self.window_results = Some(win_res);
        self.current_window_row_idx = 0;

        // Use first row (or empty row) for non-aggregate column evaluation
        let empty_row: Vec<Value> = Vec::new();
        let first_row = rows.first().unwrap_or(&empty_row);

        // Build single output row (use eval_expr_with_aggregates to handle nested aggregates)
        let mut out_row = Vec::with_capacity(output_names.len());
        for col in select_cols {
            match col {
                SelectColumn::AllColumns => {
                    for i in 0..col_names.len() {
                        out_row.push(if i < first_row.len() {
                            first_row[i].clone()
                        } else {
                            Value::Null
                        });
                    }
                }
                SelectColumn::TableAllColumns(table) => {
                    if let Some(indices) = Self::table_column_indices(table, col_names, col_map) {
                        for &idx in &indices {
                            out_row.push(if idx < first_row.len() {
                                first_row[idx].clone()
                            } else {
                                Value::Null
                            });
                        }
                    } else {
                        for i in 0..col_names.len() {
                            out_row.push(if i < first_row.len() {
                                first_row[i].clone()
                            } else {
                                Value::Null
                            });
                        }
                    }
                }
                SelectColumn::Expr { expr, .. } => {
                    let row_refs: Vec<&Row> = rows.iter().collect();
                    let val =
                        self.eval_expr_with_aggregates(expr, first_row, col_map, &row_refs)?;
                    out_row.push(val);
                }
            }
        }

        Ok((output_names, vec![out_row]))
    }

    /// Evaluate an aggregate function over a group
    fn eval_aggregate(
        &mut self,
        name: &str,
        args: &[Expr],
        distinct: bool,
        group_rows: &[&Row],
        col_map: &HashMap<String, usize>,
    ) -> Result<Value> {
        // Use eq_ignore_ascii_case to avoid to_uppercase() allocation
        if name.eq_ignore_ascii_case("COUNT") {
            if args.is_empty() || matches!(args[0], Expr::IntegerLiteral(1)) {
                Ok(Value::Integer(group_rows.len() as i64))
            } else {
                let mut count = 0i64;
                let mut seen = std::collections::HashSet::new();
                let mut key_buf = String::with_capacity(32);
                for row in group_rows {
                    let val = self.eval_expr(&args[0], row, col_map)?;
                    if !matches!(val, Value::Null) {
                        if distinct {
                            Self::typed_key_into(&val, &mut key_buf);
                            if seen.insert(key_buf.clone()) {
                                count += 1;
                            }
                        } else {
                            count += 1;
                        }
                    }
                }
                Ok(Value::Integer(count))
            }
        } else if name.eq_ignore_ascii_case("SUM") {
            if args.is_empty() {
                return Ok(Value::Null);
            }
            let mut int_sum = 0i64;
            let mut real_sum = 0.0f64;
            let mut is_int = true;
            let mut has_value = false;
            for row in group_rows {
                let val = self.eval_expr(&args[0], row, col_map)?;
                match val {
                    Value::Integer(v) => {
                        if is_int {
                            // D-NEW-1 fix: checked_add to avoid silent overflow; promote to Real
                            match int_sum.checked_add(v) {
                                Some(s) => int_sum = s,
                                None => {
                                    real_sum = int_sum as f64 + v as f64;
                                    is_int = false;
                                }
                            }
                        } else {
                            real_sum += v as f64;
                        }
                        has_value = true;
                    }
                    Value::Real(v) => {
                        if is_int {
                            real_sum = int_sum as f64 + v;
                            is_int = false;
                        } else {
                            real_sum += v;
                        }
                        has_value = true;
                    }
                    Value::Null => {}
                    _ => {
                        if let Some(v) = val.to_f64() {
                            if is_int {
                                real_sum = int_sum as f64 + v;
                                is_int = false;
                            } else {
                                real_sum += v;
                            }
                            has_value = true;
                        }
                    }
                }
            }
            if !has_value {
                return Ok(Value::Null);
            }
            if is_int {
                Ok(Value::Integer(int_sum))
            } else {
                Ok(Value::Real(real_sum))
            }
        } else if name.eq_ignore_ascii_case("AVG") {
            if args.is_empty() {
                return Ok(Value::Null);
            }
            let mut sum = 0.0f64;
            let mut count = 0i64;
            for row in group_rows {
                let val = self.eval_expr(&args[0], row, col_map)?;
                if let Some(v) = val.to_f64() {
                    sum += v;
                    count += 1;
                }
            }
            if count == 0 {
                Ok(Value::Null)
            } else {
                Ok(Value::Real(sum / count as f64))
            }
        } else if name.eq_ignore_ascii_case("MIN") {
            if args.is_empty() {
                return Ok(Value::Null);
            }
            let mut min_val: Option<Value> = None;
            for row in group_rows {
                let val = self.eval_expr(&args[0], row, col_map)?;
                if matches!(val, Value::Null) {
                    continue;
                }
                min_val = Some(match min_val {
                    None => val,
                    Some(current) => {
                        if val.partial_cmp(&current) == Some(std::cmp::Ordering::Less) {
                            val
                        } else {
                            current
                        }
                    }
                });
            }
            Ok(min_val.unwrap_or(Value::Null))
        } else if name.eq_ignore_ascii_case("MAX") {
            if args.is_empty() {
                return Ok(Value::Null);
            }
            let mut max_val: Option<Value> = None;
            for row in group_rows {
                let val = self.eval_expr(&args[0], row, col_map)?;
                if matches!(val, Value::Null) {
                    continue;
                }
                max_val = Some(match max_val {
                    None => val,
                    Some(current) => {
                        if val.partial_cmp(&current) == Some(std::cmp::Ordering::Greater) {
                            val
                        } else {
                            current
                        }
                    }
                });
            }
            Ok(max_val.unwrap_or(Value::Null))
        } else {
            Err(KkdbError::RuntimeError(format!(
                "unknown aggregate function: {}",
                name
            )))
        }
    }

    /// Eval expression that might contain aggregates (for HAVING clause)
    fn eval_expr_with_aggregates(
        &mut self,
        expr: &Expr,
        row: &Row,
        col_map: &HashMap<String, usize>,
        group_rows: &[&Row],
    ) -> Result<Value> {
        match expr {
            Expr::Function {
                name,
                args,
                distinct,
            } => {
                let n = name.as_str();
                if n == "__win" {
                    let idx = match args.first() {
                        Some(Expr::IntegerLiteral(i)) => *i as usize,
                        _ => 0,
                    };
                    return Ok(self.window_results.as_ref().map_or(Value::Null, |res| {
                        res[self.current_window_row_idx][idx].clone()
                    }));
                }
                if n.eq_ignore_ascii_case("COUNT")
                    || n.eq_ignore_ascii_case("SUM")
                    || n.eq_ignore_ascii_case("AVG")
                    || n.eq_ignore_ascii_case("MIN")
                    || n.eq_ignore_ascii_case("MAX")
                {
                    self.eval_aggregate(n, args, *distinct, group_rows, col_map)
                } else {
                    // Non-aggregate function: evaluate args with aggregate support first
                    let mut eval_args: Vec<Expr> = Vec::with_capacity(args.len());
                    for arg in args {
                        let val = self.eval_expr_with_aggregates(arg, row, col_map, group_rows)?;
                        eval_args.push(Self::value_to_expr(val));
                    }
                    let temp = Expr::Function {
                        name: name.clone(),
                        args: eval_args,
                        distinct: *distinct,
                    };
                    self.eval_expr(&temp, row, col_map)
                }
            }
            Expr::BinaryOp { left, op, right } => match op {
                BinaryOperator::And => {
                    let l = self.eval_expr_with_aggregates(left, row, col_map, group_rows)?;
                    if !matches!(l, Value::Null) && !l.is_truthy() {
                        return Ok(Value::Integer(0));
                    }
                    let r = self.eval_expr_with_aggregates(right, row, col_map, group_rows)?;
                    if !matches!(r, Value::Null) && !r.is_truthy() {
                        return Ok(Value::Integer(0));
                    }
                    if matches!(l, Value::Null) || matches!(r, Value::Null) {
                        return Ok(Value::Null);
                    }
                    Ok(Value::Integer(1))
                }
                BinaryOperator::Or => {
                    let l = self.eval_expr_with_aggregates(left, row, col_map, group_rows)?;
                    if !matches!(l, Value::Null) && l.is_truthy() {
                        return Ok(Value::Integer(1));
                    }
                    let r = self.eval_expr_with_aggregates(right, row, col_map, group_rows)?;
                    if !matches!(r, Value::Null) && r.is_truthy() {
                        return Ok(Value::Integer(1));
                    }
                    if matches!(l, Value::Null) || matches!(r, Value::Null) {
                        return Ok(Value::Null);
                    }
                    Ok(Value::Integer(0))
                }
                _ => {
                    let l = self.eval_expr_with_aggregates(left, row, col_map, group_rows)?;
                    let r = self.eval_expr_with_aggregates(right, row, col_map, group_rows)?;
                    self.apply_binary_op(op, &l, &r)
                }
            },
            Expr::UnaryOp { op, expr: inner } => {
                let val = self.eval_expr_with_aggregates(inner, row, col_map, group_rows)?;
                match op {
                    UnaryOperator::Minus => match val {
                        Value::Integer(v) => Ok(Value::Integer(v.wrapping_neg())),
                        Value::Real(v) => Ok(Value::Real(-v)),
                        Value::Null => Ok(Value::Null),
                        _ => Err(KkdbError::TypeError(
                            "cannot negate non-numeric value".into(),
                        )),
                    },
                    UnaryOperator::Not => {
                        if matches!(val, Value::Null) {
                            Ok(Value::Null)
                        } else {
                            Ok(Value::Integer(if val.is_truthy() { 0 } else { 1 }))
                        }
                    }
                }
            }
            Expr::Nested(inner) => self.eval_expr_with_aggregates(inner, row, col_map, group_rows),
            Expr::IsNull {
                expr: inner,
                negated,
            } => {
                let val = self.eval_expr_with_aggregates(inner, row, col_map, group_rows)?;
                let is_null = matches!(val, Value::Null);
                Ok(Value::Integer(if is_null != *negated { 1 } else { 0 }))
            }
            Expr::InList {
                expr: inner,
                list,
                negated,
            } => {
                let val = self.eval_expr_with_aggregates(inner, row, col_map, group_rows)?;
                if matches!(val, Value::Null) {
                    return Ok(Value::Null);
                }
                let mut found = false;
                let mut has_null = false;
                for item in list {
                    let item_val =
                        self.eval_expr_with_aggregates(item, row, col_map, group_rows)?;
                    if matches!(item_val, Value::Null) {
                        has_null = true;
                        continue;
                    }
                    if val == item_val {
                        found = true;
                        break;
                    }
                }
                if found {
                    Ok(Value::Integer(if !*negated { 1 } else { 0 }))
                } else if has_null {
                    Ok(Value::Null)
                } else {
                    Ok(Value::Integer(if *negated { 1 } else { 0 }))
                }
            }
            Expr::Between {
                expr: inner,
                low,
                high,
                negated,
            } => {
                let val = self.eval_expr_with_aggregates(inner, row, col_map, group_rows)?;
                let lo = self.eval_expr_with_aggregates(low, row, col_map, group_rows)?;
                let hi = self.eval_expr_with_aggregates(high, row, col_map, group_rows)?;
                if matches!(val, Value::Null)
                    || matches!(lo, Value::Null)
                    || matches!(hi, Value::Null)
                {
                    return Ok(Value::Null);
                }
                let in_range = val
                    .partial_cmp(&lo)
                    .is_some_and(|o| o != std::cmp::Ordering::Less)
                    && val
                        .partial_cmp(&hi)
                        .is_some_and(|o| o != std::cmp::Ordering::Greater);
                Ok(Value::Integer(if in_range != *negated { 1 } else { 0 }))
            }
            Expr::Like {
                expr: inner,
                pattern,
                escape_char,
                case_insensitive,
                negated,
            } => {
                let val = self.eval_expr_with_aggregates(inner, row, col_map, group_rows)?;
                let pat = self.eval_expr_with_aggregates(pattern, row, col_map, group_rows)?;
                if matches!(val, Value::Null) || matches!(pat, Value::Null) {
                    return Ok(Value::Null);
                }
                match (&val, &pat) {
                    (Value::Text(s), Value::Text(p)) => {
                        let matches = like_match(s, p, *escape_char, *case_insensitive);
                        Ok(Value::Integer(if matches != *negated { 1 } else { 0 }))
                    }
                    _ => Ok(Value::Integer(0)),
                }
            }
            Expr::Collate {
                expr: inner,
                collation: _,
            } => {
                // Ignore collation sorting rules during aggregate evaluation for now
                self.eval_expr_with_aggregates(inner, row, col_map, group_rows)
            }
            Expr::Interval {
                value,
                leading_field,
            } => {
                let val = self.eval_expr_with_aggregates(value, row, col_map, group_rows)?;
                if let Some(field) = leading_field {
                    match val {
                        Value::Text(s) => Ok(Value::Text(format!("{} {}", s.trim(), field).into())),
                        Value::Integer(v) => Ok(Value::Text(format!("{} {}", v, field).into())),
                        Value::Real(v) => Ok(Value::Text(format!("{} {}", v, field).into())),
                        Value::Null => Ok(Value::Null),
                        _ => Ok(Value::Null),
                    }
                } else {
                    Ok(val)
                }
            }
            _ => self.eval_expr(expr, row, col_map),
        }
    }

    /// Try to use an index for a simple WHERE condition on a single table.
    /// Returns Some((rows, col_names)) if an index was used, None otherwise.
    fn try_index_scan(
        &mut self,
        from: &FromClause,
        where_expr: &Expr,
    ) -> Result<Option<(Vec<Row>, Vec<String>)>> {
        // Only optimize single-table FROM
        let table_name = match from {
            FromClause::Table { name, .. } => name.clone(),
            _ => return Ok(None),
        };

        // L4/L5: Intercept MATCH for FTS tables before normal index lookups
        // Check for new CREATE FULLTEXT INDEX path (IndexSchema.is_fts=true)
        let fts_schema_indexes: Vec<_> = self
            .schema
            .indexes_for_table(&table_name)
            .into_iter()
            .filter(|idx| idx.is_fts)
            .cloned()
            .collect();

        if !fts_schema_indexes.is_empty() {
            // New BM25 path: CREATE FULLTEXT INDEX
            if let Expr::BinaryOp {
                left: _,
                op: BinaryOperator::FtsMatch,
                right,
            } = where_expr
            {
                if let Some(Value::Text(keyword)) = self.eval_constant_expr(right) {
                    return self.exec_fts_bm25_query(&table_name, &fts_schema_indexes, &keyword);
                }
            }
        }

        // Legacy FTS5 virtual table path (TableSchema.is_fts + *_fts_idx)
        let is_fts = self
            .schema
            .get_table(&table_name)
            .map(|t| t.is_fts)
            .unwrap_or(false);
        if is_fts {
            if let Expr::BinaryOp {
                left: _,
                op: BinaryOperator::FtsMatch,
                right,
            } = where_expr
            {
                if let Some(Value::Text(keyword)) = self.eval_constant_expr(right) {
                    let tokens = VM::tokenize(&keyword);
                    if tokens.is_empty() {
                        return Ok(Some((vec![], vec![])));
                    }

                    // Simple inverted index scan: query idx_<name>_fts_term
                    let fts_tbl = format!("{}_fts_idx", table_name);
                    let idx_term = format!("idx_{}_fts_term", table_name);

                    let mut doc_ids = std::collections::HashSet::new();
                    if let Some(idx) = self.schema.indexes.get(&idx_term).cloned() {
                        let search_val = Value::Text(tokens[0].clone().into());
                        // index_rowids_for_value gives us rowids of _fts_idx table rows
                        if let Ok(fts_entry_rowids) = self.index_rowids_for_value(&idx, &search_val)
                        {
                            if !fts_entry_rowids.is_empty() {
                                // Fetch those rows from _fts_idx to get the actual doc_id column
                                let fts_idx_table = self.schema.tables.get(&fts_tbl).cloned();
                                if let Some(fts_schema) = fts_idx_table {
                                    let fts_root = fts_schema.root_page;
                                    let fts_rows = self.fetch_rows_by_rowids(
                                        &fts_tbl,
                                        fts_root,
                                        &fts_entry_rowids,
                                    )?;
                                    for (_, fts_row) in fts_rows {
                                        // fts_idx schema: (id, term, doc_id) → doc_id is index 2
                                        if let Some(Value::Integer(doc_id)) = fts_row.get(2) {
                                            doc_ids.insert(*doc_id);
                                        }
                                    }
                                }
                            }
                        }
                    }

                    if doc_ids.is_empty() {
                        return Ok(Some((vec![], vec![])));
                    }

                    let table = self.schema.get_table(&table_name)?.clone();
                    let rowids: Vec<i64> = doc_ids.into_iter().collect();
                    let fetched_rows =
                        self.fetch_rows_by_rowids(&table_name, table.root_page, &rowids)?;

                    let mut out_rows = Vec::with_capacity(fetched_rows.len());
                    for (_, row) in fetched_rows {
                        out_rows.push(row);
                    }
                    return Ok(Some((out_rows, table.col_names.clone())));
                }
            }
        }

        enum Lookup {
            Eq(Value),
            In(Vec<Value>),
            Comparison(BinaryOperator, Value),
            Between(Value, Value),
        }

        let (col_name, lookup) = match where_expr {
            Expr::BinaryOp { left, op, right } => {
                let Some(op_normalized) = (match (left.as_ref(), right.as_ref()) {
                    (Expr::ColumnRef { .. }, _) => Some(op.clone()),
                    (_, Expr::ColumnRef { .. }) => VM::flip_comparison_operator(op),
                    _ => None,
                }) else {
                    return Ok(None);
                };

                let Some(val) = (match (left.as_ref(), right.as_ref()) {
                    (Expr::ColumnRef { .. }, rhs) => self.eval_constant_expr(rhs),
                    (lhs, Expr::ColumnRef { .. }) => self.eval_constant_expr(lhs),
                    _ => None,
                }) else {
                    return Ok(None);
                };

                let column = match (left.as_ref(), right.as_ref()) {
                    (Expr::ColumnRef { column, .. }, _) => column.clone(),
                    (_, Expr::ColumnRef { column, .. }) => column.clone(),
                    _ => return Ok(None),
                };

                let lookup = if op_normalized == BinaryOperator::Equal {
                    Lookup::Eq(val)
                } else if matches!(
                    op_normalized,
                    BinaryOperator::LessThan
                        | BinaryOperator::LessThanOrEqual
                        | BinaryOperator::GreaterThan
                        | BinaryOperator::GreaterThanOrEqual
                ) {
                    Lookup::Comparison(op_normalized, val)
                } else {
                    return Ok(None);
                };
                (column, lookup)
            }
            Expr::InList {
                expr,
                list,
                negated,
            } if !negated => {
                let Expr::ColumnRef { column, .. } = expr.as_ref() else {
                    return Ok(None);
                };
                let mut values = Vec::with_capacity(list.len());
                for item in list {
                    let Some(v) = self.eval_constant_expr(item) else {
                        return Ok(None);
                    };
                    if !matches!(v, Value::Null) {
                        values.push(v);
                    }
                }
                (column.clone(), Lookup::In(values))
            }
            Expr::Between {
                expr,
                low,
                high,
                negated,
            } if !negated => {
                let Expr::ColumnRef { column, .. } = expr.as_ref() else {
                    return Ok(None);
                };
                let Some(low_v) = self.eval_constant_expr(low) else {
                    return Ok(None);
                };
                let Some(high_v) = self.eval_constant_expr(high) else {
                    return Ok(None);
                };
                (column.clone(), Lookup::Between(low_v, high_v))
            }
            _ => return Ok(None),
        };

        // Find an index that starts with this column
        let indexes: Vec<_> = self
            .schema
            .indexes_for_table(&table_name)
            .into_iter()
            .cloned()
            .collect();
        let matching_idx = indexes
            .iter()
            .find(|idx| !idx.columns.is_empty() && idx.columns[0].eq_ignore_ascii_case(&col_name));

        let idx = match matching_idx {
            Some(i) => i.clone(),
            None => {
                // O3: No index covers this column — track full-scan access
                self.record_full_scan_access(&table_name, &col_name);
                return Ok(None);
            }
        };

        let table = self.schema.get_table(&table_name)?.clone();
        let col_names = table.col_names.clone();

        // ── O2: Cost-Based Index Selection ───────────────────────────────────
        if let Some(col_info) = table
            .columns
            .iter()
            .find(|c| c.name.eq_ignore_ascii_case(&col_name))
        {
            if let Some(ref stats) = col_info.stats {
                let total = stats.total_count as f64;
                if total > 0.0 {
                    // Estimate selectivity from predicate type and column statistics
                    let selectivity: f64 = match &lookup {
                        Lookup::Eq(eq_val) => {
                            // Try histogram-based estimation first
                            if let Some(sel) =
                                Self::histogram_eq_selectivity(stats, eq_val)
                            {
                                sel
                            } else if stats.ndv > 0 {
                                1.0 / stats.ndv as f64
                            } else {
                                0.1
                            }
                        }
                        Lookup::In(vals) => {
                            if stats.ndv > 0 {
                                (vals.len() as f64 / stats.ndv as f64).min(1.0)
                            } else {
                                0.1
                            }
                        }
                        Lookup::Between(low, high) => {
                            // Try histogram-based range estimation
                            if let Some(sel) =
                                Self::histogram_range_selectivity(stats, Some(low), Some(high))
                            {
                                sel
                            } else {
                                // Fallback: linear interpolation over [min,max]
                                match (&stats.min, &stats.max) {
                                    (
                                        Some(Value::Integer(mn)),
                                        Some(Value::Integer(mx)),
                                    ) if mx > mn => {
                                        let lo = if let Value::Integer(v) = low {
                                            *v as f64
                                        } else {
                                            *mn as f64
                                        };
                                        let hi = if let Value::Integer(v) = high {
                                            *v as f64
                                        } else {
                                            *mx as f64
                                        };
                                        ((hi - lo) / (*mx - *mn) as f64).clamp(0.0, 1.0)
                                    }
                                    _ => 0.25,
                                }
                            }
                        }
                        Lookup::Comparison(op, val) => {
                            use crate::sql::ast::BinaryOperator;
                            // Try histogram-based comparison estimation
                            let hist_sel = match op {
                                BinaryOperator::LessThan | BinaryOperator::LessThanOrEqual => {
                                    Self::histogram_range_selectivity(stats, None, Some(val))
                                }
                                BinaryOperator::GreaterThan
                                | BinaryOperator::GreaterThanOrEqual => {
                                    Self::histogram_range_selectivity(stats, Some(val), None)
                                }
                                _ => None,
                            };
                            if let Some(sel) = hist_sel {
                                sel
                            } else {
                                // Fallback: min/max linear interpolation
                                match (&stats.min, &stats.max, val) {
                                    (
                                        Some(Value::Integer(mn)),
                                        Some(Value::Integer(mx)),
                                        Value::Integer(v),
                                    ) if mx > mn => {
                                        let range = (*mx - *mn) as f64;
                                        match op {
                                            BinaryOperator::LessThan
                                            | BinaryOperator::LessThanOrEqual => {
                                                ((*v - *mn) as f64 / range).clamp(0.0, 1.0)
                                            }
                                            BinaryOperator::GreaterThan
                                            | BinaryOperator::GreaterThanOrEqual => {
                                                ((*mx - *v) as f64 / range).clamp(0.0, 1.0)
                                            }
                                            _ => 0.1,
                                        }
                                    }
                                    _ => 0.1,
                                }
                            }
                        }
                    };
                    let expected_rows = (selectivity * total).max(1.0);
                    // Enhanced cost model: index cost includes B-tree traversal depth (~log2(N))
                    // plus random I/O for each matching rowid fetch.
                    let btree_depth = (total.ln() / 2.0_f64.ln()).max(1.0);
                    let index_cost = btree_depth + expected_rows * 2.0;
                    let seq_scan_cost = total;
                    if index_cost >= seq_scan_cost {
                        // O3: Index exists but CBO prefers seq scan — still track for threshold
                        self.record_full_scan_access(&table_name, &col_name);
                        return Ok(None); // full scan is cheaper
                    }
                }
            }
        }
        // ── End O2 ──────────────────────────────────────────────────────────

        let matching_rowids = match lookup {
            Lookup::Eq(search_val) => {
                // SQL '=' with NULL is unknown, so WHERE never matches.
                if matches!(search_val, Value::Null) {
                    return Ok(Some((Vec::new(), col_names)));
                }
                self.index_rowids_for_value(&idx, &search_val)?
            }
            Lookup::In(search_vals) => {
                if search_vals.is_empty() {
                    return Ok(Some((Vec::new(), col_names)));
                }
                let mut seen = HashSet::new();
                let mut out = Vec::new();
                for v in search_vals {
                    for rid in self.index_rowids_for_value(&idx, &v)? {
                        if seen.insert(rid) {
                            out.push(rid);
                        }
                    }
                }
                out
            }
            Lookup::Comparison(op, search_val) => {
                self.index_rowids_for_comparison(&idx, &op, &search_val)?
            }
            Lookup::Between(low, high) => self.index_rowids_for_between(&idx, &low, &high)?,
        };

        // Fetch full rows by rowid.
        let fetched_rows =
            self.fetch_rows_by_rowids(&table_name, table.root_page, &matching_rowids)?;
        let mut result_rows: Vec<Row> = Vec::with_capacity(fetched_rows.len());
        for (_rid, row) in fetched_rows {
            result_rows.push(row);
        }

        Ok(Some((result_rows, col_names)))
    }

    /// Execute a SET OPERATION (UNION / INTERSECT / EXCEPT)
    pub(crate) fn exec_set_op(&mut self, setop: &SetOpStmt) -> Result<ExecResult> {
        let left_result = self.exec_select(&setop.left)?;
        let right_result = self.exec_select(&setop.right)?;

        let (mut left_rows, col_names) = match left_result {
            ExecResult::QueryResult { rows, columns } => (rows, columns),
            _ => return Err(KkdbError::Internal("set-op left not a query result".into())),
        };
        let (right_rows, _) = match right_result {
            ExecResult::QueryResult { rows, columns } => (rows, columns),
            _ => {
                return Err(KkdbError::Internal(
                    "set-op right not a query result".into(),
                ))
            }
        };

        let mut result_rows = match setop.kind {
            SetOpKind::UnionAll => {
                left_rows.extend(right_rows);
                left_rows
            }
            SetOpKind::UnionDistinct => {
                let mut seen: HashSet<Vec<u8>> = HashSet::new();
                let mut out = Vec::new();
                for row in left_rows.into_iter().chain(right_rows.into_iter()) {
                    let key = row_key(&row);
                    if seen.insert(key) {
                        out.push(row);
                    }
                }
                out
            }
            SetOpKind::IntersectAll => {
                // Count occurrences in right, consume as encountered
                let mut counts: HashMap<Vec<u8>, usize> = HashMap::new();
                for row in &right_rows {
                    *counts.entry(row_key(row)).or_insert(0) += 1;
                }
                left_rows
                    .into_iter()
                    .filter(|r| {
                        let k = row_key(r);
                        if let Some(c) = counts.get_mut(&k) {
                            if *c > 0 {
                                *c -= 1;
                                return true;
                            }
                        }
                        false
                    })
                    .collect()
            }
            SetOpKind::IntersectDistinct => {
                let right_keys: HashSet<Vec<u8>> = right_rows.iter().map(|r| row_key(r)).collect();
                let mut seen: HashSet<Vec<u8>> = HashSet::new();
                left_rows
                    .into_iter()
                    .filter(|r| {
                        let k = row_key(r);
                        right_keys.contains(&k) && seen.insert(k)
                    })
                    .collect()
            }
            SetOpKind::ExceptAll => {
                let mut counts: HashMap<Vec<u8>, usize> = HashMap::new();
                for row in &right_rows {
                    *counts.entry(row_key(row)).or_insert(0) += 1;
                }
                left_rows
                    .into_iter()
                    .filter(|r| {
                        let k = row_key(r);
                        if let Some(c) = counts.get_mut(&k) {
                            if *c > 0 {
                                *c -= 1;
                                return false;
                            }
                        }
                        true
                    })
                    .collect()
            }
            SetOpKind::ExceptDistinct => {
                let right_keys: HashSet<Vec<u8>> = right_rows.iter().map(|r| row_key(r)).collect();
                let mut seen: HashSet<Vec<u8>> = HashSet::new();
                left_rows
                    .into_iter()
                    .filter(|r| {
                        let k = row_key(r);
                        !right_keys.contains(&k) && seen.insert(k)
                    })
                    .collect()
            }
        };

        // Bug #1 fix: apply ORDER BY and LIMIT/OFFSET to the combined result
        let col_map: HashMap<String, usize> = col_names
            .iter()
            .enumerate()
            .map(|(i, n)| (n.clone(), i))
            .collect();
        let empty_row: Vec<Value> = Vec::new();

        // ORDER BY: evaluate expressions on each row, then sort
        if !setop.order_by.is_empty() {
            // Pre-evaluate sort keys to avoid repeated eval and borrow issues
            let mut keyed: Vec<(Vec<Value>, Vec<Value>)> = result_rows
                .into_iter()
                .map(|row| {
                    let keys: Vec<Value> = setop
                        .order_by
                        .iter()
                        .map(|item| {
                            self.eval_expr(&item.expr, &row, &col_map)
                                .unwrap_or(Value::Null)
                        })
                        .collect();
                    (keys, row)
                })
                .collect();
            keyed.sort_by(|(ka, _), (kb, _)| {
                for (i, item) in setop.order_by.iter().enumerate() {
                    let mut cmp = ka[i]
                        .partial_cmp(&kb[i])
                        .unwrap_or(std::cmp::Ordering::Equal);
                    if !item.ascending {
                        cmp = cmp.reverse();
                    }
                    if cmp != std::cmp::Ordering::Equal {
                        return cmp;
                    }
                }
                std::cmp::Ordering::Equal
            });
            result_rows = keyed.into_iter().map(|(_, row)| row).collect();
        }

        // OFFSET
        if let Some(ref off_expr) = setop.offset {
            let off = match self.eval_expr(off_expr, &empty_row, &col_map)? {
                Value::Integer(v) => v.max(0) as usize,
                _ => 0,
            };
            if off >= result_rows.len() {
                result_rows.clear();
            } else {
                result_rows.drain(0..off);
            }
        }

        // LIMIT
        if let Some(ref lim_expr) = setop.limit {
            let lim = match self.eval_expr(lim_expr, &empty_row, &col_map)? {
                Value::Integer(v) => v.max(0) as usize,
                _ => usize::MAX,
            };
            result_rows.truncate(lim);
        }

        Ok(ExecResult::QueryResult {
            columns: col_names,
            rows: result_rows,
        })
    }

    /// Execute SHOW TABLES — returns a sorted list of all user table names
    pub(crate) fn exec_show_tables(&mut self) -> Result<ExecResult> {
        let mut names = self.schema.list_tables();
        names.sort_unstable(); // Bug #5 fix: deterministic order
        let rows: Vec<Vec<Value>> = names
            .into_iter()
            .map(|n| vec![Value::Text(n.into())])
            .collect();
        Ok(ExecResult::QueryResult {
            columns: vec!["name".to_string()],
            rows,
        })
    }

    fn extract_window_funcs(expr: &mut Expr, extracted: &mut Vec<Expr>) {
        if matches!(expr, Expr::WindowFunction { .. }) {
            let mut original = Expr::Null;
            std::mem::swap(expr, &mut original);
            let idx = extracted.len();
            extracted.push(original);
            *expr = Expr::Function {
                name: "__win".to_string(),
                args: vec![Expr::IntegerLiteral(idx as i64)],
                distinct: false,
            };
            return;
        }
        match expr {
            Expr::BinaryOp { left, right, .. } => {
                Self::extract_window_funcs(left, extracted);
                Self::extract_window_funcs(right, extracted);
            }
            Expr::UnaryOp { expr, .. }
            | Expr::Nested(expr)
            | Expr::Cast { expr, .. }
            | Expr::Collate { expr, .. }
            | Expr::Interval { value: expr, .. }
            | Expr::IsNull { expr, .. } => Self::extract_window_funcs(expr, extracted),
            Expr::Function { args, .. } => {
                for arg in args {
                    Self::extract_window_funcs(arg, extracted);
                }
            }
            Expr::InList { expr, list, .. } => {
                Self::extract_window_funcs(expr, extracted);
                for i in list {
                    Self::extract_window_funcs(i, extracted);
                }
            }
            Expr::Between {
                expr, low, high, ..
            } => {
                Self::extract_window_funcs(expr, extracted);
                Self::extract_window_funcs(low, extracted);
                Self::extract_window_funcs(high, extracted);
            }
            Expr::Like { expr, pattern, .. } => {
                Self::extract_window_funcs(expr, extracted);
                Self::extract_window_funcs(pattern, extracted);
            }
            Expr::Case {
                operand,
                when_clauses,
                else_clause,
            } => {
                if let Some(op) = operand {
                    Self::extract_window_funcs(op, extracted);
                }
                for (cond, res) in when_clauses {
                    Self::extract_window_funcs(cond, extracted);
                    Self::extract_window_funcs(res, extracted);
                }
                if let Some(el) = else_clause {
                    Self::extract_window_funcs(el, extracted);
                }
            }
            _ => {}
        }
    }

    fn eval_window_functions_for_groups(
        &mut self,
        window_exprs: &[Expr],
        groups: &[Vec<&Row>],
        col_map: &HashMap<String, usize>,
        window_defs: &[NamedWindowDefinition],
    ) -> Result<Vec<Vec<Value>>> {
        let mut results = vec![vec![Value::Null; window_exprs.len()]; groups.len()];
        let empty_row = Vec::new();
        let empty_row_ref = &empty_row;

        for (w_idx, window_expr) in window_exprs.iter().enumerate() {
            let Expr::WindowFunction {
                func,
                partition_by,
                order_by,
                frame,
            } = window_expr
            else {
                continue;
            };

            let mut active_partition_by = partition_by;
            let mut active_order_by = order_by;
            let mut active_frame = frame;
            if let Some(Expr::ColumnRef { column, .. }) = partition_by.first() {
                if let Some(name) = column.strip_prefix("__named_window_") {
                    if let Some(def) = window_defs.iter().find(|d| d.name == name) {
                        active_partition_by = &def.partition_by;
                        active_order_by = &def.order_by;
                        active_frame = &def.frame;
                    }
                }
            }

            let mut partitions: HashMap<Vec<u8>, Vec<usize>> = HashMap::new();
            if active_partition_by.is_empty() {
                partitions.insert(vec![], (0..groups.len()).collect());
            } else {
                let mut key_buf = String::with_capacity(64);
                let mut val_buf = String::with_capacity(32);
                for (g_idx, group_rows) in groups.iter().enumerate() {
                    let first_row = group_rows.first().unwrap_or(&empty_row_ref);
                    key_buf.clear();
                    for expr in active_partition_by {
                        let v =
                            self.eval_expr_with_aggregates(expr, first_row, col_map, group_rows)?;
                        Self::typed_key_into(&v, &mut val_buf);
                        key_buf.push_str(&val_buf);
                        key_buf.push('\0');
                    }
                    partitions
                        .entry(key_buf.clone().into_bytes())
                        .or_default()
                        .push(g_idx);
                }
            }

            for (_, mut part_indices) in partitions {
                if !active_order_by.is_empty() {
                    let mut sort_keys: Vec<(usize, Vec<Value>)> = part_indices
                        .into_iter()
                        .map(|g_idx| {
                            let group_rows = &groups[g_idx];
                            let first_row = group_rows.first().unwrap_or(&empty_row_ref);
                            let keys: Vec<Value> = active_order_by
                                .iter()
                                .map(|item| {
                                    self.eval_expr_with_aggregates(
                                        &item.expr, first_row, col_map, group_rows,
                                    )
                                    .unwrap_or(Value::Null)
                                })
                                .collect();
                            (g_idx, keys)
                        })
                        .collect();

                    sort_keys.sort_by(|a, b| {
                        for (i, item) in active_order_by.iter().enumerate() {
                            let mut cmp = a.1[i]
                                .partial_cmp(&b.1[i])
                                .unwrap_or(std::cmp::Ordering::Equal);
                            if !item.ascending {
                                cmp = cmp.reverse();
                            }
                            if cmp != std::cmp::Ordering::Equal {
                                return cmp;
                            }
                        }
                        std::cmp::Ordering::Equal
                    });
                    part_indices = sort_keys.into_iter().map(|(idx, _)| idx).collect();
                }

                for p in 0..part_indices.len() {
                    let g_idx = part_indices[p];
                    let mut start = 0;
                    let mut end = part_indices.len().saturating_sub(1);

                    if let Some(wf) = active_frame {
                        if wf.unit == WindowFrameUnit::Rows {
                            start = match &wf.start {
                                WindowBound::CurrentRow => p,
                                WindowBound::UnboundedPreceding => 0,
                                WindowBound::Preceding(expr) => {
                                    let val =
                                        self.eval_constant_expr(expr).unwrap_or(Value::Integer(0));
                                    if let Value::Integer(v) = val {
                                        p.saturating_sub(v as usize)
                                    } else {
                                        0
                                    }
                                }
                                WindowBound::Following(expr) => {
                                    let val =
                                        self.eval_constant_expr(expr).unwrap_or(Value::Integer(0));
                                    if let Value::Integer(v) = val {
                                        p.saturating_add(v as usize)
                                    } else {
                                        p
                                    }
                                }
                                WindowBound::UnboundedFollowing => {
                                    part_indices.len().saturating_sub(1)
                                }
                            };
                            if let Some(eb) = &wf.end {
                                end = match eb {
                                    WindowBound::CurrentRow => p,
                                    WindowBound::UnboundedPreceding => 0,
                                    WindowBound::Preceding(expr) => {
                                        let val = self
                                            .eval_constant_expr(expr)
                                            .unwrap_or(Value::Integer(0));
                                        if let Value::Integer(v) = val {
                                            p.saturating_sub(v as usize)
                                        } else {
                                            p
                                        }
                                    }
                                    WindowBound::Following(expr) => {
                                        let val = self
                                            .eval_constant_expr(expr)
                                            .unwrap_or(Value::Integer(0));
                                        if let Value::Integer(v) = val {
                                            p.saturating_add(v as usize)
                                        } else {
                                            p
                                        }
                                    }
                                    WindowBound::UnboundedFollowing => {
                                        part_indices.len().saturating_sub(1)
                                    }
                                };
                            } else {
                                end = p;
                            }
                        }
                    } else if !active_order_by.is_empty() {
                        end = p;
                    }

                    start = start.min(part_indices.len().saturating_sub(1));
                    end = end.min(part_indices.len().saturating_sub(1)).max(start);

                    let frame_indices = &part_indices[start..=end];

                    let val = match func {
                        WindowFunc::RowNumber => Value::Integer((p + 1) as i64),
                        WindowFunc::Rank => {
                            // RANK: peers (same ORDER BY keys) share the same rank
                            // Find position of first row with same ORDER BY key as p
                            let rank = if active_order_by.is_empty() {
                                p + 1
                            } else {
                                let mut rank = p + 1;
                                let g_rows = &groups[part_indices[p]];
                                let first_row = g_rows.first().unwrap_or(&empty_row_ref);
                                let cur_keys: Vec<Value> = active_order_by
                                    .iter()
                                    .map(|item| {
                                        self.eval_expr_with_aggregates(
                                            &item.expr, first_row, col_map, g_rows,
                                        )
                                        .unwrap_or(Value::Null)
                                    })
                                    .collect();
                                for q in 0..p {
                                    let g_rows_q = &groups[part_indices[q]];
                                    let first_row_q = g_rows_q.first().unwrap_or(&empty_row_ref);
                                    let q_keys: Vec<Value> = active_order_by
                                        .iter()
                                        .map(|item| {
                                            self.eval_expr_with_aggregates(
                                                &item.expr,
                                                first_row_q,
                                                col_map,
                                                g_rows_q,
                                            )
                                            .unwrap_or(Value::Null)
                                        })
                                        .collect();
                                    if q_keys == cur_keys {
                                        rank = q + 1;
                                        break;
                                    }
                                }
                                rank
                            };
                            Value::Integer(rank as i64)
                        }
                        WindowFunc::DenseRank => {
                            // DENSE_RANK: no gaps — count distinct ORDER BY key groups up to p
                            if active_order_by.is_empty() {
                                Value::Integer((p + 1) as i64)
                            } else {
                                let mut seen_keys: Vec<Vec<Value>> = Vec::new();
                                let g_rows = &groups[part_indices[p]];
                                let first_row = g_rows.first().unwrap_or(&empty_row_ref);
                                let cur_keys: Vec<Value> = active_order_by
                                    .iter()
                                    .map(|item| {
                                        self.eval_expr_with_aggregates(
                                            &item.expr, first_row, col_map, g_rows,
                                        )
                                        .unwrap_or(Value::Null)
                                    })
                                    .collect();
                                for q in 0..=p {
                                    let g_rows_q = &groups[part_indices[q]];
                                    let first_row_q = g_rows_q.first().unwrap_or(&empty_row_ref);
                                    let q_keys: Vec<Value> = active_order_by
                                        .iter()
                                        .map(|item| {
                                            self.eval_expr_with_aggregates(
                                                &item.expr,
                                                first_row_q,
                                                col_map,
                                                g_rows_q,
                                            )
                                            .unwrap_or(Value::Null)
                                        })
                                        .collect();
                                    if !seen_keys.contains(&q_keys) {
                                        seen_keys.push(q_keys);
                                    }
                                    if seen_keys[seen_keys.len() - 1] == cur_keys && q == p {
                                        break;
                                    }
                                }
                                Value::Integer(seen_keys.len() as i64)
                            }
                        }
                        WindowFunc::PercentRank => {
                            // PERCENT_RANK = (rank - 1) / (N - 1)
                            let n = part_indices.len();
                            if n <= 1 {
                                Value::Real(0.0)
                            } else {
                                let rank = if active_order_by.is_empty() {
                                    p + 1
                                } else {
                                    let g_rows = &groups[part_indices[p]];
                                    let first_row = g_rows.first().unwrap_or(&empty_row_ref);
                                    let cur_keys: Vec<Value> = active_order_by
                                        .iter()
                                        .map(|item| {
                                            self.eval_expr_with_aggregates(
                                                &item.expr, first_row, col_map, g_rows,
                                            )
                                            .unwrap_or(Value::Null)
                                        })
                                        .collect();
                                    let mut rk = p + 1;
                                    for q in 0..p {
                                        let g_rows_q = &groups[part_indices[q]];
                                        let fr_q = g_rows_q.first().unwrap_or(&empty_row_ref);
                                        let q_keys: Vec<Value> = active_order_by
                                            .iter()
                                            .map(|item| {
                                                self.eval_expr_with_aggregates(
                                                    &item.expr, fr_q, col_map, g_rows_q,
                                                )
                                                .unwrap_or(Value::Null)
                                            })
                                            .collect();
                                        if q_keys == cur_keys {
                                            rk = q + 1;
                                            break;
                                        }
                                    }
                                    rk
                                };
                                Value::Real((rank - 1) as f64 / (n - 1) as f64)
                            }
                        }
                        WindowFunc::CumeDist => {
                            // CUME_DIST = number of rows with order_by key <= current / N
                            let n = part_indices.len();
                            if n == 0 {
                                Value::Real(0.0)
                            } else {
                                let g_rows = &groups[part_indices[p]];
                                let first_row = g_rows.first().unwrap_or(&empty_row_ref);
                                let cur_keys: Vec<Value> = active_order_by
                                    .iter()
                                    .map(|item| {
                                        self.eval_expr_with_aggregates(
                                            &item.expr, first_row, col_map, g_rows,
                                        )
                                        .unwrap_or(Value::Null)
                                    })
                                    .collect();
                                // Count how many rows have key <= cur_keys (last position with same key)
                                let mut last_pos = p;
                                for q in p + 1..part_indices.len() {
                                    let g_rows_q = &groups[part_indices[q]];
                                    let fr_q = g_rows_q.first().unwrap_or(&empty_row_ref);
                                    let q_keys: Vec<Value> = active_order_by
                                        .iter()
                                        .map(|item| {
                                            self.eval_expr_with_aggregates(
                                                &item.expr, fr_q, col_map, g_rows_q,
                                            )
                                            .unwrap_or(Value::Null)
                                        })
                                        .collect();
                                    if q_keys == cur_keys {
                                        last_pos = q;
                                    } else {
                                        break;
                                    }
                                }
                                Value::Real((last_pos + 1) as f64 / n as f64)
                            }
                        }
                        WindowFunc::Ntile(n_expr) => {
                            // NTILE(n): divide partition into n roughly equal buckets
                            let n_total = part_indices.len();
                            let n_buckets = match self
                                .eval_constant_expr(n_expr)
                                .unwrap_or(Value::Integer(1))
                            {
                                Value::Integer(v) if v > 0 => v as usize,
                                _ => 1,
                            };
                            let bucket_size = n_total / n_buckets;
                            let remainder = n_total % n_buckets;
                            // First `remainder` buckets get bucket_size+1 rows
                            let bucket = if p < remainder * (bucket_size + 1) {
                                p / (bucket_size + 1) + 1
                            } else {
                                (p - remainder * (bucket_size + 1)) / bucket_size.max(1)
                                    + remainder
                                    + 1
                            };
                            Value::Integer(bucket.min(n_buckets) as i64)
                        }
                        WindowFunc::Lag {
                            expr: lag_expr,
                            offset,
                            default: default_expr,
                        } => {
                            let off = match offset {
                                Some(o) => {
                                    match self.eval_constant_expr(o).unwrap_or(Value::Integer(1)) {
                                        Value::Integer(v) => v as usize,
                                        _ => 1,
                                    }
                                }
                                None => 1,
                            };
                            let target_p = p.checked_sub(off);
                            if let Some(tp) = target_p {
                                let g_rows = &groups[part_indices[tp]];
                                let first_row = g_rows.first().unwrap_or(&empty_row_ref);
                                self.eval_expr_with_aggregates(lag_expr, first_row, col_map, g_rows)
                                    .unwrap_or(Value::Null)
                            } else {
                                match default_expr {
                                    Some(d) => self.eval_constant_expr(d).unwrap_or(Value::Null),
                                    None => Value::Null,
                                }
                            }
                        }
                        WindowFunc::Lead {
                            expr: lead_expr,
                            offset,
                            default: default_expr,
                        } => {
                            let off = match offset {
                                Some(o) => {
                                    match self.eval_constant_expr(o).unwrap_or(Value::Integer(1)) {
                                        Value::Integer(v) => v as usize,
                                        _ => 1,
                                    }
                                }
                                None => 1,
                            };
                            let target_p = p + off;
                            if target_p < part_indices.len() {
                                let g_rows = &groups[part_indices[target_p]];
                                let first_row = g_rows.first().unwrap_or(&empty_row_ref);
                                self.eval_expr_with_aggregates(
                                    lead_expr, first_row, col_map, g_rows,
                                )
                                .unwrap_or(Value::Null)
                            } else {
                                match default_expr {
                                    Some(d) => self.eval_constant_expr(d).unwrap_or(Value::Null),
                                    None => Value::Null,
                                }
                            }
                        }
                        WindowFunc::FirstValue(fv_expr) => {
                            if frame_indices.is_empty() {
                                Value::Null
                            } else {
                                let first_g = frame_indices[0];
                                let g_rows = &groups[first_g];
                                let first_row = g_rows.first().unwrap_or(&empty_row_ref);
                                self.eval_expr_with_aggregates(fv_expr, first_row, col_map, g_rows)
                                    .unwrap_or(Value::Null)
                            }
                        }
                        WindowFunc::LastValue(lv_expr) => {
                            if frame_indices.is_empty() {
                                Value::Null
                            } else {
                                // SAFETY: `frame_indices` is non-empty (checked above)
                                let last_g = *frame_indices.last().unwrap();
                                let g_rows = &groups[last_g];
                                let first_row = g_rows.first().unwrap_or(&empty_row_ref);
                                self.eval_expr_with_aggregates(lv_expr, first_row, col_map, g_rows)
                                    .unwrap_or(Value::Null)
                            }
                        }
                        WindowFunc::NthValue(nv_expr, n_expr) => {
                            let nth = match self
                                .eval_constant_expr(n_expr)
                                .unwrap_or(Value::Integer(1))
                            {
                                Value::Integer(v) if v >= 1 => (v - 1) as usize,
                                _ => 0,
                            };
                            if nth < frame_indices.len() {
                                let g_idx2 = frame_indices[nth];
                                let g_rows = &groups[g_idx2];
                                let first_row = g_rows.first().unwrap_or(&empty_row_ref);
                                self.eval_expr_with_aggregates(nv_expr, first_row, col_map, g_rows)
                                    .unwrap_or(Value::Null)
                            } else {
                                Value::Null
                            }
                        }
                        WindowFunc::Aggregate { name, args, .. } => {
                            let mut frame_vals = Vec::with_capacity(frame_indices.len());
                            for &f_idx in frame_indices {
                                let group_rows = &groups[f_idx];
                                let first_row = group_rows.first().unwrap_or(&empty_row_ref);
                                if !args.is_empty() {
                                    let v = self
                                        .eval_expr_with_aggregates(
                                            &args[0], first_row, col_map, group_rows,
                                        )
                                        .unwrap_or(Value::Null);
                                    frame_vals.push(v);
                                }
                            }
                            if name.eq_ignore_ascii_case("SUM") {
                                let mut i_sum = 0i64;
                                let mut f_sum = 0.0f64;
                                let mut is_int = true;
                                let mut valid = false;
                                for v in frame_vals {
                                    match v {
                                        Value::Integer(x) => {
                                            if is_int {
                                                i_sum = i_sum.wrapping_add(x);
                                            } else {
                                                f_sum += x as f64;
                                            }
                                            valid = true;
                                        }
                                        Value::Real(x) => {
                                            if is_int {
                                                f_sum = i_sum as f64 + x;
                                                is_int = false;
                                            } else {
                                                f_sum += x;
                                            }
                                            valid = true;
                                        }
                                        _ => {}
                                    }
                                }
                                if !valid {
                                    Value::Null
                                } else if is_int {
                                    Value::Integer(i_sum)
                                } else {
                                    Value::Real(f_sum)
                                }
                            } else if name.eq_ignore_ascii_case("COUNT") {
                                let count = frame_vals
                                    .into_iter()
                                    .filter(|v| !matches!(v, Value::Null))
                                    .count();
                                Value::Integer(count as i64)
                            } else if name.eq_ignore_ascii_case("AVG") {
                                let non_null: Vec<Value> = frame_vals
                                    .into_iter()
                                    .filter(|v| !matches!(v, Value::Null))
                                    .collect();
                                if non_null.is_empty() {
                                    Value::Null
                                } else {
                                    let mut sum = 0.0f64;
                                    for v in &non_null {
                                        match v {
                                            Value::Integer(x) => sum += *x as f64,
                                            Value::Real(x) => sum += x,
                                            _ => {}
                                        }
                                    }
                                    Value::Real(sum / non_null.len() as f64)
                                }
                            } else if name.eq_ignore_ascii_case("MAX") {
                                frame_vals
                                    .into_iter()
                                    .filter(|v| !matches!(v, Value::Null))
                                    .max_by(|a, b| {
                                        a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal)
                                    })
                                    .unwrap_or(Value::Null)
                            } else if name.eq_ignore_ascii_case("MIN") {
                                frame_vals
                                    .into_iter()
                                    .filter(|v| !matches!(v, Value::Null))
                                    .min_by(|a, b| {
                                        a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal)
                                    })
                                    .unwrap_or(Value::Null)
                            } else {
                                Value::Null
                            }
                        }
                    };
                    results[g_idx][w_idx] = val;
                }
            }
        }
        Ok(results)
    }

    // ── Q6: Sub-query Rewriter ────────────────────────────────────────────────────

    /// Walk an expression tree and convert non-correlated `InSubquery` nodes
    /// into `InList` nodes, executing the subquery once and caching the result.
    ///
    /// A subquery is considered *non-correlated* when its WHERE clause does not
    /// contain any `ColumnRef` whose name matches a column in `outer_cols`.
    fn rewrite_uncorrelated_subqueries(
        &mut self,
        expr: &mut Expr,
        outer_cols: &[String],
    ) -> Result<()> {
        match expr {
            Expr::InSubquery {
                expr: inner,
                subquery,
                negated,
            } => {
                // Check whether subquery is non-correlated (no outer column refs)
                if !Self::subquery_references_outer(subquery, outer_cols) {
                    let result = self.exec_select(subquery)?;
                    let list = match result {
                        ExecResult::QueryResult { rows, .. } => rows
                            .into_iter()
                            .filter_map(|r| r.into_iter().next())
                            .map(|v| match v {
                                Value::Integer(i) => Expr::IntegerLiteral(i),
                                Value::Real(r) => Expr::RealLiteral(r),
                                Value::Text(s) => Expr::StringLiteral(s.to_string()),
                                _ => Expr::Null,
                            })
                            .collect::<Vec<_>>(),
                        _ => Vec::new(),
                    };
                    // Replace the whole node with InList
                    let neg = *negated;
                    let inner_owned = std::mem::replace(inner.as_mut(), Expr::Null);
                    *expr = Expr::InList {
                        expr: Box::new(inner_owned),
                        list,
                        negated: neg,
                    };
                }
            }
            Expr::BinaryOp { left, right, .. } => {
                self.rewrite_uncorrelated_subqueries(left, outer_cols)?;
                self.rewrite_uncorrelated_subqueries(right, outer_cols)?;
            }
            Expr::UnaryOp { expr: inner, .. } | Expr::Nested(inner) => {
                self.rewrite_uncorrelated_subqueries(inner, outer_cols)?;
            }
            _ => {}
        }
        Ok(())
    }

    /// Returns true if the subquery's WHERE references any column in `outer_cols`.
    fn subquery_references_outer(subquery: &SelectStmt, outer_cols: &[String]) -> bool {
        if let Some(ref where_expr) = subquery.where_clause {
            Self::expr_references_cols(where_expr, outer_cols)
        } else {
            false
        }
    }

    fn expr_references_cols(expr: &Expr, cols: &[String]) -> bool {
        match expr {
            Expr::ColumnRef { column, .. } => cols.iter().any(|c| c.eq_ignore_ascii_case(column)),
            Expr::BinaryOp { left, right, .. } => {
                Self::expr_references_cols(left, cols) || Self::expr_references_cols(right, cols)
            }
            Expr::UnaryOp { expr: inner, .. } | Expr::Nested(inner) => {
                Self::expr_references_cols(inner, cols)
            }
            Expr::Function { args, .. } => args.iter().any(|a| Self::expr_references_cols(a, cols)),
            Expr::InList {
                expr: inner, list, ..
            } => {
                Self::expr_references_cols(inner, cols)
                    || list.iter().any(|e| Self::expr_references_cols(e, cols))
            }
            _ => false,
        }
    }

    /// Returns true if the WHERE expression is (or contains) an FTS MATCH predicate
    /// that would be handled entirely by `exec_fts_bm25_query`.
    /// Used to suppress post-scan WHERE re-evaluation for FTS queries.
    fn where_is_fts_match(expr: &Expr) -> bool {
        match expr {
            Expr::BinaryOp {
                op: BinaryOperator::FtsMatch,
                ..
            } => true,
            // AND / OR compound: if any branch is FTS MATCH, treat as FTS-handled
            Expr::BinaryOp {
                op: BinaryOperator::And,
                left,
                right,
            }
            | Expr::BinaryOp {
                op: BinaryOperator::Or,
                left,
                right,
            } => Self::where_is_fts_match(left) || Self::where_is_fts_match(right),
            _ => false,
        }
    }

    /// Execute a BM25 full-text search query against a table with CREATE FULLTEXT INDEX.
    ///
    /// For each FTS index on `table_name`:
    /// 1. Tokenize the query string
    /// 2. For each token, scan postings in `_kkdb_fts_{index_id}` table
    /// 3. Compute BM25 score per doc_id (k1=1.2, b=0.75)
    /// 4. Fetch matching rows sorted by score descending
    pub(crate) fn exec_fts_bm25_query(
        &mut self,
        table_name: &str,
        fts_indexes: &[crate::schema::IndexSchema],
        keyword: &str,
    ) -> Result<Option<(Vec<crate::types::Row>, Vec<String>)>> {
        use std::collections::HashMap;

        // BM25 parameters
        const K1: f64 = 1.2;
        const B: f64 = 0.75;

        let query_tokens = crate::fulltext::tokenizer::query_tokenize(keyword);
        if query_tokens.is_empty() {
            return Ok(Some((vec![], vec![])));
        }

        // Aggregate BM25 scores across all FTS indexes for this table
        // doc_id -> cumulative BM25 score
        let mut scores: HashMap<u64, f64> = HashMap::new();

        for fts_idx in fts_indexes {
            let index_id = fts_idx.root_page; // repurposed as index_id for FTS

            // Read global stats: (total_docs N, total_field_len)
            let (n_docs, total_field_len) = self.read_fts_global_stats(index_id);
            if n_docs == 0 {
                continue;
            }
            let avg_dl = total_field_len as f64 / n_docs as f64;

            for token in &query_tokens {
                // Scan postings first: Vec<(doc_id, tf, field_len)>
                let postings = self.scan_fts_postings(index_id, token);
                if postings.is_empty() {
                    continue;
                }

                // doc_freq (df) for IDF calculation.
                // If the stored DF row is missing/stale (can happen after B-Tree splits in
                // the DML write-path), fall back to counting the postings directly so the
                // IDF formula is always self-consistent.
                let stored_df = self.get_fts_doc_freq(index_id, token);
                let df = if stored_df > 0 {
                    stored_df
                } else {
                    postings.len() as u64
                };

                // IDF(t) = log((N - df + 0.5) / (df + 0.5) + 1)
                let idf = ((n_docs as f64 - df as f64 + 0.5) / (df as f64 + 0.5) + 1.0).ln();

                for (doc_id, tf, field_len) in postings {
                    let dl = field_len as f64;
                    // BM25 term score = IDF * (tf * (k1 + 1)) / (tf + k1 * (1 - b + b * dl / avgdl))
                    let tf_norm = tf as f64 * (K1 + 1.0)
                        / (tf as f64 + K1 * (1.0 - B + B * dl / avg_dl.max(1.0)));
                    let term_score = idf * tf_norm;
                    *scores.entry(doc_id).or_insert(0.0) += term_score;
                }
            }
        }

        if scores.is_empty() {
            let table = self.schema.get_table(table_name)?;
            return Ok(Some((vec![], table.col_names.clone())));
        }

        // Sort doc_ids by BM25 score descending
        let mut scored_docs: Vec<(u64, f64)> = scores.into_iter().collect();
        scored_docs.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

        // Fetch original rows by doc_id (rowid) — Double Lookup / 回表
        let table = self.schema.get_table(table_name)?.clone();
        let rowids: Vec<i64> = scored_docs
            .iter()
            .map(|(doc_id, _)| *doc_id as i64)
            .collect();
        let fetched = self.fetch_rows_by_rowids(table_name, table.root_page, &rowids)?;

        // Re-sort fetched rows to match BM25 score order
        let rowid_to_row: HashMap<i64, _> = fetched.into_iter().collect();
        let mut out_rows = Vec::with_capacity(rowids.len());
        for rowid in &rowids {
            if let Some(row) = rowid_to_row.get(rowid) {
                out_rows.push(row.clone());
            }
        }

        Ok(Some((out_rows, table.col_names)))
    }

    // ── O2: Histogram-based selectivity helpers ──────────────────────────────

    /// Convert a Value to f64 for histogram comparison. Returns None for non-numeric types.
    fn value_to_f64(v: &Value) -> Option<f64> {
        match v {
            Value::Integer(i) => Some(*i as f64),
            Value::Real(f) => Some(*f),
            _ => None,
        }
    }

    /// Estimate selectivity for equality predicate using histogram buckets.
    /// Falls back to None when histogram is unavailable or value is non-numeric.
    fn histogram_eq_selectivity(
        stats: &crate::schema::ColumnStats,
        eq_val: &Value,
    ) -> Option<f64> {
        let hist = stats.histogram.as_ref()?;
        if hist.is_empty() {
            return None;
        }
        let v = Self::value_to_f64(eq_val)?;
        let total = stats.total_count as f64;
        if total <= 0.0 {
            return None;
        }

        // Find the bucket that contains this value
        for bucket in hist {
            let ub = Self::value_to_f64(&bucket.upper_bound)?;
            if v <= ub {
                // Assume uniform distribution within bucket
                if bucket.ndv_in_bucket > 0 {
                    let bucket_rows = if bucket.cumulative_count > 0 {
                        // This bucket's row count = cumulative - prev_cumulative
                        // For simplicity, use cumulative_count / num_buckets approximation
                        // or use ndv_in_bucket as proxy
                        (bucket.cumulative_count as f64) / (hist.len() as f64).max(1.0)
                    } else {
                        1.0
                    };
                    return Some((bucket_rows / bucket.ndv_in_bucket as f64 / total).clamp(0.0, 1.0));
                }
                return Some(1.0 / stats.ndv.max(1) as f64);
            }
        }
        // Value beyond all buckets
        Some(0.0)
    }

    /// Estimate selectivity for range predicates using histogram.
    /// `low` = None means unbounded below, `high` = None means unbounded above.
    fn histogram_range_selectivity(
        stats: &crate::schema::ColumnStats,
        low: Option<&Value>,
        high: Option<&Value>,
    ) -> Option<f64> {
        let hist = stats.histogram.as_ref()?;
        if hist.is_empty() {
            return None;
        }
        let total = stats.total_count as f64;
        if total <= 0.0 {
            return None;
        }

        let lo = match low {
            Some(v) => Self::value_to_f64(v)?,
            None => f64::NEG_INFINITY,
        };
        let hi = match high {
            Some(v) => Self::value_to_f64(v)?,
            None => f64::INFINITY,
        };

        // Walk buckets and accumulate rows in the range [lo, hi]
        let mut qualifying_rows = 0.0;
        let mut prev_cumulative = 0.0;
        for bucket in hist {
            let ub = Self::value_to_f64(&bucket.upper_bound)?;
            let bucket_rows = bucket.cumulative_count as f64 - prev_cumulative;

            if ub < lo {
                // Bucket entirely below range
                prev_cumulative = bucket.cumulative_count as f64;
                continue;
            }
            if ub <= hi {
                // Bucket entirely or partially within range
                // If lo is within this bucket, estimate partial
                let prev_ub = if prev_cumulative > 0.0 {
                    // approximate previous bucket upper bound — not available, assume lo is start
                    lo
                } else {
                    f64::NEG_INFINITY
                };
                if lo > prev_ub && lo <= ub && lo > f64::NEG_INFINITY {
                    // Partial: fraction of bucket above lo
                    let bucket_range = ub - prev_ub;
                    if bucket_range > 0.0 {
                        let frac = ((ub - lo) / bucket_range).clamp(0.0, 1.0);
                        qualifying_rows += bucket_rows * frac;
                    } else {
                        qualifying_rows += bucket_rows;
                    }
                } else {
                    qualifying_rows += bucket_rows;
                }
            } else {
                // Bucket extends beyond hi — take partial fraction
                let prev_ub_approx = if prev_cumulative > 0.0 {
                    // Use previous bucket upper bound
                    lo.max(ub - bucket_rows) // rough approximation
                } else {
                    f64::NEG_INFINITY
                };
                let bucket_range = ub - prev_ub_approx;
                if bucket_range > 0.0 && hi >= prev_ub_approx {
                    let frac = ((hi - prev_ub_approx.max(lo)) / bucket_range).clamp(0.0, 1.0);
                    qualifying_rows += bucket_rows * frac;
                }
                break; // No more buckets needed
            }
            prev_cumulative = bucket.cumulative_count as f64;
        }

        Some((qualifying_rows / total).clamp(0.0, 1.0))
    }

    // ── O2: Join reorder for INNER JOINs ─────────────────────────────────────

    /// Estimate the cardinality (row count) of a FROM clause source.
    /// Uses statistics when available, otherwise scans the B-tree.
    fn estimate_from_cardinality(&self, from: &FromClause) -> f64 {
        match from {
            FromClause::Table { name, alias: _ } => {
                let table_name = name.to_lowercase();
                if let Ok(table) = self.schema.get_table(&table_name) {
                    // Use stats if available
                    if let Some(ref stats) = table.columns.first().and_then(|c| c.stats.as_ref()) {
                        return stats.total_count as f64;
                    }
                    // Fallback: use a default estimate
                    return 1000.0;
                }
                1000.0 // unknown table
            }
            FromClause::Subquery { .. } | FromClause::SetOp { .. } | FromClause::TableFunction { .. } => {
                1000.0 // can't estimate cheaply
            }
            FromClause::Join {
                left,
                right,
                join_type: _,
                on: _,
            } => {
                // Rough estimate: product of both sides (could be refined with join selectivity)
                let l = self.estimate_from_cardinality(left);
                let r = self.estimate_from_cardinality(right);
                // For inner joins, assume ~10% selectivity as default
                (l * r * 0.1).max(1.0)
            }
        }
    }

    /// Reorder a chain of INNER JOINs to put the smaller table on the build side.
    /// This function flattens left-deep INNER JOIN trees, sorts by cardinality,
    /// and reconstructs the tree with the smallest relation scanned first.
    /// Non-inner joins (LEFT, RIGHT, FULL) are NOT reordered to preserve semantics.
    fn reorder_joins(&self, from: &mut FromClause) {
        // Only reorder if the top-level is an INNER/CROSS join
        if !Self::is_reorderable_join(from) {
            return;
        }

        // Flatten the join tree into a list of (table, ON condition) pairs
        let mut tables: Vec<FromClause> = Vec::new();
        let mut conditions: Vec<Option<Expr>> = Vec::new();
        Self::flatten_inner_joins(from, &mut tables, &mut conditions);

        if tables.len() < 2 {
            return;
        }

        // Estimate cardinality for each table and sort smallest-first
        let mut indexed: Vec<(usize, f64)> = tables
            .iter()
            .enumerate()
            .map(|(i, t)| (i, self.estimate_from_cardinality(t)))
            .collect();

        // Only reorder if cardinalities actually differ (avoid breaking queries
        // when all tables have equal/unknown stats — preserves original order).
        let cards: Vec<f64> = indexed.iter().map(|(_, c)| *c).collect();
        let all_equal = cards.windows(2).all(|w| (w[0] - w[1]).abs() < 0.5);
        if all_equal {
            return; // no benefit from reordering
        }

        indexed.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal));

        // Reconstruct the join tree in the new order
        let mut reordered_tables: Vec<FromClause> = indexed
            .iter()
            .map(|(i, _)| std::mem::replace(&mut tables[*i], FromClause::Table {
                name: String::new(),
                alias: None,
            }))
            .collect();

        // Collect all non-None ON conditions into a single AND expression
        let combined_on: Option<Expr> = conditions
            .into_iter()
            .flatten()
            .reduce(|acc, c| Expr::BinaryOp {
                left: Box::new(acc),
                op: crate::sql::ast::BinaryOperator::And,
                right: Box::new(c),
            });

        // Build left-deep tree: intermediate joins get no ON; top-level gets combined ON
        let mut result = reordered_tables.remove(0);
        let total = reordered_tables.len();
        for (i, right) in reordered_tables.into_iter().enumerate() {
            let is_last = i + 1 == total;
            result = FromClause::Join {
                left: Box::new(result),
                join_type: JoinType::Inner,
                right: Box::new(right),
                on: if is_last { combined_on.clone() } else { None },
            };
        }

        *from = result;
    }

    /// Check if a FROM clause is a reorderable (INNER/CROSS) join.
    fn is_reorderable_join(from: &FromClause) -> bool {
        matches!(
            from,
            FromClause::Join {
                join_type: JoinType::Inner | JoinType::Cross,
                ..
            }
        )
    }

    /// Flatten a left-deep chain of INNER/CROSS joins into tables and conditions.
    fn flatten_inner_joins(
        from: &FromClause,
        tables: &mut Vec<FromClause>,
        conditions: &mut Vec<Option<Expr>>,
    ) {
        match from {
            FromClause::Join {
                left,
                join_type: JoinType::Inner | JoinType::Cross,
                right,
                on,
            } => {
                Self::flatten_inner_joins(left, tables, conditions);
                // Right side is always a leaf in left-deep trees
                tables.push(*right.clone());
                conditions.push(on.clone());
            }
            other => {
                tables.push(other.clone());
            }
        }
    }
}

/// Generate a deterministic sort key for a row (used for UNION/INTERSECT/EXCEPT dedup)
fn row_key(row: &[crate::types::Value]) -> Vec<u8> {
    let mut key = Vec::new();
    for v in row {
        let bytes = v.serialize();
        key.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
        key.extend(bytes);
    }
    key
}

