// ── Serialize / Deserialize roundtrip ─────────────────────────────────────────

fn roundtrip(record: &LogRecord) -> LogRecord {
    let mut buf = Vec::new();
    record.serialize(&mut buf).unwrap();
    let (deserialized, _) = LogRecord::deserialize(&buf, 0).expect("deserialize failed");
    deserialized
}

