    let mut vm = VM::new_memory();
    vm.execute_sql("CREATE TABLE ls1 (id INTEGER PRIMARY KEY, name TEXT)").unwrap();
    vm.execute_sql("CREATE TABLE ls2 (id INTEGER PRIMARY KEY, ref_id INTEGER)").unwrap();
