         JOIN j2 ON j2.j1_id = j1.id \
         JOIN j3 ON j3.j2_id = j2.id \
         JOIN j4 ON j4.j3_id = j3.id \
         ORDER BY j1.id");
    assert_eq!(rows.len(), 2);
}

