#[test]
fn test_nested_transaction_savepoint_rollback() {
    let mut vm = VM::new_memory();
    vm.execute_sql("CREATE TABLE t_sp (id INTEGER PRIMARY KEY, v TEXT)").unwrap();
    vm.execute_sql("INSERT INTO t_sp VALUES (1, 'original')").unwrap();
