    vm.execute_sql("CREATE TABLE ls_a (id INTEGER PRIMARY KEY, name TEXT)").unwrap();
    vm.execute_sql("CREATE TABLE ls_b (id INTEGER PRIMARY KEY, ref_id INTEGER)").unwrap();
