    let rows = q(&mut vm, "SELECT id, val FROM tno ORDER BY val LIMIT 3 OFFSET 5");
    assert_eq!(rows.len(), 3);
    assert_eq!(rows[0][1], Value::Integer(60)); // 6th row (0-indexed: 5)
