    e(&mut vm, "ANALYZE TABLE ab");
    // BETWEEN should use histogram-based range selectivity
    let rows = q(&mut vm, "SELECT * FROM ab WHERE val BETWEEN 20 AND 40");
    assert_eq!(rows.len(), 21); // 20..40 inclusive
}

