#[test]
fn test_ctas_basic() {
    let mut vm = mem();
    exec(&mut vm, "CREATE TABLE src (id INTEGER PRIMARY KEY, name TEXT)").unwrap();
    exec(&mut vm, "INSERT INTO src VALUES (1,'Alice'),(2,'Bob')").unwrap();
    exec(&mut vm, "CREATE TABLE dst AS SELECT * FROM src").unwrap();
