#[test]
fn test_btree_scan_leaf_chain() {
    use crate::storage::btree::BTree;
    use crate::storage::pager::Pager;
    use crate::types::Value;
    use std::sync::Arc;

    let mut pager = Pager::open_memory();
    pager.begin_transaction().unwrap();
    let mut root;
