#[test]
fn test_vacuum_defragment() {
    let mut vm = VM::new_memory();
    exec(&mut vm, "CREATE TABLE vac(id INTEGER PRIMARY KEY, val TEXT)");
    for i in 1..=50 {
        exec(&mut vm, &format!("INSERT INTO vac VALUES ({i}, 'row_{i}')"));
