    // Create 3 partitions with different sizes and ties
    for i in 1..=5 { exec(&mut vm, &format!("INSERT INTO prmp VALUES ({i}, 'A', {})", i * 10)); }
    for i in 6..=10 { exec(&mut vm, &format!("INSERT INTO prmp VALUES ({i}, 'B', {})", (i - 5) * 10)); }
