    let r = Pager::open_cow_v2(path);
    if let Ok(mut pager) = r {
        pager.begin_transaction().unwrap();
        let pg = pager.allocate_page().unwrap();
        {
            let page = pager.get_page_mut(pg).unwrap();
            page.data[0..4].copy_from_slice(b"TEST");
