        .unwrap();

    vm.execute_sql("INSERT INTO t1 VALUES (1, 'a')").unwrap();
    vm.execute_sql("INSERT INTO t2 VALUES (2, 'b')").unwrap();
    vm.execute_sql("INSERT INTO t3 VALUES (1, 'one')").unwrap();
    vm.execute_sql("INSERT INTO t3 VALUES (2, 'two')").unwrap();

    let rows = query_rows(
        &mut vm,
