        Value::Integer(1)
    );
    // DOUBLE → Real
    assert_eq!(
        query_rows(&mut vm, "SELECT CAST(42 AS DOUBLE)")[0][0],
        Value::Real(42.0)
    );
    // FLOAT → Real
    assert_eq!(
