        Value::Real(42.0)
    );
    // VARCHAR → Text
    assert_eq!(
        query_rows(&mut vm, "SELECT CAST(42 AS VARCHAR)")[0][0],
        Value::Text("42".into())
    );
    // CHAR → Text
    assert_eq!(
        query_rows(&mut vm, "SELECT CAST(42 AS CHAR)")[0][0],
        Value::Text("42".into())
