    vm.execute_sql("CREATE TABLE wt (id INTEGER, val TEXT)")
        .unwrap();
    vm.execute_sql("INSERT INTO wt VALUES (1, 'a'), (2, 'b'), (3, 'c')")
        .unwrap();
    let rows = query_rows(
        &mut vm,
