fn test_lag_lead() {
    let mut vm = VM::new_memory();
    vm.execute_sql("CREATE TABLE ll_t (id INTEGER)").unwrap();
    vm.execute_sql("INSERT INTO ll_t VALUES (10), (20), (30)")
        .unwrap();
    let rows = query_rows(
        &mut vm,
        "SELECT id, LAG(id, 1) OVER (ORDER BY id) FROM ll_t ORDER BY id",
    );
